const views = {"CH_BA94_1CTS:ALT1":[["**Surface:** Synthetic a priori judgments are possible through the pure intuitions of space and time.","Surface: Synthetic a priori judgments are possible through the pure intuitions of space and time."]],"CH_BA94_1CTS:ALT2":[["**Structural:** Pure intuition supplies non-conceptual a priori content that can be synthetically integrated with concepts.","Structural: Pure intuition supplies non-conceptual a priori content that can be synthetically integrated with concepts."]],"CH_BA94_1CTS:ALT3":[["**Metastrategic:** The argument solves the possibility problem by simultaneously restricting the scope of the resulting cognition.","Metastrategic: The argument solves the possibility problem by simultaneously restricting the scope of the resulting cognition."]],"CH_BA94_1CTS:ALT4":[["**Ontological/Temporal:** Space and time function as a priori conditions of sensible objectivity, while objects outside possible experience remain beyond the established field of validity.","Ontological/Temporal: Space and time function as a priori conditions of sensible objectivity, while objects outside possible experience remain beyond the established field of validity."]],"CH_BA94_OSUA:ALT1":[["**Surface:** The “I think” must be capable of accompanying every representation that exists for the subject.","Surface: The “I think” must be capable of accompanying every representation that exists for the subject."]],"CH_BA94_OSUA:ALT2":[["**Structural:** The identity of consciousness is produced through the synthesis of an intuitively given manifold rather than through empirical accompaniment.","Structural: The identity of consciousness is produced through the synthesis of an intuitively given manifold rather than through empirical accompaniment."]],"CH_BA94_OSUA:ALT3":[["**Metastrategic:** The argument relocates the foundation of cognition from objects and isolated representations to the activity that unifies them under apperception.","Metastrategic: The argument relocates the foundation of cognition from objects and isolated representations to the activity that unifies them under apperception."]],"CH_BA94_OSUA:ALT4":[["**Ontological/Temporal:** A priori priority is structural rather than chronological; synthetical unity must precede determinate thought as its condition, while the ego remains formally empty without intuition.","Ontological/Temporal: A priori priority is structural rather than chronological; synthetical unity must precede determinate thought as its condition, while the ego remains formally empty without intuition."]],"CH_BA94_LFAJ:ALT1":[["**Surface:** Judgment is the objective relation among given cognitions, contrasted with a subjective report of sensation.","Surface: Judgment is the objective relation among given cognitions, contrasted with a subjective report of sensation."]],"CH_BA94_LFAJ:ALT2":[["**Structural:** Understanding produces objective unity through synthesis, whereas reproductive imagination produces subjective association.","Structural: Understanding produces objective unity through synthesis, whereas reproductive imagination produces subjective association."]],"CH_BA94_LFAJ:ALT3":[["**Metastrategic:** The analysis shifts the question from the classification of judgments to the conditions under which any relation can possess objective validity.","Metastrategic: The analysis shifts the question from the classification of judgments to the conditions under which any relation can possess objective validity."]],"CH_BA94_LFAJ:ALT4":[["**Ontological/Temporal:** Object-directed cognition is not grounded in the temporal repetition of impressions but in a necessary synthesis that orders representations according to transcendental principles.","Ontological/Temporal: Object-directed cognition is not grounded in the temporal repetition of impressions but in a necessary synthesis that orders representations according to transcendental principles."]],"CH_BA94_CIGD:ALT1":[["**Surface —** The immediate issue is whether pure categories can determine noumena and support a division of objects into sensible and intelligible kinds.","Surface — The immediate issue is whether pure categories can determine noumena and support a division of objects into sensible and intelligible kinds."]],"CH_BA94_CIGD:ALT2":[["**Structural —** Objective cognition is generated through the conjunction of sensible givenness, categorial synthesis, and schematic subsumption.","Structural — Objective cognition is generated through the conjunction of sensible givenness, categorial synthesis, and schematic subsumption."]],"CH_BA94_CIGD:ALT3":[["**Metastrategic —** Critique secures the jurisdiction of empirical knowledge by diagnosing transcendental claims as misapplications of valid cognitive forms.","Metastrategic — Critique secures the jurisdiction of empirical knowledge by diagnosing transcendental claims as misapplications of valid cognitive forms."]],"CH_BA94_CIGD:ALT4":[["**Ontological/Temporal —** Object-determination is conditioned by sensible givenness in space and time, while reality apart from those conditions remains thinkable only as an indeterminate limit.","Ontological/Temporal — Object-determination is conditioned by sensible givenness in space and time, while reality apart from those conditions remains thinkable only as an indeterminate limit."]],"CH_BA94_TRAD:ALT1":[["**Surface:** The text presents titles and sectional headings.","Surface: The text presents titles and sectional headings."]],"CH_BA94_TRAD:ALT2":[["**Structural:** The headings establish a nested relation between division, domain, subsection, and introductory function.","Structural: The headings establish a nested relation between division, domain, subsection, and introductory function."]],"CH_BA94_TRAD:ALT3":[["**Metastrategic:** The available material limits interpretation to textual placement and prohibits reconstruction of an unprovided argument.","Metastrategic: The available material limits interpretation to textual placement and prohibits reconstruction of an unprovided argument."]],"CH_BA94_TRAD:ALT4":[["**Ontological/Temporal:** The text implies a before-and-after structure in which the introduction precedes a fuller exposition, but it supplies no doctrine of reality, subject, or time.","Ontological/Temporal: The text implies a before-and-after structure in which the introduction precedes a fuller exposition, but it supplies no doctrine of reality, subject, or time."]],"CH_BA94_SITI:AF1":[["Categories derived from judgement **→** reason examined through syllogism **→** totality of conditions identified as reason’s object.","Categories derived from judgement → reason examined through syllogism → totality of conditions identified as reason’s object."]],"CH_BA94_SITI:AF2":[["Totality of conditions **→** unconditioned **→** three classes of transcendental ideas.","Totality of conditions → unconditioned → three classes of transcendental ideas."]],"CH_BA94_SITI:AF3":[["Transcendental ideas as necessary products of reason **→** absence of adequate experience **→** denial of constitutive objective use.","Transcendental ideas as necessary products of reason → absence of adequate experience → denial of constitutive objective use."]],"CH_BA94_SITI:AF4":[["Denial of constitutive use **→** retention of regulative use **→** systematic unity of understanding.","Denial of constitutive use → retention of regulative use → systematic unity of understanding."]],"CH_BA94_SITI:AF5":[["Conditioned conclusion **→** required totality of premises **→** asymmetry between completed regress and open progress.","Conditioned conclusion → required totality of premises → asymmetry between completed regress and open progress."]],"CL_BA94_01:GA-01":[["[Persistent] Knowledge may begin with experience without being wholly derived from experience.","Knowledge may begin with experience without being wholly derived from experience."]],"CL_BA94_01:GA-02":[["[Persistent] Empirical cognition is composite: sensory reception supplies material while cognition contributes ordering elements.","Empirical cognition is composite: sensory reception supplies material while cognition contributes ordering elements."]],"CL_BA94_01:GA-03":[["[Mutating] The a priori is first defined by independence from experience, then operationally identified through necessity, strict universality, and unavoidable conceptual residue.","The a priori is first defined by independence from experience, then operationally identified through necessity, strict universality, and unavoidable conceptual residue."]],"CL_BA94_01:GA-04":[["[Persistent] Necessity and strict universality cannot be produced by induction from contingent observation.","Necessity and strict universality cannot be produced by induction from contingent observation."]],"CL_BA94_01:GA-05":[["[Emergent] Experience is not the ultimate ground of its own certainty because its intelligibility presupposes non-empirical rules.","Experience is not the ultimate ground of its own certainty because its intelligibility presupposes non-empirical rules."]],"CL_BA94_01:GA-06":[["[Mutating] The a priori concerns both judgments and the irreducible forms through which objects can be thought.","The a priori concerns both judgments and the irreducible forms through which objects can be thought."]],"CL_BA94_01:GA-07":[["[Attractor] Validity depends not merely on formal coherence but on the origin and enabling conditions of cognitive additions.","Validity depends not merely on formal coherence but on the origin and enabling conditions of cognitive additions."]],"CL_BA94_01:GA-08":[["[Terminal] The existence of a priori cognition does not authorize unlimited cognition beyond possible experience.","The existence of a priori cognition does not authorize unlimited cognition beyond possible experience."]],"CL_BA94_01:GA-09":[["[Attractor] Critical inquiry must determine the possibility and extent of reason before reason constructs metaphysical conclusions.","Critical inquiry must determine the possibility and extent of reason before reason constructs metaphysical conclusions."]],"CL_BA94_01:GA-10":[["[Emergent] The distinction between analytic clarification and synthetic addition is necessary to expose unauthorized conceptual importation.","The distinction between analytic clarification and synthetic addition is necessary to expose unauthorized conceptual importation."]],"CL_BA94_02:GA-01":[["[Persistent] Analytic judgment can secure conceptual necessity but cannot produce knowledge that augments the subject-conception.","Analytic judgment can secure conceptual necessity but cannot produce knowledge that augments the subject-conception."]],"CL_BA94_02:GA-02":[["[Persistent] Empirical synthesis can connect representations and extend cognition, but cannot supply the universality and necessity required for a priori knowledge.","Empirical synthesis can connect representations and extend cognition, but cannot supply the universality and necessity required for a priori knowledge."]],"CL_BA94_02:GA-03":[["[Mutating] Synthetic a priori judgment begins as an unexplained connection between heterogeneous terms and becomes the common formal requirement of theoretical science.","Synthetic a priori judgment begins as an unexplained connection between heterogeneous terms and becomes the common formal requirement of theoretical science."]],"CL_BA94_02:GA-04":[["[Emergent] Logical contradiction tests the legitimacy of a judgment but cannot generate the synthetic ground of substantive cognition.","Logical contradiction tests the legitimacy of a judgment but cannot generate the synthetic ground of substantive cognition."]],"CL_BA94_02:GA-05":[["[Attractor] Theoretical science is constituted by necessary additions to concepts under non-empirical conditions rather than by deduction or observation alone.","Theoretical science is constituted by necessary additions to concepts under non-empirical conditions rather than by deduction or observation alone."]],"CL_BA94_02:GA-06":[["[Persistent] Mathematics and pure natural science are existing proof-cases whose possibility requires transcendental explanation.","Mathematics and pure natural science are existing proof-cases whose possibility requires transcendental explanation."]],"CL_BA94_02:GA-07":[["[Mutating] Intuition is the productive mediator of mathematical synthesis, yet its extension into a universal account of science and metaphysics remains unproven.","Intuition is the productive mediator of mathematical synthesis, yet its extension into a universal account of science and metaphysics remains unproven."]],"CL_BA94_02:GA-08":[["[Persistent] Metaphysics is naturally generated by reason but acquires scientific standing only through a valid account of synthetic a priori cognition.","Metaphysics is naturally generated by reason but acquires scientific standing only through a valid account of synthetic a priori cognition."]],"CL_BA94_02:GA-09":[["[Terminal] Critical limitation is the enabling condition of legitimate a priori extension rather than a merely negative restriction.","Critical limitation is the enabling condition of legitimate a priori extension rather than a merely negative restriction."]],"CL_BA94_02:GA-10":[["[Attractor] Reason must become the object of inquiry because its metaphysical problems, claims, and limits are self-generated.","Reason must become the object of inquiry because its metaphysical problems, claims, and limits are self-generated."]],"CL_BA94_03:GA-01":[["[Attractor] Valid a priori cognition requires prior determination of the faculties and conditions that make its object-relation possible.","Valid a priori cognition requires prior determination of the faculties and conditions that make its object-relation possible."]],"CL_BA94_03:GA-02":[["[Persistent] Human cognition has no object-directed use of concepts that is independent of intuition and givenness.","Human cognition has no object-directed use of concepts that is independent of intuition and givenness."]],"CL_BA94_03:GA-03":[["[Persistent] Sensibility and understanding are irreducibly distinct sources of cognition, because giving an object and thinking an object are non-interchangeable operations.","Sensibility and understanding are irreducibly distinct sources of cognition, because giving an object and thinking an object are non-interchangeable operations."]],"CL_BA94_03:GA-04":[["[Mutating] Critique begins as a negative limitation of pure reason but becomes an operative method for isolating the pure conditions of cognition.","Critique begins as a negative limitation of pure reason but becomes an operative method for isolating the pure conditions of cognition."]],"CL_BA94_03:GA-05":[["[Emergent] Phenomenal objectivity arises neither from raw sensation nor from conceptual construction alone, but from sensory matter ordered through a priori form.","Phenomenal objectivity arises neither from raw sensation nor from conceptual construction alone, but from sensory matter ordered through a priori form."]],"CL_BA94_03:GA-06":[["[Persistent] Space is a necessary a priori form of external intuition and therefore a condition of possible external experience.","Space is a necessary a priori form of external intuition and therefore a condition of possible external experience."]],"CL_BA94_03:GA-07":[["[Emergent] Geometrical apodeicticity is possible because spatial determination is grounded in pure intuition rather than in observed regularity or general concepts.","Geometrical apodeicticity is possible because spatial determination is grounded in pure intuition rather than in observed regularity or general concepts."]],"CL_BA94_03:GA-08":[["[Attractor] Systematic completion is conceivable only because the subject’s a priori field is bounded, although its full architectonic completion remains deferred.","Systematic completion is conceivable only because the subject’s a priori field is bounded, although its full architectonic completion remains deferred."]],"CL_BA94_03:GA-09":[["[Terminal] Critical validity terminates at the conditions of possible appearance and cannot establish the independent ontological status of space or of things beyond intuition.","Critical validity terminates at the conditions of possible appearance and cannot establish the independent ontological status of space or of things beyond intuition."]],"CL_BA94_03:GA-10":[["[Mutating] The a priori is not coextensive with conceptual generality, because the form that conditions external experience is singular, infinite, and intuitive.","The a priori is not coextensive with conceptual generality, because the form that conditions external experience is singular, infinite, and intuitive."]],"CL_BA94_04:GA-01":[["[Persistent] Synthetic a priori cognition requires pure intuition whenever cognition must extend beyond what concepts analytically contain.","Synthetic a priori cognition requires pure intuition whenever cognition must extend beyond what concepts analytically contain."]],"CL_BA94_04:GA-02":[["[Persistent] Necessity belongs to the formal conditions of possible experience rather than to empirical regularities extracted from experience.","Necessity belongs to the formal conditions of possible experience rather than to empirical regularities extracted from experience."]],"CL_BA94_04:GA-03":[["[Mutating] Space functions as the pure form of external intuition, making external appearances immediately representable without constituting things in themselves spatially.","Space functions as the pure form of external intuition, making external appearances immediately representable without constituting things in themselves spatially."]],"CL_BA94_04:GA-04":[["[Mutating] Time functions as the universal form of phenomenal intuition, making succession, coexistence, and temporal determination possible without deriving them from phenomena.","Time functions as the universal form of phenomenal intuition, making succession, coexistence, and temporal determination possible without deriving them from phenomena."]],"CL_BA94_04:GA-05":[["[Emergent] Objective validity is domain-indexed: it is secured for possible experience precisely by being denied as a determination of things in themselves.","Objective validity is domain-indexed: it is secured for possible experience precisely by being denied as a determination of things in themselves."]],"CL_BA94_04:GA-06":[["[Persistent] Receptivity is not passive empirical intake but the subject’s contribution of the formal field in which objects can appear.","Receptivity is not passive empirical intake but the subject’s contribution of the formal field in which objects can appear."]],"CL_BA94_04:GA-07":[["[Emergent] The form/content distinction governs both spatial and temporal cognition: empirical objects provide material only within forms that precede their appearance.","The form/content distinction governs both spatial and temporal cognition: empirical objects provide material only within forms that precede their appearance."]],"CL_BA94_04:GA-08":[["[Attractor] The possibility of experience is the discriminating criterion by which representations are classified as pure forms, empirical contents, or illegitimate metaphysical projections.","The possibility of experience is the discriminating criterion by which representations are classified as pure forms, empirical contents, or illegitimate metaphysical projections."]],"CL_BA94_04:GA-09":[["[Terminal] Phenomenal cognition is complete only as cognition of appearances; any transition from conditions of appearance to the intrinsic constitution of things is invalid.","Phenomenal cognition is complete only as cognition of appearances; any transition from conditions of appearance to the intrinsic constitution of things is invalid."]],"CL_BA94_04:GA-10":[["[Attractor] Unity precedes determination: one spatially and temporally enabling form is presupposed before particular magnitudes, relations, or intervals can be represented.","Unity precedes determination: one spatially and temporally enabling form is presupposed before particular magnitudes, relations, or intervals can be represented."]],"CL_BA94_05:GA-01":[["[Persistent] Time is the internal a priori form without which succession, change, and motion cannot be represented.","Time is the internal a priori form without which succession, change, and motion cannot be represented."]],"CL_BA94_05:GA-02":[["[Persistent] Temporal succession converts opposed determinations of one object from simultaneous contradiction into intelligible change.","Temporal succession converts opposed determinations of one object from simultaneous contradiction into intelligible change."]],"CL_BA94_05:GA-03":[["[Mutating] Motion presupposes temporal intuition as change of place, yet particular motion remains an empirical determination rather than a pure form.","Motion presupposes temporal intuition as change of place, yet particular motion remains an empirical determination rather than a pure form."]],"CL_BA94_05:GA-04":[["[Emergent] The internality of every representation makes time universally valid for phenomena without making time an external form.","The internality of every representation makes time universally valid for phenomena without making time an external form."]],"CL_BA94_05:GA-05":[["[Attractor] Temporal necessity has objective validity only for things as phenomena and cannot be extended to things independently of sensibility.","Temporal necessity has objective validity only for things as phenomena and cannot be extended to things independently of sensibility."]],"CL_BA94_05:GA-06":[["[Persistent] Empirical reality does not entail absolute reality: actual change is real within experience without proving that time exists independently of intuition.","Empirical reality does not entail absolute reality: actual change is real within experience without proving that time exists independently of intuition."]],"CL_BA94_05:GA-07":[["[Emergent] Synthetic a priori cognition is possible because temporal and spatial forms precede empirical objects and determine the field in which objects can appear.","Synthetic a priori cognition is possible because temporal and spatial forms precede empirical objects and determine the field in which objects can appear."]],"CL_BA94_05:GA-08":[["[Terminal] Space and time exhaust the pure forms of sensibility; every further sensible determination requires empirical content.","Space and time exhaust the pure forms of sensibility; every further sensible determination requires empirical content."]],"CL_BA94_05:GA-09":[["[Attractor] Time is a condition of object-presentation, not an object, relation, or objective property inhering in things in themselves.","Time is a condition of object-presentation, not an object, relation, or objective property inhering in things in themselves."]],"CL_BA94_05:GA-10":[["[Mutating] Subjectivity denotes the necessary human form of receptivity that establishes empirical objectivity, not a private or arbitrary psychological construction.","Subjectivity denotes the necessary human form of receptivity that establishes empirical objectivity, not a private or arbitrary psychological construction."]],"CL_BA94_05:ALT-B01":[["[Surface] Actual change, motion, and the status of time are the explicit objects through which the cluster tests whether temporal reality is absolute or phenomenal.","Actual change, motion, and the status of time are the explicit objects through which the cluster tests whether temporal reality is absolute or phenomenal."]],"CL_BA94_05:ALT-B02":[["[Structural] Internal sense mediates every representation, while space and time organize the formal field in which empirical objects can appear.","Internal sense mediates every representation, while space and time organize the formal field in which empirical objects can appear."]],"CL_BA94_05:ALT-B03":[["[Metastrategic] The system retains empirical realism and mathematical necessity by assigning objectivity and subject-dependence to distinct but coordinated domains.","The system retains empirical realism and mathematical necessity by assigning objectivity and subject-dependence to distinct but coordinated domains."]],"CL_BA94_05:ALT-B04":[["[Ontological / Temporal] Time is necessary for phenomenal succession but has no status as a self-subsisting feature of things in themselves.","Time is necessary for phenomenal succession but has no status as a self-subsisting feature of things in themselves."]],"CL_BA94_05:ALT-B05":[["[Methodological / Performative] The argument preserves a claim only by regressing from empirical appearance to its condition of representation and then restricting that condition to its legitimate domain.","The argument preserves a claim only by regressing from empirical appearance to its condition of representation and then restricting that condition to its legitimate domain."]],"CL_BA94_06:GA-01":[["[Persistent] Finite cognition requires both receptive givenness and spontaneous conceptual thought; neither faculty produces cognition alone.","Finite cognition requires both receptive givenness and spontaneous conceptual thought; neither faculty produces cognition alone."]],"CL_BA94_06:GA-02":[["[Persistent] Space and time are a priori forms through which objects are given only as phenomena.","Space and time are a priori forms through which objects are given only as phenomena."]],"CL_BA94_06:GA-03":[["[Persistent] Pure intuition contributes a priori content beyond a given conception and thereby makes synthetic a priori judgment possible.","Pure intuition contributes a priori content beyond a given conception and thereby makes synthetic a priori judgment possible."]],"CL_BA94_06:GA-04":[["[Mutating] Necessity signifies the structure objects must exhibit under the conditions of experience rather than the constitution of objects in themselves.","Necessity signifies the structure objects must exhibit under the conditions of experience rather than the constitution of objects in themselves."]],"CL_BA94_06:GA-05":[["[Persistent] Faculty cooperation requires functional differentiation because sensibility and understanding cannot exchange their respective operations.","Faculty cooperation requires functional differentiation because sensibility and understanding cannot exchange their respective operations."]],"CL_BA94_06:GA-06":[["[Emergent] Objective cognition requires both formally conditioned sensible presentation and conceptual determination.","Objective cognition requires both formally conditioned sensible presentation and conceptual determination."]],"CL_BA94_06:GA-07":[["[Mutating] Universality is condition-relative: sensible universality arises from shared forms of intuition, whereas logical universality arises through abstraction from object-differences and empirical circumstances.","Universality is condition-relative: sensible universality arises from shared forms of intuition, whereas logical universality arises through abstraction from object-differences and empirical circumstances."]],"CL_BA94_06:GA-08":[["[Persistent] The constitution of objects independently of sensible conditions remains cognitively unavailable.","The constitution of objects independently of sensible conditions remains cognitively unavailable."]],"CL_BA94_06:GA-09":[["[Attractor] Cognitive enabling and cognitive limitation are one structure because the conditions that generate validity also determine its boundary.","Cognitive enabling and cognitive limitation are one structure because the conditions that generate validity also determine its boundary."]],"CL_BA94_06:GA-10":[["[Mutating] Purity names distinct exclusions: pure intuition excludes empirical sensation while retaining non-conceptual form, whereas pure logic excludes object-content and empirical conditions.","Purity names distinct exclusions: pure intuition excludes empirical sensation while retaining non-conceptual form, whereas pure logic excludes object-content and empirical conditions."]],"CL_BA94_06:GA-11":[["[Terminal] Pure general logic is an a priori canon of formal thought and cannot by itself extend cognition of objects.","Pure general logic is an a priori canon of formal thought and cannot by itself extend cognition of objects."]],"CL_BA94_06:GA-12":[["[Emergent] The subject conditions appearances while remaining available to itself only through temporally conditioned self-presentation.","The subject conditions appearances while remaining available to itself only through temporally conditioned self-presentation."]],"CL_BA94_06:GA-13":[["[Terminal] The dual-source architecture establishes the need for synthesis without yet explaining how determinate conceptions connect to intuitions.","The dual-source architecture establishes the need for synthesis without yet explaining how determinate conceptions connect to intuitions."]],"CL_BA94_06:GA-14":[["[Attractor] Human finitude consists in the absence of both a self-sufficient cognitive faculty and purely intellectual access to objects.","Human finitude consists in the absence of both a self-sufficient cognitive faculty and purely intellectual access to objects."]],"CL_BA94_07:GA-01":[["[Persistent] Formal coherence is a necessary negative condition of cognition but cannot establish agreement between cognition and object.","Formal coherence is a necessary negative condition of cognition but cannot establish agreement between cognition and object."]],"CL_BA94_07:GA-02":[["[Persistent] Objective cognition requires pure conceptual conditions and objects given through intuition or experience; neither factor produces objective knowledge alone.","Objective cognition requires pure conceptual conditions and objects given through intuition or experience; neither factor produces objective knowledge alone."]],"CL_BA94_07:GA-03":[["[Mutating] Content is internally divided: empirical content is excluded from the pure science, while intuitively supplied matter remains indispensable to the objective use of pure concepts.","Content is internally divided: empirical content is excluded from the pure science, while intuitively supplied matter remains indispensable to the objective use of pure concepts."]],"CL_BA94_07:GA-04":[["[Persistent] Transcendentality concerns the a priori possibility, scope, and object-directed use of cognition rather than the mere a priori origin of a representation.","Transcendentality concerns the a priori possibility, scope, and object-directed use of cognition rather than the mere a priori origin of a representation."]],"CL_BA94_07:GA-05":[["[Emergent] Analytic and dialectic distinguish legitimate and illegitimate uses of cognitive principles rather than separate inventories of propositions or faculties.","Analytic and dialectic distinguish legitimate and illegitimate uses of cognitive principles rather than separate inventories of propositions or faculties."]],"CL_BA94_07:GA-06":[["[Attractor] The canon–organon distinction governs the system: a rule may regulate already given cognition without authorizing the production of objects or objective knowledge.","The canon–organon distinction governs the system: a rule may regulate already given cognition without authorizing the production of objects or objective knowledge."]],"CL_BA94_07:GA-07":[["[Mutating] Dialectic is the critique of illusion generated when valid formal or transcendental conditions are detached from the conditions of their application.","Dialectic is the critique of illusion generated when valid formal or transcendental conditions are detached from the conditions of their application."]],"CL_BA94_07:GA-08":[["[Persistent] Possible experience is the functional boundary at which pure thought can retain objective validity and beyond which it becomes empty or hyperphysical.","Possible experience is the functional boundary at which pure thought can retain objective validity and beyond which it becomes empty or hyperphysical."]],"CL_BA94_07:GA-09":[["[Terminal] Critique culminates in policing the legitimacy, scope, and limits of pure principles rather than extending cognition through them.","Critique culminates in policing the legitimacy, scope, and limits of pure principles rather than extending cognition through them."]],"CL_BA94_07:GA-10":[["[Attractor] Truth remains defined through cognition’s accordance with objects, while no universal positive criterion can certify that accordance.","Truth remains defined through cognition’s accordance with objects, while no universal positive criterion can certify that accordance."]],"CL_BA94_07:RMD-01":[["[Stable Identity] Formal logic retains its role as the universal examination of relations among cognitions, but its universality remains inseparable from its formal limitation.","Formal logic retains its role as the universal examination of relations among cognitions, but its universality remains inseparable from its formal limitation."]],"CL_BA94_07:RMD-02":[["[Mutation] Content changes from what general logic brackets to what transcendental inquiry must distinguish between excluded empirical material and required intuitive matter.","Content changes from what general logic brackets to what transcendental inquiry must distinguish between excluded empirical material and required intuitive matter."]],"CL_BA94_07:RMD-03":[["[Displacement] Object-relation moves from the factor abstracted by general logic to the criterion of transcendental validity and finally to intuition-conditioned objective cognition.","Object-relation moves from the factor abstracted by general logic to the criterion of transcendental validity and finally to intuition-conditioned objective cognition."]],"CL_BA94_07:RMD-04":[["[Reversal] Dialectic changes from the appearance of formal knowledge-production into a critical name for the misuse of formal and transcendental principles.","Dialectic changes from the appearance of formal knowledge-production into a critical name for the misuse of formal and transcendental principles."]],"CL_BA94_07:RMD-05":[["[Escalation] The distinction between universal and sensible application expands into the boundary between possible experience and hyperphysical object-claims.","The distinction between universal and sensible application expands into the boundary between possible experience and hyperphysical object-claims."]],"CL_BA94_07:RMD-06":[["[Absorption] Inquiry into cognitive origin is retained only after being subordinated to the broader question of how pure cognition acquires valid object-reference.","Inquiry into cognitive origin is retained only after being subordinated to the broader question of how pure cognition acquires valid object-reference."]],"CL_BA94_07:RMD-07":[["[Terminal Transformation] A logic of truth survives only as a conditional analytic of possible object-cognition, not as an unrestricted truth-producing discipline.","A logic of truth survives only as a conditional analytic of possible object-cognition, not as an unrestricted truth-producing discipline."]],"CL_BA94_07:CGD-01":[["[Local] The case of space applied universally or only to objects of sense remains a local demonstration of scope-sensitive transcendental status.","The case of space applied universally or only to objects of sense remains a local demonstration of scope-sensitive transcendental status."]],"CL_BA94_07:CGD-02":[["[Local] The distinction between pure and empirical thought remains a local taxonomy until it is converted into the current-level distinction between pure conditions and empirical object-givenness.","The distinction between pure and empirical thought remains a local taxonomy until it is converted into the current-level distinction between pure conditions and empirical object-givenness."]],"CL_BA94_07:CGD-03":[["[Scales] The difference between formal consistency and objective validity becomes global because it governs both general logic and transcendental analytic.","The difference between formal consistency and objective validity becomes global because it governs both general logic and transcendental analytic."]],"CL_BA94_07:CGD-04":[["[Bridge] Object-reference links the inquiry into transcendental use with the requirement that objects be given in intuition.","Object-reference links the inquiry into transcendental use with the requirement that objects be given in intuition."]],"CL_BA94_07:CGD-05":[["[Catalyst] The canon–organon distinction drives the transition from legitimate logical testing to the diagnosis of dialectical illusion.","The canon–organon distinction drives the transition from legitimate logical testing to the diagnosis of dialectical illusion."]],"CL_BA94_07:CGD-06":[["[Recoded] Cognitive origin no longer functions as a sufficient ground of transcendental status but as one condition requiring validation through scope and use.","Cognitive origin no longer functions as a sufficient ground of transcendental status but as one condition requiring validation through scope and use."]],"CL_BA94_07:CGD-07":[["[Superseded] A logic of truth understood as an unqualified source of truth is superseded by a bounded analytic whose validity depends on possible object-reference.","A logic of truth understood as an unqualified source of truth is superseded by a bounded analytic whose validity depends on possible object-reference."]],"CL_BA94_08:GA-01":[["[Persistent] Completeness is architectonic rather than the result of accumulated instances.","Completeness is architectonic rather than the result of accumulated instances."]],"CL_BA94_08:GA-02":[["[Persistent] Pure understanding is a self-sufficient source of the forms under investigation.","Pure understanding is a self-sufficient source of the forms under investigation."]],"CL_BA94_08:GA-03":[["[Mutating] The object of analysis shifts from given conceptual contents to the faculty and principle that generate them.","The object of analysis shifts from given conceptual contents to the faculty and principle that generate them."]],"CL_BA94_08:GA-04":[["[Persistent] The relevant conceptions must be pure, intellectual, and elementary rather than empirical or compound.","The relevant conceptions must be pure, intellectual, and elementary rather than empirical or compound."]],"CL_BA94_08:GA-05":[["[Emergent] The governing connection both assigns each conception its proper place and determines the system’s completeness.","The governing connection both assigns each conception its proper place and determines the system’s completeness."]],"CL_BA94_08:GA-06":[["[Mutating] Experience is recoded from possible origin into activating occasion, after which understanding removes empirical conditions.","Experience is recoded from possible origin into activating occasion, after which understanding removes empirical conditions."]],"CL_BA94_08:GA-07":[["[Emergent] The systematic whole functions as a reciprocal criterion for the legitimacy of its parts.","The systematic whole functions as a reciprocal criterion for the legitimacy of its parts."]],"CL_BA94_08:GA-08":[["[Persistent] Similarity, quantity, and graded complexity cannot supply necessary systematic connection.","Similarity, quantity, and graded complexity cannot supply necessary systematic connection."]],"CL_BA94_08:GA-09":[["[Attractor] Pure conceptions are organized as expressions of an underlying unity that precedes their complete exhibition.","Pure conceptions are organized as expressions of an underlying unity that precedes their complete exhibition."]],"CL_BA94_08:GA-10":[["[Terminal] Transcendental analysis culminates in an internally differentiated architecture of conceptions and principles.","Transcendental analysis culminates in an internally differentiated architecture of conceptions and principles."]],"CL_BA94_08:GA-11":[["[Mutating] Purity means abstraction from empirical conditions, not absolute separation from experiential activation.","Purity means abstraction from empirical conditions, not absolute separation from experiential activation."]],"CL_BA94_08:GA-12":[["[Attractor] The system seeks closure without admitting an unassimilated remainder within pure understanding.","The system seeks closure without admitting an unassimilated remainder within pure understanding."]],"CL_BA94_08:RMD-01":[["[Persistence] Totality recurs first as the condition of completeness and then as the principle that orders the complete field.","Totality recurs first as the condition of completeness and then as the principle that orders the complete field."]],"CL_BA94_08:RMD-02":[["[Mutation] Autonomy migrates from a property of pure understanding into an operation by which understanding generates, develops, and purifies conceptions.","Autonomy migrates from a property of pure understanding into an operation by which understanding generates, develops, and purifies conceptions."]],"CL_BA94_08:RMD-03":[["[Reversal] The exclusion of the empirical as origin becomes a qualified inclusion of experience as an activating occasion.","The exclusion of the empirical as origin becomes a qualified inclusion of experience as an activating occasion."]],"CL_BA94_08:RMD-04":[["[Mutation] Classification changes from inventory-making into derivational placement within a necessary order.","Classification changes from inventory-making into derivational placement within a necessary order."]],"CL_BA94_08:RMD-05":[["[Displacement] Elementarity is absorbed into a developmental account in which conceptual germs become explicit through activation and purification.","Elementarity is absorbed into a developmental account in which conceptual germs become explicit through activation and purification."]],"CL_BA94_08:RMD-06":[["[Escalation] Systematic completeness shifts from a criterion used to test cognitions into an effect generated by the governing principle itself.","Systematic completeness shifts from a criterion used to test cognitions into an effect generated by the governing principle itself."]],"CL_BA94_08:RMD-07":[["[Absorption] The local division between conceptions and principles is absorbed into the larger relation between source, ordering rule, and complete system.","The local division between conceptions and principles is absorbed into the larger relation between source, ordering rule, and complete system."]],"CL_BA94_08:RMD-08":[["[Terminal Transformation] Mechanical discovery is not merely rejected; it is replaced by principled derivation as the only route to closure.","Mechanical discovery is not merely rejected; it is replaced by principled derivation as the only route to closure."]],"CL_BA94_08:ALT-B01":[["[Surface] The explicit problem is the determination of pure, elementary conceptions and their complete order.","The explicit problem is the determination of pure, elementary conceptions and their complete order."]],"CL_BA94_08:ALT-B02":[["[Structural] The operative mechanism is the relation among faculty, empirical occasion, governing principle, systematic placement, and whole-to-part validation.","The operative mechanism is the relation among faculty, empirical occasion, governing principle, systematic placement, and whole-to-part validation."]],"CL_BA94_08:ALT-B03":[["[Metastrategic] The system claims methodological authority by replacing contingent collection with principled derivation.","The system claims methodological authority by replacing contingent collection with principled derivation."]],"CL_BA94_08:ALT-B04":[["[Ontological / Temporal] Pure understanding is treated as an autonomous unity whose forms are temporally activated and purified through experience.","Pure understanding is treated as an autonomous unity whose forms are temporally activated and purified through experience."]],"CL_BA94_08:ALT-B05":[["[Methodological / Performative] The text performs closure by repeatedly excluding alternatives until systematic totality appears as the only admissible ground.","The text performs closure by repeatedly excluding alternatives until systematic totality appears as the only admissible ground."]],"CL_BA94_09:GA-01":[["[Persistent] Human understanding is non-sensuous, non-intuitive, and therefore discursive.","Human understanding is non-sensuous, non-intuitive, and therefore discursive."]],"CL_BA94_09:GA-02":[["[Persistent] Receptivity supplies intuitions, while spontaneity supplies the conceptual activity required to think them.","Receptivity supplies intuitions, while spontaneity supplies the conceptual activity required to think them."]],"CL_BA94_09:GA-03":[["[Mutating] A concept is fundamentally a function that unifies diverse representations under a common representation.","A concept is fundamentally a function that unifies diverse representations under a common representation."]],"CL_BA94_09:GA-04":[["[Persistent] Concepts become cognitively operative only in judgments, to which all acts of the understanding are reducible.","Concepts become cognitively operative only in judgments, to which all acts of the understanding are reducible."]],"CL_BA94_09:GA-05":[["[Attractor] Object-directed cognition by the understanding is necessarily mediated through an organized representational order.","Object-directed cognition by the understanding is necessarily mediated through an organized representational order."]],"CL_BA94_09:GA-06":[["[Persistent] Judgmental form can be abstracted from content and exhaustively ordered through a finite table of functions.","Judgmental form can be abstracted from content and exhaustively ordered through a finite table of functions."]],"CL_BA94_09:GA-07":[["[Emergent] Formal-logical equivalence does not entail transcendental identity, because cognitively distinct functions may have the same inferential use.","Formal-logical equivalence does not entail transcendental identity, because cognitively distinct functions may have the same inferential use."]],"CL_BA94_09:GA-08":[["[Emergent] Cognition begins with synthesis rather than analysis and requires the ordered cooperation of sensibility, imagination, and understanding.","Cognition begins with synthesis rather than analysis and requires the ordered cooperation of sensibility, imagination, and understanding."]],"CL_BA94_09:GA-09":[["[Mutating] The unifying function exercised in judgment also supplies necessary unity to the manifold given in intuition.","The unifying function exercised in judgment also supplies necessary unity to the manifold given in intuition."]],"CL_BA94_09:GA-10":[["[Emergent] The complete inventory of original categories corresponds exactly to the complete inventory of logical judgment-functions.","The complete inventory of original categories corresponds exactly to the complete inventory of logical judgment-functions."]],"CL_BA94_09:GA-11":[["[Terminal] Categories apply to objects only as necessary functions for synthesizing an intuitive manifold into object-cognition.","Categories apply to objects only as necessary functions for synthesizing an intuitive manifold into object-cognition."]],"CL_BA94_09:GA-12":[["[Terminal] Primitive conceptual closure is compatible with indefinite regulated expansion through derivative predicables.","Primitive conceptual closure is compatible with indefinite regulated expansion through derivative predicables."]],"CL_BA94_09:GA-13":[["[Attractor] Cognitive completeness requires articulated exclusions as well as positive connections, while taxonomic exclusion protects the primitive inventory.","Cognitive completeness requires articulated exclusions as well as positive connections, while taxonomic exclusion protects the primitive inventory."]],"CL_BA94_09:GA-14":[["[Terminal] Formal conditions of coherent cognition cannot be converted into properties of things in themselves.","Formal conditions of coherent cognition cannot be converted into properties of things in themselves."]],"CL_BA94_09:GA-15":[["[Attractor] The table functions as an architectonic operator that inventories primitive concepts, regulates derivation, and organizes rational science.","The table functions as an architectonic operator that inventories primitive concepts, regulates derivation, and organizes rational science."]],"CL_BA94_09:ALT-B01":[["[Surface] The system defines understanding, classifies judgments, enumerates categories, and distinguishes original categories from derivative predicables.","The system defines understanding, classifies judgments, enumerates categories, and distinguishes original categories from derivative predicables."]],"CL_BA94_09:ALT-B02":[["[Structural] Cognition is produced by the ordered relay from sensible manifold through imaginative synthesis to conceptual and judgmental unity.","Cognition is produced by the ordered relay from sensible manifold through imaginative synthesis to conceptual and judgmental unity."]],"CL_BA94_09:ALT-B03":[["[Metastrategic] The system reframes transcendental inquiry as systematic derivation, regulated inclusion, and exclusion rather than introspection or inherited taxonomy.","The system reframes transcendental inquiry as systematic derivation, regulated inclusion, and exclusion rather than introspection or inherited taxonomy."]],"CL_BA94_09:ALT-B04":[["[Ontological / Temporal] Cognizable reality is conditioned by synthesis, while relational form distinguishes causal succession from reciprocal coexistence.","Cognizable reality is conditioned by synthesis, while relational form distinguishes causal succession from reciprocal coexistence."]],"CL_BA94_09:ALT-B05":[["[Methodological / Performative] The architecture performs its thesis by abstracting, classifying, redifferentiating, mapping, deriving, and excluding through the same formal operations it attributes to understanding.","The architecture performs its thesis by abstracting, classifying, redifferentiating, mapping, deriving, and excluding through the same formal operations it attributes to understanding."]],"CL_BA94_10:GA-01":[["[Persistent] Objective validity concerns a concept’s right to determine objects, not the historical, psychological, or empirical origin of its possession.","Objective validity concerns a concept’s right to determine objects, not the historical, psychological, or empirical origin of its possession."]],"CL_BA94_10:GA-02":[["[Mutating] Objectivity shifts from correspondence with an independently ready-made object to universally necessary conditions under which anything can count as an object of experience.","Objectivity shifts from correspondence with an independently ready-made object to universally necessary conditions under which anything can count as an object of experience."]],"CL_BA94_10:GA-03":[["[Emergent] An object of experience requires the cooperation of receptive givenness and spontaneous synthesis; neither sensibility nor understanding is sufficient alone.","An object of experience requires the cooperation of receptive givenness and spontaneous synthesis; neither sensibility nor understanding is sufficient alone."]],"CL_BA94_10:GA-04":[["[Persistent] Necessity and strict universality cannot be inferred from repetition, expectation, or observed regularity.","Necessity and strict universality cannot be inferred from repetition, expectation, or observed regularity."]],"CL_BA94_10:GA-05":[["[Emergent] Categories possess objective validity only insofar as they are constitutive conditions of possible experience and of the cognition of objects therein.","Categories possess objective validity only insofar as they are constitutive conditions of possible experience and of the cognition of objects therein."]],"CL_BA94_10:GA-06":[["[Mutating] The relation between representation and object becomes constitutive without becoming productive of existence: representation determines cognizability rather than creates being.","The relation between representation and object becomes constitutive without becoming productive of existence: representation determines cognizability rather than creates being."]],"CL_BA94_10:GA-07":[["[Attractor] Every represented conjunction presupposes a unity prior to categorical unity, making higher qualitative unity the regress-point of the architecture.","Every represented conjunction presupposes a unity prior to categorical unity, making higher qualitative unity the regress-point of the architecture."]],"CL_BA94_10:GA-08":[["[Terminal] The proof of categorial validity and the restriction of categories to possible experience are inseparable moments of one critical act.","The proof of categorial validity and the restriction of categories to possible experience are inseparable moments of one critical act."]],"CL_BA94_10:RMD-01":[["[Stable identity] The distinction between factual acquisition and juridical entitlement remains invariant and governs every later account of objective validity.","The distinction between factual acquisition and juridical entitlement remains invariant and governs every later account of objective validity."]],"CL_BA94_10:RMD-02":[["[Functional recurrence] Space and sensibility recur first as forms of givenness and then as the receptive pole whose manifold requires synthesis; their role shifts from contrastive example to material condition.","Space and sensibility recur first as forms of givenness and then as the receptive pole whose manifold requires synthesis; their role shifts from contrastive example to material condition."]],"CL_BA94_10:RMD-03":[["[Mutation] Categories shift from pure conditions of thought whose objective status is uncertain to conditions under which an intuition is cognized as an object.","Categories shift from pure conditions of thought whose objective status is uncertain to conditions under which an intuition is cognized as an object."]],"CL_BA94_10:RMD-04":[["[Absorption] Causality begins as the exemplary problem of necessary connection and is absorbed into the more general requirement that all objective synthesis carry non-empirical necessity.","Causality begins as the exemplary problem of necessary connection and is absorbed into the more general requirement that all objective synthesis carry non-empirical necessity."]],"CL_BA94_10:RMD-05":[["[Reversal] Representation ceases to be merely an effect of objects and becomes a condition under which objects are available as objects of cognition.","Representation ceases to be merely an effect of objects and becomes a condition under which objects are available as objects of cognition."]],"CL_BA94_10:RMD-06":[["[Escalation] Conjunction shifts from a local operation of combining representations into the condition of categorical unity, forcing an ascent to a unity that precedes conjunction itself.","Conjunction shifts from a local operation of combining representations into the condition of categorical unity, forcing an ascent to a unity that precedes conjunction itself."]],"CL_BA94_10:RMD-07":[["[Terminal transformation] Higher qualitative unity remains functionally indispensable while its content and operation remain underdetermined.","Higher qualitative unity remains functionally indispensable while its content and operation remain underdetermined."]],"CL_BA94_10:CGD-01":[["[Local residue] The contrast between observed succession and necessary causation remains a local diagnostic case; at cluster scale it survives as evidence that objectivity cannot be grounded in induction.","The contrast between observed succession and necessary causation remains a local diagnostic case; at cluster scale it survives as evidence that objectivity cannot be grounded in induction."]],"CL_BA94_10:CGD-02":[["[Local contrast] The secure applicability of space and time to appearances remains a contrastive model and cannot itself justify the categories.","The secure applicability of space and time to appearances remains a contrastive model and cannot itself justify the categories."]],"CL_BA94_10:CGD-03":[["[Scales upward] The distinction between empirical origin and transcendental right becomes the governing criterion for all claims concerning necessity, objectivity, and cognition.","The distinction between empirical origin and transcendental right becomes the governing criterion for all claims concerning necessity, objectivity, and cognition."]],"CL_BA94_10:CGD-04":[["[Bridge] Sensibility and understanding become complementary conditions of experience: one gives manifold content while the other makes that content objectively thinkable.","Sensibility and understanding become complementary conditions of experience: one gives manifold content while the other makes that content objectively thinkable."]],"CL_BA94_10:CGD-05":[["[Catalyst] The claim that conjunction is not sensibly given converts the deduction from a problem of applying finished concepts into a problem of the synthesis that first makes objects representable.","The claim that conjunction is not sensibly given converts the deduction from a problem of applying finished concepts into a problem of the synthesis that first makes objects representable."]],"CL_BA94_10:CGD-06":[["[Recoded] Logical functions of judgment no longer function as a self-sufficient ground; they become downstream expressions of a prior synthetic and qualitative unity.","Logical functions of judgment no longer function as a self-sufficient ground; they become downstream expressions of a prior synthetic and qualitative unity."]],"CL_BA94_10:ALT-B01":[["[Surface] Pure concepts, especially causality, require justification for their necessary application to objects.","Pure concepts, especially causality, require justification for their necessary application to objects."]],"CL_BA94_10:ALT-B02":[["[Structural] Sensibility supplies manifold givenness while understanding supplies synthesis, and their conjunction produces objects of experience.","Sensibility supplies manifold givenness while understanding supplies synthesis, and their conjunction produces objects of experience."]],"CL_BA94_10:ALT-B03":[["[Metastrategic] Transcendental deduction displaces empirical explanation with an inquiry into enabling conditions and thereby avoids both dogmatic excess and sceptical withdrawal.","Transcendental deduction displaces empirical explanation with an inquiry into enabling conditions and thereby avoids both dogmatic excess and sceptical withdrawal."]],"CL_BA94_10:ALT-B04":[["[Ontological / Temporal] Objective temporal connection requires necessary synthesis rather than the mere succession of events, while objecthood remains restricted to phenomenal experience.","Objective temporal connection requires necessary synthesis rather than the mere succession of events, while objecthood remains restricted to phenomenal experience."]],"CL_BA94_10:ALT-B05":[["[Methodological / Performative] The argument performs its own regress by repeatedly displacing apparent foundations—empirical origin, sensation, analysis, category—toward a higher unity.","The argument performs its own regress by repeatedly displacing apparent foundations—empirical origin, sensation, analysis, category—toward a higher unity."]],"CL_BA94_11:GA-01":[["[Persistent] Representations belong to a subject only insofar as they are synthesizable within one self-consciousness.","Representations belong to a subject only insofar as they are synthesizable within one self-consciousness."]],"CL_BA94_11:GA-02":[["[Persistent] Analytical identity of consciousness presupposes a prior synthetical unity rather than generating that unity independently.","Analytical identity of consciousness presupposes a prior synthetical unity rather than generating that unity independently."]],"CL_BA94_11:GA-03":[["[Mutating] The “I think” begins as the formal condition of subjective ownership and becomes the condition through which manifold intuition can be related to an object.","The “I think” begins as the formal condition of subjective ownership and becomes the condition through which manifold intuition can be related to an object."]],"CL_BA94_11:GA-04":[["[Emergent] Objectivity is constituted by the necessary unification of a manifold in consciousness rather than received from a merely given manifold.","Objectivity is constituted by the necessary unification of a manifold in consciousness rather than received from a merely given manifold."]],"CL_BA94_11:GA-05":[["[Persistent] Understanding is the faculty that actively conjoins representations a priori under the unity of apperception.","Understanding is the faculty that actively conjoins representations a priori under the unity of apperception."]],"CL_BA94_11:GA-06":[["[Mutating] Empirical unity is derivative, contingent, and association-governed, whereas transcendental unity is the a priori condition of its possible synthesis.","Empirical unity is derivative, contingent, and association-governed, whereas transcendental unity is the a priori condition of its possible synthesis."]],"CL_BA94_11:GA-07":[["[Terminal] The highest principle of understanding is supreme only for a discursive human intellect that thinks but does not intuit its objects.","The highest principle of understanding is supreme only for a discursive human intellect that thinks but does not intuit its objects."]],"CL_BA94_11:GA-08":[["[Persistent] Apperception supplies formal unity but no manifold content; cognition therefore requires irreducible cooperation between receptivity and spontaneity.","Apperception supplies formal unity but no manifold content; cognition therefore requires irreducible cooperation between receptivity and spontaneity."]],"CL_BA94_11:GA-09":[["[Attractor] Synthesis is the generative operation through which selfhood, conceptuality, objecthood, cognition, and objective validity become mutually conditioned.","Synthesis is the generative operation through which selfhood, conceptuality, objecthood, cognition, and objective validity become mutually conditioned."]],"CL_BA94_12:GA-01":[["[Persistent] Objective cognition requires a synthesis that brings representations under the unity of apperception rather than merely recording their association.","Objective cognition requires a synthesis that brings representations under the unity of apperception rather than merely recording their association."]],"CL_BA94_12:GA-02":[["[Persistent] Objective validity concerns the form of necessary unification, not the empirical necessity or repeated co-occurrence of represented content.","Objective validity concerns the form of necessary unification, not the empirical necessity or repeated co-occurrence of represented content."]],"CL_BA94_12:GA-03":[["[Mutating] Judgment is first the objective unification of cognitions and then the logical operation through which an intuitive manifold is synthetically determined.","Judgment is first the objective unification of cognitions and then the logical operation through which an intuitive manifold is synthetically determined."]],"CL_BA94_12:GA-04":[["[Emergent] Categories are logical functions of judgment insofar as those functions organize the manifold required for unified consciousness.","Categories are logical functions of judgment insofar as those functions organize the manifold required for unified consciousness."]],"CL_BA94_12:GA-05":[["[Persistent] Objectual unity is neither contained in sensuous givenness nor produced by subjective imagination; it arises through understanding’s synthesis of a given manifold.","Objectual unity is neither contained in sensuous givenness nor produced by subjective imagination; it arises through understanding’s synthesis of a given manifold."]],"CL_BA94_12:GA-06":[["[Attractor] Apperception is the common condition through which judgment, categorical determination, represented objects, and empirical consciousness become mutually articulable.","Apperception is the common condition through which judgment, categorical determination, represented objects, and empirical consciousness become mutually articulable."]],"CL_BA94_12:GA-07":[["[Mutating] Categories originate independently of sensibility but possess objective applicability only through their necessary operation upon sensibly given manifolds.","Categories originate independently of sensibility but possess objective applicability only through their necessary operation upon sensibly given manifolds."]],"CL_BA94_12:GA-08":[["[Terminal] Human cognition is finite and discursive because understanding connects and arranges intuition supplied from elsewhere rather than intuiting or generating objects directly.","Human cognition is finite and discursive because understanding connects and arranges intuition supplied from elsewhere rather than intuiting or generating objects directly."]],"CL_BA94_12:GA-09":[["[Terminal] The deduction establishes conditions of validity without deriving why cognition possesses precisely its given inventory of logical functions, categories, and forms of intuition.","The deduction establishes conditions of validity without deriving why cognition possesses precisely its given inventory of logical functions, categories, and forms of intuition."]],"CL_BA94_13:GA-01":[["[Persistent] Cognition arises only where conceptual determination and intuition jointly determine an object.","Cognition arises only where conceptual determination and intuition jointly determine an object."]],"CL_BA94_13:GA-02":[["[Mutating] Categories are empty thought-forms apart from intuition but become conditions of objective experience when they govern empirical synthesis.","Categories are empty thought-forms apart from intuition but become conditions of objective experience when they govern empirical synthesis."]],"CL_BA94_13:GA-03":[["[Emergent] Productive imagination is the operative mediator that translates the unity of apperception into a categorial determination of sensibility.","Productive imagination is the operative mediator that translates the unity of apperception into a categorial determination of sensibility."]],"CL_BA94_13:GA-04":[["[Persistent] Human intuition is sensuous, spatial-temporal, and therefore incapable of giving either external objects or the self as they are in themselves.","Human intuition is sensuous, spatial-temporal, and therefore incapable of giving either external objects or the self as they are in themselves."]],"CL_BA94_13:GA-05":[["[Emergent] Perception is not primitive givenness but the synthesis of a sensible manifold under the same unity of consciousness expressed through categories.","Perception is not primitive givenness but the synthesis of a sensible manifold under the same unity of consciousness expressed through categories."]],"CL_BA94_13:GA-06":[["[Attractor] Objectivity consists in lawful synthesis of appearances rather than correspondence with independently cognized things in themselves.","Objectivity consists in lawful synthesis of appearances rather than correspondence with independently cognized things in themselves."]],"CL_BA94_13:GA-07":[["[Terminal] Categories legislate only the universal form of lawful nature, while experience alone determines particular empirical laws.","Categories legislate only the universal form of lawful nature, while experience alone determines particular empirical laws."]],"CL_BA94_13:GA-08":[["[Persistent] Formal thought can exceed experience, but legitimate cognition cannot exceed the conditions under which intuition gives an object.","Formal thought can exceed experience, but legitimate cognition cannot exceed the conditions under which intuition gives an object."]],"CL_BA94_13:GA-09":[["[Mutating] The subject is spontaneous as determining intellect but receptive as self-intuited appearance, so self-relation is structurally asymmetric.","The subject is spontaneous as determining intellect but receptive as self-intuited appearance, so self-relation is structurally asymmetric."]],"CL_BA94_13:GA-10":[["[Terminal] Things in themselves remain limiting correlates of phenomenal cognition rather than objects whose constitution can ground or complete experience.","Things in themselves remain limiting correlates of phenomenal cognition rather than objects whose constitution can ground or complete experience."]],"CL_BA94_14:GA-01":[["[Persistent] Objective cognition requires more than conceptual thought: it requires the relation of concepts to intuition and possible object-givenness.","Objective cognition requires more than conceptual thought: it requires the relation of concepts to intuition and possible object-givenness."]],"CL_BA94_14:GA-02":[["[Persistent] Human cognition is objectively valid only within possible experience because human intuition is sensuous.","Human cognition is objectively valid only within possible experience because human intuition is sensuous."]],"CL_BA94_14:GA-03":[["[Persistent] Categories are a priori conditions of the possibility of experience rather than empirical products or contingent subjective dispositions.","Categories are a priori conditions of the possibility of experience rather than empirical products or contingent subjective dispositions."]],"CL_BA94_14:GA-04":[["[Mutating] Necessity secures objectivity only when it governs the conditions of possible experience rather than merely formal inference or subjective compulsion.","Necessity secures objectivity only when it governs the conditions of possible experience rather than merely formal inference or subjective compulsion."]],"CL_BA94_14:GA-05":[["[Emergent] Validity is an application-relation among pure concept, judgment, and phenomenon, not an intrinsic property of concepts or faculties considered separately.","Validity is an application-relation among pure concept, judgment, and phenomenon, not an intrinsic property of concepts or faculties considered separately."]],"CL_BA94_14:GA-06":[["[Mutating] Judgment is irreducible in ordinary subsumption but receives restricted transcendental direction through conditions governing pure conceptual employment.","Judgment is irreducible in ordinary subsumption but receives restricted transcendental direction through conditions governing pure conceptual employment."]],"CL_BA94_14:GA-07":[["[Persistent] The synthetic unity of apperception, together with space and time, provides the formal ground linking categories to experienced objects.","The synthetic unity of apperception, together with space and time, provides the formal ground linking categories to experienced objects."]],"CL_BA94_14:GA-08":[["[Terminal] Reason loses objective authority when it seeks to cognize objects beyond possible experience, becoming dialectical rather than analytic.","Reason loses objective authority when it seeks to cognize objects beyond possible experience, becoming dialectical rather than analytic."]],"CL_BA94_14:GA-09":[["[Attractor] Possible experience functions as the jurisdictional boundary that sorts legitimate a priori cognition from illusion.","Possible experience functions as the jurisdictional boundary that sorts legitimate a priori cognition from illusion."]],"CL_BA94_14:GA-10":[["[Attractor] Critique secures pure cognition negatively by regulating and preventing misuse rather than positively enlarging a stock of pure knowledge.","Critique secures pure cognition negatively by regulating and preventing misuse rather than positively enlarging a stock of pure knowledge."]],"CL_BA94_15:GA-01":[["[Persistent] Objective categorical cognition requires rule-governed temporal specification; categories without schemata do not determine objects.","Objective categorical cognition requires rule-governed temporal specification; categories without schemata do not determine objects."]],"CL_BA94_15:GA-02":[["[Persistent] The principles of pure understanding derive their systematic order from categories as applied to possible experience under sensible conditions.","The principles of pure understanding derive their systematic order from categories as applied to possible experience under sensible conditions."]],"CL_BA94_15:GA-03":[["[Mutating] Objective validity is established reflexively through conditions of possible cognition rather than by deduction from a higher object-level proposition.","Objective validity is established reflexively through conditions of possible cognition rather than by deduction from a higher object-level proposition."]],"CL_BA94_15:GA-04":[["[Persistent] Noncontradiction is universally necessary for judgment but is insufficient to establish truth, correspondence, or grounds.","Noncontradiction is universally necessary for judgment but is insufficient to establish truth, correspondence, or grounds."]],"CL_BA94_15:GA-05":[["[Mutating] The analytical–synthetic distinction distributes logical power unequally: contradiction recognizes analytical truth but only constrains synthetic judgment.","The analytical–synthetic distinction distributes logical power unequally: contradiction recognizes analytical truth but only constrains synthetic judgment."]],"CL_BA94_15:GA-06":[["[Mutating] Time is the universal medium of categorical applicability but cannot serve as the defining condition of logical contradiction.","Time is the universal medium of categorical applicability but cannot serve as the defining condition of logical contradiction."]],"CL_BA94_15:GA-07":[["[Attractor] Possible experience is both the field that realizes categories and the boundary that prevents their objective extension beyond appearances.","Possible experience is both the field that realizes categories and the boundary that prevents their objective extension beyond appearances."]],"CL_BA94_15:GA-08":[["[Terminal] Categories retain logical function when abstracted from sensibility, but their objective significance terminates with the loss of sensible givenness.","Categories retain logical function when abstracted from sensibility, but their objective significance terminates with the loss of sensible givenness."]],"CL_BA94_15:GA-09":[["[Emergent] Systematic completeness depends on maintaining functional distinctions among sensibility, intuition, understanding, and formal logic.","Systematic completeness depends on maintaining functional distinctions among sensibility, intuition, understanding, and formal logic."]],"CL_BA94_15:ALT-B01":[["[Surface] The explicit problem is how categories, principles, and the principle of contradiction can legitimately govern judgments about objects.","The explicit problem is how categories, principles, and the principle of contradiction can legitimately govern judgments about objects."]],"CL_BA94_15:ALT-B02":[["[Structural] Cognition is organized through temporal schematization, categorical synthesis, faculty differentiation, and graded logical constraint.","Cognition is organized through temporal schematization, categorical synthesis, faculty differentiation, and graded logical constraint."]],"CL_BA94_15:ALT-B03":[["[Metastrategic] The system replaces appeals to self-evident foundations with an analysis of the conditions under which object-cognition is possible.","The system replaces appeals to self-evident foundations with an analysis of the conditions under which object-cognition is possible."]],"CL_BA94_15:ALT-B04":[["[Ontological / Temporal] Objects are cognizable only as temporally conditioned appearances, while temporal alteration itself does not constitute logical contradiction.","Objects are cognizable only as temporally conditioned appearances, while temporal alteration itself does not constitute logical contradiction."]],"CL_BA94_15:ALT-B05":[["[Methodological / Performative] The system performs its thesis by repeatedly generating validity through differentiation, restriction, and recursive return to conditions of use.","The system performs its thesis by repeatedly generating validity through differentiation, restriction, and recursive return to conditions of use."]],"CL_BA94_16:GA-01":[["[Persistent] Synthetic a priori principles possess objective validity only by expressing conditions under which possible experience and its objects are possible.","Synthetic a priori principles possess objective validity only by expressing conditions under which possible experience and its objects are possible."]],"CL_BA94_16:GA-02":[["[Persistent] Objective cognition requires sensible givenness together with a priori intuition, synthesis, and conceptual unity.","Objective cognition requires sensible givenness together with a priori intuition, synthesis, and conceptual unity."]],"CL_BA94_16:GA-03":[["[Mutating] The unification first assigned to imagination and apperception becomes operationally specified as schematic subsumption under concepts.","The unification first assigned to imagination and apperception becomes operationally specified as schematic subsumption under concepts."]],"CL_BA94_16:GA-04":[["[Persistent] Objectivity consists in necessary conformity to rules through which appearances can be synthesized into cognizable objects.","Objectivity consists in necessary conformity to rules through which appearances can be synthesized into cognizable objects."]],"CL_BA94_16:GA-05":[["[Emergent] The category table functions as a generator of the complete principial forms through which pure understanding can govern experience.","The category table functions as a generator of the complete principial forms through which pure understanding can govern experience."]],"CL_BA94_16:GA-06":[["[Emergent] Categorical synthesis divides into mathematical determination of intuition and dynamical connection of phenomenal existence.","Categorical synthesis divides into mathematical determination of intuition and dynamical connection of phenomenal existence."]],"CL_BA94_16:GA-07":[["[Emergent] Every phenomenon is quantitatively determined through extensive intuition and intensive sensible reality.","Every phenomenon is quantitatively determined through extensive intuition and intensive sensible reality."]],"CL_BA94_16:GA-08":[["[Persistent] A priori cognition determines invariant experiential form but cannot anticipate the qualitative content supplied by sensation.","A priori cognition determines invariant experiential form but cannot anticipate the qualitative content supplied by sensation."]],"CL_BA94_16:GA-09":[["[Mutating] A priori origin does not enlarge legitimate cognitive range; it intensifies the obligation to restrict application to experiential conditions.","A priori origin does not enlarge legitimate cognitive range; it intensifies the obligation to restrict application to experiential conditions."]],"CL_BA94_16:GA-10":[["[Attractor] Possible experience is simultaneously the ground of objective validity, the field of principial determination, and the limit of human objective cognition.","Possible experience is simultaneously the ground of objective validity, the field of principial determination, and the limit of human objective cognition."]],"CL_BA94_16:GA-11":[["[Mutating] Noumenon divides into a negative non-sensible limit-concept and a positive object requiring intellectual intuition.","Noumenon divides into a negative non-sensible limit-concept and a positive object requiring intellectual intuition."]],"CL_BA94_16:GA-12":[["[Terminal] Only the negative noumenon survives critical examination, and it bounds sensible cognition without supplying positive supersensible knowledge.","Only the negative noumenon survives critical examination, and it bounds sensible cognition without supplying positive supersensible knowledge."]],"CL_BA94_16:GA-13":[["[Terminal] Critical restriction secures empirical validity without converting the conditions of human cognition into conditions of every possible reality.","Critical restriction secures empirical validity without converting the conditions of human cognition into conditions of every possible reality."]],"CL_BA94_17:GA-01":[["[Persistent] Objective validity requires representations to be assigned to their cognitive sources and connected with corresponding sensible conditions.","Objective validity requires representations to be assigned to their cognitive sources and connected with corresponding sensible conditions."]],"CL_BA94_17:GA-02":[["[Persistent] Sensibility and understanding are irreducible faculties whose cooperation, not reduction to either faculty, generates cognition.","Sensibility and understanding are irreducible faculties whose cooperation, not reduction to either faculty, generates cognition."]],"CL_BA94_17:GA-03":[["[Attractor] Possible experience is the sole positive domain in which objects, categories, and principles can acquire cognitive validity.","Possible experience is the sole positive domain in which objects, categories, and principles can acquire cognitive validity."]],"CL_BA94_17:GA-04":[["[Emergent] Objectivity arises neither from perception alone nor from pure conception, but from necessary rule-governed synthesis in one consciousness.","Objectivity arises neither from perception alone nor from pure conception, but from necessary rule-governed synthesis in one consciousness."]],"CL_BA94_17:GA-05":[["[Persistent] Space and time condition sensible presentation, while categories apply objectively only through intuition and temporal schemata.","Space and time condition sensible presentation, while categories apply objectively only through intuition and temporal schemata."]],"CL_BA94_17:GA-06":[["[Emergent] Because time is not perceived, phenomenal existence receives temporal determination only through permanence, succession, and coexistence.","Because time is not perceived, phenomenal existence receives temporal determination only through permanence, succession, and coexistence."]],"CL_BA94_17:GA-07":[["[Mutating] Substance, causality, and community cease to determine supersensible being and become rules for organizing phenomenal duration, events, and coexistence.","Substance, causality, and community cease to determine supersensible being and become rules for organizing phenomenal duration, events, and coexistence."]],"CL_BA94_17:GA-08":[["[Mutating] Modality determines a conception’s relation to experiential procedures: possibility through formal conformity, reality through perception, and necessity through causal law.","Modality determines a conception’s relation to experiential procedures: possibility through formal conformity, reality through perception, and necessity through causal law."]],"CL_BA94_17:GA-09":[["[Emergent] Empirically determinate subjectivity depends on external spatial permanence because internal sense supplies no permanent intuition.","Empirically determinate subjectivity depends on external spatial permanence because internal sense supplies no permanent intuition."]],"CL_BA94_17:GA-10":[["[Persistent] A priori principles determine the form of experiential connection while leaving particular existents, powers, and states empirically open.","A priori principles determine the form of experiential connection while leaving particular existents, powers, and states empirically open."]],"CL_BA94_17:GA-11":[["[Terminal] The same experiential conditions that legitimate pure principles prevent their conversion into a transcendent ontology.","The same experiential conditions that legitimate pure principles prevent their conversion into a transcendent ontology."]],"CL_BA94_17:GA-12":[["[Attractor] The noumenal remainder preserves the non-exhaustiveness of sensibility while withholding every usable criterion of supersensible cognition or modality.","The noumenal remainder preserves the non-exhaustiveness of sensibility while withholding every usable criterion of supersensible cognition or modality."]],"CL_BA94_17:GA-13":[["[Emergent] Nature is one law-governed experiential field whose necessity concerns conditioned phenomenal relations rather than absolute being.","Nature is one law-governed experiential field whose necessity concerns conditioned phenomenal relations rather than absolute being."]],"CL_BA94_17:RMD-01":[["[Stable identity] The distinction between sensibility and understanding retains its identity throughout and remains the non-reducible basis of cognition.","The distinction between sensibility and understanding retains its identity throughout and remains the non-reducible basis of cognition."]],"CL_BA94_17:RMD-02":[["[Functional recurrence] The distinction between logical and objective comparison recurs as the distinction between noncontradictory thought and objective possibility.","The distinction between logical and objective comparison recurs as the distinction between noncontradictory thought and objective possibility."]],"CL_BA94_17:RMD-03":[["[Mutation] Reflection expands from assigning comparison-concepts to faculties into a general demand that every principle establish its experiential provenance and scope.","Reflection expands from assigning comparison-concepts to faculties into a general demand that every principle establish its experiential provenance and scope."]],"CL_BA94_17:RMD-04":[["[Migration] Time moves from being a sensible form to becoming the unavailable medium whose determination requires phenomenal relations and external permanence.","Time moves from being a sensible form to becoming the unavailable medium whose determination requires phenomenal relations and external permanence."]],"CL_BA94_17:RMD-05":[["[Escalation] Necessity moves from what perception lacks, through the rule governing objective succession, to the modal status of a causally determined effect.","Necessity moves from what perception lacks, through the rule governing objective succession, to the modal status of a causally determined effect."]],"CL_BA94_17:RMD-06":[["[Mutation] Relation changes from a limit on cognizing absolute internality into the positive mechanism of reciprocal phenomenal community.","Relation changes from a limit on cognizing absolute internality into the positive mechanism of reciprocal phenomenal community."]],"CL_BA94_17:RMD-07":[["[Reversal] Externality changes from a merely phenomenal relational order into a constitutive condition of temporally determinate inner experience.","Externality changes from a merely phenomenal relational order into a constitutive condition of temporally determinate inner experience."]],"CL_BA94_17:RMD-08":[["[Absorption] The noumenon persists but is absorbed into the broader experiential boundary governing category use and modal judgment.","The noumenon persists but is absorbed into the broader experiential boundary governing category use and modal judgment."]],"CL_BA94_17:RMD-09":[["[Terminal transformation] The fourfold division of nothing ceases to govern the argument directly after differentiating contradiction, privation, empty intuition, and unsupported thought within the modal boundary.","The fourfold division of nothing ceases to govern the argument directly after differentiating contradiction, privation, empty intuition, and unsupported thought within the modal boundary."]],"CL_BA94_17:RMD-10":[["[Disappearance after structural work] The particular critique of Leibnitzian doctrines disappears once intellectualization is generalized into the prohibition against categories authenticating their own objective reference.","The particular critique of Leibnitzian doctrines disappears once intellectualization is generalized into the prohibition against categories authenticating their own objective reference."]],"CL_BA94_17:CGD-01":[["[Local] The four reflection-concepts remain a specific diagnostic apparatus; what scales upward is the requirement that objective claims be indexed to their cognitive source.","The four reflection-concepts remain a specific diagnostic apparatus; what scales upward is the requirement that objective claims be indexed to their cognitive source."]],"CL_BA94_17:CGD-02":[["[Superseded] Indiscernibility, monadology, predetermined harmony, and intellectualized space-time remain local targets absorbed into the higher-order diagnosis of faculty-confusion.","Indiscernibility, monadology, predetermined harmony, and intellectualized space-time remain local targets absorbed into the higher-order diagnosis of faculty-confusion."]],"CL_BA94_17:CGD-03":[["[Scales upward] The three analogies scale from temporal principles into the relational architecture required for one possible experience and one nature.","The three analogies scale from temporal principles into the relational architecture required for one possible experience and one nature."]],"CL_BA94_17:CGD-04":[["[Local] Conservation of the total quantum of phenomenal substance remains a compressed extension of permanence rather than a necessary cluster-level premise.","Conservation of the total quantum of phenomenal substance remains a compressed extension of permanence rather than a necessary cluster-level premise."]],"CL_BA94_17:CGD-05":[["[Bridge] Reciprocal temporal determination bridges coexistence and world-unity, while the stronger claim of complete dynamical reciprocity remains locally under-argued.","Reciprocal temporal determination bridges coexistence and world-unity, while the stronger claim of complete dynamical reciprocity remains locally under-argued."]],"CL_BA94_17:CGD-06":[["[Bridge] The modal postulates connect the temporal organization of nature with criteria for judging objects as possible, real, or necessary.","The modal postulates connect the temporal organization of nature with criteria for judging objects as possible, real, or necessary."]],"CL_BA94_17:CGD-07":[["[Catalyst] The refutation of problematic idealism catalyzes the transition from category dependence on intuition to the external constitution of empirical subjectivity.","The refutation of problematic idealism catalyzes the transition from category dependence on intuition to the external constitution of empirical subjectivity."]],"CL_BA94_17:CGD-08":[["[Recoded] The table of nothing survives at cluster level only as a discipline preventing contradiction, non-givenness, privation, and formal emptiness from collapsing into one modal status.","The table of nothing survives at cluster level only as a discipline preventing contradiction, non-givenness, privation, and formal emptiness from collapsing into one modal status."]],"CL_BA94_18:GA-01":[["[Persistent] Truth, error, and illusory appearance are assessed at the level of judgement, where subjective grounds can acquire objective status.","Truth, error, and illusory appearance are assessed at the level of judgement, where subjective grounds can acquire objective status."]],"CL_BA94_18:GA-02":[["[Persistent] Reason differs from understanding because it systematizes rules under principles without directly determining sensible objects.","Reason differs from understanding because it systematizes rules under principles without directly determining sensible objects."]],"CL_BA94_18:GA-03":[["[Attractor] The recursive search for conditions necessarily produces the demand for an unconditioned ground of cognitive completeness.","The recursive search for conditions necessarily produces the demand for an unconditioned ground of cognitive completeness."]],"CL_BA94_18:GA-04":[["[Mutating] Reason’s subjective law of systematic unity becomes transcendental illusion when treated as an objective law of things.","Reason’s subjective law of systematic unity becomes transcendental illusion when treated as an objective law of things."]],"CL_BA94_18:GA-05":[["[Persistent] Possible experience is the criterion limiting the objective use of principles and excluding transcendent cognition.","Possible experience is the criterion limiting the objective use of principles and excluding transcendent cognition."]],"CL_BA94_18:GA-06":[["[Emergent] Dialectic is the critical separation of regulative systematic unity from constitutive claims about objects beyond experience.","Dialectic is the critical separation of regulative systematic unity from constitutive claims about objects beyond experience."]],"CL_BA94_18:GA-07":[["[Terminal] Criticism cannot abolish transcendental illusion because the rational tendency generating it recurs after its invalidity is disclosed.","Criticism cannot abolish transcendental illusion because the rational tendency generating it recurs after its invalidity is disclosed."]],"CL_BA94_18:GA-08":[["[Persistent] Sectional designation supplies orientation but cannot provide the predicates, premises, or proof required for doctrine.","Sectional designation supplies orientation but cannot provide the predicates, premises, or proof required for doctrine."]],"CL_BA94_18:GA-09":[["[Attractor] The decisive error-form is the conversion of subjective cognitive necessity into objective necessity in things.","The decisive error-form is the conversion of subjective cognitive necessity into objective necessity in things."]],"CL_BA94_18:GA-10":[["[Mutating] The transition from logical ascent to an objectively given unconditioned totality is synthetic and therefore requires critical suspension.","The transition from logical ascent to an objectively given unconditioned totality is synthetic and therefore requires critical suspension."]],"CL_BA94_19:GA-01":[["[Persistent] Objective determination of objects depends upon conditions of possible experience and cannot be extended without qualification beyond that domain.","Objective determination of objects depends upon conditions of possible experience and cannot be extended without qualification beyond that domain."]],"CL_BA94_19:GA-02":[["[Persistent] Reason necessarily transforms conditioned cognition into a search for totality of grounds.","Reason necessarily transforms conditioned cognition into a search for totality of grounds."]],"CL_BA94_19:GA-03":[["[Attractor] The unconditioned is necessary as the horizon of totality but unavailable as an object of empirical presentation.","The unconditioned is necessary as the horizon of totality but unavailable as an object of empirical presentation."]],"CL_BA94_19:GA-04":[["[Mutating] Ideas arise through rational inference, become operative in practical freedom, and regulate the systematic use of understanding without becoming empirical objects.","Ideas arise through rational inference, become operative in practical freedom, and regulate the systematic use of understanding without becoming empirical objects."]],"CL_BA94_19:GA-05":[["[Persistent] The absence of a corresponding empirical object does not eliminate an idea’s reality, necessity, or legitimate function.","The absence of a corresponding empirical object does not eliminate an idea’s reality, necessity, or legitimate function."]],"CL_BA94_19:GA-06":[["[Emergent] Systematic unity is the legitimate theoretical surrogate for unavailable knowledge of the unconditioned.","Systematic unity is the legitimate theoretical surrogate for unavailable knowledge of the unconditioned."]],"CL_BA94_19:GA-07":[["[Mutating] Validity divides into empirical object-determination, practical normativity, and regulative systematization; none authorizes speculative hypostatization.","Validity divides into empirical object-determination, practical normativity, and regulative systematization; none authorizes speculative hypostatization."]],"CL_BA94_19:GA-08":[["[Terminal] Critique is the tribunal that preserves reason’s necessary excess while denying it unrestricted constitutive use.","Critique is the tribunal that preserves reason’s necessary excess while denying it unrestricted constitutive use."]],"CL_BA94_19:GA-09":[["[Attractor] The asymmetry between completed regress toward grounds and indefinitely open progress through consequences prevents rational totality from becoming a finished possession.","The asymmetry between completed regress toward grounds and indefinitely open progress through consequences prevents rational totality from becoming a finished possession."]],"CL_BA94_19:RLE-04":[["[Attractor] The unconditioned attracts every series of conditions while permanently withdrawing from empirical capture.","The unconditioned attracts every series of conditions while permanently withdrawing from empirical capture."]],"CL_BA94_19:FL-01":[["[Tension] Objective reality is tied to possible experience, yet cognition without a corresponding empirical object is asserted to possess practical reality.","Objective reality is tied to possible experience, yet cognition without a corresponding empirical object is asserted to possess practical reality."]],"CL_BA94_19:FL-02":[["[Tension] Practical ideas are said to become operative causes, but the basis on which an unpresentable cognition acquires such efficacy remains underdetermined.","Practical ideas are said to become operative causes, but the basis on which an unpresentable cognition acquires such efficacy remains underdetermined."]],"CL_BA94_19:FL-03":[["[Tension] The transition from the logical forms of syllogism to an exhaustive architecture of transcendental ideas is compressed rather than fully demonstrated.","The transition from the logical forms of syllogism to an exhaustive architecture of transcendental ideas is compressed rather than fully demonstrated."]],"CL_BA94_19:FL-04":[["[Tension] Regulative unity must guide specific systematization without covertly committing reason to the objective reality of what it regulates toward.","Regulative unity must guide specific systematization without covertly committing reason to the objective reality of what it regulates toward."]],"CL_BA94_19:MP-01":[["[Mutation] “Idea” changes function from a taxonomic designation to a practical archetype and then to a theoretically regulative concept.","“Idea” changes function from a taxonomic designation to a practical archetype and then to a theoretically regulative concept."]],"CL_BA94_19:MP-02":[["[Mutation] “Validity” changes from empirical objective reality to practical authority and finally to regulative legitimacy.","“Validity” changes from empirical objective reality to practical authority and finally to regulative legitimacy."]],"CL_BA94_20:GA-01":[["[Persistent] Reason necessarily ascends from conditioned cognition toward unconditioned unity.","Reason necessarily ascends from conditioned cognition toward unconditioned unity."]],"CL_BA94_20:GA-02":[["[Persistent] Objective cognition requires intuition governed by the conditions of possible experience.","Objective cognition requires intuition governed by the conditions of possible experience."]],"CL_BA94_20:GA-03":[["[Mutating] The triad of self, world, and supreme being becomes the dialectical triad of paralogism, antinomy, and ideal.","The triad of self, world, and supreme being becomes the dialectical triad of paralogism, antinomy, and ideal."]],"CL_BA94_20:GA-04":[["[Persistent] The subjective necessity of an idea never by itself establishes knowledge of an object.","The subjective necessity of an idea never by itself establishes knowledge of an object."]],"CL_BA94_20:GA-05":[["[Emergent] Logical form is both the generative grammar of rational ideas and the vehicle of dialectical error when transferred into ontology.","Logical form is both the generative grammar of rational ideas and the vehicle of dialectical error when transferred into ontology."]],"CL_BA94_20:GA-06":[["[Attractor] The thinking subject is demanded as an absolute unity but remains unavailable as a determinate object.","The thinking subject is demanded as an absolute unity but remains unavailable as a determinate object."]],"CL_BA94_20:GA-07":[["[Mutating] Reason’s system-producing power becomes a structurally necessary power of overreach once its forms are treated as object-determinations.","Reason’s system-producing power becomes a structurally necessary power of overreach once its forms are treated as object-determinations."]],"CL_BA94_20:GA-08":[["[Emergent] Transcendental illusion cannot be eliminated, although assent to its conclusions can be disciplined.","Transcendental illusion cannot be eliminated, although assent to its conclusions can be disciplined."]],"CL_BA94_20:GA-09":[["[Terminal] Rational psychology survives speculative collapse only as a negative discipline restraining opposed dogmatisms.","Rational psychology survives speculative collapse only as a negative discipline restraining opposed dogmatisms."]],"CL_BA94_20:GA-10":[["[Terminal] Claims about existence beyond present life are removed from theoretical proof and preserved only as practically oriented commitments.","Claims about existence beyond present life are removed from theoretical proof and preserved only as practically oriented commitments."]],"CL_BA94_20:GA-11":[["[Attractor] The unconditioned remains operationally necessary precisely where it remains unavailable within possible experience.","The unconditioned remains operationally necessary precisely where it remains unavailable within possible experience."]],"CL_BA94_21:GA-01":[["[Persistent] Whenever a conditioned phenomenon is given, reason necessarily demands the absolute totality of its antecedent conditions.","Whenever a conditioned phenomenon is given, reason necessarily demands the absolute totality of its antecedent conditions."]],"CL_BA94_21:GA-02":[["[Mutating] Understanding supplies pure categories, but reason transforms eligible conditioned syntheses into transcendental ideas by extending them beyond possible experience.","Understanding supplies pure categories, but reason transforms eligible conditioned syntheses into transcendental ideas by extending them beyond possible experience."]],"CL_BA94_21:GA-03":[["[Persistent] Only regressively subordinated serial conditions support cosmological totalization; coordinated aggregates and progressive consequences do not.","Only regressively subordinated serial conditions support cosmological totalization; coordinated aggregates and progressive consequences do not."]],"CL_BA94_21:GA-04":[["[Emergent] Composition, division, origination, and dependence are the four modes through which phenomenal conditioning becomes cosmologically totalized.","Composition, division, origination, and dependence are the four modes through which phenomenal conditioning becomes cosmologically totalized."]],"CL_BA94_21:GA-05":[["[Mutating] The unconditioned is represented either as the complete totality of conditioned members or as an unconditioned first member, and this bifurcation generates opposed determinations.","The unconditioned is represented either as the complete totality of conditioned members or as an unconditioned first member, and this bifurcation generates opposed determinations."]],"CL_BA94_21:GA-06":[["[Persistent] Cosmological synthesis must obey the conditions of possible experience while answering a demand for completeness that no merely empirical synthesis can satisfy.","Cosmological synthesis must obey the conditions of possible experience while answering a demand for completeness that no merely empirical synthesis can satisfy."]],"CL_BA94_21:GA-07":[["[Emergent] Extending the demand for unconditioned unity beyond possible experience produces natural, recurrent, and internally contradictory transcendental illusion.","Extending the demand for unconditioned unity beyond possible experience produces natural, recurrent, and internally contradictory transcendental illusion."]],"CL_BA94_21:GA-08":[["[Persistent] Cosmological ideas retain phenomenal reference while exceeding every possible empirical completion and therefore cannot become knowledge of noumenal totality.","Cosmological ideas retain phenomenal reference while exceeding every possible empirical completion and therefore cannot become knowledge of noumenal totality."]],"CL_BA94_21:GA-09":[["[Emergent] Each side of an antinomy can possess internal rational necessity even though neither side admits empirical or intuitive adjudication.","Each side of an antinomy can possess internal rational necessity even though neither side admits empirical or intuitive adjudication."]],"CL_BA94_21:GA-10":[["[Attractor] Contradiction is evidence that reason has misclassified the scope or status of its principles, not evidence that the world itself bears contradictory predicates.","Contradiction is evidence that reason has misclassified the scope or status of its principles, not evidence that the world itself bears contradictory predicates."]],"CL_BA94_21:GA-11":[["[Terminal] Critical philosophy must reject both dogmatic selection and skeptical abandonment in favor of a method that diagnoses the source of disagreement.","Critical philosophy must reject both dogmatic selection and skeptical abandonment in favor of a method that diagnoses the source of disagreement."]],"CL_BA94_21:GA-12":[["[Attractor] Because transcendental illusion survives its exposure, critique must operate as a recurrent discipline rather than a final eradication of cosmological error.","Because transcendental illusion survives its exposure, critique must operate as a recurrent discipline rather than a final eradication of cosmological error."]],"CL_BA94_22:GA-01":[["[Persistent] Objective speculative cognition is authorized only where an object can be related to possible experience.","Objective speculative cognition is authorized only where an object can be related to possible experience."]],"CL_BA94_22:GA-02":[["[Attractor] Reason necessarily seeks an unconditioned totality for every conditioned empirical synthesis.","Reason necessarily seeks an unconditioned totality for every conditioned empirical synthesis."]],"CL_BA94_22:GA-03":[["[Mutating] Cosmological totality changes from a presumed terminal object into an idea governing the required progress of empirical synthesis.","Cosmological totality changes from a presumed terminal object into an idea governing the required progress of empirical synthesis."]],"CL_BA94_22:GA-04":[["[Persistent] Neither dogmatic affirmation nor dogmatic negation can claim knowledge beyond the conditions warranted by possible experience.","Neither dogmatic affirmation nor dogmatic negation can claim knowledge beyond the conditions warranted by possible experience."]],"CL_BA94_22:GA-05":[["[Mutating] Empirical regress is valid as an indefinitely extensible procedure but invalid as a completed cosmological whole.","Empirical regress is valid as an indefinitely extensible procedure but invalid as a completed cosmological whole."]],"CL_BA94_22:GA-06":[["[Emergent] Reason answers internally generated cosmological questions reflexively by determining their cognitive ground and legitimate use.","Reason answers internally generated cosmological questions reflexively by determining their cognitive ground and legitimate use."]],"CL_BA94_22:GA-07":[["[Emergent] Every dogmatic cosmological alternative fails by either exceeding possible synthesis or terminating at something that still requires a condition.","Every dogmatic cosmological alternative fails by either exceeding possible synthesis or terminating at something that still requires a condition."]],"CL_BA94_22:GA-08":[["[Terminal] Antinomy is a symptom of transcendental illusion produced when reason treats its idea as an independently determinable object.","Antinomy is a symptom of transcendental illusion produced when reason treats its idea as an independently determinable object."]],"CL_BA94_22:GA-09":[["[Attractor] Critical self-limitation is reason’s positive form of completion because it resolves the illusion without supplying an impossible total object.","Critical self-limitation is reason’s positive form of completion because it resolves the illusion without supplying an impossible total object."]],"CL_BA94_22:GA-10":[["[Mutating] Practical and architectonic interests explain allegiance to cosmological doctrines but remain categorically distinct from speculative authorization.","Practical and architectonic interests explain allegiance to cosmological doctrines but remain categorically distinct from speculative authorization."]],"CL_BA94_23:GA-01":[["[Persistent] Empirical objectivity consists in lawful integration within possible experience, not in self-subsistent existence outside it.","Empirical objectivity consists in lawful integration within possible experience, not in self-subsistent existence outside it."]],"CL_BA94_23:GA-02":[["[Persistent] Spatial-temporal objects are appearances, so their reality cannot be identified with the reality of things in themselves.","Spatial-temporal objects are appearances, so their reality cannot be identified with the reality of things in themselves."]],"CL_BA94_23:GA-03":[["[Mutating] Conditionedness imposes an unbounded demand to seek further conditions, but never entitles reason to posit their completed availability.","Conditionedness imposes an unbounded demand to seek further conditions, but never entitles reason to posit their completed availability."]],"CL_BA94_23:GA-04":[["[Emergent] Cosmological totality is legitimate only as an idea of completed possible experience transformed into a regulative rule.","Cosmological totality is legitimate only as an idea of completed possible experience transformed into a regulative rule."]],"CL_BA94_23:GA-05":[["[Persistent] Phenomenal conditions are available only through temporally successive synthesis and regress rather than as a co-given whole.","Phenomenal conditions are available only through temporally successive synthesis and regress rather than as a co-given whole."]],"CL_BA94_23:GA-06":[["[Attractor] The unconditioned directs inquiry as an unattainable terminus while remaining unavailable as an empirical discovery.","The unconditioned directs inquiry as an unattainable terminus while remaining unavailable as an empirical discovery."]],"CL_BA94_23:GA-07":[["[Persistent] No ontological conclusion about the world follows from the logical necessity of continuing explanatory regress.","No ontological conclusion about the world follows from the logical necessity of continuing explanatory regress."]],"CL_BA94_23:GA-08":[["[Emergent] Antinomy diagnoses a shared invalid object-model, allowing opposed cosmological judgments to be jointly false.","Antinomy diagnoses a shared invalid object-model, allowing opposed cosmological judgments to be jointly false."]],"CL_BA94_23:GA-09":[["[Terminal] The world as a phenomenal whole cannot be determined as finite, infinite, begun, unbegun, simple, composite, free, or necessitated in itself.","The world as a phenomenal whole cannot be determined as finite, infinite, begun, unbegun, simple, composite, free, or necessitated in itself."]],"CL_BA94_23:GA-10":[["[Persistent] The unknowable ground of appearances functions as a limiting correlate and cannot furnish positive cognition of a supersensible object.","The unknowable ground of appearances functions as a limiting correlate and cannot furnish positive cognition of a supersensible object."]],"CL_BA94_23:GA-11":[["[Attractor] Reason is legitimate where it expands empirical inquiry systematically without converting that expansion into transcendent cognition.","Reason is legitimate where it expands empirical inquiry systematically without converting that expansion into transcendent cognition."]],"CL_BA94_23:GA-12":[["[Terminal] The dissolution of antinomy operates as an indirect confirmation of transcendental ideality rather than as cosmological knowledge.","The dissolution of antinomy operates as an indirect confirmation of transcendental ideality rather than as cosmological knowledge."]],"CL_BA94_24:GA-01":[["[Persistent] Phenomena cannot bear determinations that require treating them as completed things in themselves.","Phenomena cannot bear determinations that require treating them as completed things in themselves."]],"CL_BA94_24:GA-02":[["[Attractor] The unconditioned persists as the demand ordering the search for conditions while remaining unavailable as an empirical object or terminus.","The unconditioned persists as the demand ordering the search for conditions while remaining unavailable as an empirical object or terminus."]],"CL_BA94_24:GA-03":[["[Emergent] The legitimate status of totality is determined by the mode through which its conditions are given, constructed, or related to a series.","The legitimate status of totality is determined by the mode through which its conditions are given, constructed, or related to a series."]],"CL_BA94_24:GA-04":[["[Mutating] Regress has non-equivalent forms: empirical composition remains indefinitely extensible, while continuous division proceeds in infinitum through jointly given conditions.","Regress has non-equivalent forms: empirical composition remains indefinitely extensible, while continuous division proceeds in infinitum through jointly given conditions."]],"CL_BA94_24:GA-05":[["[Persistent] A rule for seeking conditions cannot be converted into a constitutive predicate of a completed cosmological object.","A rule for seeking conditions cannot be converted into a constitutive predicate of a completed cosmological object."]],"CL_BA94_24:GA-06":[["[Emergent] Homogeneous mathematical series exclude an unconditioned phenomenal member, while heterogeneous dynamical dependence may conditionally admit a non-sensuous ground.","Homogeneous mathematical series exclude an unconditioned phenomenal member, while heterogeneous dynamical dependence may conditionally admit a non-sensuous ground."]],"CL_BA94_24:GA-07":[["[Persistent] Every attained empirical condition remains subject to further conditioning, so no empirical datum can function as absolute closure.","Every attained empirical condition remains subject to further conditioning, so no empirical datum can function as absolute closure."]],"CL_BA94_24:GA-08":[["[Terminal] Finite and actual-infinite cosmological predicates lose objective standing when neither an absolute boundary nor a pre-given total magnitude can be presented.","Finite and actual-infinite cosmological predicates lose objective standing when neither an absolute boundary nor a pre-given total magnitude can be presented."]],"CL_BA94_24:GA-09":[["[Attractor] Empirical lawfulness is the gate that prevents an intelligible condition from becoming a hidden empirical cause or an interruption of explanation.","Empirical lawfulness is the gate that prevents an intelligible condition from becoming a hidden empirical cause or an interruption of explanation."]],"CL_BA94_24:GA-10":[["[Mutating] Critical limitation transfers reason’s authority from metaphysical inventory to the correction and extension of empirical cognition.","Critical limitation transfers reason’s authority from metaphysical inventory to the correction and extension of empirical cognition."]],"CL_BA94_24:GA-11":[["[Terminal] Antinomy is resolved not by selecting a victorious thesis but by diagnosing the illicit totalization that generates opposed theses.","Antinomy is resolved not by selecting a victorious thesis but by diagnosing the illicit totalization that generates opposed theses."]],"CL_BA94_24:RMD-01":[["[Stable Identity] The relation of conditioned appearance to a further condition persists as the invariant motor of both empirical inquiry and divisive analysis.","The relation of conditioned appearance to a further condition persists as the invariant motor of both empirical inquiry and divisive analysis."]],"CL_BA94_24:RMD-02":[["[Functional Recurrence] Totality changes from a falsely presumed object of completed magnitude into a horizon or rule governing its own construction through regress.","Totality changes from a falsely presumed object of completed magnitude into a horizon or rule governing its own construction through regress."]],"CL_BA94_24:RMD-03":[["[Mutation] Infinity splits into regressus in indefinitum for empirical composition and regressus in infinitum for continuous division, blocking their conflation into one ontological thesis.","Infinity splits into regressus in indefinitum for empirical composition and regressus in infinitum for continuous division, blocking their conflation into one ontological thesis."]],"CL_BA94_24:RMD-04":[["[Reversal] Critical restriction reverses apparent epistemic loss into enlarged empirical authority by converting prohibition into a rule of correction.","Critical restriction reverses apparent epistemic loss into enlarged empirical authority by converting prohibition into a rule of correction."]],"CL_BA94_24:RMD-05":[["[Escalation] The unconditioned moves from an excluded phenomenal endpoint in mathematical synthesis to a conditionally admissible intelligible non-member in dynamical synthesis.","The unconditioned moves from an excluded phenomenal endpoint in mathematical synthesis to a conditionally admissible intelligible non-member in dynamical synthesis."]],"CL_BA94_24:RMD-06":[["[Absorption] Phenomenal substance and infinitely pre-organized wholes disappear as positive candidates for closure after establishing that neither simple residue nor determinate infinite organization can complete analysis.","Phenomenal substance and infinitely pre-organized wholes disappear as positive candidates for closure after establishing that neither simple residue nor determinate infinite organization can complete analysis."]],"CL_BA94_24:RMD-07":[["[Terminal Transformation] Infinity ceases to signify a number of already existing parts and becomes inexhaustible determinability through an operation of division.","Infinity ceases to signify a number of already existing parts and becomes inexhaustible determinability through an operation of division."]],"CL_BA94_24:CGD-01":[["[Lower-Layer Local] The void-boundary argument is a specific anti-finitist proof for cosmical composition rather than the universal ground of all cosmological regress.","The void-boundary argument is a specific anti-finitist proof for cosmical composition rather than the universal ground of all cosmological regress."]],"CL_BA94_24:CGD-02":[["[Lower-Layer Local] The dismantling of phenomenal substance and infinitely pre-given organization belongs specifically to the analysis of division and discrete multiplicity.","The dismantling of phenomenal substance and infinitely pre-given organization belongs specifically to the analysis of division and discrete multiplicity."]],"CL_BA94_24:CGD-03":[["[Current-Level Scaling] The distinction between appearances and things in themselves scales across every cosmological conflict by withdrawing the object-domain presupposed by completed totality.","The distinction between appearances and things in themselves scales across every cosmological conflict by withdrawing the object-domain presupposed by completed totality."]],"CL_BA94_24:CGD-04":[["[Bridge Structure] Totality becomes legitimate only as a representation generated through regress rather than as a magnitude available before synthesis.","Totality becomes legitimate only as a representation generated through regress rather than as a magnitude available before synthesis."]],"CL_BA94_24:CGD-05":[["[Transition Catalyst] The distinction between homogeneous and heterogeneous synthesis generates the shift from reciprocal rejection in mathematics to conditional admissibility in dynamical explanation.","The distinction between homogeneous and heterogeneous synthesis generates the shift from reciprocal rejection in mathematics to conditional admissibility in dynamical explanation."]],"CL_BA94_24:CGD-06":[["[Recoding] The finite-versus-infinite binary is superseded by a typology distinguishing indefinite inquiry, infinite divisibility, and prohibited actual completion.","The finite-versus-infinite binary is superseded by a typology distinguishing indefinite inquiry, infinite divisibility, and prohibited actual completion."]],"CL_BA94_24:CGD-07":[["[Retained Subordinate] Relative empirical beginnings and limits remain valid within experience but cannot be elevated into absolute cosmological closure.","Relative empirical beginnings and limits remain valid within experience but cannot be elevated into absolute cosmological closure."]],"CL_BA94_25:GA-01":[["[Persistent] Objective cognition requires sensible presentation; what exceeds possible experience may be thought but cannot thereby become an object of knowledge.","Objective cognition requires sensible presentation; what exceeds possible experience may be thought but cannot thereby become an object of knowledge."]],"CL_BA94_25:GA-02":[["[Persistent] Every empirical object, event, and existence remains conditioned within an exceptionless and indefinitely extendable series.","Every empirical object, event, and existence remains conditioned within an exceptionless and indefinitely extendable series."]],"CL_BA94_25:GA-03":[["[Mutating] The unconditioned cannot appear as a temporal beginning, highest phenomenal member, or concretely presented ideal.","The unconditioned cannot appear as a temporal beginning, highest phenomenal member, or concretely presented ideal."]],"CL_BA94_25:GA-04":[["[Persistent] A dynamical condition may differ in kind from what it conditions, permitting empirical and intelligible relations to concern the same effect without entering one homogeneous series.","A dynamical condition may differ in kind from what it conditions, permitting empirical and intelligible relations to concern the same effect without entering one homogeneous series."]],"CL_BA94_25:GA-05":[["[Mutating] The intelligible register supports distinct functions that must not be conflated: spontaneous causality for action, an extramundane condition for phenomenal dependence, and rational determination for the ideal.","The intelligible register supports distinct functions that must not be conflated: spontaneous causality for action, an extramundane condition for phenomenal dependence, and rational determination for the ideal."]],"CL_BA94_25:GA-06":[["[Persistent] Complete empirical explanation does not establish that empirical reality exhausts every possible ground, relation, or standard.","Complete empirical explanation does not establish that empirical reality exhausts every possible ground, relation, or standard."]],"CL_BA94_25:GA-07":[["[Persistent] Thinkability exceeds knowability, but noncontradiction never by itself proves actuality, real possibility, or determinate constitution.","Thinkability exceeds knowability, but noncontradiction never by itself proves actuality, real possibility, or determinate constitution."]],"CL_BA94_25:GA-08":[["[Emergent] Withdrawal of objective presentation preserves or intensifies systematic function: the nonobjective can orient explanation, judgment, imputation, and perfectibility without becoming constitutive knowledge.","Withdrawal of objective presentation preserves or intensifies systematic function: the nonobjective can orient explanation, judgment, imputation, and perfectibility without becoming constitutive knowledge."]],"CL_BA94_25:GA-09":[["[Attractor] Reason persistently seeks complete unity, an unconditioned condition, and exhaustive determination even though experience can supply none of them.","Reason persistently seeks complete unity, an unconditioned condition, and exhaustive determination even though experience can supply none of them."]],"CL_BA94_25:GA-10":[["[Terminal] The unconditioned is legitimate only as a differentiated boundary-structure or regulative archetype, never as an empirically located or theoretically established entity.","The unconditioned is legitimate only as a differentiated boundary-structure or regulative archetype, never as an empirically located or theoretically established entity."]],"CL_BA94_25:RMD-01":[["[Functional recurrence] Empirical conditioning retains its restrictive identity across natural action and phenomenal existence, then reappears as the incompleteness of every empirical copy measured against an ideal.","Empirical conditioning retains its restrictive identity across natural action and phenomenal existence, then reappears as the incompleteness of every empirical copy measured against an ideal."]],"CL_BA94_25:RMD-02":[["[Mutation] The intelligible changes from a timeless causal source, to a nonmember condition of the world-series, to a field of complete rational determination whose force is archetypal rather than causal.","The intelligible changes from a timeless causal source, to a nonmember condition of the world-series, to a field of complete rational determination whose force is archetypal rather than causal."]],"CL_BA94_25:RMD-03":[["[Displacement] The unconditioned is displaced from a supposed gap inside nature to an extramundane ground and then from explanatory grounding to regulative judgment.","The unconditioned is displaced from a supposed gap inside nature to an extramundane ground and then from explanatory grounding to regulative judgment."]],"CL_BA94_25:RMD-04":[["[Expansion] Practical normativity begins as evidence motivating the representation of free reason and expands into an archetypal structure for judging and reforming empirical action.","Practical normativity begins as evidence motivating the representation of free reason and expands into an archetypal structure for judging and reforming empirical action."]],"CL_BA94_25:RMD-05":[["[Absorption] The unattainable totality of causal conditions and the unlimited regress of dependence are absorbed into a broader structure of indefinite approximation toward rational completeness.","The unattainable totality of causal conditions and the unlimited regress of dependence are absorbed into a broader structure of indefinite approximation toward rational completeness."]],"CL_BA94_25:RMD-06":[["[Stable identity with altered use] Nonempirical grounds leave empirical inquiry methodologically intact, but the ideal converts this separation from passive limitation into an active procedure of comparison and criticism.","Nonempirical grounds leave empirical inquiry methodologically intact, but the ideal converts this separation from passive limitation into an active procedure of comparison and criticism."]],"CL_BA94_25:RMD-07":[["[Terminal transformation] The necessary being ceases to function as a candidate member of the cosmos and becomes the projected object of a transcendent inquiry whose general formal category is the ideal.","The necessary being ceases to function as a candidate member of the cosmos and becomes the projected object of a transcendent inquiry whose general formal category is the ideal."]],"CL_BA94_25:CGD-01":[["[Lower-layer local] The empirical–intelligible character distinction is specific machinery for reconciling natural explanation and rational imputation in the case of action.","The empirical–intelligible character distinction is specific machinery for reconciling natural explanation and rational imputation in the case of action."]],"CL_BA94_25:CGD-02":[["[Lower-layer local] The nonmembership of a necessary being in the phenomenal series is specific machinery for resolving the antinomy of existential dependence.","The nonmembership of a necessary being in the phenomenal series is specific machinery for resolving the antinomy of existential dependence."]],"CL_BA94_25:CGD-03":[["[Lower-layer local] Selection among contradictory predicates is the specific mechanism by which an ideal receives exhaustive rational determination.","Selection among contradictory predicates is the specific mechanism by which an ideal receives exhaustive rational determination."]],"CL_BA94_25:CGD-04":[["[Current-level scaling] The shared architecture is not any local supersensible object but the restriction of empirical validity combined with the preservation of nonempirical thinkability and function.","The shared architecture is not any local supersensible object but the restriction of empirical validity combined with the preservation of nonempirical thinkability and function."]],"CL_BA94_25:CGD-05":[["[Bridge] Practical normativity connects the freedom analysis to the ideal analysis by turning rational causality into judgment according to a nonempirical archetype.","Practical normativity connects the freedom analysis to the ideal analysis by turning rational causality into judgment according to a nonempirical archetype."]],"CL_BA94_25:CGD-06":[["[Catalyst and supersession] The fourth antinomy catalyzes the transition toward transcendent ideas, while the searches for an empirical first cause, highest member, or perfect specimen are jointly superseded.","The fourth antinomy catalyzes the transition toward transcendent ideas, while the searches for an empirical first cause, highest member, or perfect specimen are jointly superseded."]],"CL_BA94_25:ALT-B01":[["[Surface level] The explicit objects are free action, the necessary ground of phenomenal existence, and the rational ideal.","The explicit objects are free action, the necessary ground of phenomenal existence, and the rational ideal."]],"CL_BA94_25:ALT-B02":[["[Structural level] The system distributes conditioning, explanation, and determination across empirical series, intelligible relations, and regulative archetypes.","The system distributes conditioning, explanation, and determination across empirical series, intelligible relations, and regulative archetypes."]],"CL_BA94_25:ALT-B03":[["[Metastrategic level] The system limits both dogmatic transcendence and empirical exclusivism by converting supersensible claims into differentiated permissions and prohibitions.","The system limits both dogmatic transcendence and empirical exclusivism by converting supersensible claims into differentiated permissions and prohibitions."]],"CL_BA94_25:ALT-B04":[["[Ontological / Temporal level] Reality is presented as temporally conditioned appearance underlain by timelessly conceived relations, while rational completion remains asymptotic rather than historically attained.","Reality is presented as temporally conditioned appearance underlain by timelessly conceived relations, while rational completion remains asymptotic rather than historically attained."]],"CL_BA94_25:ALT-B05":[["[Methodological / Performative level] The argument repeatedly performs its own rule by withdrawing objective assertion, preserving a restricted rational function, and returning that function to empirical inquiry or practice.","The argument repeatedly performs its own rule by withdrawing objective assertion, preserving a restricted rational function, and returning that function to empirical inquiry or practice."]],"CL_BA94_26:GA-01":[["[Persistent] Complete determination requires relation to a total field of possible predicates and therefore exceeds mere exclusion of contradictories.","Complete determination requires relation to a total field of possible predicates and therefore exceeds mere exclusion of contradictories."]],"CL_BA94_26:GA-02":[["[Persistent] Negative determination is structurally derivative of affirmative reality, because limitation is intelligible only against a prior material of reality.","Negative determination is structurally derivative of affirmative reality, because limitation is intelligible only against a prior material of reality."]],"CL_BA94_26:GA-03":[["[Attractor] The totality of reality condenses into the ens realissimum as the ideal through which finite determinations are conceived as partial and limited.","The totality of reality condenses into the ens realissimum as the ideal through which finite determinations are conceived as partial and limited."]],"CL_BA94_26:GA-04":[["[Mutating] The ens realissimum changes function from regulative prototype to preferred candidate for necessity, but never acquires theoretical existence through that transition.","The ens realissimum changes function from regulative prototype to preferred candidate for necessity, but never acquires theoretical existence through that transition."]],"CL_BA94_26:GA-05":[["[Persistent] Reason’s demand for an unconditioned ground arises from conditioned existence and causal regress, but the demand itself supplies no object.","Reason’s demand for an unconditioned ground arises from conditioned existence and causal regress, but the demand itself supplies no object."]],"CL_BA94_26:GA-06":[["[Emergent] Speculative theology depends on the illicit conversion of non-equivalent operations—regress, conceptual selection, existential assertion, and practical endorsement—into one alleged proof.","Speculative theology depends on the illicit conversion of non-equivalent operations—regress, conceptual selection, existential assertion, and practical endorsement—into one alleged proof."]],"CL_BA94_26:GA-07":[["[Persistent] Necessity belonging to a judgement or predicate-relation cannot establish the necessary existence of the subject or object judged.","Necessity belonging to a judgement or predicate-relation cannot establish the necessary existence of the subject or object judged."]],"CL_BA94_26:GA-08":[["[Persistent] Existential cognition requires an object’s givenness within possible experience and cannot be supplied by conceptual completeness alone.","Existential cognition requires an object’s givenness within possible experience and cannot be supplied by conceptual completeness alone."]],"CL_BA94_26:GA-09":[["[Terminal] The exhaustion of speculative proof-paths terminates not in atheistic demonstration but in the foreclosure of theoretical theology.","The exhaustion of speculative proof-paths terminates not in atheistic demonstration but in the foreclosure of theoretical theology."]],"CL_BA94_26:GA-10":[["[Mutating] Practical obligation may sustain subjective rational adherence where speculative cognition fails, but cannot restore objective proof.","Practical obligation may sustain subjective rational adherence where speculative cognition fails, but cannot restore objective proof."]],"CL_BA94_27:GA-01":[["[Persistent] Principles supplying objective theoretical cognition are valid only within possible experience.","Principles supplying objective theoretical cognition are valid only within possible experience."]],"CL_BA94_27:GA-02":[["[Persistent] Existence cannot be extracted from a concept, however complete or non-contradictory that concept may be.","Existence cannot be extracted from a concept, however complete or non-contradictory that concept may be."]],"CL_BA94_27:GA-03":[["[Persistent] Every empirically accessible cause remains conditioned, whereas a cause outside the empirical series cannot be reached by empirical causality.","Every empirically accessible cause remains conditioned, whereas a cause outside the empirical series cannot be reached by empirical causality."]],"CL_BA94_27:GA-04":[["[Mutating] Natural purposiveness warrants at most an architect of worldly form, not an all-sufficient creator of matter and existence.","Natural purposiveness warrants at most an architect of worldly form, not an all-sufficient creator of matter and existence."]],"CL_BA94_27:GA-05":[["[Persistent] Comparative empirical predicates cannot yield the absolute totality required for a completely determinate Supreme Being.","Comparative empirical predicates cannot yield the absolute totality required for a completely determinate Supreme Being."]],"CL_BA94_27:GA-06":[["[Emergent] Every speculative proof of a Supreme Being ultimately depends upon the ontological transition from complete concept to necessary existence.","Every speculative proof of a Supreme Being ultimately depends upon the ontological transition from complete concept to necessary existence."]],"CL_BA94_27:GA-07":[["[Terminal] Speculative reason can establish neither the existence nor the nonexistence of a Supreme Being.","Speculative reason can establish neither the existence nor the nonexistence of a Supreme Being."]],"CL_BA94_27:GA-08":[["[Attractor] Reason necessarily orients explanation toward an unconditioned ground that it cannot possess as an object of speculative cognition.","Reason necessarily orients explanation toward an unconditioned ground that it cannot possess as an object of speculative cognition."]],"CL_BA94_27:GA-09":[["[Mutating] Necessity changes from an alleged property of an object into a regulative demand and then into a possible practical requirement.","Necessity changes from an alleged property of an object into a regulative demand and then into a possible practical requirement."]],"CL_BA94_27:GA-10":[["[Terminal] The Supreme Being is retained as an as-if ground of systematic unity without corresponding theoretical existence-knowledge.","The Supreme Being is retained as an as-if ground of systematic unity without corresponding theoretical existence-knowledge."]],"CL_BA94_27:GA-11":[["[Emergent] Speculative reason retains a legitimate negative office: it can purify the divine concept and protect the possibility of practical postulation.","Speculative reason retains a legitimate negative office: it can purify the divine concept and protect the possibility of practical postulation."]],"CL_BA94_27:GA-12":[["[Terminal] Theological warrant divides by jurisdiction: theoretical cognition concerns being, while practical reason may posit conditions required by obligation.","Theological warrant divides by jurisdiction: theoretical cognition concerns being, while practical reason may posit conditions required by obligation."]],"CL_BA94_28:GA-01":[["[Persistent] Possible experience is the jurisdictional boundary of speculative cognition, but that boundary does not abolish reason’s demand for systematicity.","Possible experience is the jurisdictional boundary of speculative cognition, but that boundary does not abolish reason’s demand for systematicity."]],"CL_BA94_28:GA-02":[["[Persistent] Reason properly operates through the understanding by ordering its cognitions rather than by directly cognizing supersensible objects.","Reason properly operates through the understanding by ordering its cognitions rather than by directly cognizing supersensible objects."]],"CL_BA94_28:GA-03":[["[Mutating] Transcendental ideas persist as necessary projections whose legitimate force lies in directing inquiry rather than constituting objects.","Transcendental ideas persist as necessary projections whose legitimate force lies in directing inquiry rather than constituting objects."]],"CL_BA94_28:GA-04":[["[Mutating] The projected systematic whole becomes both a regulative horizon for cognition and an architectonic plan for arranging its parts.","The projected systematic whole becomes both a regulative horizon for cognition and an architectonic plan for arranging its parts."]],"CL_BA94_28:GA-05":[["[Emergent] Cognitive limitation is an enabling condition of secure system-building because it determines which materials, claims, and methods can be integrated.","Cognitive limitation is an enabling condition of secure system-building because it determines which materials, claims, and methods can be integrated."]],"CL_BA94_28:GA-06":[["[Emergent] Legitimate method must be proportioned to available cognitive materials and differentiated according to the cognition or object being organized.","Legitimate method must be proportioned to available cognitive materials and differentiated according to the cognition or object being organized."]],"CL_BA94_28:GA-07":[["[Emergent] Pure reason’s lack of external constraint allows its general principles to generate interconnected illusion rather than merely isolated error.","Pure reason’s lack of external constraint allows its general principles to generate interconnected illusion rather than merely isolated error."]],"CL_BA94_28:GA-08":[["[Mutating] Negative restraint becomes a constructive condition of knowledge wherever unrestricted positive expansion would amplify systematic illusion.","Negative restraint becomes a constructive condition of knowledge wherever unrestricted positive expansion would amplify systematic illusion."]],"CL_BA94_28:GA-09":[["[Persistent] Dialectic arises from the misemployment, hypostatization, or illicit transfer of rational procedures rather than from the mere existence of ideas.","Dialectic arises from the misemployment, hypostatization, or illicit transfer of rational procedures rather than from the mere existence of ideas."]],"CL_BA94_28:GA-10":[["[Attractor] Complete systematic unity must guide inquiry while remaining unavailable as a completed empirical object.","Complete systematic unity must guide inquiry while remaining unavailable as a completed empirical object."]],"CL_BA94_28:GA-11":[["[Emergent] Reason is recursively self-governing: it supplies principles of unity while becoming the object of critical discipline.","Reason is recursively self-governing: it supplies principles of unity while becoming the object of critical discipline."]],"CL_BA94_28:GA-12":[["[Terminal] A legitimate system combines positive cognitive materials, regulative orientation, architectonic organization, and negative methodological control within finite experience.","A legitimate system combines positive cognitive materials, regulative orientation, architectonic organization, and negative methodological control within finite experience."]],"CL_BA94_28:RMD-01":[["[Stable identity] The boundary of possible experience retains its prohibitive identity while acquiring the additional function of delimiting a secure cognitive jurisdiction.","The boundary of possible experience retains its prohibitive identity while acquiring the additional function of delimiting a secure cognitive jurisdiction."]],"CL_BA94_28:RMD-02":[["[Mutation] Systematic unity changes from an asymptotic regulative horizon into the formal architectonic according to which bounded cognition is organized.","Systematic unity changes from an asymptotic regulative horizon into the formal architectonic according to which bounded cognition is organized."]],"CL_BA94_28:RMD-03":[["[Displacement] The soul, world-totality, and God cease to function as speculative objects and migrate into analogical procedures for organizing experience.","The soul, world-totality, and God cease to function as speculative objects and migrate into analogical procedures for organizing experience."]],"CL_BA94_28:RMD-04":[["[Reversal] Reason changes from the presumed sovereign judge of cognition into a power whose authority makes its own distortions require special scrutiny.","Reason changes from the presumed sovereign judge of cognition into a power whose authority makes its own distortions require special scrutiny."]],"CL_BA94_28:RMD-05":[["[Reversal] Negativity changes from apparent obstruction of knowledge into the disciplinary infrastructure that makes reliable positive cognition possible.","Negativity changes from apparent obstruction of knowledge into the disciplinary infrastructure that makes reliable positive cognition possible."]],"CL_BA94_28:RMD-06":[["[Escalation] Hypostatization first produces local contradiction and explanatory closure, then expands into a connected methodological system of fallacies.","Hypostatization first produces local contradiction and explanatory closure, then expands into a connected methodological system of fallacies."]],"CL_BA94_28:RMD-07":[["[Functional recurrence] The distinction between constrained and unconstrained cognition recurs as the demand that methods remain specific to their valid domains.","The distinction between constrained and unconstrained cognition recurs as the demand that methods remain specific to their valid domains."]],"CL_BA94_28:RMD-08":[["[Terminal transformation] Cognitive completion bifurcates into permanently unfinished empirical systematization and formally complete regulation of the systematizing process.","Cognitive completion bifurcates into permanently unfinished empirical systematization and formally complete regulation of the systematizing process."]],"CL_BA94_28:RMD-09":[["[Absorption] The architectural image of materials, plan, and dwelling is absorbed into a general account of how finitude, method, and discipline jointly constitute systematic reason.","The architectural image of materials, plan, and dwelling is absorbed into a general account of how finitude, method, and discipline jointly constitute systematic reason."]],"CL_BA94_28:CGD-01":[["[Local] Homogeneity, specification, and affinity remain particular regulative maxims rather than the complete architecture of method.","Homogeneity, specification, and affinity remain particular regulative maxims rather than the complete architecture of method."]],"CL_BA94_28:CGD-02":[["[Local] The psychological, cosmological, and theological schemata remain domain-specific implementations of the wider rule that ideals may regulate without constituting objects.","The psychological, cosmological, and theological schemata remain domain-specific implementations of the wider rule that ideals may regulate without constituting objects."]],"CL_BA94_28:CGD-03":[["[Scales upward] The experiential boundary scales from a limit on speculative claims into the jurisdictional principle governing the entire method of pure reason.","The experiential boundary scales from a limit on speculative claims into the jurisdictional principle governing the entire method of pure reason."]],"CL_BA94_28:CGD-04":[["[Bridge] Regulative systematicity bridges the recovery of transcendental ideas and the architectonic construction of a bounded cognitive system.","Regulative systematicity bridges the recovery of transcendental ideas and the architectonic construction of a bounded cognitive system."]],"CL_BA94_28:CGD-05":[["[Bridge] The doctrine of method supplies the formal location in which the recovered uses of reason can be organized and policed.","The doctrine of method supplies the formal location in which the recovered uses of reason can be organized and policed."]],"CL_BA94_28:CGD-06":[["[Catalyst] The absence of empirical or intuitive tests converts ordinary criticism into a general discipline against systematic transcendental error.","The absence of empirical or intuitive tests converts ordinary criticism into a general discipline against systematic transcendental error."]],"CL_BA94_28:CGD-07":[["[Recoded] Failed transcendent construction is not simply discarded; it is recoded as the negative condition for proportioned, finite, and secure construction.","Failed transcendent construction is not simply discarded; it is recoded as the negative condition for proportioned, finite, and secure construction."]],"CL_BA94_28:CGD-08":[["[Superseded] A generic method derived from logical form alone is superseded by object-sensitive regulation grounded in cognitive conditions and limits.","A generic method derived from logical form alone is superseded by object-sensitive regulation grounded in cognitive conditions and limits."]],"CL_BA94_29:GA-01":[["[Persistent] Possible experience is simultaneously the domain, validity criterion, and operational boundary of objective speculative cognition.","Possible experience is simultaneously the domain, validity criterion, and operational boundary of objective speculative cognition."]],"CL_BA94_29:GA-02":[["[Persistent] Theoretical cognition of an object requires an admissible mode of presentation, and the categories determine objects only within possible experiential presentation.","Theoretical cognition of an object requires an admissible mode of presentation, and the categories determine objects only within possible experiential presentation."]],"CL_BA94_29:GA-03":[["[Mutating] A priori cognition is internally differentiated into intuitive construction, discursive determination, regulative systematization, and critical adjudication rather than governed by one transferable method.","A priori cognition is internally differentiated into intuitive construction, discursive determination, regulative systematization, and critical adjudication rather than governed by one transferable method."]],"CL_BA94_29:GA-04":[["[Persistent] Neither a concept, rational idea, nor logically consistent supposition can establish the objective possibility or reality of its corresponding object.","Neither a concept, rational idea, nor logically consistent supposition can establish the objective possibility or reality of its corresponding object."]],"CL_BA94_29:GA-05":[["[Emergent] Rational entitlement depends upon function-specific mediation: construction for mathematics, deduction for transcendental principles, and empirical-law connection for explanatory hypotheses.","Rational entitlement depends upon function-specific mediation: construction for mathematics, deduction for transcendental principles, and empirical-law connection for explanatory hypotheses."]],"CL_BA94_29:GA-06":[["[Attractor] Reason is autonomous only by legislating and submitting to universal conditions of criticism, validity, and limitation.","Reason is autonomous only by legislating and submitting to universal conditions of criticism, validity, and limitation."]],"CL_BA94_29:GA-07":[["[Mutating] Opposition changes from external methodological contrast and doctrinal combat into an internal engine of reason’s self-examination.","Opposition changes from external methodological contrast and doctrinal combat into an internal engine of reason’s self-examination."]],"CL_BA94_29:GA-08":[["[Emergent] Supersensible claims remain speculatively undecidable while acquiring sharply delimited practical, regulative, or defensive functions.","Supersensible claims remain speculatively undecidable while acquiring sharply delimited practical, regulative, or defensive functions."]],"CL_BA94_29:GA-09":[["[Persistent] The abolition of dogmatic form does not abolish philosophical system; it reconstructs systematicity through deduction, criticism, and lawful differentiation of uses.","The abolition of dogmatic form does not abolish philosophical system; it reconstructs systematicity through deduction, criticism, and lawful differentiation of uses."]],"CL_BA94_29:GA-10":[["[Terminal] Pure reason terminates in bounded authority: necessary cognition within its domain, declared non-cognition beyond it, and no intermediate theoretical opinion concerning transcendendent objects.","Pure reason terminates in bounded authority: necessary cognition within its domain, declared non-cognition beyond it, and no intermediate theoretical opinion concerning transcendendent objects."]],"CL_BA94_30:GA-01":[["[Persistent] Theoretical objectivity belongs only to principles whose validity is restricted to objects of possible experience.","Theoretical objectivity belongs only to principles whose validity is restricted to objects of possible experience."]],"CL_BA94_30:GA-02":[["[Persistent] A transcendental synthetic claim is entitled to proof only after the objective validity of its concepts and the possibility of their synthesis have been established.","A transcendental synthetic claim is entitled to proof only after the objective validity of its concepts and the possibility of their synthesis have been established."]],"CL_BA94_30:GA-03":[["[Persistent] Subjective necessities of association, completion, or thought cannot be converted into determinations of objects without producing transcendental illusion.","Subjective necessities of association, completion, or thought cannot be converted into determinations of objects without producing transcendental illusion."]],"CL_BA94_30:GA-04":[["[Mutating] Critique transforms proof from an inferential accomplishment into a self-disciplinary tribunal over the source, right, and scope of rational principles.","Critique transforms proof from an inferential accomplishment into a self-disciplinary tribunal over the source, right, and scope of rational principles."]],"CL_BA94_30:GA-05":[["[Emergent] Restriction of speculative claims functions positively by securing the residual domain of legitimate cognition against dialectical overreach.","Restriction of speculative claims functions positively by securing the residual domain of legitimate cognition against dialectical overreach."]],"CL_BA94_30:GA-06":[["[Attractor] Reason remains oriented toward what exceeds experience even though speculative reason cannot satisfy that orientation through cognition.","Reason remains oriented toward what exceeds experience even though speculative reason cannot satisfy that orientation through cognition."]],"CL_BA94_30:GA-07":[["[Mutating] A canon governs only a faculty with a possible proper employment; the impossibility of speculative synthesis therefore disqualifies a speculative canon.","A canon governs only a faculty with a possible proper employment; the impossibility of speculative synthesis therefore disqualifies a speculative canon."]],"CL_BA94_30:GA-08":[["[Terminal] Moral law alone provides the canon of pure practical reason because it is determined a priori and commands unconditionally.","Moral law alone provides the canon of pure practical reason because it is determined a priori and commands unconditionally."]],"CL_BA94_30:GA-09":[["[Mutating] Freedom, immortality, and God cannot explain objects of experience but retain their highest rational significance as practical concerns.","Freedom, immortality, and God cannot explain objects of experience but retain their highest rational significance as practical concerns."]],"CL_BA94_30:GA-10":[["[Attractor] Practical freedom is admissible as rational determination of the will, while transcendental freedom remains theoretically unresolved.","Practical freedom is admissible as rational determination of the will, while transcendental freedom remains theoretically unresolved."]],"CL_BA94_30:GA-11":[["[Terminal] The ultimate question of pure reason is transformed from what can be known into what ought to be done.","The ultimate question of pure reason is transformed from what can be known into what ought to be done."]],"CL_BA94_31:GA-01":[["[Persistent] Speculative reason cannot cognize the supersensible conditions required by reason’s final moral ends.","Speculative reason cannot cognize the supersensible conditions required by reason’s final moral ends."]],"CL_BA94_31:GA-02":[["[Persistent] Moral law obligates rational agents independently of happiness, reward, theology, and speculative proof.","Moral law obligates rational agents independently of happiness, reward, theology, and speculative proof."]],"CL_BA94_31:GA-03":[["[Persistent] The highest good requires happiness to be distributed in exact proportion to moral worthiness.","The highest good requires happiness to be distributed in exact proportion to moral worthiness."]],"CL_BA94_31:GA-04":[["[Persistent] Natural causality supplies no cognizable guarantee that virtue and proportionate happiness will coincide.","Natural causality supplies no cognizable guarantee that virtue and proportionate happiness will coincide."]],"CL_BA94_31:GA-05":[["[Mutating] God and future life arise first as practical hypotheses of the highest good and become morally necessary objects of belief.","God and future life arise first as practical hypotheses of the highest good and become morally necessary objects of belief."]],"CL_BA94_31:GA-06":[["[Emergent] Moral belief combines subjective sufficiency with acknowledged objective insufficiency.","Moral belief combines subjective sufficiency with acknowledged objective insufficiency."]],"CL_BA94_31:GA-07":[["[Attractor] Practical necessity may orient reason beyond experience but may never be converted into theoretical cognition.","Practical necessity may orient reason beyond experience but may never be converted into theoretical cognition."]],"CL_BA94_31:GA-08":[["[Terminal] Theology remains legitimate only as a derivative of autonomous moral law and cannot become the source of obligation.","Theology remains legitimate only as a derivative of autonomous moral law and cannot become the source of obligation."]],"CL_BA94_31:GA-09":[["[Mutating] Rational universality changes form across domains: cognition requires objectively communicable grounds, whereas moral orientation requires universally accessible commitment under law.","Rational universality changes form across domains: cognition requires objectively communicable grounds, whereas moral orientation requires universally accessible commitment under law."]],"CL_BA94_31:GA-10":[["[Emergent] The limitation of theoretical reason is productive because it establishes the boundary within which practical belief becomes legitimate.","The limitation of theoretical reason is productive because it establishes the boundary within which practical belief becomes legitimate."]],"CL_BA94_31:GA-11":[["[Attractor] The systematic unity of moral ends organizes freedom, happiness, nature, teleology, hope, and assent without becoming an object of speculative knowledge.","The systematic unity of moral ends organizes freedom, happiness, nature, teleology, hope, and assent without becoming an object of speculative knowledge."]],"CL_BA94_32:GA-01":[["[Persistent] Cognition becomes scientific only when systematic procedure subordinates its parts to a rationally unified whole.","Cognition becomes scientific only when systematic procedure subordinates its parts to a rationally unified whole."]],"CL_BA94_32:GA-02":[["[Persistent] A rational system legislates the ends, limits, membership, and positions of its parts rather than merely arranging them after accumulation.","A rational system legislates the ends, limits, membership, and positions of its parts rather than merely arranging them after accumulation."]],"CL_BA94_32:GA-03":[["[Emergent] Philosophical history is rationally significant only when reconstructed as a transcendental field of epistemic positions rather than retained as chronology.","Philosophical history is rationally significant only when reconstructed as a transcendental field of epistemic positions rather than retained as chronology."]],"CL_BA94_32:GA-04":[["[Mutating] The idea governing a rational science may remain germinal until historical conflict retrospectively discloses the structure that can correct inherited definitions.","The idea governing a rational science may remain germinal until historical conflict retrospectively discloses the structure that can correct inherited definitions."]],"CL_BA94_32:GA-05":[["[Emergent] Rational legitimacy depends on the alignment of cognitive object, source, method, and the subject’s autonomous derivation from principles.","Rational legitimacy depends on the alignment of cognitive object, source, method, and the subject’s autonomous derivation from principles."]],"CL_BA94_32:GA-06":[["[Mutating] Systematicity is necessary but insufficient because dogmatism and scepticism can themselves be systematic; criticism must judge their admissibility.","Systematicity is necessary but insufficient because dogmatism and scepticism can themselves be systematic; criticism must judge their admissibility."]],"CL_BA94_32:GA-07":[["[Attractor] Criticism is simultaneously an internal organ of metaphysics and the higher-order path by which reason audits every metaphysical procedure.","Criticism is simultaneously an internal organ of metaphysics and the higher-order path by which reason audits every metaphysical procedure."]],"CL_BA94_32:GA-08":[["[Persistent] Philosophy is an unattained legislative practice that judges actual cognition by its relation to the ultimate ends of reason.","Philosophy is an unattained legislative practice that judges actual cognition by its relation to the ultimate ends of reason."]],"CL_BA94_32:GA-09":[["[Mutating] Metaphysics becomes a jurisdiction defined by a priori origin, disciplinary exclusion, and critical regulation rather than unrestricted speculative extension.","Metaphysics becomes a jurisdiction defined by a priori origin, disciplinary exclusion, and critical regulation rather than unrestricted speculative extension."]],"CL_BA94_32:GA-10":[["[Emergent] Reason has a dual temporality in which its systematic idea precedes historical articulation while its critical settlement remains future and collective.","Reason has a dual temporality in which its systematic idea precedes historical articulation while its critical settlement remains future and collective."]],"CL_BA94_32:GA-11":[["[Terminal] The destination of humanity supplies the ultimate architectonic end under which the historically motivating concerns of theology and morality must be reordered.","The destination of humanity supplies the ultimate architectonic end under which the historically motivating concerns of theology and morality must be reordered."]],"CL_BA94_32:GA-12":[["[Attractor] Durable rational satisfaction is sought through the prevention of speculative error rather than through unlimited positive acquisition of transcendent knowledge.","Durable rational satisfaction is sought through the prevention of speculative error rather than through unlimited positive acquisition of transcendent knowledge."]],"MC_BA94_L1_01:GA-01":[["[Persistent] Cognition may begin through experience without being wholly derivable from experience.","Cognition may begin through experience without being wholly derivable from experience."]],"MC_BA94_L1_01:GA-02":[["[Attractor] Synthetic a priori cognition is necessary cognitive augmentation whose possibility cannot be explained by conceptual analysis or empirical association.","Synthetic a priori cognition is necessary cognitive augmentation whose possibility cannot be explained by conceptual analysis or empirical association."]],"MC_BA94_L1_01:GA-03":[["[Persistent] Analysis supplies necessity without extension, while experience supplies extension without strict necessity; neither can independently ground theoretical science.","Analysis supplies necessity without extension, while experience supplies extension without strict necessity; neither can independently ground theoretical science."]],"MC_BA94_L1_01:GA-04":[["[Attractor] Possible experience is both the field within which a priori structures acquire objective validity and the criterion limiting their legitimate use.","Possible experience is both the field within which a priori structures acquire objective validity and the criterion limiting their legitimate use."]],"MC_BA94_L1_01:GA-05":[["[Persistent] Critical examination of cognitive authority must precede every doctrinal extension of pure reason.","Critical examination of cognitive authority must precede every doctrinal extension of pure reason."]],"MC_BA94_L1_01:GA-06":[["[Emergent] Transcendental explanation validates cognition by regressing from claims about objects to the conditions that make object-relation possible.","Transcendental explanation validates cognition by regressing from claims about objects to the conditions that make object-relation possible."]],"MC_BA94_L1_01:GA-07":[["[Persistent] Intuition is indispensable both to object-directed conceptual use and to synthetic extension beyond what concepts analytically contain.","Intuition is indispensable both to object-directed conceptual use and to synthetic extension beyond what concepts analytically contain."]],"MC_BA94_L1_01:GA-08":[["[Persistent] Sensibility and understanding are irreducible but ordered faculties: objects must be given before they can be thought.","Sensibility and understanding are irreducible but ordered faculties: objects must be given before they can be thought."]],"MC_BA94_L1_01:GA-09":[["[Mutating] The a priori expands from independence from experience into the formal structure of sensibility embodied by space and time.","The a priori expands from independence from experience into the formal structure of sensibility embodied by space and time."]],"MC_BA94_L1_01:GA-10":[["[Emergent] The finite subject is neither a sovereign creator nor a passive spectator, but a receptive-formal operator that supplies conditions without supplying empirical content.","The finite subject is neither a sovereign creator nor a passive spectator, but a receptive-formal operator that supplies conditions without supplying empirical content."]],"MC_BA94_L1_01:GA-11":[["[Terminal] Objective validity is domain-indexed to appearances, and no valid inference runs from conditions of appearance to the intrinsic constitution of things.","Objective validity is domain-indexed to appearances, and no valid inference runs from conditions of appearance to the intrinsic constitution of things."]],"MC_BA94_L1_01:GA-12":[["[Mutating] Metaphysics persists as a rational disposition but can become a science only by submitting its claims to critical authorization.","Metaphysics persists as a rational disposition but can become a science only by submitting its claims to critical authorization."]],"MC_BA94_L2_01:GA-01":[["[Persistent] Finite cognition requires irreducibly distinct sensible and conceptual sources whose coordination cannot be replaced by either source alone.","Finite cognition requires irreducibly distinct sensible and conceptual sources whose coordination cannot be replaced by either source alone."]],"MC_BA94_L2_01:GA-02":[["[Attractor] Synthesis is prior to analysis and objecthood because sensible multiplicity does not arrive as an already unified cognition.","Synthesis is prior to analysis and objecthood because sensible multiplicity does not arrive as an already unified cognition."]],"MC_BA94_L2_01:GA-03":[["[Emergent] Original apperception is the higher unity through which subjective self-ascription and objective relation are co-generated.","Original apperception is the higher unity through which subjective self-ascription and objective relation are co-generated."]],"MC_BA94_L2_01:GA-04":[["[Mutating] A logical function becomes an objectively valid category only when it determines sensible multiplicity through synthesis and temporal specification.","A logical function becomes an objectively valid category only when it determines sensible multiplicity through synthesis and temporal specification."]],"MC_BA94_L2_01:GA-05":[["[Attractor] Mediation is the system’s operative center, linking intuition, synthesis, apperception, judgment, schema, category, principle, and object.","Mediation is the system’s operative center, linking intuition, synthesis, apperception, judgment, schema, category, principle, and object."]],"MC_BA94_L2_01:GA-06":[["[Attractor] Possible experience is simultaneously the ground of objective validity, the domain of application, and the criterion of cognitive limitation.","Possible experience is simultaneously the ground of objective validity, the domain of application, and the criterion of cognitive limitation."]],"MC_BA94_L2_01:GA-07":[["[Mutating] Objectivity is condition-relative without being arbitrary because universally necessary synthesis replaces comparison with independently cognized being.","Objectivity is condition-relative without being arbitrary because universally necessary synthesis replaces comparison with independently cognized being."]],"MC_BA94_L2_01:GA-08":[["[Terminal] A priori authority is domain-indexed: its necessity becomes legitimate only by accepting restriction to possible experience.","A priori authority is domain-indexed: its necessity becomes legitimate only by accepting restriction to possible experience."]],"MC_BA94_L2_01:GA-09":[["[Emergent] The subject is a constitutive but non-sovereign integrating function that organizes givenness while remaining temporally non-coincident with its own activity.","The subject is a constitutive but non-sovereign integrating function that organizes givenness while remaining temporally non-coincident with its own activity."]],"MC_BA94_L2_01:GA-10":[["[Terminal] Pure understanding legislates the universal form of lawful nature while leaving its particular empirical determinations open.","Pure understanding legislates the universal form of lawful nature while leaving its particular empirical determinations open."]],"MC_BA94_L2_01:GA-11":[["[Persistent] Critique is a positive jurisdictional operation through which cognition examines, distributes, and limits its own authority.","Critique is a positive jurisdictional operation through which cognition examines, distributes, and limits its own authority."]],"MC_BA94_L2_01:GA-12":[["[Terminal] Positive noumenal cognition collapses, but an indeterminate noumenal remainder persists because it can be neither positively known nor eliminated.","Positive noumenal cognition collapses, but an indeterminate noumenal remainder persists because it can be neither positively known nor eliminated."]],"MC_BA94_L1_02:GA-01":[["[Persistent] Finite cognition requires both receptive sensible givenness and spontaneous conceptual determination; neither faculty constitutes cognition alone.","Finite cognition requires both receptive sensible givenness and spontaneous conceptual determination; neither faculty constitutes cognition alone."]],"MC_BA94_L1_02:GA-02":[["[Persistent] Space and time constitute the a priori field of appearance, so their objective validity extends only to objects under sensible conditions.","Space and time constitute the a priori field of appearance, so their objective validity extends only to objects under sensible conditions."]],"MC_BA94_L1_02:GA-03":[["[Persistent] Objective cognition requires pure conceptual conditions to be applied to an object supplied through intuition.","Objective cognition requires pure conceptual conditions to be applied to an object supplied through intuition."]],"MC_BA94_L1_02:GA-04":[["[Attractor] Cognitive possibility and cognitive limitation are one structure because the conditions generating validity also determine its boundary at possible experience.","Cognitive possibility and cognitive limitation are one structure because the conditions generating validity also determine its boundary at possible experience."]],"MC_BA94_L1_02:GA-05":[["[Mutating] Subjectivity is not private construction but the universally binding receptive and conceptual organization through which empirical objectivity becomes possible.","Subjectivity is not private construction but the universally binding receptive and conceptual organization through which empirical objectivity becomes possible."]],"MC_BA94_L1_02:GA-06":[["[Mutating] Purity names differentiated operations: exclusion of sensation from pure intuition, abstraction from content in logic, and removal of empirical conditions from activated conceptions.","Purity names differentiated operations: exclusion of sensation from pure intuition, abstraction from content in logic, and removal of empirical conditions from activated conceptions."]],"MC_BA94_L1_02:GA-07":[["[Persistent] Formal coherence is a necessary negative condition of cognition but cannot establish objective agreement by itself.","Formal coherence is a necessary negative condition of cognition but cannot establish objective agreement by itself."]],"MC_BA94_L1_02:GA-08":[["[Attractor] The canon–organon distinction governs all pure principles: they may regulate cognition already given but may not independently produce objects or material knowledge.","The canon–organon distinction governs all pure principles: they may regulate cognition already given but may not independently produce objects or material knowledge."]],"MC_BA94_L1_02:GA-09":[["[Mutating] Transcendental status depends on the possibility, scope, and valid object-directed use of a representation rather than on a priori origin alone.","Transcendental status depends on the possibility, scope, and valid object-directed use of a representation rather than on a priori origin alone."]],"MC_BA94_L1_02:GA-10":[["[Emergent] Systematic totality must assign each pure conception its place and reciprocally validate the legitimacy and completeness of the conceptual field.","Systematic totality must assign each pure conception its place and reciprocally validate the legitimacy and completeness of the conceptual field."]],"MC_BA94_L1_02:GA-11":[["[Mutating] Experience is neither the origin of pure forms nor dispensable: it supplies givenness, activates conceptual development, and conditions objective application.","Experience is neither the origin of pure forms nor dispensable: it supplies givenness, activates conceptual development, and conditions objective application."]],"MC_BA94_L1_02:GA-12":[["[Terminal] Critique preserves empirical objectivity and pure principles only by restricting their legitimacy, scope, and extension to authorized use.","Critique preserves empirical objectivity and pure principles only by restricting their legitimacy, scope, and extension to authorized use."]],"MC_BA94_L1_02:GA-13":[["[Attractor] Human finitude is the absence of a self-sufficient cognitive faculty and of intellectual intuition capable of producing or immediately knowing its objects.","Human finitude is the absence of a self-sufficient cognitive faculty and of intellectual intuition capable of producing or immediately knowing its objects."]],"MC_BA94_L1_02:GA-14":[["[Terminal] Pure conceptual completeness must be architectonically derivable, but its closure remains anticipatory until the governing principle and concrete inventory are exhibited.","Pure conceptual completeness must be architectonically derivable, but its closure remains anticipatory until the governing principle and concrete inventory are exhibited."]],"MC_BA94_L1_02:RMD-01":[["[Expansion] Space and time retain identity as a priori forms while expanding from conditions of appearance into sources of synthetic content and boundaries of judgment.","Space and time retain identity as a priori forms while expanding from conditions of appearance into sources of synthetic content and boundaries of judgment."]],"MC_BA94_L1_02:RMD-02":[["[Reversal] Subjectivity changes from a suspected source of illusion into the formal condition of empirical objectivity.","Subjectivity changes from a suspected source of illusion into the formal condition of empirical objectivity."]],"MC_BA94_L1_02:RMD-03":[["[Mutation] Purity shifts from isolating non-empirical sensible form, through exclusion of logical content, to active abstraction from empirically activated conceptions.","Purity shifts from isolating non-empirical sensible form, through exclusion of logical content, to active abstraction from empirically activated conceptions."]],"MC_BA94_L1_02:RMD-04":[["[Repartition] Content changes from what formal logic excludes into the intuitive matter that must return for pure concepts to acquire objects.","Content changes from what formal logic excludes into the intuitive matter that must return for pure concepts to acquire objects."]],"MC_BA94_L1_02:RMD-05":[["[Displacement] Universality migrates from shared sensible constitution to formal logical reach and finally becomes a trigger for restriction to valid objective use.","Universality migrates from shared sensible constitution to formal logical reach and finally becomes a trigger for restriction to valid objective use."]],"MC_BA94_L1_02:RMD-06":[["[Mutation] Autonomy migrates from a static property of understanding into its operation of generating, developing, purifying, and ordering conceptions.","Autonomy migrates from a static property of understanding into its operation of generating, developing, purifying, and ordering conceptions."]],"MC_BA94_L1_02:RMD-07":[["[Reversal] Experience changes from an excluded origin of a priori form into an indispensable occasion of conceptual activation and objective fulfillment.","Experience changes from an excluded origin of a priori form into an indispensable occasion of conceptual activation and objective fulfillment."]],"MC_BA94_L1_02:RMD-08":[["[Terminal Transformation] Classification ceases to be inventory-making and becomes derivational placement within a necessary systematic order.","Classification ceases to be inventory-making and becomes derivational placement within a necessary systematic order."]],"MC_BA94_L1_02:RMD-09":[["[Reversal] Dialectic changes from an apparent technique of knowledge-production into the critique of hyperphysical extension and rule-misuse.","Dialectic changes from an apparent technique of knowledge-production into the critique of hyperphysical extension and rule-misuse."]],"MC_BA94_L1_02:RMD-10":[["[Absorption] The thing in itself persists as a limit but is absorbed into the broader boundary separating possible experience from inadmissible objectivity independent of intuition.","The thing in itself persists as a limit but is absorbed into the broader boundary separating possible experience from inadmissible objectivity independent of intuition."]],"MC_BA94_L1_02:ALT-B01":[["[Surface] Change, motion, space, time, geometry, logic, pure conceptions, and their complete order are the explicit objects through which cognitive validity is tested.","Change, motion, space, time, geometry, logic, pure conceptions, and their complete order are the explicit objects through which cognitive validity is tested."]],"MC_BA94_L1_02:ALT-B02":[["[Structural] Cognition is a dual-source circuit governed by sensible formatting, conceptual determination, the canon–organon distinction, and possible experience.","Cognition is a dual-source circuit governed by sensible formatting, conceptual determination, the canon–organon distinction, and possible experience."]],"MC_BA94_L1_02:ALT-B03":[["[Metastrategic] Inquiry shifts from assertions about independent objects and contingent collections toward conditions, scope, exclusions, and principled derivation.","Inquiry shifts from assertions about independent objects and contingent collections toward conditions, scope, exclusions, and principled derivation."]],"MC_BA94_L1_02:ALT-B04":[["[Ontological / Temporal] Reality for finite knowers is phenomenal, while time structures both finite self-appearance and the recursive anticipation of systematic totality.","Reality for finite knowers is phenomenal, while time structures both finite self-appearance and the recursive anticipation of systematic totality."]],"MC_BA94_L1_02:ALT-B05":[["[Methodological / Performative] Successive acts of purification and repeated exclusions perform the system’s claim that validity arises through disciplined delimitation.","Successive acts of purification and repeated exclusions perform the system’s claim that validity arises through disciplined delimitation."]],"MC_BA94_L2_02:GA-01":[["[Persistent] Objective cognition requires sensible presentation, lawful synthesis, and restriction to the conditions of possible experience.","Objective cognition requires sensible presentation, lawful synthesis, and restriction to the conditions of possible experience."]],"MC_BA94_L2_02:GA-02":[["[Persistent] Cognitive functions and jurisdictions are irreducibly differentiated, and validity is destroyed when one function substitutes for another.","Cognitive functions and jurisdictions are irreducibly differentiated, and validity is destroyed when one function substitutes for another."]],"MC_BA94_L2_02:GA-03":[["[Attractor] Every conditioned cognition activates reason’s unavoidable demand for complete determination, systematic unity, and an unconditioned ground.","Every conditioned cognition activates reason’s unavoidable demand for complete determination, systematic unity, and an unconditioned ground."]],"MC_BA94_L2_02:GA-04":[["[Mutating] The unconditioned changes from a presumed object or terminal condition into a receding horizon, selective gate, regulative principle, practical concern, and architectonic destination.","The unconditioned changes from a presumed object or terminal condition into a receding horizon, selective gate, regulative principle, practical concern, and architectonic destination."]],"MC_BA94_L2_02:GA-05":[["[Emergent] Transcendental illusion is the lawful misclassification by which inferential, rational, or systematic necessity is transferred into objective determination.","Transcendental illusion is the lawful misclassification by which inferential, rational, or systematic necessity is transferred into objective determination."]],"MC_BA94_L2_02:GA-06":[["[Attractor] Possible experience is simultaneously the positive field of theoretical objectivity and the tribunal filtering every claim to objective reference.","Possible experience is simultaneously the positive field of theoretical objectivity and the tribunal filtering every claim to objective reference."]],"MC_BA94_L2_02:GA-07":[["[Emergent] Contradiction has critical force when it discloses the invalid completed object-model shared by apparently exhaustive alternatives.","Contradiction has critical force when it discloses the invalid completed object-model shared by apparently exhaustive alternatives."]],"MC_BA94_L2_02:GA-08":[["[Persistent] Conceptual completeness, causal demand, logical compatibility, natural order, and systematic coherence cannot independently establish existence.","Conceptual completeness, causal demand, logical compatibility, natural order, and systematic coherence cannot independently establish existence."]],"MC_BA94_L2_02:GA-09":[["[Emergent] Negative criticism is a constitutive governance mechanism that secures cognition by allocating claims among distinct modes of validity.","Negative criticism is a constitutive governance mechanism that secures cognition by allocating claims among distinct modes of validity."]],"MC_BA94_L2_02:GA-10":[["[Mutating] Limitation changes from deprivation into productive protection of objective cognition, empirical openness, practical commitment, and systematic order.","Limitation changes from deprivation into productive protection of objective cognition, empirical openness, practical commitment, and systematic order."]],"MC_BA94_L2_02:GA-11":[["[Terminal] Speculative reason can establish neither the existence nor the nonexistence of supersensible objects, and practical authorization cannot reverse this theoretical suspension.","Speculative reason can establish neither the existence nor the nonexistence of supersensible objects, and practical authorization cannot reverse this theoretical suspension."]],"MC_BA94_L2_02:GA-12":[["[Attractor] Rational autonomy consists in recursive self-legislation, self-criticism, and submission of every rational power to the conditions of its legitimate use.","Rational autonomy consists in recursive self-legislation, self-criticism, and submission of every rational power to the conditions of its legitimate use."]],"MC_BA94_L2_02:GA-13":[["[Terminal] Closure consists in bounded theoretical authority and formally governed inquiry rather than possession of empirical, cosmological, moral, or architectonic completion.","Closure consists in bounded theoretical authority and formally governed inquiry rather than possession of empirical, cosmological, moral, or architectonic completion."]],"MC_BA94_L2_02:GA-14":[["[Emergent] Rational validity forms a topology of constitutive cognition, regulative direction, practical necessity, architectonic legitimacy, and critical control rather than a single scalar order.","Rational validity forms a topology of constitutive cognition, regulative direction, practical necessity, architectonic legitimacy, and critical control rather than a single scalar order."]],"MC_BA94_L2_02:RMD-01":[["[Stable identity] Possible experience remains the condition of theoretical objectivity while expanding into the central jurisdictional pole of the critical constitution.","Possible experience remains the condition of theoretical objectivity while expanding into the central jurisdictional pole of the critical constitution."]],"MC_BA94_L2_02:RMD-02":[["[Functional recurrence] Differentiated faculties recur as differentiated jurisdictions, converting psychological architecture into a constitutional rule against functional substitution.","Differentiated faculties recur as differentiated jurisdictions, converting psychological architecture into a constitutional rule against functional substitution."]],"MC_BA94_L2_02:RMD-03":[["[Serial mutation] The unconditioned migrates from demanded completion through cosmological and theological objectification into a regulative, practical, and architectonic horizon.","The unconditioned migrates from demanded completion through cosmological and theological objectification into a regulative, practical, and architectonic horizon."]],"MC_BA94_L2_02:RMD-04":[["[Escalation] Categories first constitute experience, then generate dialectical totalization when absolutized, and finally return as constraints on regulated inquiry.","Categories first constitute experience, then generate dialectical totalization when absolutized, and finally return as constraints on regulated inquiry."]],"MC_BA94_L2_02:RMD-05":[["[Reversal] Totality changes from the intended object and endpoint of explanation into an open procedural rule preventing arbitrary empirical arrest.","Totality changes from the intended object and endpoint of explanation into an open procedural rule preventing arbitrary empirical arrest."]],"MC_BA94_L2_02:RMD-06":[["[Reversal] Contradiction changes from evidence of world-conflict into a diagnostic instrument exposing the object-construction shared by opposed claims.","Contradiction changes from evidence of world-conflict into a diagnostic instrument exposing the object-construction shared by opposed claims."]],"MC_BA94_L2_02:RMD-07":[["[Valence reversal] Nonpresentation disqualifies constitutive knowledge but simultaneously enables regulative, organizational, and practical functions that require no presented object.","Nonpresentation disqualifies constitutive knowledge but simultaneously enables regulative, organizational, and practical functions that require no presented object."]],"MC_BA94_L2_02:RMD-08":[["[Mutation] Negation changes from denial of content into the institutional and procedural governance of positive cognitive production.","Negation changes from denial of content into the institutional and procedural governance of positive cognitive production."]],"MC_BA94_L2_02:RMD-09":[["[Terminal transformation] Completion ceases to mean possession of total content and becomes completeness in the formal allocation and regulation of unfinished inquiry.","Completion ceases to mean possession of total content and becomes completeness in the formal allocation and regulation of unfinished inquiry."]],"MC_BA94_L2_02:RMD-10":[["[Subject mutation] Reason changes from a presumed sovereign projector into a divided architect that legislates, generates error, submits to judgment, and acts without total knowledge.","Reason changes from a presumed sovereign projector into a divided architect that legislates, generates error, submits to judgment, and acts without total knowledge."]],"MC_BA94_L2_02:RMD-11":[["[Escalation] Critique and discipline expand from local correction into the recurrent tribunal governing theoretical claims, practical entitlement, history, and architectonic organization.","Critique and discipline expand from local correction into the recurrent tribunal governing theoretical claims, practical entitlement, history, and architectonic organization."]],"MC_BA94_L2_02:CGD-01":[["[Local] Reflection-concepts, individual antinomy proofs, mathematical procedures, and detailed hypothesis tests remain local instruments rather than current-level governing principles.","Reflection-concepts, individual antinomy proofs, mathematical procedures, and detailed hypothesis tests remain local instruments rather than current-level governing principles."]],"MC_BA94_L2_02:CGD-02":[["[Scales upward] Temporal synthesis and synthesis-sensitive regress scale into the general principle that objective experience is constituted successively while total synthesis remains unavailable.","Temporal synthesis and synthesis-sensitive regress scale into the general principle that objective experience is constituted successively while total synthesis remains unavailable."]],"MC_BA94_L2_02:CGD-03":[["[Scales upward] Possible experience, transcendental deduction, and authorized presentation scale into the universal criterion separating object-cognition from legitimate nonobjective orientation.","Possible experience, transcendental deduction, and authorized presentation scale into the universal criterion separating object-cognition from legitimate nonobjective orientation."]],"MC_BA94_L2_02:CGD-04":[["[Bridge] The transcendental ideal bridges complete determination, theological reification, proof dependency, and the regulative recovery of systematic unity.","The transcendental ideal bridges complete determination, theological reification, proof dependency, and the regulative recovery of systematic unity."]],"MC_BA94_L2_02:CGD-05":[["[Bridge] Discipline, canon, teleology, and criticism connect speculative restriction to practical legislation and architectonic reconstruction.","Discipline, canon, teleology, and criticism connect speculative restriction to practical legislation and architectonic reconstruction."]],"MC_BA94_L2_02:CGD-06":[["[Catalyst] Objective attribution, antinomial contradiction, and repeated proof failure catalyze the transition from local refutation to procedural governance.","Objective attribution, antinomial contradiction, and repeated proof failure catalyze the transition from local refutation to procedural governance."]],"MC_BA94_L2_02:CGD-07":[["[Superseded and recoded] Soul, world-totality, God, object-level victory, and merely problematical assent lose terminal authority and survive only as regulated problems, functions, or positions.","Soul, world-totality, God, object-level victory, and merely problematical assent lose terminal authority and survive only as regulated problems, functions, or positions."]],"MC_BA94_L2_02:ALT-B01":[["[Surface level] The system adjudicates objective synthesis, selfhood, world-totality, freedom, theological proofs, moral postulates, assent, method, and scientific organization.","The system adjudicates objective synthesis, selfhood, world-totality, freedom, theological proofs, moral postulates, assent, method, and scientific organization."]],"MC_BA94_L2_02:ALT-B02":[["[Structural level] Differentiated faculties and jurisdictions constitute objects, generate projected totalities, diagnose excess, and redistribute nonobjective demands.","Differentiated faculties and jurisdictions constitute objects, generate projected totalities, diagnose excess, and redistribute nonobjective demands."]],"MC_BA94_L2_02:ALT-B03":[["[Metastrategic level] Intervention shifts from selecting doctrines to testing object-models, governing claim-production, policing functional conversion, and institutionalizing criticism.","Intervention shifts from selecting doctrines to testing object-models, governing claim-production, policing functional conversion, and institutionalizing criticism."]],"MC_BA94_L2_02:ALT-B04":[["[Ontological / Temporal level] Reality is a lawfully synthesized field of conditioned appearances, while time is successive, regressive, recursive, and prospectively oriented toward unavailable completion.","Reality is a lawfully synthesized field of conditioned appearances, while time is successive, regressive, recursive, and prospectively oriented toward unavailable completion."]],"MC_BA94_L2_02:ALT-B05":[["[Methodological / Performative level] The system performs its thesis by producing rational projections, exposing their inflation, reclassifying their functions, and reopening the criticism it authorizes.","The system performs its thesis by producing rational projections, exposing their inflation, reclassifying their functions, and reopening the criticism it authorizes."]],"MC_BA94_L1_03:GA-01":[["[Persistent] Human cognition is discursive because sensibility supplies manifold content while understanding supplies its conceptual unification.","Human cognition is discursive because sensibility supplies manifold content while understanding supplies its conceptual unification."]],"MC_BA94_L1_03:GA-02":[["[Persistent] Synthesis precedes analysis and every represented conjunction because multiplicity is not received as already connected.","Synthesis precedes analysis and every represented conjunction because multiplicity is not received as already connected."]],"MC_BA94_L1_03:GA-03":[["[Attractor] Original apperception is the higher unity under which manifold representations can belong to one consciousness and refer to an object.","Original apperception is the higher unity under which manifold representations can belong to one consciousness and refer to an object."]],"MC_BA94_L1_03:GA-04":[["[Emergent] Subjective identity and objective unity are co-generated by the same necessary synthesis rather than founded independently.","Subjective identity and objective unity are co-generated by the same necessary synthesis rather than founded independently."]],"MC_BA94_L1_03:GA-05":[["[Mutating] Judgment is both the use of concepts and the synthetic function through which manifold cognition acquires objective unity.","Judgment is both the use of concepts and the synthetic function through which manifold cognition acquires objective unity."]],"MC_BA94_L1_03:GA-06":[["[Mutating] A logical function becomes a category when it operates as the rule for unifying a sensible manifold under apperception.","A logical function becomes a category when it operates as the rule for unifying a sensible manifold under apperception."]],"MC_BA94_L1_03:GA-07":[["[Persistent] Objective validity consists in universally necessary conditions of possible experience, not in empirical origin, repetition, or subjective compulsion.","Objective validity consists in universally necessary conditions of possible experience, not in empirical origin, repetition, or subjective compulsion."]],"MC_BA94_L1_03:GA-08":[["[Persistent] Necessity belongs to the lawful form of synthesis rather than to observed succession or the material content of sensations.","Necessity belongs to the lawful form of synthesis rather than to observed succession or the material content of sensations."]],"MC_BA94_L1_03:GA-09":[["[Emergent] Understanding constitutes objecthood without producing existence because it unifies material that must be given independently through sensibility.","Understanding constitutes objecthood without producing existence because it unifies material that must be given independently through sensibility."]],"MC_BA94_L1_03:GA-10":[["[Terminal] The proof that categories are valid for possible experience simultaneously restricts their legitimate use to that domain.","The proof that categories are valid for possible experience simultaneously restricts their legitimate use to that domain."]],"MC_BA94_L1_03:GA-11":[["[Terminal] Apperceptive and categorial principles are supreme only for a finite intellect that thinks a manifold it does not intuitively generate.","Apperceptive and categorial principles are supreme only for a finite intellect that thinks a manifold it does not intuitively generate."]],"MC_BA94_L1_03:GA-12":[["[Emergent] The deduction establishes the necessary operation of the cognitive architecture without deriving the exact inventory or ultimate source of its forms.","The deduction establishes the necessary operation of the cognitive architecture without deriving the exact inventory or ultimate source of its forms."]],"MC_BA94_L1_03:GA-13":[["[Attractor] Mediation organizes the whole architecture: manifold, synthesis, apperception, judgment, category, and object form a recursive dependency system.","Mediation organizes the whole architecture: manifold, synthesis, apperception, judgment, category, and object form a recursive dependency system."]],"MC_BA94_L1_03:RMD-01":[["[Stable identity] The exclusion of intellectual intuition remains the permanent boundary separating finite cognition from immediate self-grounding knowledge.","The exclusion of intellectual intuition remains the permanent boundary separating finite cognition from immediate self-grounding knowledge."]],"MC_BA94_L1_03:RMD-02":[["[Mutation] Function develops from arranging representations in judgment into the rule that gives necessary unity to sensible multiplicity.","Function develops from arranging representations in judgment into the rule that gives necessary unity to sensible multiplicity."]],"MC_BA94_L1_03:RMD-03":[["[Escalation] Unity moves from conceptual commonality through represented conjunction to apperception as the prior condition of both subject and object.","Unity moves from conceptual commonality through represented conjunction to apperception as the prior condition of both subject and object."]],"MC_BA94_L1_03:RMD-04":[["[Mutation] Judgment changes from a logical relation among cognitions into the operative synthesis that determines intuition under one consciousness.","Judgment changes from a logical relation among cognitions into the operative synthesis that determines intuition under one consciousness."]],"MC_BA94_L1_03:RMD-05":[["[Mutation] Categories move from a formally derived inventory to constitutive rules whose validity depends upon their necessary operation in sensible experience.","Categories move from a formally derived inventory to constitutive rules whose validity depends upon their necessary operation in sensible experience."]],"MC_BA94_L1_03:RMD-06":[["[Reversal] Objectivity ceases to mean correspondence with a ready-made object and becomes the necessary synthesis through which objecthood is representable.","Objectivity ceases to mean correspondence with a ready-made object and becomes the necessary synthesis through which objecthood is representable."]],"MC_BA94_L1_03:RMD-07":[["[Absorption] The initially underdetermined higher qualitative unity is absorbed into the architecture of original apperception, although its ultimate ground remains unavailable.","The initially underdetermined higher qualitative unity is absorbed into the architecture of original apperception, although its ultimate ground remains unavailable."]],"MC_BA94_L1_03:RMD-08":[["[Functional recurrence] The “I think” retains formal identity while expanding from possible self-ascription into the condition of universal object-reference.","The “I think” retains formal identity while expanding from possible self-ascription into the condition of universal object-reference."]],"MC_BA94_L1_03:RMD-09":[["[Displacement] Necessity migrates from relations apparently found among events to the transcendental form under which events can be objectively connected.","Necessity migrates from relations apparently found among events to the transcendental form under which events can be objectively connected."]],"MC_BA94_L1_03:RMD-10":[["[Disappearance after structural work] Empirical association first isolates the difference between subjective connection and objective unity, then recedes once constitutive synthesis is established.","Empirical association first isolates the difference between subjective connection and objective unity, then recedes once constitutive synthesis is established."]],"MC_BA94_L1_03:RMD-11":[["[Absorption] The judgment table retains its inventory function but becomes subordinate to apperceptive synthesis as the ground of objective applicability.","The judgment table retains its inventory function but becomes subordinate to apperceptive synthesis as the ground of objective applicability."]],"MC_BA94_L1_03:RMD-12":[["[Terminal transformation] Human finitude changes from an initial lack of intuition into the terminal condition defining both categorial validity and its limits.","Human finitude changes from an initial lack of intuition into the terminal condition defining both categorial validity and its limits."]],"MC_BA94_L1_03:ALT-B01":[["[Surface] The explicit problem concerns the inventory, entitlement, application, and experiential limits of categories.","The explicit problem concerns the inventory, entitlement, application, and experiential limits of categories."]],"MC_BA94_L1_03:ALT-B02":[["[Structural] Receptivity, synthesis, apperception, judgment, and category form a distributed mechanism converting multiplicity into objective cognition.","Receptivity, synthesis, apperception, judgment, and category form a distributed mechanism converting multiplicity into objective cognition."]],"MC_BA94_L1_03:ALT-B03":[["[Metastrategic] The system replaces empirical explanation and inherited taxonomy with a regress to enabling conditions followed by regulated inclusion and exclusion.","The system replaces empirical explanation and inherited taxonomy with a regress to enabling conditions followed by regulated inclusion and exclusion."]],"MC_BA94_L1_03:ALT-B04":[["[Ontological / Temporal] Objects are phenomenal unities of synthesis, while objective succession requires non-empirical lawfulness that time alone cannot provide.","Objects are phenomenal unities of synthesis, while objective succession requires non-empirical lawfulness that time alone cannot provide."]],"MC_BA94_L1_03:ALT-B05":[["[Methodological / Performative] The deduction performs its thesis by abstracting logical form, regressing to apperception, and reintegrating that unity with sensibility.","The deduction performs its thesis by abstracting logical form, regressing to apperception, and reintegrating that unity with sensibility."]],"MC_BA94_L1_04:GA-01":[["[Persistent] Objective cognition requires the conjunction of sensible givenness and conceptual determination; neither receptivity nor thought has independent cognitive sufficiency.","Objective cognition requires the conjunction of sensible givenness and conceptual determination; neither receptivity nor thought has independent cognitive sufficiency."]],"MC_BA94_L1_04:GA-02":[["[Persistent] Objectivity consists in necessary rule-governed synthesis through which appearances become determinately cognizable objects.","Objectivity consists in necessary rule-governed synthesis through which appearances become determinately cognizable objects."]],"MC_BA94_L1_04:GA-03":[["[Attractor] Possible experience is simultaneously the ground of objective validity, the field of legitimate application, and the limit of finite cognition.","Possible experience is simultaneously the ground of objective validity, the field of legitimate application, and the limit of finite cognition."]],"MC_BA94_L1_04:GA-04":[["[Mutating] Categories change from empty logical forms into objectively determining rules only through sensible and temporal specification.","Categories change from empty logical forms into objectively determining rules only through sensible and temporal specification."]],"MC_BA94_L1_04:GA-05":[["[Mutating] Productive imagination supplies the mediating synthesis whose function is subsequently inherited by schema and subsumption.","Productive imagination supplies the mediating synthesis whose function is subsequently inherited by schema and subsumption."]],"MC_BA94_L1_04:GA-06":[["[Persistent] A priori necessity establishes objectivity only by expressing necessary conditions of possible experience, not by origin, formal consistency, or subjective compulsion alone.","A priori necessity establishes objectivity only by expressing necessary conditions of possible experience, not by origin, formal consistency, or subjective compulsion alone."]],"MC_BA94_L1_04:GA-07":[["[Emergent] Systematic cognition depends on preserving the functional differences among sensibility, intuition, imagination, understanding, judgment, and reason.","Systematic cognition depends on preserving the functional differences among sensibility, intuition, imagination, understanding, judgment, and reason."]],"MC_BA94_L1_04:GA-08":[["[Mutating] Validity is an application-relation completed through judgment, although no universally mechanical rule can eliminate judgment from subsumption.","Validity is an application-relation completed through judgment, although no universally mechanical rule can eliminate judgment from subsumption."]],"MC_BA94_L1_04:GA-09":[["[Emergent] Truth is distributed across heterogeneous registers: logical admissibility, analytical recognition, transcendental validity, and synthetic object-determination.","Truth is distributed across heterogeneous registers: logical admissibility, analytical recognition, transcendental validity, and synthetic object-determination."]],"MC_BA94_L1_04:GA-10":[["[Terminal] Pure understanding legislates the universal form of lawful nature but cannot anticipate particular empirical laws, qualities, or causes.","Pure understanding legislates the universal form of lawful nature but cannot anticipate particular empirical laws, qualities, or causes."]],"MC_BA94_L1_04:GA-11":[["[Mutating] The finite subject is the functional source of synthetic unity while remaining sensibly and temporally non-coincident with its determining activity.","The finite subject is the functional source of synthetic unity while remaining sensibly and temporally non-coincident with its determining activity."]],"MC_BA94_L1_04:GA-12":[["[Emergent] Constitution and restriction are inseparable: the conditions producing experiential objects also prohibit their conversion into things as cognized independently of experience.","Constitution and restriction are inseparable: the conditions producing experiential objects also prohibit their conversion into things as cognized independently of experience."]],"MC_BA94_L1_04:GA-13":[["[Emergent] The category table becomes a generative system whose schematized forms yield the principial architecture of possible experience.","The category table becomes a generative system whose schematized forms yield the principial architecture of possible experience."]],"MC_BA94_L1_04:GA-14":[["[Terminal] Positive noumenal cognition collapses, while the negative noumenon persists as an indispensable but indeterminate limit-concept.","Positive noumenal cognition collapses, while the negative noumenon persists as an indispensable but indeterminate limit-concept."]],"MC_BA94_L1_05:GA-01":[["[Persistent] Objective validity requires sensible givenness, lawful synthesis, and restriction to the conditions under which an object can enter possible experience.","Objective validity requires sensible givenness, lawful synthesis, and restriction to the conditions under which an object can enter possible experience."]],"MC_BA94_L1_05:GA-02":[["[Persistent] Sensibility, understanding, and reason possess irreducible functions whose coordination generates cognition without licensing their mutual substitution.","Sensibility, understanding, and reason possess irreducible functions whose coordination generates cognition without licensing their mutual substitution."]],"MC_BA94_L1_05:GA-03":[["[Attractor] Possible experience is both the sole positive domain of theoretical object-determination and the criterion limiting the objective use of principles.","Possible experience is both the sole positive domain of theoretical object-determination and the criterion limiting the objective use of principles."]],"MC_BA94_L1_05:GA-04":[["[Persistent] Reason necessarily ascends from conditioned cognition toward an unconditioned completion that experience cannot supply.","Reason necessarily ascends from conditioned cognition toward an unconditioned completion that experience cannot supply."]],"MC_BA94_L1_05:GA-05":[["[Mutating] The unconditioned changes from a demanded terminus into a horizon, a triadic architecture of ideas, and finally a taxonomy of dialectical problems.","The unconditioned changes from a demanded terminus into a horizon, a triadic architecture of ideas, and finally a taxonomy of dialectical problems."]],"MC_BA94_L1_05:GA-06":[["[Emergent] Logical form is simultaneously the grammar through which reason organizes totality and the vehicle through which rational functions are falsely projected into ontology.","Logical form is simultaneously the grammar through which reason organizes totality and the vehicle through which rational functions are falsely projected into ontology."]],"MC_BA94_L1_05:GA-07":[["[Persistent] Subjective necessity, inferential inevitability, and rational demand never establish objective knowledge without corresponding conditions of intuition.","Subjective necessity, inferential inevitability, and rational demand never establish objective knowledge without corresponding conditions of intuition."]],"MC_BA94_L1_05:GA-08":[["[Emergent] Validity differentiates into constitutive object-cognition, regulative systematic unity, and practical orientation without permitting speculative hypostatization.","Validity differentiates into constitutive object-cognition, regulative systematic unity, and practical orientation without permitting speculative hypostatization."]],"MC_BA94_L1_05:GA-09":[["[Mutating] The experiential boundary changes from a prohibition against transcendence into a productive operator that secures objectivity and allocates reason’s nonconstitutive uses.","The experiential boundary changes from a prohibition against transcendence into a productive operator that secures objectivity and allocates reason’s nonconstitutive uses."]],"MC_BA94_L1_05:GA-10":[["[Mutating] Subjectivity divides into an empirically determinable self dependent on external relations and a transcendental subject required for cognition but unavailable as a determinate object.","Subjectivity divides into an empirically determinable self dependent on external relations and a transcendental subject required for cognition but unavailable as a determinate object."]],"MC_BA94_L1_05:GA-11":[["[Attractor] Critique is recurrent self-limitation rather than final correction because transcendental illusion survives disclosure of its invalidity.","Critique is recurrent self-limitation rather than final correction because transcendental illusion survives disclosure of its invalidity."]],"MC_BA94_L1_05:GA-12":[["[Emergent] Time divides into a phenomenal order constructed through lawful relations and a rational temporality kept open by regress, approximation, and noncompletion.","Time divides into a phenomenal order constructed through lawful relations and a rational temporality kept open by regress, approximation, and noncompletion."]],"MC_BA94_L1_05:GA-13":[["[Terminal] Failed speculative doctrine terminates not in an opposed ontology but in boundary-discipline, reciprocal restraint, and practically oriented commitment.","Failed speculative doctrine terminates not in an opposed ontology but in boundary-discipline, reciprocal restraint, and practically oriented commitment."]],"MC_BA94_L1_05:GA-14":[["[Attractor] Possible experience and the unavailable unconditioned form coupled poles: one determines what cognition can possess, while the other perpetually organizes what reason must seek.","Possible experience and the unavailable unconditioned form coupled poles: one determines what cognition can possess, while the other perpetually organizes what reason must seek."]],"MC_BA94_L1_05:RMD-01":[["[Stable identity] The distinction between sensibility and understanding persists, while reason is added as a non-object-determining faculty of systematic totalization.","The distinction between sensibility and understanding persists, while reason is added as a non-object-determining faculty of systematic totalization."]],"MC_BA94_L1_05:RMD-02":[["[Functional recurrence] Possible experience retains its limiting function but expands from a domain of objectivity into a juridical and allocative criterion for reason’s uses.","Possible experience retains its limiting function but expands from a domain of objectivity into a juridical and allocative criterion for reason’s uses."]],"MC_BA94_L1_05:RMD-03":[["[Escalation] Reason changes from an organizer of rules into a totalizing engine whose lawful drive toward unity generates systematic overreach.","Reason changes from an organizer of rules into a totalizing engine whose lawful drive toward unity generates systematic overreach."]],"MC_BA94_L1_05:RMD-04":[["[Mutation] The unconditioned moves from demanded completion through triadic differentiation to the absent attractor of dialectical regulation.","The unconditioned moves from demanded completion through triadic differentiation to the absent attractor of dialectical regulation."]],"MC_BA94_L1_05:RMD-05":[["[Mutation] The idea changes from taxonomic conception into practical archetype, regulative rule, dialectical premise, and finally disciplined orientation.","The idea changes from taxonomic conception into practical archetype, regulative rule, dialectical premise, and finally disciplined orientation."]],"MC_BA94_L1_05:RMD-06":[["[Reversal] Logical form changes from the architecture of rational systematization into the medium of its own ontological misuse.","Logical form changes from the architecture of rational systematization into the medium of its own ontological misuse."]],"MC_BA94_L1_05:RMD-07":[["[Escalation] Critique changes from local diagnosis into permanent regulation once illusion is recognized as structurally recurrent.","Critique changes from local diagnosis into permanent regulation once illusion is recognized as structurally recurrent."]],"MC_BA94_L1_05:RMD-08":[["[Displacement] The empirical self dependent on external permanence is displaced at the dialectical level by an indispensable but indeterminate transcendental subject.","The empirical self dependent on external permanence is displaced at the dialectical level by an indispensable but indeterminate transcendental subject."]],"MC_BA94_L1_05:RMD-09":[["[Reversal] Nonempirical status changes from apparent absence of objectivity into the enabling condition of regulative and practical efficacy.","Nonempirical status changes from apparent absence of objectivity into the enabling condition of regulative and practical efficacy."]],"MC_BA94_L1_05:RMD-10":[["[Absorption] The negative noumenon is absorbed into the general boundary of category-use, while the unconditioned assumes the distinct dynamic role of reason’s unattainable horizon.","The negative noumenon is absorbed into the general boundary of category-use, while the unconditioned assumes the distinct dynamic role of reason’s unattainable horizon."]],"MC_BA94_L1_05:RMD-11":[["[Domain bifurcation] Time changes from an unavailable medium reconstructed through phenomenal relations into a recursive structure of rational regress and open approximation.","Time changes from an unavailable medium reconstructed through phenomenal relations into a recursive structure of rational regress and open approximation."]],"MC_BA94_L1_05:CGD-01":[["[Local] Reflection-concepts and the differentiated table of nothing remain diagnostic instruments; only the general provenance-test scales into the current architecture.","Reflection-concepts and the differentiated table of nothing remain diagnostic instruments; only the general provenance-test scales into the current architecture."]],"MC_BA94_L1_05:CGD-02":[["[Scales upward] The temporal analogies scale from determinate principles of experience into the positive relational ground presupposed by every later rational totalization.","The temporal analogies scale from determinate principles of experience into the positive relational ground presupposed by every later rational totalization."]],"MC_BA94_L1_05:CGD-03":[["[Bridge] The local account of sensory error scales into a general grammar in which subjective determination is projected as objective ground.","The local account of sensory error scales into a general grammar in which subjective determination is projected as objective ground."]],"MC_BA94_L1_05:CGD-04":[["[Bridge] The derivation of ideas from syllogistic forms remains classificatory machinery, but it bridges rational totalization and the taxonomy of dialectical error.","The derivation of ideas from syllogistic forms remains classificatory machinery, but it bridges rational totalization and the taxonomy of dialectical error."]],"MC_BA94_L1_05:CGD-05":[["[Scales upward] Reciprocal legal freedom remains a local example, while the priority of practical norms over empirical institutions becomes current-level architecture.","Reciprocal legal freedom remains a local example, while the priority of practical norms over empirical institutions becomes current-level architecture."]],"MC_BA94_L1_05:CGD-06":[["[Underdetermined] Antinomy and ideal remain taxonomic branches because only paralogism receives detailed diagnostic execution.","Antinomy and ideal remain taxonomic branches because only paralogism receives detailed diagnostic execution."]],"MC_BA94_L1_05:CGD-07":[["[Catalyst] The attribution of objective reality catalyzes the transition from a general theory of rational ideas to the concrete diagnosis of self-objectification.","The attribution of objective reality catalyzes the transition from a general theory of rational ideas to the concrete diagnosis of self-objectification."]],"MC_BA94_L1_05:CGD-08":[["[Superseded] Rational psychology loses its status as positive science and survives only as a negative discipline restraining opposed dogmatisms.","Rational psychology loses its status as positive science and survives only as a negative discipline restraining opposed dogmatisms."]],"MC_BA94_L1_05:CGD-09":[["[Local] Introductory titles and sectional designations remain insufficient to establish doctrine, though their insufficiency reinforces the prohibition against deriving content from form alone.","Introductory titles and sectional designations remain insufficient to establish doctrine, though their insufficiency reinforces the prohibition against deriving content from form alone."]],"MC_BA94_L1_06:GA-01":[["[Persistent] Every conditioned appearance necessarily activates reason’s demand to seek the unconditioned totality of its conditions.","Every conditioned appearance necessarily activates reason’s demand to seek the unconditioned totality of its conditions."]],"MC_BA94_L1_06:GA-02":[["[Persistent] Speculative objectivity is authorized only where an object can be related to lawful possible experience.","Speculative objectivity is authorized only where an object can be related to lawful possible experience."]],"MC_BA94_L1_06:GA-03":[["[Persistent] Spatial-temporal objects are appearances whose empirical reality does not entail self-subsistent transcendental reality.","Spatial-temporal objects are appearances whose empirical reality does not entail self-subsistent transcendental reality."]],"MC_BA94_L1_06:GA-04":[["[Mutating] Cosmological totality changes from a presumed terminal object into a regulative principle governing inquiry.","Cosmological totality changes from a presumed terminal object into a regulative principle governing inquiry."]],"MC_BA94_L1_06:GA-05":[["[Persistent] Phenomenal conditions are available through successive synthesis, never as a complete regress already given.","Phenomenal conditions are available through successive synthesis, never as a complete regress already given."]],"MC_BA94_L1_06:GA-06":[["[Emergent] Antinomy is generated when recurrent rational totalization converts conditioned appearances into a completed cosmological object.","Antinomy is generated when recurrent rational totalization converts conditioned appearances into a completed cosmological object."]],"MC_BA94_L1_06:GA-07":[["[Attractor] Contradiction has critical force because it exposes the false object presupposed by opposed cosmological judgments.","Contradiction has critical force because it exposes the false object presupposed by opposed cosmological judgments."]],"MC_BA94_L1_06:GA-08":[["[Terminal] The phenomenal world-whole cannot legitimately bear finite, infinite, simple, composite, free, necessitated, or absolutely dependent determinations.","The phenomenal world-whole cannot legitimately bear finite, infinite, simple, composite, free, necessitated, or absolutely dependent determinations."]],"MC_BA94_L1_06:GA-09":[["[Mutating] Empirical regress is necessarily nonterminal, but its form varies between indefinite extension and infinite divisibility according to the synthesis involved.","Empirical regress is necessarily nonterminal, but its form varies between indefinite extension and infinite divisibility according to the synthesis involved."]],"MC_BA94_L1_06:GA-10":[["[Emergent] Homogeneous mathematical series exclude an unconditioned member, whereas dynamical synthesis may admit a heterogeneous ground only if empirical lawfulness remains uninterrupted.","Homogeneous mathematical series exclude an unconditioned member, whereas dynamical synthesis may admit a heterogeneous ground only if empirical lawfulness remains uninterrupted."]],"MC_BA94_L1_06:GA-11":[["[Attractor] The unconditioned remains an unattainable terminus that orders the search for conditions without becoming its empirical endpoint.","The unconditioned remains an unattainable terminus that orders the search for conditions without becoming its empirical endpoint."]],"MC_BA94_L1_06:GA-12":[["[Terminal] Critical self-limitation is reason’s positive completion because prohibition is converted into systematic empirical correction and extension.","Critical self-limitation is reason’s positive completion because prohibition is converted into systematic empirical correction and extension."]],"MC_BA94_L1_06:GA-13":[["[Attractor] Transcendental illusion survives exposure, so critique must recur as vigilance rather than conclude in permanent emancipation from totalization.","Transcendental illusion survives exposure, so critique must recur as vigilance rather than conclude in permanent emancipation from totalization."]],"MC_BA94_L1_06:GA-14":[["[Persistent] The logical necessity of seeking conditions cannot legislate the ontological constitution of the world.","The logical necessity of seeking conditions cannot legislate the ontological constitution of the world."]],"MC_BA94_L1_07:GA-01":[["[Persistent] Objective theoretical cognition requires sensible givenness within possible experience; thought beyond experience does not by itself produce an object.","Objective theoretical cognition requires sensible givenness within possible experience; thought beyond experience does not by itself produce an object."]],"MC_BA94_L1_07:GA-02":[["[Persistent] Every empirically accessible object, event, and cause remains conditioned within an indefinitely extendable series.","Every empirically accessible object, event, and cause remains conditioned within an indefinitely extendable series."]],"MC_BA94_L1_07:GA-03":[["[Attractor] Reason necessarily demands complete determination, systematic unity, and an unconditioned ground that experience cannot present as complete.","Reason necessarily demands complete determination, systematic unity, and an unconditioned ground that experience cannot present as complete."]],"MC_BA94_L1_07:GA-04":[["[Mutating] The unconditioned changes from intelligible causality and extramundane ground into ideal totality, alleged necessary being, and finally regulative horizon.","The unconditioned changes from intelligible causality and extramundane ground into ideal totality, alleged necessary being, and finally regulative horizon."]],"MC_BA94_L1_07:GA-05":[["[Persistent] Conceptual completeness, causal demand, logical compatibility, and natural order cannot independently establish existence.","Conceptual completeness, causal demand, logical compatibility, and natural order cannot independently establish existence."]],"MC_BA94_L1_07:GA-06":[["[Emergent] Speculative theology is generated by collapsing regress, conceptual selection, existential positing, and practical endorsement into one purported proof.","Speculative theology is generated by collapsing regress, conceptual selection, existential positing, and practical endorsement into one purported proof."]],"MC_BA94_L1_07:GA-07":[["[Terminal] Speculative reason establishes neither the existence nor the nonexistence of a Supreme Being.","Speculative reason establishes neither the existence nor the nonexistence of a Supreme Being."]],"MC_BA94_L1_07:GA-08":[["[Mutating] Transcendental ideas survive loss of constitutive objecthood by becoming regulative projections and architectonic principles of inquiry.","Transcendental ideas survive loss of constitutive objecthood by becoming regulative projections and architectonic principles of inquiry."]],"MC_BA94_L1_07:GA-09":[["[Emergent] Negative restriction is constitutive of secure cognition because it governs the procedures through which reason would otherwise systematize illusion.","Negative restriction is constitutive of secure cognition because it governs the procedures through which reason would otherwise systematize illusion."]],"MC_BA94_L1_07:GA-10":[["[Terminal] Rational autonomy terminates in recursive self-government rather than unrestricted speculative expansion.","Rational autonomy terminates in recursive self-government rather than unrestricted speculative expansion."]],"MC_BA94_L1_07:GA-11":[["[Mutating] Practical reason may authorize adherence, imputation, or postulation where speculative cognition fails, but it cannot convert this authorization into objective proof.","Practical reason may authorize adherence, imputation, or postulation where speculative cognition fails, but it cannot convert this authorization into objective proof."]],"MC_BA94_L1_07:GA-12":[["[Emergent] Withdrawal of objective presentation enables nonobjective ideas to acquire intensified organizational, critical, and practical functions.","Withdrawal of objective presentation enables nonobjective ideas to acquire intensified organizational, critical, and practical functions."]],"MC_BA94_L1_07:RMD-01":[["[Stable identity] Empirical conditioning remains exceptionless, but its function expands from explaining events to exposing the illegitimacy of every empirical ascent toward an absolute ground.","Empirical conditioning remains exceptionless, but its function expands from explaining events to exposing the illegitimacy of every empirical ascent toward an absolute ground."]],"MC_BA94_L1_07:RMD-02":[["[Serial mutation] The unconditioned migrates from spontaneous causality through extramundane dependence and ideal completeness into an unoccupiable regulative horizon.","The unconditioned migrates from spontaneous causality through extramundane dependence and ideal completeness into an unoccupiable regulative horizon."]],"MC_BA94_L1_07:RMD-03":[["[Reversal] The ideal of complete reality changes from a prototype of determination into a claimed necessary being and then reverses into a nonconstitutive orientation.","The ideal of complete reality changes from a prototype of determination into a claimed necessary being and then reverses into a nonconstitutive orientation."]],"MC_BA94_L1_07:RMD-04":[["[Differentiation] Necessity divides into empirical conditionality, conceptual relation, alleged ontological status, regulative demand, and practical requirement.","Necessity divides into empirical conditionality, conceptual relation, alleged ontological status, regulative demand, and practical requirement."]],"MC_BA94_L1_07:RMD-05":[["[Reversal] Negation changes from apparent deprivation into the disciplinary infrastructure governing positive cognitive production.","Negation changes from apparent deprivation into the disciplinary infrastructure governing positive cognitive production."]],"MC_BA94_L1_07:RMD-06":[["[Terminal transformation] Completion ceases to mean possession of an exhaustive object and becomes formal completeness in the regulation of unfinished inquiry.","Completion ceases to mean possession of an exhaustive object and becomes formal completeness in the regulation of unfinished inquiry."]],"MC_BA94_L1_07:RMD-07":[["[Subject mutation] Reason changes from a totalizing projector and presumed sovereign judge into a finite architect subjected to its own rules.","Reason changes from a totalizing projector and presumed sovereign judge into a finite architect subjected to its own rules."]],"MC_BA94_L1_07:RMD-08":[["[Absorption] The speculative proofs disappear as independent routes and are absorbed into one dependency structure centered on ontological reification.","The speculative proofs disappear as independent routes and are absorbed into one dependency structure centered on ontological reification."]],"MC_BA94_L1_07:ALT-B01":[["[Surface level] The explicit field contains free action, phenomenal dependence, complete reality, theological proofs, systematic unity, and methodological discipline.","The explicit field contains free action, phenomenal dependence, complete reality, theological proofs, systematic unity, and methodological discipline."]],"MC_BA94_L1_07:ALT-B02":[["[Structural level] Empirical conditioning, conceptual projection, existential positing, regulation, architectonic, and discipline form a distributed cognitive machine.","Empirical conditioning, conceptual projection, existential positing, regulation, architectonic, and discipline form a distributed cognitive machine."]],"MC_BA94_L1_07:ALT-B03":[["[Metastrategic level] Critique shifts intervention from refuting dogmatic claims to governing the procedures and jurisdictions that generate them.","Critique shifts intervention from refuting dogmatic claims to governing the procedures and jurisdictions that generate them."]],"MC_BA94_L1_07:ALT-B04":[["[Ontological / Temporal level] Reality appears as an open series of conditioned appearances under indefinitely extensible inquiry and an unavailable horizon of totality.","Reality appears as an open series of conditioned appearances under indefinitely extensible inquiry and an unavailable horizon of totality."]],"MC_BA94_L1_07:ALT-B05":[["[Methodological / Performative level] The system performs its thesis by reconstructing its projected objects, exposing their production, and converting failure into rules and recursive checks.","The system performs its thesis by reconstructing its projected objects, exposing their production, and converting failure into rules and recursive checks."]],"MC_BA94_L1_08:GA-01":[["[Persistent] Possible experience is the exclusive field of theoretical objectivity and the primary tribunal for claims concerning objects, causes, and explanations.","Possible experience is the exclusive field of theoretical objectivity and the primary tribunal for claims concerning objects, causes, and explanations."]],"MC_BA94_L1_08:GA-02":[["[Persistent] Objective cognition requires an authorized mode of presentation and a prior deduction of the validity and synthesis of its concepts.","Objective cognition requires an authorized mode of presentation and a prior deduction of the validity and synthesis of its concepts."]],"MC_BA94_L1_08:GA-03":[["[Mutating] Rational entitlement is function-specific: construction, deduction, empirical explanation, regulation, practical legislation, and critical adjudication cannot substitute for one another.","Rational entitlement is function-specific: construction, deduction, empirical explanation, regulation, practical legislation, and critical adjudication cannot substitute for one another."]],"MC_BA94_L1_08:GA-04":[["[Attractor] Reason is autonomous only when it legislates its own powers while submitting every exercise of those powers to criticism.","Reason is autonomous only when it legislates its own powers while submitting every exercise of those powers to criticism."]],"MC_BA94_L1_08:GA-05":[["[Emergent] Systematic unity is necessary but never self-validating; architectonic organization requires critical authorization because error can itself assume systematic form.","Systematic unity is necessary but never self-validating; architectonic organization requires critical authorization because error can itself assume systematic form."]],"MC_BA94_L1_08:GA-06":[["[Mutating] Supersensible ideas lose constitutive theoretical status but persist as regulative orientations, practical concerns, postulates, beliefs, or retractable defensive suppositions.","Supersensible ideas lose constitutive theoretical status but persist as regulative orientations, practical concerns, postulates, beliefs, or retractable defensive suppositions."]],"MC_BA94_L1_08:GA-07":[["[Terminal] Moral law is autonomous from happiness and theology and supplies the only proper canon of pure practical reason.","Moral law is autonomous from happiness and theology and supplies the only proper canon of pure practical reason."]],"MC_BA94_L1_08:GA-08":[["[Emergent] The highest good generates practically necessary belief by requiring a unity of virtue and happiness that natural causality cannot guarantee, while objective theoretical sufficiency remains absent.","The highest good generates practically necessary belief by requiring a unity of virtue and happiness that natural causality cannot guarantee, while objective theoretical sufficiency remains absent."]],"MC_BA94_L1_08:GA-09":[["[Emergent] Theoretical objectivity and practical necessity are irreducible but coordinated modalities of reason rather than competing claims to one undifferentiated validity.","Theoretical objectivity and practical necessity are irreducible but coordinated modalities of reason rather than competing claims to one undifferentiated validity."]],"MC_BA94_L1_08:GA-10":[["[Mutating] Limitation reverses from deprivation into productive protection by securing cognition, belief, inquiry, and systematic order against illegitimate extension.","Limitation reverses from deprivation into productive protection by securing cognition, belief, inquiry, and systematic order against illegitimate extension."]],"MC_BA94_L1_08:GA-11":[["[Attractor] Architectonic unity orders objects, methods, disciplines, practical interests, and historical positions under a single human destination without supplying speculative possession of that destination.","Architectonic unity orders objects, methods, disciplines, practical interests, and historical positions under a single human destination without supplying speculative possession of that destination."]],"MC_BA94_L1_08:GA-12":[["[Mutating] The rational subject becomes a self-legislating and self-accusing office that must act and believe without becoming the sovereign producer of its objects.","The rational subject becomes a self-legislating and self-accusing office that must act and believe without becoming the sovereign producer of its objects."]],"MC_BA94_L1_08:GA-13":[["[Emergent] Rational development has a recursively divided temporality in which failure discloses prior conditions, criticism reorganizes the present, and moral-systematic completion remains future.","Rational development has a recursively divided temporality in which failure discloses prior conditions, criticism reorganizes the present, and moral-systematic completion remains future."]],"MC_BA94_L1_08:GA-14":[["[Terminal] The system terminates in bounded theoretical authority, practically governed commitment, open inquiry, and prospective rather than completed architectonic closure.","The system terminates in bounded theoretical authority, practically governed commitment, open inquiry, and prospective rather than completed architectonic closure."]],"WB_BA94:GA-01":[["[Persistent] Finite cognition requires irreducibly differentiated sensible presentation and conceptual synthesis under the common restriction of possible experience.","Finite cognition requires irreducibly differentiated sensible presentation and conceptual synthesis under the common restriction of possible experience."]],"WB_BA94:GA-02":[["[Attractor] Mediation is the operative center through which cognitive functions acquire authority only by being coordinated within their proper jurisdictions.","Mediation is the operative center through which cognitive functions acquire authority only by being coordinated within their proper jurisdictions."]],"WB_BA94:GA-03":[["[Attractor] Possible experience is simultaneously the constituted field of objective cognition and the tribunal testing every theoretical claim to object-reference.","Possible experience is simultaneously the constituted field of objective cognition and the tribunal testing every theoretical claim to object-reference."]],"WB_BA94:GA-04":[["[Mutating] Objectivity changes from presumed correspondence with independent being into universally necessary, temporally enacted, and jurisdictionally restricted synthesis.","Objectivity changes from presumed correspondence with independent being into universally necessary, temporally enacted, and jurisdictionally restricted synthesis."]],"WB_BA94:GA-05":[["[Mutating] The subject is generated as an apperceptive integrating function and subsequently divided into projector, legislator, accused party, critic, and finite believer.","The subject is generated as an apperceptive integrating function and subsequently divided into projector, legislator, accused party, critic, and finite believer."]],"WB_BA94:GA-06":[["[Attractor] The field of conditioned experience necessarily activates reason’s demand for complete determination, systematic unity, and an unconditioned ground.","The field of conditioned experience necessarily activates reason’s demand for complete determination, systematic unity, and an unconditioned ground."]],"WB_BA94:GA-07":[["[Emergent] Transcendental illusion is generated when valid conceptual or inferential functions are detached from sensible authorization and transferred to unpresentable total objects.","Transcendental illusion is generated when valid conceptual or inferential functions are detached from sensible authorization and transferred to unpresentable total objects."]],"WB_BA94:GA-08":[["[Emergent] Contradiction and proof collapse acquire critical force by exposing an invalid completed object-model shared by opposed metaphysical claims.","Contradiction and proof collapse acquire critical force by exposing an invalid completed object-model shared by opposed metaphysical claims."]],"WB_BA94:GA-09":[["[Emergent] Critique is a positive governance mechanism that produces valid cognition by allocating, restricting, and coordinating heterogeneous rational functions.","Critique is a positive governance mechanism that produces valid cognition by allocating, restricting, and coordinating heterogeneous rational functions."]],"WB_BA94:GA-10":[["[Persistent] Rational validity is topological because differentiated faculties and functions support irreducibly distinct modes of authorization rather than one homogeneous scale.","Rational validity is topological because differentiated faculties and functions support irreducibly distinct modes of authorization rather than one homogeneous scale."]],"WB_BA94:GA-11":[["[Mutating] Limitation changes from apparent deprivation into the condition protecting objective validity, empirical openness, practical commitment, and systematic orientation.","Limitation changes from apparent deprivation into the condition protecting objective validity, empirical openness, practical commitment, and systematic orientation."]],"WB_BA94:GA-12":[["[Terminal] Supersensible objects remain theoretically indeterminate, and their regulative or practical recovery cannot restore theoretical objecthood.","Supersensible objects remain theoretically indeterminate, and their regulative or practical recovery cannot restore theoretical objecthood."]],"WB_BA94:GA-13":[["[Terminal] Formal legislation and jurisdiction can close while particular empirical determinations and the realization of rational ends remain unfinished.","Formal legislation and jurisdiction can close while particular empirical determinations and the realization of rational ends remain unfinished."]],"WB_BA94:GA-14":[["[Attractor] Rational autonomy consists in recursively legislating and criticizing authority through the same finite powers whose legitimacy remains under examination.","Rational autonomy consists in recursively legislating and criticizing authority through the same finite powers whose legitimacy remains under examination."]],"WB_BA94:RMD-01":[["[Stable identity with expansion] Experience remains cognition’s field but expands from constituted outcome into the central jurisdictional pole governing theoretical reference.","Experience remains cognition’s field but expands from constituted outcome into the central jurisdictional pole governing theoretical reference."]],"WB_BA94:RMD-02":[["[Serial mutation] Synthesis escalates from the prior operation of object-constitution into lawful natural legislation and becomes dialectical totalization when extended beyond presentation.","Synthesis escalates from the prior operation of object-constitution into lawful natural legislation and becomes dialectical totalization when extended beyond presentation."]],"WB_BA94:RMD-03":[["[Functional recurrence] Faculty differentiation migrates from an account of cognitive production into a constitutional prohibition against jurisdictional substitution.","Faculty differentiation migrates from an account of cognitive production into a constitutional prohibition against jurisdictional substitution."]],"WB_BA94:RMD-04":[["[Subject mutation] Subjectivity reverses from suspected distortion into a universal formal condition, then becomes a divided architect implicated in its own projections.","Subjectivity reverses from suspected distortion into a universal formal condition, then becomes a divided architect implicated in its own projections."]],"WB_BA94:RMD-05":[["[Domain expansion] Time develops from sensible form and schematic medium into the recursive asymmetry of incomplete self-presence, regress, criticism, and prospective completion.","Time develops from sensible form and schematic medium into the recursive asymmetry of incomplete self-presence, regress, criticism, and prospective completion."]],"WB_BA94:RMD-06":[["[Valence reversal] Critique and negation change from restraint into the constructive, institutional, and procedural governance of positive rational production.","Critique and negation change from restraint into the constructive, institutional, and procedural governance of positive rational production."]],"WB_BA94:RMD-07":[["[Reversal] Contradiction changes from an apparent collision within reality into a diagnostic instrument for exposing valid forms operating through an invalid object-model.","Contradiction changes from an apparent collision within reality into a diagnostic instrument for exposing valid forms operating through an invalid object-model."]],"WB_BA94:RMD-08":[["[Absorption] Noumenal objecthood and the unconditioned are absorbed into a differentiated boundary architecture of negative limit, regulative horizon, practical concern, and architectonic destination.","Noumenal objecthood and the unconditioned are absorbed into a differentiated boundary architecture of negative limit, regulative horizon, practical concern, and architectonic destination."]],"WB_BA94:RMD-09":[["[Terminal transformation] Completion ceases to mean possession of total content and becomes formal completeness in the allocation of permanently open inquiry.","Completion ceases to mean possession of total content and becomes formal completeness in the allocation of permanently open inquiry."]],"CH_THN_SIOO:D1":[["The perception field is organized by two intersecting distinctions: impression versus idea and simple versus complex. (from Axioms CH_THN_SIOO:A1 + CH_THN_SIOO:A4 + CH_THN_SIOO:A5 + CH_THN_SIOO:A6)","The perception field is organized by two intersecting distinctions: impression versus idea and simple versus complex."]],"CH_THN_SIOO:D2":[["Failure of exact complex correspondence does not defeat exact correspondence at the simple level. (from Axioms CH_THN_SIOO:A6 + CH_THN_SIOO:A7 + CH_THN_SIOO:A8)","Failure of exact complex correspondence does not defeat exact correspondence at the simple level."]],"CH_THN_SIOO:D3":[["Corresponding simple impressions and ideas form dependent rather than accidental pairs. (from Axioms CH_THN_SIOO:A7 + CH_THN_SIOO:A9)","Corresponding simple impressions and ideas form dependent rather than accidental pairs."]],"CH_THN_SIOO:D4":[["Impressions are causes and first ideas are effects. (from Axioms CH_THN_SIOO:A9 + CH_THN_SIOO:A10 + CH_THN_SIOO:A11)","Impressions are causes and first ideas are effects."]],"CH_THN_SIOO:D5":[["Normal acquisition of a simple idea requires operative access to its corresponding impression. (from Axioms CH_THN_SIOO:A12 + CH_THN_SIOO:A13)","Normal acquisition of a simple idea requires operative access to its corresponding impression."]],"CH_THN_SIOO:D6":[["Complex imagination may exceed experienced wholes without exceeding impression-derived simple content. (from Axioms CH_THN_SIOO:A6 + CH_THN_SIOO:A7 + CH_THN_SIOO:A8 + CH_THN_SIOO:A13)","Complex imagination may exceed experienced wholes without exceeding impression-derived simple content."]],"CH_THN_SIOO:D7":[["Ideas may generate further ideas without becoming the ultimate source of their simple content. (from Axioms CH_THN_SIOO:A13 + CH_THN_SIOO:A14)","Ideas may generate further ideas without becoming the ultimate source of their simple content."]],"CH_THN_SIOO:D8":[["The admitted missing-shade case converts the derivation principle logically into an exception-tolerant general maxim. (from Axioms CH_THN_SIOO:A13 + CH_THN_SIOO:A15 + CH_THN_SIOO:A16)","The admitted missing-shade case converts the derivation principle logically into an exception-tolerant general maxim."]],"CH_THN_SIOO:D9":[["The dispute over innate ideas is reconstructed as a question of whether ideas are preceded by livelier perceptions. (from Axioms CH_THN_SIOO:A2 + CH_THN_SIOO:A3 + CH_THN_SIOO:A11 + CH_THN_SIOO:A13)","The dispute over innate ideas is reconstructed as a question of whether ideas are preceded by livelier perceptions."]],"CH_THN_SIIM:D1":[["Memory and imagination differ by mode of recurrence rather than by the origin of their contents. (from Axioms CH_THN_SIIM:A1 + CH_THN_SIIM:A2 + CH_THN_SIIM:A3 + CH_THN_SIIM:A4)","Memory and imagination differ by mode of recurrence rather than by the origin of their contents."]],"CH_THN_SIIM:D2":[["Memory ideas are more forceful, lively, distinct, and stable than imagination ideas. (from Axioms CH_THN_SIIM:A3 + CH_THN_SIIM:A4)","Memory ideas are more forceful, lively, distinct, and stable than imagination ideas."]],"CH_THN_SIIM:D3":[["Memory’s characteristic work is preservation of relational order and position rather than preservation of simple contents as such. (from Axioms CH_THN_SIIM:A2 + CH_THN_SIIM:A5 + CH_THN_SIIM:A10)","Memory’s characteristic work is preservation of relational order and position rather than preservation of simple contents as such."]],"CH_THN_SIIM:D4":[["Deliberate narrative reordering remains compatible with memory when due positions are retained. (from Axioms CH_THN_SIIM:A5 + CH_THN_SIIM:A6)","Deliberate narrative reordering remains compatible with memory when due positions are retained."]],"CH_THN_SIIM:D5":[["Imagination can form unexperienced complexes by separating and rearranging impression-derived components. (from Axioms CH_THN_SIIM:A2 + CH_THN_SIIM:A7 + CH_THN_SIIM:A9 + CH_THN_SIIM:A10)","Imagination can form unexperienced complexes by separating and rearranging impression-derived components."]],"CH_THN_SIIM:D6":[["Perceived difference becomes compositional liberty because distinguishable components are separable rather than necessarily conjoined. (from Axioms CH_THN_SIIM:A7 + CH_THN_SIIM:A8 + CH_THN_SIIM:A9)","Perceived difference becomes compositional liberty because distinguishable components are separable rather than necessarily conjoined."]],"CH_THN_SVIE:MRT1":[["CH_THN_SVIE:A1 through CH_THN_SVIE:A9 are sufficient to reconstruct both the existence argument and its extension to external existence.","The chapter’s axioms are sufficient to reconstruct both the existence argument and its extension to external existence."]],"CH_THN_SVNI:D1":[["From CH_THN_SVNI:A2 + CH_THN_SVNI:A3 + CH_THN_SVNI:A6: bare conception, existential conception, and existential belief can preserve identical object-content.","Bare conception, existential conception, and existential belief can preserve identical object-content."]],"CH_THN_SVNI:D2":[["From CH_THN_SVNI:A4 + CH_THN_SVNI:A5 + CH_THN_SVNI:A6: factual assent cannot be identified by contradiction, intelligibility, or semantic content.","Factual assent cannot be identified by contradiction, intelligibility, or semantic content."]],"CH_THN_SVNI:D3":[["From CH_THN_SVNI:A7 + CH_THN_SVNI:A8 + CH_THN_SVNI:A11: the principle fixing opinion must operate through scalar intensification rather than representational modification.","The principle fixing opinion must operate through scalar intensification rather than representational modification."]],"CH_THN_SVNI:D4":[["From CH_THN_SVNI:A2 + CH_THN_SVNI:A16: existential judgments can contain only one object-idea, invalidating the universal model of judgment as the union of two ideas.","Existential judgments can contain only one object-idea, invalidating the universal model of judgment as the union of two ideas."]],"CH_THN_SVNI:D5":[["From CH_THN_SVNI:A13 + CH_THN_SVNI:A14 + CH_THN_SVNI:A16: causal inference can pass directly from a present perception to a correlative idea without an interposed third idea.","Causal inference can pass directly from a present perception to a correlative idea without an interposed third idea."]],"CH_THN_SVNI:D6":[["From CH_THN_SVNI:A12 + CH_THN_SVNI:A15: belief distinguishes experienced reality from fiction by cognitive weight and practical influence despite representational identity.","Belief distinguishes experienced reality from fiction by cognitive weight and practical influence despite representational identity."]],"CH_THN_SVNI:D7":[["From CH_THN_SVNI:A9 + CH_THN_SVNI:A11 + CH_THN_SVNI:A12: belief is not a third species of perception but an idea intensified toward the condition of an impression.","Belief is not a third species of perception but an idea intensified toward the condition of an impression."]],"CH_THN_SVNI:D8":[["From CH_THN_SVNI:A12 + CH_THN_SVNI:A17: force, vivacity, solidity, firmness, and steadiness are approximate names for one felt mode rather than separate constituents of belief.","Force, vivacity, solidity, firmness, and steadiness are approximate names for one felt mode rather than separate constituents of belief."]],"CH_THN_SVNI:MRT1":[["CH_THN_SVNI:A1–CH_THN_SVNI:A17 are sufficient to reconstruct the movement from representational invariance to the intensive definition of belief.","The chapter’s axioms are sufficient to reconstruct the movement from representational invariance to the intensive definition of belief."]],"CH_THN_SXUP:D1":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7, the same remembered fact loses authority as its impression fades despite retaining the same propositional content.","The same remembered fact loses authority as its impression fades despite retaining the same propositional content."]],"CH_THN_SXUP:D2":[["From CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A5 + CH_THN_SXUP:A7 + CH_THN_SXUP:A14, recent observations receive disproportionate weight because both their impressions and their customary transitions remain intact.","Recent observations receive disproportionate weight because both their impressions and their customary transitions remain intact."]],"CH_THN_SXUP:D3":[["From CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7, demonstratively connected reasoning can psychologically degenerate into probability when it requires many distinct transitions.","Demonstratively connected reasoning can psychologically degenerate into probability when it requires many distinct transitions."]],"CH_THN_SXUP:D4":[["From CH_THN_SXUP:A4 + CH_THN_SXUP:A8, historical evidence survives long transmission when repeated links are sufficiently homogeneous to be traversed as a compressed general sequence.","Historical evidence survives long transmission when repeated links are sufficiently homogeneous to be traversed as a compressed general sequence."]],"CH_THN_SXUP:D5":[["From CH_THN_SXUP:A7 + CH_THN_SXUP:A8, a chain composed of genuinely distinct probabilistic links would undergo repeated diminution, whereas homogeneous proof-preserving links need not.","A chain composed of genuinely distinct probabilistic links would undergo repeated diminution, whereas homogeneous proof-preserving links need not."]],"CH_THN_SXUP:D6":[["From CH_THN_SXUP:A5 + CH_THN_SXUP:A6 + CH_THN_SXUP:A10, prejudice is ordinary causal habit extended from conspicuous resemblance while material differences are neglected.","Prejudice is ordinary causal habit extended from conspicuous resemblance while material differences are neglected."]],"CH_THN_SXUP:D7":[["From CH_THN_SXUP:A10 + CH_THN_SXUP:A11 + CH_THN_SXUP:A12, philosophical correction occurs when a more general rule reclassifies a first-order customary inference as accidental.","Philosophical correction occurs when a more general rule reclassifies a first-order customary inference as accidental."]],"CH_THN_SXUP:D8":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A4 + CH_THN_SXUP:A12 + CH_THN_SXUP:A13 + CH_THN_SXUP:A14, convergence between judgment and a common sign produces stronger affect than an equally certain conclusion assembled from oblique signs.","Convergence between judgment and a common sign produces stronger affect than an equally certain conclusion assembled from oblique signs."]],"CH_THN_SXUP:D9":[["From CH_THN_SXUP:A11 + CH_THN_SXUP:A13 + CH_THN_SXUP:A14, social rules can make an originally stronger offense indirectly less painful by supplying a vivid adverse inference about the offender.","Social rules can make an originally stronger offense indirectly less painful by supplying a vivid adverse inference about the offender."]],"CH_THN_SXUP:D10":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A2 + CH_THN_SXUP:A3 + CH_THN_SXUP:A4 + CH_THN_SXUP:A9, memory, proof, and probability form a descending continuum of vivacity rather than distinct species of belief.","Memory, proof, and probability form a descending continuum of vivacity rather than distinct species of belief."]],"CH_THN_SXUP:SD1":[["From CH_THN_SXUP:A5 + CH_THN_SXUP:A10 + CH_THN_SXUP:A11 + CH_THN_SXUP:A12, philosophical correction redirects custom from first-order resemblance toward more extensive regularity rather than opposing custom with an independent faculty.","Philosophical correction redirects custom from first-order resemblance toward more extensive regularity rather than opposing custom with an independent faculty."]],"CH_THN_SXUP:SD2":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A4 + CH_THN_SXUP:A7 + CH_THN_SXUP:A13, logical warrant and experienced conviction can vary independently because only the latter tracks the transmission of vivacity.","Logical warrant and experienced conviction can vary independently because only the latter tracks the transmission of vivacity."]],"CH_THN_SXUP:SD3":[["From CH_THN_SXUP:A7 + CH_THN_SXUP:A8 + CH_THN_SXUP:A13, effective inferential distance is determined by cognitive heterogeneity and labor rather than by the number of links alone.","Effective inferential distance is determined by cognitive heterogeneity and labor rather than by the number of links alone."]],"CH_THN_SXUP:SD4":[["From CH_THN_SXUP:A13 + CH_THN_SXUP:A14, modes of presentation can reorganize passion without altering the conclusion accepted by judgment.","Modes of presentation can reorganize passion without altering the conclusion accepted by judgment."]],"CH_THN_SXUP:SD5":[["From CH_THN_SXUP:A1 + CH_THN_SXUP:A2 + CH_THN_SXUP:A3 + CH_THN_SXUP:A9, proof and probability differ by the organization and intensity of one mechanism, not by possessing different psychological foundations.","Proof and probability differ by the organization and intensity of one mechanism, not by possessing different psychological foundations."]],"CH_THN_SXUP:SD6":[["From CH_THN_SXUP:A12 + CH_THN_SXUP:A15, philosophy remains disposition-sensitive because either the prejudicial rule or its corrective metarule may prevail in a particular mind.","Philosophy remains disposition-sensitive because either the prejudicial rule or its corrective metarule may prevail in a particular mind."]],"CH_THN_SVME:D1":[["(from CH_THN_SVME:A2 + CH_THN_SVME:A3 + CH_THN_SVME:A4) Comparison can change judgment while leaving representation unchanged because contrast alters the attendant emotion and custom attributes that alteration to the object.","Comparison can change judgment while leaving representation unchanged because contrast alters the attendant emotion and custom attributes that alteration to the object."]],"CH_THN_SVME:D2":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A5 + CH_THN_SVME:A6) Another’s misery elevates one’s apparent happiness and produces pleasure, while another’s happiness diminishes it and produces pain.","Another’s misery elevates one’s apparent happiness and produces pleasure, while another’s happiness diminishes it and produces pain."]],"CH_THN_SVME:D3":[["(from CH_THN_SVME:A6) The same misery can be painful under direct survey and pleasurable under comparative survey.","The same misery can be painful under direct survey and pleasurable under comparative survey."]],"CH_THN_SVME:D4":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A5) Past pain becomes agreeable when contrasted with present satisfaction, while past pleasure becomes painful when contrasted with present deficiency.","Past pain becomes agreeable when contrasted with present satisfaction, while past pleasure becomes painful when contrasted with present deficiency."]],"CH_THN_SVME:D5":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A12) Self-inflicted suffering can remove a contrast that would otherwise intensify predominant grief or the imagined punishment of remorse.","Self-inflicted suffering can remove a contrast that would otherwise intensify predominant grief or the imagined punishment of remorse."]],"CH_THN_SVME:D6":[["(from CH_THN_SVME:A1 + CH_THN_SVME:A3 + CH_THN_SVME:A5 + CH_THN_SVME:A10) An inferior’s approach converts decreased comparative pleasure into positive pain by comparing the reduced advantage with its former degree.","An inferior’s approach converts decreased comparative pleasure into positive pain by comparing the reduced advantage with its former degree."]],"CH_THN_SVME:D7":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A9 + CH_THN_SVME:A10) Nearby or resembling rivals provoke more envy than remote superiors because proximity sustains the transition required for comparison.","Nearby or resembling rivals provoke more envy than remote superiors because proximity sustains the transition required for comparison."]],"CH_THN_SVME:D8":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A9) Separating related objects into distinct conceptual units prevents their attendant passions from influencing or contradicting one another.","Separating related objects into distinct conceptual units prevents their attendant passions from influencing or contradicting one another."]],"CH_THN_SVME:D9":[["(from CH_THN_SVME:A7 + CH_THN_SVME:A8 + CH_THN_SVME:A10) The mind seeks relief from related superiority either by breaking the association or by removing the superiority itself.","The mind seeks relief from related superiority either by breaking the association or by removing the superiority itself."]],"CH_THN_SVME:MRT1":[["CH_THN_SVME:A1–CH_THN_SVME:A12 are sufficient to reconstruct the perceptual mechanism, passion differentiation, and relational boundary.","The chapter’s axioms are sufficient to reconstruct the perceptual mechanism, passion differentiation, and relational boundary."]],"CH_THN_PIJI:MRT1":[["CH_THN_PIJI:A1–CH_THN_PIJI:A18 are sufficient to reconstruct the argument’s semantic, motivational, genealogical, institutional, and sentimental stages.","The chapter’s axioms are sufficient to reconstruct the argument’s semantic, motivational, genealogical, institutional, and sentimental stages."]],"CH_THN_SIRW:MRT1":[["CH_THN_SIRW:A1 through CH_THN_SIRW:A16 are sufficient to reconstruct the allocation problem, the dual explanatory mechanism, and the four established titles.","The chapter’s axioms are sufficient to reconstruct the allocation problem, the dual explanatory mechanism, and the four established titles."]],"CH_THN_SVSF:MRT1":[["CH_THN_SVSF:A1–CH_THN_SVSF:A17 are sufficient to reconstruct the chapter’s three proofs and final two-foundation model.","The chapter’s axioms are sufficient to reconstruct the chapter’s three proofs and final two-foundation model."]],"CH_THN_SIGB:MRT1":[["CH_THN_SIGB:A1–CH_THN_SIGB:A14 are sufficient to reconstruct the dual-source account of benevolent merit and its relational closure.","The chapter’s axioms are sufficient to reconstruct the dual-source account of benevolent merit and its relational closure."]],"CL_THN_01:GA-01":[["[Attractor] A secure science of human nature is the strategic center of scientific reconstruction because human faculties mediate every scientific judgment.","A secure science of human nature is the strategic center of scientific reconstruction because human faculties mediate every scientific judgment."]],"CL_THN_01:GA-02":[["[Persistent] Mental inquiry must proceed from experienced operations, effects, and relations rather than from speculative access to mental essence.","Mental inquiry must proceed from experienced operations, effects, and relations rather than from speculative access to mental essence."]],"CL_THN_01:GA-03":[["[Emergent] Empirical investigation of mind requires both a taxonomy of perceptions and a genealogy specifying their dependency and order.","Empirical investigation of mind requires both a taxonomy of perceptions and a genealogy specifying their dependency and order."]],"CL_THN_01:GA-04":[["[Persistent] Simple ideas generally derive on first appearance from corresponding prior simple impressions.","Simple ideas generally derive on first appearance from corresponding prior simple impressions."]],"CL_THN_01:GA-05":[["[Emergent] Restriction at the level of simple content permits recombination and recursive productivity at the level of complex ideas and later perceptions.","Restriction at the level of simple content permits recombination and recursive productivity at the level of complex ideas and later perceptions."]],"CL_THN_01:GA-06":[["[Mutating] Temporal priority establishes causal direction only within a specified dependency relation; it cannot assign one absolute order to impressions and ideas as total classes.","Temporal priority establishes causal direction only within a specified dependency relation; it cannot assign one absolute order to impressions and ideas as total classes."]],"CL_THN_01:GA-07":[["[Mutating] Ideas are derivative copies relative to sensation but productive mediators relative to impressions of reflection.","Ideas are derivative copies relative to sensation but productive mediators relative to impressions of reflection."]],"CL_THN_01:GA-08":[["[Emergent] Mental life forms an asymmetrically grounded recursive sequence: sensation → idea → reflection → idea → possible further perception.","Mental life forms an asymmetrically grounded recursive sequence: sensation → idea → reflection → idea → possible further perception."]],"CL_THN_01:GA-09":[["[Mutating] Proper methodological order follows the operative antecedents of the selected object, not necessarily the chronology of absolute origin.","Proper methodological order follows the operative antecedents of the selected object, not necessarily the chronology of absolute origin."]],"CL_THN_01:GA-10":[["[Terminal] The ultimate causes of sensation and the original qualities of human nature remain unavailable; legitimate explanation terminates at maximally general experienced relations.","The ultimate causes of sensation and the original qualities of human nature remain unavailable; legitimate explanation terminates at maximally general experienced relations."]],"CL_THN_01:GA-11":[["[Mutating] Scientific warrant at this level belongs to stable empirical generalization rather than exceptionless universality.","Scientific warrant at this level belongs to stable empirical generalization rather than exceptionless universality."]],"CL_THN_01:GA-12":[["[Attractor] The human subject functions as both the medium of inquiry and a relay within the perception-chain being investigated.","The human subject functions as both the medium of inquiry and a relay within the perception-chain being investigated."]],"CL_THN_01:CGD-01":[["[Local] The initial diagnosis of philosophical discredit and rhetorical controversy motivates the reconstruction but does not itself govern the later perceptual machinery.","The initial diagnosis of philosophical discredit and rhetorical controversy motivates the reconstruction but does not itself govern the later perceptual machinery."]],"CL_THN_01:CGD-02":[["[Local] Force and liveliness provide the initial impression–idea distinction, but exceptional states prevent them from functioning as the complete current-level criterion.","Force and liveliness provide the initial impression–idea distinction, but exceptional states prevent them from functioning as the complete current-level criterion."]],"CL_THN_01:CGD-03":[["[Local] The missing-shade case remains a concentrated anomaly rather than an alternative generative principle.","The missing-shade case remains a concentrated anomaly rather than an alternative generative principle."]],"CL_THN_01:CGD-04":[["[Scales upward] The prohibition on essence-first explanation becomes the common boundary governing both the science of human nature and the origin of perception.","The prohibition on essence-first explanation becomes the common boundary governing both the science of human nature and the origin of perception."]],"CL_THN_01:CGD-05":[["[Bridge] The simple–complex distinction links empirical restriction to imaginative productivity: primitive content is constrained while complex formation remains open.","The simple–complex distinction links empirical restriction to imaginative productivity: primitive content is constrained while complex formation remains open."]],"CL_THN_01:CGD-06":[["[Catalyst] Division of impressions into sensation and reflection converts the linear copy model into an asymmetrical recursive system.","Division of impressions into sensation and reflection converts the linear copy model into an asymmetrical recursive system."]],"CL_THN_01:CGD-07":[["[Superseded] Undifferentiated impressions-first method is recoded as a default valid only before object, scope, and internal dependency are specified.","Undifferentiated impressions-first method is recoded as a default valid only before object, scope, and internal dependency are specified."]],"CL_THN_01:CGD-08":[["[Scales upward] Disciplinary exclusion of sensory causes becomes a general methodological principle: proximate operations may be investigated securely without resolving absolute origins.","Disciplinary exclusion of sensory causes becomes a general methodological principle: proximate operations may be investigated securely without resolving absolute origins."]],"CL_THN_02:GA-01":[["[Persistent] Every legitimate idea must derive its elemental content from antecedent impression-material.","Every legitimate idea must derive its elemental content from antecedent impression-material."]],"CL_THN_02:GA-02":[["[Emergent] Elemental provenance and relational organization are distinct explanatory levels: identical copied materials can support preservation, recombination, association, or ordered appearance.","Elemental provenance and relational organization are distinct explanatory levels: identical copied materials can support preservation, recombination, association, or ordered appearance."]],"CL_THN_02:GA-03":[["[Attractor] Order is the common object of the cluster: memory conserves it, imagination alters it, association regenerates it, and space and time consist in its coexistent or successive forms.","Order is the common object of the cluster: memory conserves it, imagination alters it, association regenerates it, and space and time consist in its coexistent or successive forms."]],"CL_THN_02:GA-04":[["[Mutating] Difference licenses distinguishability and separability, but separation remains possible only where a positive component can be conceived apart.","Difference licenses distinguishability and separability, but separation remains possible only where a positive component can be conceived apart."]],"CL_THN_02:GA-05":[["[Persistent] Memory is recurrence under retained vivacity and fidelity to the experienced form, order, and position of its objects.","Memory is recurrence under retained vivacity and fidelity to the experienced form, order, and position of its objects."]],"CL_THN_02:GA-06":[["[Persistent] Imagination is dependent at the level of simple contents but free to separate, transpose, and recombine those contents at the level of arrangement.","Imagination is dependent at the level of simple contents but free to separate, transpose, and recombine those contents at the level of arrangement."]],"CL_THN_02:GA-07":[["[Emergent] Associative tendency mediates between compulsory connexion and random succession, producing regularity without abolishing imaginative liberty.","Associative tendency mediates between compulsory connexion and random succession, producing regularity without abolishing imaginative liberty."]],"CL_THN_02:GA-08":[["[Persistent] Resemblance, spatiotemporal contiguity, and cause and effect are the primary operators by which one idea introduces another.","Resemblance, spatiotemporal contiguity, and cause and effect are the primary operators by which one idea introduces another."]],"CL_THN_02:GA-09":[["[Mutating] Relational efficacy is graded: it propagates through intermediaries, weakens with distance, and expands causally from production to capacity and social influence.","Relational efficacy is graded: it propagates through intermediaries, weakens with distance, and expands causally from production to capacity and social influence."]],"CL_THN_02:GA-10":[["[Emergent] Space and time are ordered manners of appearance rather than independent impressions: extension is coexistent disposition, and duration is noncoexistent succession.","Space and time are ordered manners of appearance rather than independent impressions: extension is coexistent disposition, and duration is noncoexistent succession."]],"CL_THN_02:GA-11":[["[Mutating] Abstraction produces general representation by selectively regarding a determinate particular, not by generating a contentless universal.","Abstraction produces general representation by selectively regarding a determinate particular, not by generating a contentless universal."]],"CL_THN_02:GA-12":[["[Attractor] An idea’s genealogy limits its legitimate application: recombination may alter conjunctions, but predication cannot properly exceed the kind of content or order supplied by the originating impression.","An idea’s genealogy limits its legitimate application: recombination may alter conjunctions, but predication cannot properly exceed the kind of content or order supplied by the originating impression."]],"CL_THN_02:GA-13":[["[Terminal] Empirical explanation may stop at a recurrent principle established through its effects even when the ultimate cause of that principle remains inaccessible.","Empirical explanation may stop at a recurrent principle established through its effects even when the ultimate cause of that principle remains inaccessible."]],"CL_THN_02:GA-14":[["[Terminal] Conceptual decomposition cannot terminate in nonentity: spatial minima must retain sensible quality, and temporal minima must be filled by successive existence.","Conceptual decomposition cannot terminate in nonentity: spatial minima must retain sensible quality, and temporal minima must be filled by successive existence."]],"CL_THN_02:CGD-01":[["[Local] The precise degree of vivacity distinguishing memory from imagination remains a faculty-specific criterion and does not govern association or spatiotemporal conception.","The precise degree of vivacity distinguishing memory from imagination remains a faculty-specific criterion and does not govern association or spatiotemporal conception."]],"CL_THN_02:CGD-02":[["[Local] The claim that sight and touch alone provide extension’s source is required for spatial genealogy but does not scale into a general theory of all ideational recurrence.","The claim that sight and touch alone provide extension’s source is required for spatial genealogy but does not scale into a general theory of all ideational recurrence."]],"CL_THN_02:CGD-03":[["[Local] The asserted exhaustiveness of resemblance, contiguity, and causation remains local to the associative taxonomy; the current level requires only nonnecessary relational regulation.","The asserted exhaustiveness of resemblance, contiguity, and causation remains local to the associative taxonomy; the current level requires only nonnecessary relational regulation."]],"CL_THN_02:CGD-04":[["[Scaled] The copy principle scales upward because it constrains faculty content, abstract representation, spatial and temporal conception, and semantic application.","The copy principle scales upward because it constrains faculty content, abstract representation, spatial and temporal conception, and semantic application."]],"CL_THN_02:CGD-05":[["[Scaled] The distinction between content and arrangement becomes the cluster’s primary architecture, subsuming memory, imagination, association, space, and time.","The distinction between content and arrangement becomes the cluster’s primary architecture, subsuming memory, imagination, association, space, and time."]],"CL_THN_02:CGD-06":[["[Bridge] Separability connects imaginative composition to conceptual analysis, but its cross-unit use requires distinguishing separation from an original complex from separation from every content-bearing instance.","Separability connects imaginative composition to conceptual analysis, but its cross-unit use requires distinguishing separation from an original complex from separation from every content-bearing instance."]],"CL_THN_02:CGD-07":[["[Catalyst] Imaginative freedom generates the problem solved by association: once ideas can combine arbitrarily, recurrent regularity demands a non-random but noncompulsory principle.","Imaginative freedom generates the problem solved by association: once ideas can combine arbitrarily, recurrent regularity demands a non-random but noncompulsory principle."]],"CL_THN_02:CGD-08":[["[Superseded] The binary opposition between necessary determination and pure chance is replaced by graded tendency, custom, and attenuating relational force.","The binary opposition between necessary determination and pure chance is replaced by graded tendency, custom, and attenuating relational force."]],"CL_THN_02:CGD-09":[["[Recoded] Fiction is divided into lawful relational recombination and genealogically unsupported predication; novelty alone no longer determines illegitimacy.","Fiction is divided into lawful relational recombination and genealogically unsupported predication; novelty alone no longer determines illegitimacy."]],"CL_THN_02:CGD-10":[["[Transition] The expansion of causal association into social power demonstrates domain migration, but it does not itself govern the spatial and temporal ontology of the cluster.","The expansion of causal association into social power demonstrates domain migration, but it does not itself govern the spatial and temporal ontology of the cluster."]],"CL_THN_02:ALT-B01":[["[Surface] The explicit objects are memory, imagination, ideational association, extension, duration, abstraction, and the formation of complex ideas.","The explicit objects are memory, imagination, ideational association, extension, duration, abstraction, and the formation of complex ideas."]],"CL_THN_02:ALT-B02":[["[Structural] The active mechanisms are copying, recurrence, vivacity loss, order preservation, separation, recombination, associative routing, abstraction, and decomposition.","The active mechanisms are copying, recurrence, vivacity loss, order preservation, separation, recombination, associative routing, abstraction, and decomposition."]],"CL_THN_02:ALT-B03":[["[Metastrategic] Conceptual disputes are reframed as questions of source, operation, relational distance, and permissible application rather than contests among untested metaphysical entities.","Conceptual disputes are reframed as questions of source, operation, relational distance, and permissible application rather than contests among untested metaphysical entities."]],"CL_THN_02:ALT-B04":[["[Ontological / Temporal] Reality available to thought consists of content-bearing configurations, while time emerges from perceptible noncoexistence and is preserved or rearranged through mental recurrence.","Reality available to thought consists of content-bearing configurations, while time emerges from perceptible noncoexistence and is preserved or rearranged through mental recurrence."]],"CL_THN_02:ALT-B05":[["[Methodological / Performative] The system repeatedly performs its own claim by decomposing apparent unities, tracing their sources, removing unsupported additions, and reconstructing them as relational operations.","The system repeatedly performs its own claim by decomposing apparent unities, tracing their sources, removing unsupported additions, and reconstructing them as relational operations."]],"CL_THN_03:GA-01":[["[Persistent] Positive conceptual content is restricted to impressions, ideas, and their copied or recombined perceptual materials.","Positive conceptual content is restricted to impressions, ideas, and their copied or recombined perceptual materials."]],"CL_THN_03:GA-02":[["[Persistent] Existence is not an additional quality, predicate, or idea but is identical with the object as conceived.","Existence is not an additional quality, predicate, or idea but is identical with the object as conceived."]],"CL_THN_03:GA-03":[["[Emergent] Bare conception, existential conception, and factual belief can preserve identical representational content while producing radically different cognitive and practical effects.","Bare conception, existential conception, and factual belief can preserve identical representational content while producing radically different cognitive and practical effects."]],"CL_THN_03:GA-04":[["[Mutating] Belief begins as a difference in manner, becomes an intensification of force and vivacity, and terminates as a comparatively steady, impression-related, causally regulated mode.","Belief begins as a difference in manner, becomes an intensification of force and vivacity, and terminates as a comparatively steady, impression-related, causally regulated mode."]],"CL_THN_03:GA-05":[["[Persistent] Since contrary matters of fact remain conceivable, factual selection cannot arise from demonstrative necessity and must be determined by custom or association.","Since contrary matters of fact remain conceivable, factual selection cannot arise from demonstrative necessity and must be determined by custom or association."]],"CL_THN_03:GA-06":[["[Emergent] A present impression functions both as the experiential anchor of inference and as the reservoir from which vivacity is transmitted to a related idea.","A present impression functions both as the experiential anchor of inference and as the reservoir from which vivacity is transmitted to a related idea."]],"CL_THN_03:GA-07":[["[Emergent] Selective vivification gives absent and future objects present motivational efficacy without granting equivalent efficacy to every passing fiction.","Selective vivification gives absent and future objects present motivational efficacy without granting equivalent efficacy to every passing fiction."]],"CL_THN_03:GA-08":[["[Mutating] Force and vivacity expand from a distinction between impressions and ideas into a transmissible causal currency linking belief, passion, imagination, and action.","Force and vivacity expand from a distinction between impressions and ideas into a transmissible causal currency linking belief, passion, imagination, and action."]],"CL_THN_03:GA-09":[["[Emergent] Judgment, imagination, passion, and volition form a reciprocally permeable system rather than independent faculties.","Judgment, imagination, passion, and volition form a reciprocally permeable system rather than independent faculties."]],"CL_THN_03:GA-10":[["[Attractor] Factuality converges on stable practical presence: an idea counts as real for the mind by persistently affecting inference, passion, and conduct without acquiring new content.","Factuality converges on stable practical presence: an idea counts as real for the mind by persistently affecting inference, passion, and conduct without acquiring new content."]],"CL_THN_03:GA-11":[["[Terminal] First-order vividness cannot authenticate itself; settled conviction requires discrimination by source, steadiness, reality-connection, reflection, and general rules.","First-order vividness cannot authenticate itself; settled conviction requires discrimination by source, steadiness, reality-connection, reflection, and general rules."]],"CL_THN_03:GA-12":[["[Attractor] Reality is retained as a regulative relation organizing assent and correction while its intrinsic extra-perceptual nature remains positively unrepresented.","Reality is retained as a regulative relation organizing assent and correction while its intrinsic extra-perceptual nature remains positively unrepresented."]],"CL_THN_04:GA-01":[["[Persistent] Repeated conjunction and close relation acquire cognitive efficacy by facilitating transitions among perceptions rather than by revealing intrinsic bonds among objects.","Repeated conjunction and close relation acquire cognitive efficacy by facilitating transitions among perceptions rather than by revealing intrinsic bonds among objects."]],"CL_THN_04:GA-02":[["[Persistent] Neither substance nor causal power is available through mere inspection; actual causal judgment begins only from experienced relational structure.","Neither substance nor causal power is available through mere inspection; actual causal judgment begins only from experienced relational structure."]],"CL_THN_04:GA-03":[["[Mutating] Ease of mental transition produces belief when it transfers vivacity, but produces fictive identity and simplicity when its own fluency is attributed to objects.","Ease of mental transition produces belief when it transfers vivacity, but produces fictive identity and simplicity when its own fluency is attributed to objects."]],"CL_THN_04:GA-04":[["[Persistent] Natural customary transition precedes reflection and remains active after reflective correction; philosophy can redirect but cannot abolish it.","Natural customary transition precedes reflection and remains active after reflective correction; philosophy can redirect but cannot abolish it."]],"CL_THN_04:GA-05":[["[Mutating] Resemblance extends inference beyond identical cases, becoming prejudice when material differences are neglected and an experimental operator when resemblance is controlled by contrast.","Resemblance extends inference beyond identical cases, becoming prejudice when material differences are neglected and an experimental operator when resemblance is controlled by contrast."]],"CL_THN_04:GA-06":[["[Emergent] Reflection works through comparison, counterinstance, and circumstance-variation; it corrects fluent apprehension by making suppressed differences operationally salient.","Reflection works through comparison, counterinstance, and circumstance-variation; it corrects fluent apprehension by making suppressed differences operationally salient."]],"CL_THN_04:GA-07":[["[Emergent] Philosophical normativity is immanent to custom: more extensive and constant regularities regulate narrower associations without invoking an extra-customary tribunal.","Philosophical normativity is immanent to custom: more extensive and constant regularities regulate narrower associations without invoking an extra-customary tribunal."]],"CL_THN_04:GA-08":[["[Emergent] Actual causation is operationally constituted by contiguous, temporally ordered, uniform conjunction among experimentally discriminated circumstances.","Actual causation is operationally constituted by contiguous, temporally ordered, uniform conjunction among experimentally discriminated circumstances."]],"CL_THN_04:GA-09":[["[Persistent] Phenomena are compound, so causal identity must migrate from whole objects to qualities, differences, and auxiliary circumstances isolated through comparative tests.","Phenomena are compound, so causal identity must migrate from whole objects to qualities, differences, and auxiliary circumstances isolated through comparative tests."]],"CL_THN_04:GA-10":[["[Mutating] Contradiction and disappointed expectation do not determine their own resolution: they can provoke fictive substrates, prejudicial persistence, or renewed experimental decomposition.","Contradiction and disappointed expectation do not determine their own resolution: they can provoke fictive substrates, prejudicial persistence, or renewed experimental decomposition."]],"CL_THN_04:GA-11":[["[Persistent] Evidential warrant and experienced conviction are separable because conviction varies with vivacity, transition, temporal distance, and presentation, while warrant depends on comparative regularity.","Evidential warrant and experienced conviction are separable because conviction varies with vivacity, transition, temporal distance, and presentation, while warrant depends on comparative regularity."]],"CL_THN_04:GA-12":[["[Terminal] Corrective inquiry has no self-applying or final form: every metarule competes with prior habit, and every experiment becomes subject to renewed circumstance-analysis.","Corrective inquiry has no self-applying or final form: every metarule competes with prior habit, and every experiment becomes subject to renewed circumstance-analysis."]],"CL_THN_04:GA-13":[["[Attractor] Legitimate explanation converges on two constraints: terms must possess assignable ideational content, and causal distinctions must survive discriminating variation.","Legitimate explanation converges on two constraints: terms must possess assignable ideational content, and causal distinctions must survive discriminating variation."]],"CL_THN_04:GA-14":[["[Attractor] Moderate scepticism suspends claims to hidden substance and power while preserving disciplined empirical inquiry into observable regularities.","Moderate scepticism suspends claims to hidden substance and power while preserving disciplined empirical inquiry into observable regularities."]],"CL_THN_04:RMD-01":[["[Stable Identity] Constant conjunction retains its function as the empirical condition of causal inference while remaining explicitly distinct from perceived necessary connection.","Constant conjunction retains its function as the empirical condition of causal inference while remaining explicitly distinct from perceived necessary connection."]],"CL_THN_04:RMD-02":[["[Functional Recurrence] Facilitated transition recurs as belief-production, inferential compression, imputed identity, and imputed simplicity; its function changes with the object onto which fluency is projected.","Facilitated transition recurs as belief-production, inferential compression, imputed identity, and imputed simplicity; its function changes with the object onto which fluency is projected."]],"CL_THN_04:RMD-03":[["[Mutation] Custom moves from a first-order producer of expectation and prejudice to the material from which second-order philosophical rules are constructed.","Custom moves from a first-order producer of expectation and prejudice to the material from which second-order philosophical rules are constructed."]],"CL_THN_04:RMD-04":[["[Reversal] Resemblance changes from a source of illicit transfer into a controlled comparative instrument once difference is deliberately introduced.","Resemblance changes from a source of illicit transfer into a controlled comparative instrument once difference is deliberately introduced."]],"CL_THN_04:RMD-05":[["[Migration] Reflective comparison migrates from exposing variation and composition in bodies to isolating causal circumstances within compound phenomena.","Reflective comparison migrates from exposing variation and composition in bodies to isolating causal circumstances within compound phenomena."]],"CL_THN_04:RMD-06":[["[Escalation] The general rule expands from a correction of prejudicial inference into a recursive methodology for causal projection, decomposition, and experimental enlargement.","The general rule expands from a correction of prejudicial inference into a recursive methodology for causal projection, decomposition, and experimental enlargement."]],"CL_THN_04:RMD-07":[["[Displacement] Qualities cease to require a substantial bearer and become separable elements whose causal relevance must be experimentally determined.","Qualities cease to require a substantial bearer and become separable elements whose causal relevance must be experimentally determined."]],"CL_THN_04:RMD-08":[["[Terminal Transformation] Contradiction ceases to be evidence for an unknown substrate and becomes a demand to identify an omitted difference, scope condition, or auxiliary cause.","Contradiction ceases to be evidence for an unknown substrate and becomes a demand to identify an omitted difference, scope condition, or auxiliary cause."]],"CL_THN_04:RMD-09":[["[Absorption] The local theory of vivacity is absorbed into the current-level distinction between psychological uptake and methodological warrant.","The local theory of vivacity is absorbed into the current-level distinction between psychological uptake and methodological warrant."]],"CL_THN_04:RMD-10":[["[Disappearance] Substance, substantial form, accident, faculty, and occult quality disappear after supplying negative cases of how unexplained transition is converted into simulated ontology.","Substance, substantial form, accident, faculty, and occult quality disappear after supplying negative cases of how unexplained transition is converted into simulated ontology."]],"CL_THN_04:CGD-01":[["[Lower-Layer Local] Temporal fading, historical transmission, sign generality, and passion-amplification remain local specifications of how belief-force varies.","Temporal fading, historical transmission, sign generality, and passion-amplification remain local specifications of how belief-force varies."]],"CL_THN_04:CGD-02":[["[Lower-Layer Local] The individual comparative, proportional, and incomplete-cause rules remain local instruments; their recursive subjection to renewed variation scales upward.","The individual comparative, proportional, and incomplete-cause rules remain local instruments; their recursive subjection to renewed variation scales upward."]],"CL_THN_04:CGD-03":[["[Lower-Layer Local] The specific genealogy of matter, substantial forms, accidents, and occult qualities remains a local historical diagnosis.","The specific genealogy of matter, substantial forms, accidents, and occult qualities remains a local historical diagnosis."]],"CL_THN_04:CGD-04":[["[Scaled] The denial of intrinsic causal legibility scales upward into a general restriction against both a priori causal ontology and metaphysical explanation by hidden powers.","The denial of intrinsic causal legibility scales upward into a general restriction against both a priori causal ontology and metaphysical explanation by hidden powers."]],"CL_THN_04:CGD-05":[["[Bridge] The conflict between first-order and second-order general rules bridges the psychology of prejudice and the methodology of experimental causal judgment.","The conflict between first-order and second-order general rules bridges the psychology of prejudice and the methodology of experimental causal judgment."]],"CL_THN_04:CGD-06":[["[Bridge] Smooth mental transition connects belief-formation to fictive object-construction, revealing a shared mechanism beneath epistemic and ontological error.","Smooth mental transition connects belief-formation to fictive object-construction, revealing a shared mechanism beneath epistemic and ontological error."]],"CL_THN_04:CGD-07":[["[Catalyst] Reflectively disclosed contradiction catalyzes the transition from passive customary association to either metaphysical repair or active experimental differentiation.","Reflectively disclosed contradiction catalyzes the transition from passive customary association to either metaphysical repair or active experimental differentiation."]],"CL_THN_04:CGD-08":[["[Recoded] “Same cause” is recoded from identity of whole objects to identity of experimentally isolated operative circumstances.","“Same cause” is recoded from identity of whole objects to identity of experimentally isolated operative circumstances."]],"CL_THN_04:CGD-09":[["[Superseded] Objective substances, intrinsic faculties, and occult agencies are superseded by relational descriptions that remain answerable to assignable ideas and observable variation.","Objective substances, intrinsic faculties, and occult agencies are superseded by relational descriptions that remain answerable to assignable ideas and observable variation."]],"CL_THN_04:CGD-10":[["[Current-Level Emergent] Genuine philosophy becomes the conjunction of psychological self-diagnosis, comparative experiment, and refusal of semantically empty closure.","Genuine philosophy becomes the conjunction of psychological self-diagnosis, comparative experiment, and refusal of semantically empty closure."]],"CL_THN_05:GA-01":[["[Persistent] Legitimate explanation begins from experienced perceptions, conjunctions, pleasures, pains, and their observable transitions rather than from impression-transcendent entities.","Legitimate explanation begins from experienced perceptions, conjunctions, pleasures, pains, and their observable transitions rather than from impression-transcendent entities."]],"CL_THN_05:GA-02":[["[Emergent] Once unknown supports are excluded, the primary explanatory object becomes the network of relations and transformations among perceptions and affects.","Once unknown supports are excluded, the primary explanatory object becomes the network of relations and transformations among perceptions and affects."]],"CL_THN_05:GA-03":[["[Attractor] Imagination is simultaneously the indispensable medium of cognitive and affective synthesis and the source of fictive completion, contradiction, and excess.","Imagination is simultaneously the indispensable medium of cognitive and affective synthesis and the source of fictive completion, contradiction, and excess."]],"CL_THN_05:GA-04":[["[Mutating] Relation is not a uniform binary bond: it changes across separability, spatial compatibility, causal succession, self-reference, comparison, publicity, and temporal durability.","Relation is not a uniform binary bond: it changes across separability, spatial compatibility, causal succession, self-reference, comparison, publicity, and temporal durability."]],"CL_THN_05:GA-05":[["[Persistent] Repetition becomes operational through habit or custom, which projects conjunctions, stabilizes classifications, and regularizes otherwise delicate transitions.","Repetition becomes operational through habit or custom, which projects conjunctions, stabilizes classifications, and regularizes otherwise delicate transitions."]],"CL_THN_05:GA-06":[["[Emergent] Cognitive and affective efficacy requires force: vivacity, pleasure, pain, passion, or propensity must animate a relation before it governs assent or self-evaluation.","Cognitive and affective efficacy requires force: vivacity, pleasure, pain, passion, or propensity must animate a relation before it governs assent or self-evaluation."]],"CL_THN_05:GA-07":[["[Persistent] Causal intelligibility does not require perceived necessity; experienced conjunction and the transition it induces provide the operative causal content.","Causal intelligibility does not require perceived necessity; experienced conjunction and the transition it induces provide the operative causal content."]],"CL_THN_05:GA-08":[["[Persistent] Heterogeneous effects cannot be explained by indiscriminately extending one medium, faculty, or response-class over the entire field.","Heterogeneous effects cannot be explained by indiscriminately extending one medium, faculty, or response-class over the entire field."]],"CL_THN_05:GA-09":[["[Emergent] Unrestricted principles reveal their inadequacy by overgeneration: universal extension, pure reason, unrestricted fancy, and mere self-relation each produce contradictions or false positives.","Unrestricted principles reveal their inadequacy by overgeneration: universal extension, pure reason, unrestricted fancy, and mere self-relation each produce contradictions or false positives."]],"CL_THN_05:GA-10":[["[Mutating] Correction is immanent and restrictive: undecidability, skeptical diffidence, empirical practice, and threshold conditions limit mechanisms without abolishing them.","Correction is immanent and restrictive: undecidability, skeptical diffidence, empirical practice, and threshold conditions limit mechanisms without abolishing them."]],"CL_THN_05:GA-11":[["[Mutating] The self has no established status as a substantial bearer but remains indispensable as an object of passion and a temporally extended standard of comparison.","The self has no established status as a substantial bearer but remains indispensable as an object of passion and a temporally extended standard of comparison."]],"CL_THN_05:GA-12":[["[Emergent] Natural production and representational success do not guarantee correspondence: belief may lack rational foundation, apparent location may be fictive, and self-estimation may diverge from welfare.","Natural production and representational success do not guarantee correspondence: belief may lack rational foundation, apparent location may be fictive, and self-estimation may diverge from welfare."]],"CL_THN_05:GA-13":[["[Terminal] The viable endpoint is a reflexive science of human nature that investigates its own fallible operations under permanent skeptical and empirical restraint.","The viable endpoint is a reflexive science of human nature that investigates its own fallible operations under permanent skeptical and empirical restraint."]],"CL_THN_06:GA-01":[["[Persistent] Ideas and impressions differ principally in force and vivacity, permitting associative processes to transform represented affect into operative passion without changing its content.","Ideas and impressions differ principally in force and vivacity, permitting associative processes to transform represented affect into operative passion without changing its content."]],"CL_THN_06:GA-02":[["[Persistent] Relations are effective only as directed pathways that facilitate, preserve, intensify, interrupt, or redirect imaginative transition.","Relations are effective only as directed pathways that facilitate, preserve, intensify, interrupt, or redirect imaginative transition."]],"CL_THN_06:GA-03":[["[Persistent] Social passion requires a coupling between affective force and a relation that assigns or compares that force to a person.","Social passion requires a coupling between affective force and a relation that assigns or compares that force to a person."]],"CL_THN_06:GA-04":[["[Mutating] The self is not a sovereign source of valuation: its initial vivacity enables the very transitions through which external sentiments and comparative conditions alter it.","The self is not a sovereign source of valuation: its initial vivacity enables the very transitions through which external sentiments and comparative conditions alter it."]],"CL_THN_06:GA-05":[["[Mutating] Sympathy begins as conversion of an inferred sentiment into an impression but expands into constructive simulation capable of supplementing or replacing the source’s actual emotion.","Sympathy begins as conversion of an inferred sentiment into an impression but expands into constructive simulation capable of supplementing or replacing the source’s actual emotion."]],"CL_THN_06:GA-06":[["[Emergent] Sympathy and comparison are distinct transformations of retained affect: sympathy imports another’s represented condition, whereas comparison converts that condition into an inverse estimate of the self.","Sympathy and comparison are distinct transformations of retained affect: sympathy imports another’s represented condition, whereas comparison converts that condition into an inverse estimate of the self."]],"CL_THN_06:GA-07":[["[Emergent] Affective valence belongs neither to representation nor object alone; it depends on whether the object is directly surveyed, sympathetically appropriated, or comparatively opposed.","Affective valence belongs neither to representation nor object alone; it depends on whether the object is directly surveyed, sympathetically appropriated, or comparatively opposed."]],"CL_THN_06:GA-08":[["[Mutating] Personal attribution is regulated by forms of certification—durability, intention, authority, causal inference, and general expectation—that determine whether an affect is attached to a person and sustained.","Personal attribution is regulated by forms of certification—durability, intention, authority, causal inference, and general expectation—that determine whether an affect is attached to a person and sustained."]],"CL_THN_06:GA-09":[["[Emergent] Relational proximity is valence-neutral amplification: it can intensify affection, praise, pity, rivalry, envy, or humiliation according to the process routed through it.","Relational proximity is valence-neutral amplification: it can intensify affection, praise, pity, rivalry, envy, or humiliation according to the process routed through it."]],"CL_THN_06:GA-10":[["[Attractor] Social affect has a topology in which authority, resemblance, contiguity, acquaintance, convergence, direction, and separation govern force more decisively than bare content or absolute rank.","Social affect has a topology in which authority, resemblance, contiguity, acquaintance, convergence, direction, and separation govern force more decisively than bare content or absolute rank."]],"CL_THN_06:GA-11":[["[Attractor] The recurrent generative circuit is self → related other → transformed affect → altered self, with the altered self producing further judgments, signs, desires, and reflected sentiments.","The recurrent generative circuit is self → related other → transformed affect → altered self, with the altered self producing further judgments, signs, desires, and reflected sentiments."]],"CL_THN_06:GA-12":[["[Terminal] Passions can endogenously produce the beliefs and imagined conditions that preserve or amplify them.","Passions can endogenously produce the beliefs and imagined conditions that preserve or amplify them."]],"CL_THN_06:GA-13":[["[Terminal] No intrinsic affective baseline stabilizes self-worth, social value, or hierarchy independently of transmitted sentiment and active comparison.","No intrinsic affective baseline stabilizes self-worth, social value, or hierarchy independently of transmitted sentiment and active comparison."]],"CL_THN_06:RMD-01":[["[Stable identity] Force and vivacity retain their function as the common currency linking ideas, impressions, associative transitions, and passions.","Force and vivacity retain their function as the common currency linking ideas, impressions, associative transitions, and passions."]],"CL_THN_06:RMD-02":[["[Functional recurrence] Relation recurs as a conductor of sympathy, a condition of durable affection, a bidirectional pathway of attachment, and a gate permitting comparative impressions to interact.","Relation recurs as a conductor of sympathy, a condition of durable affection, a bidirectional pathway of attachment, and a gate permitting comparative impressions to interact."]],"CL_THN_06:RMD-03":[["[Mutation] Sympathy shifts from reproducing another’s expressed sentiment to appropriating proprietary satisfaction and finally to constructing sorrow absent from the observed person.","Sympathy shifts from reproducing another’s expressed sentiment to appropriating proprietary satisfaction and finally to constructing sorrow absent from the observed person."]],"CL_THN_06:RMD-04":[["[Domain migration] Resemblance moves from general human access to other minds, through affection and pity, into the wider topology determining which persons become affectively comparable.","Resemblance moves from general human access to other minds, through affection and pity, into the wider topology determining which persons become affectively comparable."]],"CL_THN_06:RMD-05":[["[Mutation] The self moves from vivid associative origin, to object of socially communicated judgment, to variable magnitude constituted against related others.","The self moves from vivid associative origin, to object of socially communicated judgment, to variable magnitude constituted against related others."]],"CL_THN_06:RMD-06":[["[Reversal] Pleasure and pain cease to have invariant direction: another’s satisfaction can become esteem through sympathy or pain through comparison, while another’s misery can become pity or malicious pleasure.","Pleasure and pain cease to have invariant direction: another’s satisfaction can become esteem through sympathy or pain through comparison, while another’s misery can become pity or malicious pleasure."]],"CL_THN_06:RMD-07":[["[Reversal] Proximity changes from a means of sympathetic intimacy into a condition of intensified rivalry without ceasing to perform its basic function of preserving affect across transition.","Proximity changes from a means of sympathetic intimacy into a condition of intensified rivalry without ceasing to perform its basic function of preserving affect across transition."]],"CL_THN_06:RMD-08":[["[Escalation] General rules progress from tests of causal regularity to constructive templates that supply absent passions and project altered emotional magnitude back onto objects.","General rules progress from tests of causal regularity to constructive templates that supply absent passions and project altered emotional magnitude back onto objects."]],"CL_THN_06:RMD-09":[["[Absorption] Intention and evaluator authority lose the status of isolated causes and become forms of personal certification governing durable attribution and evidential uptake.","Intention and evaluator authority lose the status of isolated causes and become forms of personal certification governing durable attribution and evidential uptake."]],"CL_THN_06:RMD-10":[["[Terminal transformation] Esteem becomes recursive social capital: communicated satisfaction generates esteem, perceived esteem increases satisfaction, and renewed satisfaction generates further esteem.","Esteem becomes recursive social capital: communicated satisfaction generates esteem, perceived esteem increases satisfaction, and renewed satisfaction generates further esteem."]],"CL_THN_06:RMD-11":[["[Disappearance] Original fame, intrinsic wealth-value, calculated advantage, and autonomous malevolence disappear after their explanatory roles are redistributed across sympathy, comparison, and associative topology.","Original fame, intrinsic wealth-value, calculated advantage, and autonomous malevolence disappear after their explanatory roles are redistributed across sympathy, comparison, and associative topology."]],"CL_THN_06:CGD-01":[["[Lower-layer local] The exact weighting of evaluator authority, self-concurrence, jest, and numerical accumulation remains specific to reputational influence rather than defining every social passion.","The exact weighting of evaluator authority, self-concurrence, jest, and numerical accumulation remains specific to reputational influence rather than defining every social passion."]],"CL_THN_06:CGD-02":[["[Lower-layer local] The distinction between durable qualities and transient intentional actions solves the temporal attribution of love and hatred but scales upward only as a general certification principle.","The distinction between durable qualities and transient intentional actions solves the temporal attribution of love and hatred but scales upward only as a general certification principle."]],"CL_THN_06:CGD-03":[["[Lower-layer local] The contingent conjunction of love with benevolence and hatred with anger remains an irreducible constitutional supplement rather than a global relational mechanism.","The contingent conjunction of love with benevolence and hatred with anger remains an irreducible constitutional supplement rather than a global relational mechanism."]],"CL_THN_06:CGD-04":[["[Lower-layer local] Habitual projection from altered emotion to altered object-magnitude is the specific perceptual machinery of comparative judgment, not the general form of sympathy.","Habitual projection from altered emotion to altered object-magnitude is the specific perceptual machinery of comparative judgment, not the general form of sympathy."]],"CL_THN_06:CGD-05":[["[Scales upward] Force, vivacity, associative transition, and retained impressions form the common machinery through which all three units generate social affect.","Force, vivacity, associative transition, and retained impressions form the common machinery through which all three units generate social affect."]],"CL_THN_06:CGD-06":[["[Bridge] Fame and wealth-esteem jointly establish that social rank is produced by circulated satisfaction and reflected judgment rather than by isolated possession or intrinsic excellence.","Fame and wealth-esteem jointly establish that social rank is produced by circulated satisfaction and reflected judgment rather than by isolated possession or intrinsic excellence."]],"CL_THN_06:CGD-07":[["[Bridge] Pity and envy demonstrate that proximity does not determine valence; it intensifies whichever sympathetic or comparative operation controls the transition.","Pity and envy demonstrate that proximity does not determine valence; it intensifies whichever sympathetic or comparative operation controls the transition."]],"CL_THN_06:CGD-08":[["[Catalyst] Constructed pity, resisted contempt, and direct pain joined to comparative pleasure force the separation of affective reception from belief, source-fidelity, and direct valence.","Constructed pity, resisted contempt, and direct pain joined to comparative pleasure force the separation of affective reception from belief, source-fidelity, and direct valence."]],"CL_THN_06:CGD-09":[["[Superseded] Primitive social appetites and static classifications are recoded as outputs of directed transitions, relational weights, and recursive feedback.","Primitive social appetites and static classifications are recoded as outputs of directed transitions, relational weights, and recursive feedback."]],"CL_THN_07:GA-01":[["[Attractor] Affective value is constituted through an encounter between an object and an operating sensitive system, not fixed by the object alone.","Affective value is constituted through an encounter between an object and an operating sensitive system, not fixed by the object alone."]],"CL_THN_07:GA-02":[["[Persistent] Pleasure and pain function both as direct effects and as mobile forces capable of augmenting, redirecting, transmitting, or reversing passions.","Pleasure and pain function both as direct effects and as mobile forces capable of augmenting, redirecting, transmitting, or reversing passions."]],"CL_THN_07:GA-03":[["[Mutating] Cognitive capacity is not the universal source of passion; it regulates the accessibility, complexity, and prevalence of particular affective channels.","Cognitive capacity is not the universal source of passion; it regulates the accessibility, complexity, and prevalence of particular affective channels."]],"CL_THN_07:GA-04":[["[Emergent] Affective causes become identifiable through controlled differences: remove reflection, vary repetition, or hold truth and assurance constant while altering the mode of attainment.","Affective causes become identifiable through controlled differences: remove reflection, vary repetition, or hold truth and assurance constant while altering the mode of attainment."]],"CL_THN_07:GA-05":[["[Mutating] Difficulty, facility, excitation, and stability have no invariant valence; their effects depend on degree, temporal position, and active or passive mode.","Difficulty, facility, excitation, and stability have no invariant valence; their effects depend on degree, temporal position, and active or passive mode."]],"CL_THN_07:GA-06":[["[Emergent] Affect is transferable across functional relations: from attendant emotion into a predominant passion, from action into its end, and from one sensitive being into another.","Affect is transferable across functional relations: from attendant emotion into a predominant passion, from action into its end, and from one sensitive being into another."]],"CL_THN_07:GA-07":[["[Persistent] Present passion is path-dependent: prior encounters, repeated performances, acquired inclinations, and transferred concerns enter into its current constitution.","Present passion is path-dependent: prior encounters, repeated performances, acquired inclinations, and transferred concerns enter into its current constitution."]],"CL_THN_07:GA-08":[["[Mutating] Relation is a generative operator rather than a static resemblance: it supports animal attachment, strengthens ideational force, transfers concern, and fixes attention.","Relation is a generative operator rather than a static resemblance: it supports animal attachment, strengthens ideational force, transfers concern, and fixes attention."]],"CL_THN_07:GA-09":[["[Emergent] Activity and passivity divide affective dynamics: active exercise can sustain force and produce concern, while passive reception tends toward transmitted affect, fading excitation, or uncertainty-relief.","Activity and passivity divide affective dynamics: active exercise can sustain force and produce concern, while passive reception tends toward transmitted affect, fading excitation, or uncertainty-relief."]],"CL_THN_07:GA-10":[["[Mutating] Stability is pleasurable when it resolves resistance or vacillation, but destructive when excessive facility removes the excitation required for interest.","Stability is pleasurable when it resolves resistance or vacillation, but destructive when excessive facility removes the excitation required for interest."]],"CL_THN_07:GA-11":[["[Emergent] Concern for an end need not precede the process directed toward it; repetition and pleasurable activity can generate inclination or acquired end-concern retrospectively.","Concern for an end need not precede the process directed toward it; repetition and pleasurable activity can generate inclination or acquired end-concern retrospectively."]],"CL_THN_07:GA-12":[["[Terminal] Affective plasticity is bounded by prior endowment: natural good and evil, complete disagreeability, instinct, and pre-existing salience constrain what process can produce.","Affective plasticity is bounded by prior endowment: natural good and evil, complete disagreeability, instinct, and pre-existing salience constrain what process can produce."]],"CL_THN_07:GA-13":[["[Terminal] The field is unified by species-general and recursively transferable operations, not by a single uniform mechanism of affective production.","The field is unified by species-general and recursively transferable operations, not by a single uniform mechanism of affective production."]],"CL_THN_07:RMD-01":[["[Stable identity] Pleasure and pain remain the basic affective currency, but their source migrates from sensible benefit and injury to mental motion, exercised understanding, belief, and doubt.","Pleasure and pain remain the basic affective currency, but their source migrates from sensible benefit and injury to mental motion, exercised understanding, belief, and doubt."]],"CL_THN_07:RMD-02":[["[Mutation] Cognition shifts from a capacity whose subtraction tests affective simplicity to an activity whose difficult exercise becomes an original source of pleasure.","Cognition shifts from a capacity whose subtraction tests affective simplicity to an activity whose difficult exercise becomes an original source of pleasure."]],"CL_THN_07:RMD-03":[["[Expansion] Relation begins as obvious animal association, then expands into attentional support, ideational force, and the transfer of passion from pursuit to end.","Relation begins as obvious animal association, then expands into attentional support, ideational force, and the transfer of passion from pursuit to end."]],"CL_THN_07:RMD-04":[["[Reversal] Difficulty is painful resistance in unfamiliar passive apprehension but pleasurable exercise when attention and attainable success organize active inquiry.","Difficulty is painful resistance in unfamiliar passive apprehension but pleasurable exercise when attention and attainable success organize active inquiry."]],"CL_THN_07:RMD-05":[["[Reversal] Familiarity extinguishes novelty and may produce languor under custom, yet can intensify informational curiosity by strengthening relation and ideational force.","Familiarity extinguishes novelty and may produce languor under custom, yet can intensify informational curiosity by strengthening relation and ideational force."]],"CL_THN_07:RMD-06":[["[Functional recurrence] Stabilization recurs as tranquillity, orderly facility, and fixed belief; it relieves disturbance but ceases to sustain interest once movement becomes excessively faint.","Stabilization recurs as tranquillity, orderly facility, and fixed belief; it relieves disturbance but ceases to sustain interest once movement becomes excessively faint."]],"CL_THN_07:RMD-07":[["[Displacement] Sympathy moves from direct communication of animal passion to faint imaginative concern whose function is not benevolence but attentional fixation.","Sympathy moves from direct communication of animal passion to faint imaginative concern whose function is not benevolence but attentional fixation."]],"CL_THN_07:RMD-08":[["[Absorption] The active/passive distinction moves from habit formation into a higher division between self-sustaining pursuit and receptive uncertainty-relief.","The active/passive distinction moves from habit formation into a higher division between self-sustaining pursuit and receptive uncertainty-relief."]],"CL_THN_07:RMD-09":[["[Terminal transformation] Truth disappears as an intrinsic motive after performing an exclusionary function, then returns as either an acquired endpoint of pursuit or the content stabilized by belief.","Truth disappears as an intrinsic motive after performing an exclusionary function, then returns as either an acquired endpoint of pursuit or the content stabilized by belief."]],"CL_THN_07:RMD-10":[["[Disappearance after structural work] Peculiar parental instinct does not generalize into the cluster’s main process model, but remains as the exception that blocks exhaustive associative reduction.","Peculiar parental instinct does not generalize into the cluster’s main process model, but remains as the exception that blocks exhaustive associative reduction."]],"CL_THN_07:CGD-01":[["[Local] Peculiar parental instinct remains specific to animal affection; at cluster scale it functions chiefly as a limit on causal monism.","Peculiar parental instinct remains specific to animal affection; at cluster scale it functions chiefly as a limit on causal monism."]],"CL_THN_07:CGD-02":[["[Local] The motion of the spirits is a chapter-level causal vocabulary for custom whose exact physiology does not scale upward.","The motion of the spirits is a chapter-level causal vocabulary for custom whose exact physiology does not scale upward."]],"CL_THN_07:CGD-03":[["[Local] The division between abstract relations and matters of existence, and the special role of imagined public utility, remain machinery of scientific curiosity.","The division between abstract relations and matters of existence, and the special role of imagined public utility, remain machinery of scientific curiosity."]],"CL_THN_07:CGD-04":[["[Scales upward] The survival of passion under reduced reflection becomes the general proposition that cognition selects affective routes without constituting sensitive life itself.","The survival of passion under reduced reflection becomes the general proposition that cognition selects affective routes without constituting sensitive life itself."]],"CL_THN_07:CGD-05":[["[Scales upward] Custom’s degree-sensitive phases become a general rule that affective operations change valence according to threshold, sequence, and mode.","Custom’s degree-sensitive phases become a general rule that affective operations change valence according to threshold, sequence, and mode."]],"CL_THN_07:CGD-06":[["[Bridge] Conversion, relational transfer, and sympathy jointly produce the current-level principle of mobile affective force.","Conversion, relational transfer, and sympathy jointly produce the current-level principle of mobile affective force."]],"CL_THN_07:CGD-07":[["[Bridge] The active/passive habit distinction connects custom to curiosity’s division between challenge-seeking inquiry and uncertainty-relieving fixation.","The active/passive habit distinction connects custom to curiosity’s division between challenge-seeking inquiry and uncertainty-relieving fixation."]],"CL_THN_07:CGD-08":[["[Catalyst] Animal comparison, repeated encounter, and equal-truth comparison become three implementations of one differential method for separating content from operation.","Animal comparison, repeated encounter, and equal-truth comparison become three implementations of one differential method for separating content from operation."]],"CL_THN_07:CGD-09":[["[Recoded] Sensible benefit, natural emotion, utility, and truth retain local efficacy but are subordinated to the histories and operations through which they become affectively forceful.","Sensible benefit, natural emotion, utility, and truth retain local efficacy but are subordinated to the histories and operations through which they become affectively forceful."]],"CL_THN_08:GA-01":[["[Persistent] Society is necessary under conditions in which human weakness, partial affection, conflicting self-love, and scarce transferable goods make unregulated possession unstable.","Society is necessary under conditions in which human weakness, partial affection, conflicting self-love, and scarce transferable goods make unregulated possession unstable."]],"CL_THN_08:GA-02":[["[Persistent] A moral predicate cannot supply the first motive for the conduct whose morality it evaluates; institutional genesis must therefore begin from pre-moral passions and interests.","A moral predicate cannot supply the first motive for the conduct whose morality it evaluates; institutional genesis must therefore begin from pre-moral passions and interests."]],"CL_THN_08:GA-03":[["[Attractor] Justice is artificial without being arbitrary: it is convention-dependent in origin but functionally necessitated by durable human and material conditions.","Justice is artificial without being arbitrary: it is convention-dependent in origin but functionally necessitated by durable human and material conditions."]],"CL_THN_08:GA-04":[["[Persistent] Convention arises through mutually known, conditionally reciprocal restraint grounded in common interest and repeated experience, not through an antecedent promise or sovereign command.","Convention arises through mutually known, conditionally reciprocal restraint grounded in common interest and repeated experience, not through an antecedent promise or sovereign command."]],"CL_THN_08:GA-05":[["[Mutating] Self-interest changes function across scales: immediate acquisition destabilizes society, while reflective and coordinated self-interest generates the rules that restrain acquisition.","Self-interest changes function across scales: immediate acquisition destabilizes society, while reflective and coordinated self-interest generates the rules that restrain acquisition."]],"CL_THN_08:GA-06":[["[Terminal] Property is not antecedent to justice but is constituted as a socially enforced relation of duties, expectations, rights, and exclusions.","Property is not antecedent to justice but is constituted as a socially enforced relation of duties, expectations, rights, and exclusions."]],"CL_THN_08:GA-07":[["[Emergent] The convention stabilizing possession does not itself assign goods; institutional existence and juridical individuation are distinct generative problems.","The convention stabilizing possession does not itself assign goods; institutional existence and juridical individuation are distinct generative problems."]],"CL_THN_08:GA-08":[["[Emergent] Property has a dual determination: general utility necessitates settled allocation, while imagination and antecedent relations principally specify who receives which title.","Property has a dual determination: general utility necessitates settled allocation, while imagination and antecedent relations principally specify who receives which title."]],"CL_THN_08:GA-09":[["[Persistent] Stable justice requires society-wide general and inflexible rules because case-sensitive judgments of need, merit, fitness, or immediate utility reproduce partiality and contention.","Stable justice requires society-wide general and inflexible rules because case-sensitive judgments of need, merit, fitness, or immediate utility reproduce partiality and contention."]],"CL_THN_08:GA-10":[["[Mutating] Title is temporally layered: present possession governs founding settlement, while occupation, prescription, accession, and succession govern differentiated acquisition within established society.","Title is temporally layered: present possession governs founding settlement, while occupation, prescription, accession, and succession govern differentiated acquisition within established society."]],"CL_THN_08:GA-11":[["[Emergent] Juridical outputs are integral and binary even though their psychological, utilitarian, temporal, and relational grounds vary by degree.","Juridical outputs are integral and binary even though their psychological, utilitarian, temporal, and relational grounds vary by degree."]],"CL_THN_08:GA-12":[["[Terminal] Municipal law supplies practical closure where natural association and public utility fail to determine a unique title.","Municipal law supplies practical closure where natural association and public utility fail to determine a unique title."]],"CL_THN_08:GA-13":[["[Attractor] The justice of an act derives from its position within a socially advantageous rule-system rather than from its isolated consequences.","The justice of an act derives from its position within a socially advantageous rule-system rather than from its isolated consequences."]],"CL_THN_08:GA-14":[["[Persistent] Justice has a temporally divided foundation: common interest generates observance before sympathy with public utility generates moral approval.","Justice has a temporally divided foundation: common interest generates observance before sympathy with public utility generates moral approval."]],"CL_THN_08:GA-15":[["[Attractor] Once established, convention, juridical determination, moral approbation, education, reputation, and government form a reinforcing system that converts artificial rules into durable dispositions.","Once established, convention, juridical determination, moral approbation, education, reputation, and government form a reinforcing system that converts artificial rules into durable dispositions."]],"CL_THN_08:RMD-01":[["[Stable identity] Justice remains an artificial virtue throughout: neither its necessity, its utility, nor its affective approval converts it into an innate moral principle.","Justice remains an artificial virtue throughout: neither its necessity, its utility, nor its affective approval converts it into an innate moral principle."]],"CL_THN_08:RMD-02":[["[Functional recurrence] Stability of possession first solves social conflict, then reappears as an insufficient general rule whose allocation gap generates the detailed property regime.","Stability of possession first solves social conflict, then reappears as an insufficient general rule whose allocation gap generates the detailed property regime."]],"CL_THN_08:RMD-03":[["[Escalation] Property moves from an effect of stabilized possession, to a differentiated system of relational titles, to evidence that juridical reality is institutionally constituted.","Property moves from an effect of stabilized possession, to a differentiated system of relational titles, to evidence that juridical reality is institutionally constituted."]],"CL_THN_08:RMD-04":[["[Mutation] Utility first explains why justice is necessary, then becomes insufficient to specify particular titles, and finally becomes the public effect whose contemplation moralizes the completed system.","Utility first explains why justice is necessary, then becomes insufficient to specify particular titles, and finally becomes the public effect whose contemplation moralizes the completed system."]],"CL_THN_08:RMD-05":[["[Reversal] Self-love changes from the principal source of possessory conflict into the originating material of reciprocal restraint and unintended public advantage.","Self-love changes from the principal source of possessory conflict into the originating material of reciprocal restraint and unintended public advantage."]],"CL_THN_08:RMD-06":[["[Displacement] Imagination migrates from a general psychological faculty of associative completion into a juridical mechanism that joins persons to objects, extends titles, and structures inheritance.","Imagination migrates from a general psychological faculty of associative completion into a juridical mechanism that joins persons to objects, extends titles, and structures inheritance."]],"CL_THN_08:RMD-07":[["[Mutation] Generality changes from reciprocal abstention governing possession into differentiated but society-wide rules whose inflexibility suppresses case-specific natural motivation.","Generality changes from reciprocal abstention governing possession into differentiated but society-wide rules whose inflexibility suppresses case-specific natural motivation."]],"CL_THN_08:RMD-08":[["[Terminal transformation] Present possession produces founding title but disappears as a perpetual criterion once its founding work is complete; occupation and restitution require its restriction.","Present possession produces founding title but disappears as a perpetual criterion once its founding work is complete; occupation and restitution require its restriction."]],"CL_THN_08:RMD-09":[["[Migration] Graduality moves from possessory probability and temporal association into a general challenge to the integral form of property, right, and obligation.","Graduality moves from possessory probability and temporal association into a general challenge to the integral form of property, right, and obligation."]],"CL_THN_08:RMD-10":[["[Absorption] Sympathy begins as the explanation of moral approval and is absorbed into a larger institutional feedback loop involving public judgment, education, reputation, and stabilized compliance.","Sympathy begins as the explanation of moral approval and is absorbed into a larger institutional feedback loop involving public judgment, education, reputation, and stabilized compliance."]],"CL_THN_08:RMD-11":[["[Disappearance after structural work] Universal benevolence, direct public concern, private benevolence, and an innate sense of justice disappear as originating motives after forcing the transition to convention and reflected interest.","Universal benevolence, direct public concern, private benevolence, and an innate sense of justice disappear as originating motives after forcing the transition to convention and reflected interest."]],"CL_THN_08:CGD-01":[["[Local-to-scaling] The semantic disambiguation of “nature” remains preparatory machinery, but it scales upward by preventing artificial justice from being classified as unnatural, arbitrary, or morally defective.","The semantic disambiguation of “nature” remains preparatory machinery, but it scales upward by preventing artificial justice from being classified as unnatural, arbitrary, or morally defective."]],"CL_THN_08:CGD-02":[["[Local] The detailed taxonomies of occupation, prescription, accession, and succession remain lower-layer jurisprudential machinery; only their common relational and temporal structure scales upward.","The detailed taxonomies of occupation, prescription, accession, and succession remain lower-layer jurisprudential machinery; only their common relational and temporal structure scales upward."]],"CL_THN_08:CGD-03":[["[Scales upward] The convention of stable possession becomes the cluster’s constitutive threshold between physical control and normative property.","The convention of stable possession becomes the cluster’s constitutive threshold between physical control and normative property."]],"CL_THN_08:CGD-04":[["[Bridge] Imagination bridges institutional necessity and determinate title by converting natural relations of proximity, causality, duration, scale, and kinship into socially stabilized juridical attachments.","Imagination bridges institutional necessity and determinate title by converting natural relations of proximity, causality, duration, scale, and kinship into socially stabilized juridical attachments."]],"CL_THN_08:CGD-05":[["[Bridge] The priority of motive over moral judgment bridges the sentimental theory of virtue and the institutional genealogy by requiring pre-moral interest to precede moral obligation.","The priority of motive over moral judgment bridges the sentimental theory of virtue and the institutional genealogy by requiring pre-moral interest to precede moral obligation."]],"CL_THN_08:CGD-06":[["[Catalyst] The gradation test converts local observations about fluid possession and natural motivation into a general explanation of why juridical decision requires imposed binary closure.","The gradation test converts local observations about fluid possession and natural motivation into a general explanation of why juridical decision requires imposed binary closure."]],"CL_THN_08:CGD-07":[["[Superseded] Present possession is indispensable at the founding threshold but becomes invalid as a universal title once an established regime supports restitution and differentiated acquisition.","Present possession is indispensable at the founding threshold but becomes invalid as a universal title once an established regime supports restitution and differentiated acquisition."]],"CL_THN_08:CGD-08":[["[Recoded] Education, reputation, and political reinforcement do not originate justice; they recode an established convention as honor, duty, and second nature.","Education, reputation, and political reinforcement do not originate justice; they recode an established convention as honor, duty, and second nature."]],"CL_THN_08:CGD-09":[["[Local] The solitary state of nature remains an analytical fiction used to isolate passions from understanding; the cluster does not require it as an actual historical stage.","The solitary state of nature remains an analytical fiction used to isolate passions from understanding; the cluster does not require it as an actual historical stage."]],"CL_THN_08:CGD-10":[["[Peripheral] Consensual transfer and promise-performance mark the broader perimeter of justice, but the current architecture develops possession and property rather than independently reconstructing those laws.","Consensual transfer and promise-performance mark the broader perimeter of justice, but the current architecture develops possession and property rather than independently reconstructing those laws."]],"CL_THN_08:ALT-B01":[["[Surface] The explicit objects are justice, stable possession, property, acquisition, title, adjudication, and the moral approval attached to their observance.","The explicit objects are justice, stable possession, property, acquisition, title, adjudication, and the moral approval attached to their observance."]],"CL_THN_08:ALT-B02":[["[Structural] Partial passions, scarcity, reciprocal expectations, general rules, associative imagination, municipal closure, and sympathetic reinforcement form the operative institutional system.","Partial passions, scarcity, reciprocal expectations, general rules, associative imagination, municipal closure, and sympathetic reinforcement form the operative institutional system."]],"CL_THN_08:ALT-B03":[["[Metastrategic] Explanation proceeds by reversing presumed dependencies: motives precede moral predicates, justice precedes property, systemic utility precedes approval, and legal decision completes rather than discovers natural determinacy.","Explanation proceeds by reversing presumed dependencies: motives precede moral predicates, justice precedes property, systemic utility precedes approval, and legal decision completes rather than discovers natural determinacy."]],"CL_THN_08:ALT-B04":[["[Ontological / Temporal] Reality contains no object-inherent property; juridical relations emerge gradually, change through temporal and institutional mediation, and become integral only through rule-governed recognition.","Reality contains no object-inherent property; juridical relations emerge gradually, change through temporal and institutional mediation, and become integral only through rule-governed recognition."]],"CL_THN_08:ALT-B05":[["[Methodological / Performative] The system performs its thesis through successive elimination, inversion, differentiation, and forced closure: its method reproduces the passage from fluid natural materials to determinate artificial relations.","The system performs its thesis through successive elimination, inversion, differentiation, and forced closure: its method reproduces the passage from fluid natural materials to determinate artificial relations."]],"CL_THN_09:GA-01":[["[Persistent] Normative authority is generated within ordinary human nature: interest, pleasure, uneasiness, and sympathetically apprehended relations furnish its operative materials.","Normative authority is generated within ordinary human nature: interest, pleasure, uneasiness, and sympathetically apprehended relations furnish its operative materials."]],"CL_THN_09:GA-02":[["[Persistent] Human motivation is partial, variable, and passion-bound; neither rulers nor spectators occupy a naturally impartial or morally transformed position.","Human motivation is partial, variable, and passion-bound; neither rulers nor spectators occupy a naturally impartial or morally transformed position."]],"CL_THN_09:GA-03":[["[Persistent] Sympathy makes the effects of qualities on others available to spectators who possess no direct private interest in those effects.","Sympathy makes the effects of qualities on others available to spectators who possess no direct private interest in those effects."]],"CL_THN_09:GA-04":[["[Attractor] Shared moral order is produced by generalizing situated responses into stable rules, common standpoints, and publicly usable evaluative language.","Shared moral order is produced by generalizing situated responses into stable rules, common standpoints, and publicly usable evaluative language."]],"CL_THN_09:GA-05":[["[Persistent] The principal evaluative object is a durable tendency or function, not an isolated act, transient feeling, or accidental outcome.","The principal evaluative object is a durable tendency or function, not an isolated act, transient feeling, or accidental outcome."]],"CL_THN_09:GA-06":[["[Mutating] Interest and utility change scope across the cluster: they uniquely sanction political allegiance but constitute only part of the plural basis of moral approval.","Interest and utility change scope across the cluster: they uniquely sanction political allegiance but constitute only part of the plural basis of moral approval."]],"CL_THN_09:GA-07":[["[Mutating] Artifice does not create ultimate value; it coordinates natural limitations and interests into promises, government, justice, good-breeding, and stable moral discourse.","Artifice does not create ultimate value; it coordinates natural limitations and interests into promises, government, justice, good-breeding, and stable moral discourse."]],"CL_THN_09:GA-08":[["[Emergent] Generalized judgment acquires relative autonomy from its origin: it can preserve obligation beyond immediate interest and preserve esteem despite weak affection, distance, or bad fortune.","Generalized judgment acquires relative autonomy from its origin: it can preserve obligation beyond immediate interest and preserve esteem despite weak affection, distance, or bad fortune."]],"CL_THN_09:GA-09":[["[Emergent] A legitimate exception must itself be generalizable: repeated anti-functional conduct, not private injury or isolated failure, authorizes normative reversal.","A legitimate exception must itself be generalizable: repeated anti-functional conduct, not private injury or isolated failure, authorizes normative reversal."]],"CL_THN_09:GA-10":[["[Persistent] Corrected judgment, occurrent affection, moral language, and practical motivation remain distinct layers and need not converge.","Corrected judgment, occurrent affection, moral language, and practical motivation remain distinct layers and need not converge."]],"CL_THN_09:GA-11":[["[Terminal] Offices, capacities, passions, and dispositions acquire moral valence from their direction and relational effects; systematic reversal of function produces reclassification from virtue or authority into vice or enmity.","Offices, capacities, passions, and dispositions acquire moral valence from their direction and relational effects; systematic reversal of function produces reclassification from virtue or authority into vice or enmity."]],"CL_THN_09:GA-12":[["[Attractor] The cluster converges on a conditionally ordered relational field: character is judged across its roles and government by its protective function, while no single utility calculus governs every moral source.","The cluster converges on a conditionally ordered relational field: character is judged across its roles and government by its protective function, while no single utility calculus governs every moral source."]],"CL_THN_09:RMD-01":[["[Stable identity] Sympathy retains its function as affective transmission: another’s pleasures and pains become spectator sentiments capable of grounding approval, affection, blame, and hatred.","Sympathy retains its function as affective transmission: another’s pleasures and pains become spectator sentiments capable of grounding approval, affection, blame, and hatred."]],"CL_THN_09:RMD-02":[["[Mutation] Interest moves from the cause of convention and exclusive sanction of allegiance to one evaluative relation among usefulness, immediate agreeableness, self-regard, and regard for others.","Interest moves from the cause of convention and exclusive sanction of allegiance to one evaluative relation among usefulness, immediate agreeableness, self-regard, and regard for others."]],"CL_THN_09:RMD-03":[["[Functional recurrence] The general point of view, common standard, general moral rule, and general opinion perform homologous work: they convert situated responses into socially stable verdicts.","The general point of view, common standard, general moral rule, and general opinion perform homologous work: they convert situated responses into socially stable verdicts."]],"CL_THN_09:RMD-04":[["[Reversal] Generalization first stabilizes allegiance and moral language, then becomes the mechanism by which recurrent abuses establish an exception to obedience.","Generalization first stabilizes allegiance and moral language, then becomes the mechanism by which recurrent abuses establish an exception to obedience."]],"CL_THN_09:RMD-05":[["[Domain expansion] Natural tendency migrates from the evaluation of personal dispositions under bad fortune to the evaluation of government under repeated historical performance.","Natural tendency migrates from the evaluation of personal dispositions under bad fortune to the evaluation of government under repeated historical performance."]],"CL_THN_09:RMD-06":[["[Absorption] The natural/artificial distinction ceases to divide sources of moral authority and instead marks different scales and mechanisms of coordinated benefit.","The natural/artificial distinction ceases to divide sources of moral authority and instead marks different scales and mechanisms of coordinated benefit."]],"CL_THN_09:RMD-07":[["[Escalation] Neutral capacities become morally charged through direction: benevolence makes power useful, while ambition or cruelty converts capacity and office into magnified harm.","Neutral capacities become morally charged through direction: benevolence makes power useful, while ambition or cruelty converts capacity and office into magnified harm."]],"CL_THN_09:RMD-08":[["[Disappearance after structural work] Promise, custom, and imitation disappear as original grounds once they have exposed the need for a prior interest capable of generating and transmitting allegiance.","Promise, custom, and imitation disappear as original grounds once they have exposed the need for a prior interest capable of generating and transmitting allegiance."]],"CL_THN_09:RMD-09":[["[Absorption after diagnostic use] Pride, tenderness, modesty, and heroic elevation remain local test cases, but their higher-order result is retained as evaluative pluralism and the separation of inward merit from social presentation.","Pride, tenderness, modesty, and heroic elevation remain local test cases, but their higher-order result is retained as evaluative pluralism and the separation of inward merit from social presentation."]],"CL_THN_09:RMD-10":[["[Mutation] Negative passion moves from constitutionally fitting anger to moral blame and, under public, recurrent, and severe injury, to resistance against tyrannical power.","Negative passion moves from constitutionally fitting anger to moral blame and, under public, recurrent, and severe injury, to resistance against tyrannical power."]],"CL_THN_09:CGD-01":[["[Local] The regress from promise through convention to interest is specific machinery for dismantling contractual allegiance; its scalable result is the dependence of artificial norms on prior human interests.","The regress from promise through convention to interest is specific machinery for dismantling contractual allegiance; its scalable result is the dependence of artificial norms on prior human interests."]],"CL_THN_09:CGD-02":[["[Local] The detailed mechanics of pride, comparison, heroic elevation, and conventional modesty remain a stress test of the four-source moral system rather than a global account of political authority.","The detailed mechanics of pride, comparison, heroic elevation, and conventional modesty remain a stress test of the four-source moral system rather than a global account of political authority."]],"CL_THN_09:CGD-03":[["[Local] Tenderness and qualified anger establish the dual sources and degree-sensitivity of benevolent merit but do not independently determine the limits of allegiance.","Tenderness and qualified anger establish the dual sources and degree-sensitivity of benevolent merit but do not independently determine the limits of allegiance."]],"CL_THN_09:CGD-04":[["[Scales upward] Correction for distance, private position, current disposition, and fortune becomes the cluster-wide mechanism for separating stable judgment from immediate affect.","Correction for distance, private position, current disposition, and fortune becomes the cluster-wide mechanism for separating stable judgment from immediate affect."]],"CL_THN_09:CGD-05":[["[Scales upward] Evaluation by durable tendency scales from personal character to institutional function and supplies the shared grammar of virtue, vice, legitimacy, and tyranny.","Evaluation by durable tendency scales from personal character to institutional function and supplies the shared grammar of virtue, vice, legitimacy, and tyranny."]],"CL_THN_09:CGD-06":[["[Bridge] Artificial justice and government are coordinated schemes whose moral standing depends on general benefit rather than the independent value of every isolated act.","Artificial justice and government are coordinated schemes whose moral standing depends on general benefit rather than the independent value of every isolated act."]],"CL_THN_09:CGD-07":[["[Catalyst] The distinction between originating cause and persisting moral rule forces the transition from simple causal genealogy to a temporal account of normative inertia and correction.","The distinction between originating cause and persisting moral rule forces the transition from simple causal genealogy to a temporal account of normative inertia and correction."]],"CL_THN_09:CGD-08":[["[Superseded] Utility monism, raw sympathetic intensity, isolated outcome evaluation, and absolute allegiance are jointly replaced by plural sources, corrected judgment, dispositional appraisal, and conditional authority.","Utility monism, raw sympathetic intensity, isolated outcome evaluation, and absolute allegiance are jointly replaced by plural sources, corrected judgment, dispositional appraisal, and conditional authority."]],"MC_THN_L1_01:GA-01":[["[Attractor] A science of human nature must reconstruct the perceptual medium through which evidence, inference, belief, and every other science operate.","A science of human nature must reconstruct the perceptual medium through which evidence, inference, belief, and every other science operate."]],"MC_THN_L1_01:GA-02":[["[Persistent] Legitimate inquiry proceeds from experienced perceptions, operations, relations, and effects rather than from speculative access to mental or external essence.","Legitimate inquiry proceeds from experienced perceptions, operations, relations, and effects rather than from speculative access to mental or external essence."]],"MC_THN_L1_01:GA-03":[["[Persistent] Simple ideational content is asymmetrically dependent on antecedent impression-material, even when later ideas become causally productive.","Simple ideational content is asymmetrically dependent on antecedent impression-material, even when later ideas become causally productive."]],"MC_THN_L1_01:GA-04":[["[Emergent] Provenance, arrangement, and force constitute distinct explanatory coordinates: what an idea contains, how it is ordered, and how efficaciously it is conceived cannot be reduced to one another.","Provenance, arrangement, and force constitute distinct explanatory coordinates: what an idea contains, how it is ordered, and how efficaciously it is conceived cannot be reduced to one another."]],"MC_THN_L1_01:GA-05":[["[Mutating] The idea is first a derivative copy, then a recombinable component, an associative node, and finally a force-bearing mediator of belief, passion, and action.","The idea is first a derivative copy, then a recombinable component, an associative node, and finally a force-bearing mediator of belief, passion, and action."]],"MC_THN_L1_01:GA-06":[["[Attractor] Mental production is asymmetrically recursive: sensory grounding remains one-way, while downstream perceptions repeatedly exchange the roles of effect, antecedent, and regulator.","Mental production is asymmetrically recursive: sensory grounding remains one-way, while downstream perceptions repeatedly exchange the roles of effect, antecedent, and regulator."]],"MC_THN_L1_01:GA-07":[["[Emergent] Novelty is relational and intensive rather than elemental: new complexes, abstractions, expectations, and reality-effects arise without unprecedented simple content.","Novelty is relational and intensive rather than elemental: new complexes, abstractions, expectations, and reality-effects arise without unprecedented simple content."]],"MC_THN_L1_01:GA-08":[["[Mutating] Order changes from a preserved feature of experience into a manipulable arrangement, an associative pathway, and the constitutive form of spatial and temporal appearance.","Order changes from a preserved feature of experience into a manipulable arrangement, an associative pathway, and the constitutive form of spatial and temporal appearance."]],"MC_THN_L1_01:GA-09":[["[Emergent] Stable mental regularity is generated by associative tendency and custom, which constrain transitions without imposing demonstrative necessity or abolishing imaginative variation.","Stable mental regularity is generated by associative tendency and custom, which constrain transitions without imposing demonstrative necessity or abolishing imaginative variation."]],"MC_THN_L1_01:GA-10":[["[Persistent] Space and time are content-bearing orders of coexistence and succession, not independent impressions or empty containers.","Space and time are content-bearing orders of coexistence and succession, not independent impressions or empty containers."]],"MC_THN_L1_01:GA-11":[["[Emergent] Existence contributes no additional represented quality; factuality must therefore be generated through a difference in the manner and force of conception.","Existence contributes no additional represented quality; factuality must therefore be generated through a difference in the manner and force of conception."]],"MC_THN_L1_01:GA-12":[["[Mutating] Force and vivacity develop from taxonomic marks into transmissible causal quantities, then into regulated quantities whose epistemic status depends on pedigree and steadiness.","Force and vivacity develop from taxonomic marks into transmissible causal quantities, then into regulated quantities whose epistemic status depends on pedigree and steadiness."]],"MC_THN_L1_01:GA-13":[["[Emergent] A present impression anchors inference, supplies transferable vivacity, and gives absent or future objects current motivational efficacy.","A present impression anchors inference, supplies transferable vivacity, and gives absent or future objects current motivational efficacy."]],"MC_THN_L1_01:GA-14":[["[Attractor] Practical reality is stable, regulated presence within the perception-system: an idea becomes real for the mind insofar as it persistently governs inference, passion, expectation, and conduct.","Practical reality is stable, regulated presence within the perception-system: an idea becomes real for the mind insofar as it persistently governs inference, passion, expectation, and conduct."]],"MC_THN_L1_01:GA-15":[["[Emergent] Epistemic legitimacy is genealogical and second-order: it requires admissible content, permissible relational application, and a force-producing history capable of surviving correction.","Epistemic legitimacy is genealogical and second-order: it requires admissible content, permissible relational application, and a force-producing history capable of surviving correction."]],"MC_THN_L1_01:GA-16":[["[Terminal] Explanation terminates at maximally general experienced relations while sensory origins, associative attraction, external actuality, and the final authority of corrective rules remain undisclosed.","Explanation terminates at maximally general experienced relations while sensory origins, associative attraction, external actuality, and the final authority of corrective rules remain undisclosed."]],"MC_THN_L1_01:RMD-01":[["[Stable identity] Experience remains the admissible field from the initial science of human nature through compositional analysis and the genealogy of factual assent.","Experience remains the admissible field from the initial science of human nature through compositional analysis and the genealogy of factual assent."]],"MC_THN_L1_01:RMD-02":[["[Functional recurrence] Observation mutates into perceptual classification, source-audit, compositional decomposition, tracking of associative effects, and diagnosis of force-producing pedigrees.","Observation mutates into perceptual classification, source-audit, compositional decomposition, tracking of associative effects, and diagnosis of force-producing pedigrees."]],"MC_THN_L1_01:RMD-03":[["[Escalation] The copy principle moves from a claim about simple ideas to a general constraint on imagination, abstraction, spatiotemporal predication, and existential representation.","The copy principle moves from a claim about simple ideas to a general constraint on imagination, abstraction, spatiotemporal predication, and existential representation."]],"MC_THN_L1_01:RMD-04":[["[Mutation] The idea changes from faint effect into reflective cause, recombinable component, associated transition-node, and practically efficacious object of belief.","The idea changes from faint effect into reflective cause, recombinable component, associated transition-node, and practically efficacious object of belief."]],"MC_THN_L1_01:RMD-05":[["[Mutation] Order changes from a standard of mnemonic fidelity into the common machinery of recombination, association, extension, duration, and customary expectation.","Order changes from a standard of mnemonic fidelity into the common machinery of recombination, association, extension, duration, and customary expectation."]],"MC_THN_L1_01:RMD-06":[["[Domain migration] Association moves from a gentle relation among freely recombinable ideas into the customary mechanism that selects factual alternatives and transmits vivacity.","Association moves from a gentle relation among freely recombinable ideas into the customary mechanism that selects factual alternatives and transmits vivacity."]],"MC_THN_L1_01:RMD-07":[["[Escalation and reversal] Vivacity progresses from perception-classification and mnemonic discrimination to belief-production, then reverses when poetry, passion, and madness show that intensity cannot warrant itself.","Vivacity progresses from perception-classification and mnemonic discrimination to belief-production, then reverses when poetry, passion, and madness show that intensity cannot warrant itself."]],"MC_THN_L1_01:RMD-08":[["[Absorption] Existence disappears as an independent content-question after its non-addition becomes the constraint forcing factual difference into modal and causal explanation.","Existence disappears as an independent content-question after its non-addition becomes the constraint forcing factual difference into modal and causal explanation."]],"MC_THN_L1_01:RMD-09":[["[Reversal] Separability first authorizes imaginative liberty, then becomes a negative test excluding empty space, bare time, and other structures detached from every positive content.","Separability first authorizes imaginative liberty, then becomes a negative test excluding empty space, bare time, and other structures detached from every positive content."]],"MC_THN_L1_01:RMD-10":[["[Escalation] Causation migrates from temporal dependence and ideational association to productive capacity, social authority, force transmission, and the regulation of belief.","Causation migrates from temporal dependence and ideational association to productive capacity, social authority, force transmission, and the regulation of belief."]],"MC_THN_L1_01:RMD-11":[["[Terminal transformation] Ignorance changes from a disciplinary deficiency into a constitutive boundary permitting operational explanation without essential, causal, or metaphysical completion.","Ignorance changes from a disciplinary deficiency into a constitutive boundary permitting operational explanation without essential, causal, or metaphysical completion."]],"MC_THN_L1_01:RMD-12":[["[Disappearance through absorption] Separate faculty names lose final explanatory status as memory, imagination, judgment, passion, and volition become differentiated operations within one distributed perception-system.","Separate faculty names lose final explanatory status as memory, imagination, judgment, passion, and volition become differentiated operations within one distributed perception-system."]],"MC_THN_L1_01:CGD-01":[["[Local] The initial diagnosis of philosophical controversy motivates the metascientific project but does not govern the later machinery of order, association, and belief.","The initial diagnosis of philosophical controversy motivates the metascientific project but does not govern the later machinery of order, association, and belief."]],"MC_THN_L1_01:CGD-02":[["[Local] The missing shade remains an exception to strict copy-priority rather than an alternative source of the current-level architecture.","The missing shade remains an exception to strict copy-priority rather than an alternative source of the current-level architecture."]],"MC_THN_L1_01:CGD-03":[["[Local] Exact mnemonic vivacity, the sensory source of extension, and content-filled minima remain local criteria whose broader function is only to constrain unconstrained separation.","Exact mnemonic vivacity, the sensory source of extension, and content-filled minima remain local criteria whose broader function is only to constrain unconstrained separation."]],"MC_THN_L1_01:CGD-04":[["[Local] The exhaustiveness of the three associative relations and the extension of causation into social subordination are domain-specific claims, not universal axioms of the whole meta-cluster.","The exhaustiveness of the three associative relations and the extension of causation into social subordination are domain-specific claims, not universal axioms of the whole meta-cluster."]],"MC_THN_L1_01:CGD-05":[["[Scales upward] The prohibition on essence-first explanation becomes the common boundary governing perceptions, faculties, space, time, existence, belief, and reality.","The prohibition on essence-first explanation becomes the common boundary governing perceptions, faculties, space, time, existence, belief, and reality."]],"MC_THN_L1_01:CGD-06":[["[Scales upward] The copy principle becomes a general genealogy of admissible content, while the distinction between content and operation prevents genealogy from collapsing into passive replay.","The copy principle becomes a general genealogy of admissible content, while the distinction between content and operation prevents genealogy from collapsing into passive replay."]],"MC_THN_L1_01:CGD-07":[["[Bridge] Ideas connect sensory derivation to reflection, memory, recombination, association, factual belief, and practical action.","Ideas connect sensory derivation to reflection, memory, recombination, association, factual belief, and practical action."]],"MC_THN_L1_01:CGD-08":[["[Bridge] Association and custom connect relational order to intensive actuality by converting recurrent transitions into channels of transferred vivacity.","Association and custom connect relational order to intensive actuality by converting recurrent transitions into channels of transferred vivacity."]],"MC_THN_L1_01:CGD-09":[["[Catalyst] Poetry, eloquence, passion, and madness are local cases that scale only as stress tests forcing belief to mutate from raw vividness into regulated intensity.","Poetry, eloquence, passion, and madness are local cases that scale only as stress tests forcing belief to mutate from raw vividness into regulated intensity."]],"MC_THN_L1_01:CGD-10":[["[Superseded and recoded] Linear copy chronology, passive receptivity, sealed faculties, empty forms, and intrinsic actuality-markers are replaced by asymmetrical recursion, relational organization, and second-order genealogy.","Linear copy chronology, passive receptivity, sealed faculties, empty forms, and intrinsic actuality-markers are replaced by asymmetrical recursion, relational organization, and second-order genealogy."]],"MC_THN_L1_01:ALT-B01":[["[Surface] The explicit field comprises human nature, impressions, ideas, memory, imagination, association, space, time, existence, belief, passion, fiction, and factual judgment.","The explicit field comprises human nature, impressions, ideas, memory, imagination, association, space, time, existence, belief, passion, fiction, and factual judgment."]],"MC_THN_L1_01:ALT-B02":[["[Structural] Copying, recurrence, separation, recombination, associative routing, ordered coexistence and succession, force-transfer, affective feedback, and correction form one distributed mechanism.","Copying, recurrence, separation, recombination, associative routing, ordered coexistence and succession, force-transfer, affective feedback, and correction form one distributed mechanism."]],"MC_THN_L1_01:ALT-B03":[["[Metastrategic] Metaphysical disputes are converted into audits of perceptual origin, relational operation, permissible application, causal pedigree, and susceptibility to correction.","Metaphysical disputes are converted into audits of perceptual origin, relational operation, permissible application, causal pedigree, and susceptibility to correction."]],"MC_THN_L1_01:ALT-B04":[["[Ontological / Temporal] Reality available to thought consists of content-bearing events and configurations; time is generated succession recursively reorganized by memory, custom, expectation, and present practical force.","Reality available to thought consists of content-bearing events and configurations; time is generated succession recursively reorganized by memory, custom, expectation, and present practical force."]],"MC_THN_L1_01:ALT-B05":[["[Methodological / Performative] The system performs its claims by decomposing apparent unities, denying unsupported additions, reconstructing operational relations, testing them against anomalies, and replacing universality with qualified recursive regulation.","The system performs its claims by decomposing apparent unities, denying unsupported additions, reconstructing operational relations, testing them against anomalies, and replacing universality with qualified recursive regulation."]],"MC_THN_L1_02:GA-01":[["[Persistent] Legitimate explanation begins from perceptions, affects, experienced conjunctions, and observable transformations rather than from unknown substances or intrinsic productive powers.","Legitimate explanation begins from perceptions, affects, experienced conjunctions, and observable transformations rather than from unknown substances or intrinsic productive powers."]],"MC_THN_L1_02:GA-02":[["[Persistent] Relation is causally effective only through the transitions it facilitates, preserves, interrupts, or redirects; it is not an inert predicate or an intrinsically binding nexus.","Relation is causally effective only through the transitions it facilitates, preserves, interrupts, or redirects; it is not an inert predicate or an intrinsically binding nexus."]],"MC_THN_L1_02:GA-03":[["[Mutating] Force and vivacity migrate from determinants of conviction into the general currency by which cognitive, affective, and social representations become operative.","Force and vivacity migrate from determinants of conviction into the general currency by which cognitive, affective, and social representations become operative."]],"MC_THN_L1_02:GA-04":[["[Persistent] Repetition, habit, and custom stabilize transitions without converting psychological regularity, practical necessity, or social circulation into truth.","Repetition, habit, and custom stabilize transitions without converting psychological regularity, practical necessity, or social circulation into truth."]],"MC_THN_L1_02:GA-05":[["[Attractor] Imagination is the indispensable medium of synthesis and the endogenous source of fictive completion, overextension, constructed sentiment, and self-confirming error.","Imagination is the indispensable medium of synthesis and the endogenous source of fictive completion, overextension, constructed sentiment, and self-confirming error."]],"MC_THN_L1_02:GA-06":[["[Mutating] Comparison changes from controlled experimental differentiation into affective opposition, retaining the common operation of preserving difference while reversing its epistemic function.","Comparison changes from controlled experimental differentiation into affective opposition, retaining the common operation of preserving difference while reversing its epistemic function."]],"MC_THN_L1_02:GA-07":[["[Mutating] Causation expands from regular conjunction among discriminated circumstances into gated conversion and recursive feedback in which effects alter subsequent causes, judgments, and relations.","Causation expands from regular conjunction among discriminated circumstances into gated conversion and recursive feedback in which effects alter subsequent causes, judgments, and relations."]],"MC_THN_L1_02:GA-08":[["[Emergent] Anomalies and contradictions reveal unrestricted principles by their excesses and force their conversion into range-bound, threshold-dependent mechanisms.","Anomalies and contradictions reveal unrestricted principles by their excesses and force their conversion into range-bound, threshold-dependent mechanisms."]],"MC_THN_L1_02:GA-09":[["[Attractor] Normative correction is immanent: broader comparison, discriminating variation, skeptical restraint, and recursive audit regulate the same natural operations that generate error.","Normative correction is immanent: broader comparison, discriminating variation, skeptical restraint, and recursive audit regulate the same natural operations that generate error."]],"MC_THN_L1_02:GA-10":[["[Mutating] The self has no warranted status as a substantial origin but remains operative as a vivid relay, represented object, temporal comparator, and socially altered magnitude.","The self has no warranted status as a substantial origin but remains operative as a vivid relay, represented object, temporal comparator, and socially altered magnitude."]],"MC_THN_L1_02:GA-11":[["[Persistent] Natural production and felt efficacy do not establish representational truth, epistemic warrant, intrinsic value, or source-fidelity.","Natural production and felt efficacy do not establish representational truth, epistemic warrant, intrinsic value, or source-fidelity."]],"MC_THN_L1_02:GA-12":[["[Emergent] Social value is generated in circulation: transmitted satisfaction, reflected judgment, comparative opposition, and recursive uptake constitute rank and self-estimation.","Social value is generated in circulation: transmitted satisfaction, reflected judgment, comparative opposition, and recursive uptake constitute rank and self-estimation."]],"MC_THN_L1_02:GA-13":[["[Emergent] Relational proximity and intensity possess no intrinsic valence; they amplify whichever epistemic, sympathetic, or comparative transformation controls the route.","Relational proximity and intensity possess no intrinsic valence; they amplify whichever epistemic, sympathetic, or comparative transformation controls the route."]],"MC_THN_L1_02:GA-14":[["[Emergent] Time is an active operator of projection, attenuation, retention, durable attribution, and feedback rather than a neutral container for stable objects and subjects.","Time is an active operator of projection, attenuation, retention, durable attribution, and feedback rather than a neutral container for stable objects and subjects."]],"MC_THN_L1_02:GA-15":[["[Terminal] The viable endpoint is a reflexive science of human nature that preserves empirically useful causal and affective mechanisms under permanent semantic, experimental, skeptical, and relational correction.","The viable endpoint is a reflexive science of human nature that preserves empirically useful causal and affective mechanisms under permanent semantic, experimental, skeptical, and relational correction."]],"MC_THN_L1_02:RMD-01":[["[Stable Identity] Experienced conjunction remains the minimum causal input, although its output expands from expectation to bodily influence, affective conversion, and social feedback.","Experienced conjunction remains the minimum causal input, although its output expands from expectation to bodily influence, affective conversion, and social feedback."]],"MC_THN_L1_02:RMD-02":[["[Escalation] Vivacity moves from explaining unequal conviction to animating belief and passion, then becomes the transmissible currency of a social-affective network.","Vivacity moves from explaining unequal conviction to animating belief and passion, then becomes the transmissible currency of a social-affective network."]],"MC_THN_L1_02:RMD-03":[["[Mutation] Imagination changes from a producer of causal expectation and fictive object-unity into the general medium of cognition, then into a simulator capable of constructing another’s absent emotion.","Imagination changes from a producer of causal expectation and fictive object-unity into the general medium of cognition, then into a simulator capable of constructing another’s absent emotion."]],"MC_THN_L1_02:RMD-04":[["[Functional Recurrence] Custom recurs as first-order projection, second-order regulation, affective stabilization, and constructive expectation, with renewed overextension at every phase.","Custom recurs as first-order projection, second-order regulation, affective stabilization, and constructive expectation, with renewed overextension at every phase."]],"MC_THN_L1_02:RMD-05":[["[Reversal] Comparison changes from a corrective instrument that exposes suppressed differences into a social operator that preserves difference as inverse self-estimation.","Comparison changes from a corrective instrument that exposes suppressed differences into a social operator that preserves difference as inverse self-estimation."]],"MC_THN_L1_02:RMD-06":[["[Migration] Relation migrates from conjunction, separability, and spatial compatibility into cognitive gating, self-reference, social proximity, directed transmission, and comparative interaction.","Relation migrates from conjunction, separability, and spatial compatibility into cognitive gating, self-reference, social proximity, directed transmission, and comparative interaction."]],"MC_THN_L1_02:RMD-07":[["[Terminal Transformation] The self moves from an absent invariant bearer to an operational object and finally to a socially constituted relay-comparator whose states are generated through feedback.","The self moves from an absent invariant bearer to an operational object and finally to a socially constituted relay-comparator whose states are generated through feedback."]],"MC_THN_L1_02:RMD-08":[["[Escalation] Cause shifts from whole-object identity to operative circumstance, then to domain-specific conversion, and finally to nonlinear circuits in which generated passions modify their own conditions.","Cause shifts from whole-object identity to operative circumstance, then to domain-specific conversion, and finally to nonlinear circuits in which generated passions modify their own conditions."]],"MC_THN_L1_02:RMD-09":[["[Mutation] Contradiction changes from a stimulus for metaphysical repair into a diagnostic of unrestricted transition and then into a controlled anomaly for reconstructing social-affective routing.","Contradiction changes from a stimulus for metaphysical repair into a diagnostic of unrestricted transition and then into a controlled anomaly for reconstructing social-affective routing."]],"MC_THN_L1_02:RMD-10":[["[Disappearance] Substance, autonomous reason, intrinsic value, primitive social instinct, and sovereign selfhood disappear after their explanatory work is redistributed across relation, force, custom, comparison, and feedback.","Substance, autonomous reason, intrinsic value, primitive social instinct, and sovereign selfhood disappear after their explanatory work is redistributed across relation, force, custom, comparison, and feedback."]],"MC_THN_L1_02:CGD-01":[["[Lower-Layer Local] Particular rules for isolating causal circumstances remain local experimental instruments; their scalable function is recursive differentiation under counterinstance.","Particular rules for isolating causal circumstances remain local experimental instruments; their scalable function is recursive differentiation under counterinstance."]],"MC_THN_L1_02:CGD-02":[["[Lower-Layer Local] Spatial compatibility, soul-substance, immortality, and the exact gates of pride and humility remain local problems rather than current-level explanatory centers.","Spatial compatibility, soul-substance, immortality, and the exact gates of pride and humility remain local problems rather than current-level explanatory centers."]],"MC_THN_L1_02:CGD-03":[["[Lower-Layer Local] Fame, wealth-esteem, pity, envy, malice, and the constitutional conjunctions of love or hatred remain local outputs of the broader relational machine.","Fame, wealth-esteem, pity, envy, malice, and the constitutional conjunctions of love or hatred remain local outputs of the broader relational machine."]],"MC_THN_L1_02:CGD-04":[["[Scaled] Relation-mediated force scales upward as the common architecture connecting belief, causal inference, affective conversion, and social valuation.","Relation-mediated force scales upward as the common architecture connecting belief, causal inference, affective conversion, and social valuation."]],"MC_THN_L1_02:CGD-05":[["[Bridge] Experimental circumstance-analysis and affective threshold-gating jointly establish that causal mechanisms are individuated by controlled differences in routing, not by whole-object classification.","Experimental circumstance-analysis and affective threshold-gating jointly establish that causal mechanisms are individuated by controlled differences in routing, not by whole-object classification."]],"MC_THN_L1_02:CGD-06":[["[Bridge] The operational self of the skeptical and affective analyses becomes the relay-comparator required by social transmission and reflected valuation.","The operational self of the skeptical and affective analyses becomes the relay-comparator required by social transmission and reflected valuation."]],"MC_THN_L1_02:CGD-07":[["[Catalyst] Social anomalies demonstrate that unchanged content or objective condition can generate opposed effects, forcing causation to include sequence, topology, retention, and mode selection.","Social anomalies demonstrate that unchanged content or objective condition can generate opposed effects, forcing causation to include sequence, topology, retention, and mode selection."]],"MC_THN_L1_02:CGD-08":[["[Recoded] Causal identity is recoded from an intrinsic power or whole object into a reproducible transformation distributed across input, relation, force, gate, and feedback.","Causal identity is recoded from an intrinsic power or whole object into a reproducible transformation distributed across input, relation, force, gate, and feedback."]],"MC_THN_L1_02:CGD-09":[["[Current-Level Emergent] Philosophy becomes a reflexive regulation of cognitive and social-affective machinery rather than a separate faculty judging nature from outside.","Philosophy becomes a reflexive regulation of cognitive and social-affective machinery rather than a separate faculty judging nature from outside."]],"MC_THN_L1_03:GA-01":[["[Persistent] Pleasure, pain, interest, uneasiness, sympathy, and acquired concern are the indispensable materials from which social and normative order must be generated.","Pleasure, pain, interest, uneasiness, sympathy, and acquired concern are the indispensable materials from which social and normative order must be generated."]],"MC_THN_L1_03:GA-02":[["[Attractor] Affective, juridical, and moral value is relationally constituted: objects, goods, persons, dispositions, and offices acquire force or status through mediated relations rather than intrinsic properties alone.","Affective, juridical, and moral value is relationally constituted: objects, goods, persons, dispositions, and offices acquire force or status through mediated relations rather than intrinsic properties alone."]],"MC_THN_L1_03:GA-03":[["[Persistent] Present force and authority are path-dependent effects of prior encounters, repeated conduct, stabilized expectations, institutional history, and accumulated evaluations.","Present force and authority are path-dependent effects of prior encounters, repeated conduct, stabilized expectations, institutional history, and accumulated evaluations."]],"MC_THN_L1_03:GA-04":[["[Mutating] Partiality is both destabilizing material and generative resource: immediate passion produces conflict, while reflected, coordinated, and generalized partiality produces durable order.","Partiality is both destabilizing material and generative resource: immediate passion produces conflict, while reflected, coordinated, and generalized partiality produces durable order."]],"MC_THN_L1_03:GA-05":[["[Mutating] Reflection is not a sovereign source of value; it changes the scale, temporal horizon, and organization of passions already in operation.","Reflection is not a sovereign source of value; it changes the scale, temporal horizon, and organization of passions already in operation."]],"MC_THN_L1_03:GA-06":[["[Persistent] A generated category cannot explain its own genesis: acquired ends cannot presuppose antecedent concern, justice cannot presuppose property, and allegiance cannot presuppose contractual obligation.","A generated category cannot explain its own genesis: acquired ends cannot presuppose antecedent concern, justice cannot presuppose property, and allegiance cannot presuppose contractual obligation."]],"MC_THN_L1_03:GA-07":[["[Attractor] Artifice is necessary without being arbitrary when durable natural limitations require second-order coordination but do not independently determine the form of that coordination.","Artifice is necessary without being arbitrary when durable natural limitations require second-order coordination but do not independently determine the form of that coordination."]],"MC_THN_L1_03:GA-08":[["[Persistent] Convention begins as mutually legible, conditionally reciprocal conduct whose repetition stabilizes expectation before explicit moral obligation or authoritative command.","Convention begins as mutually legible, conditionally reciprocal conduct whose repetition stabilizes expectation before explicit moral obligation or authoritative command."]],"MC_THN_L1_03:GA-09":[["[Terminal] Institutions constitute normative objects: stabilized possession becomes property, coordinated benefit becomes justice, and protective function becomes political authority only within rule-governed relations.","Institutions constitute normative objects: stabilized possession becomes property, coordinated benefit becomes justice, and protective function becomes political authority only within rule-governed relations."]],"MC_THN_L1_03:GA-10":[["[Emergent] Integral rights and stable verdicts require imposed closure because their affective, possessory, utilitarian, and relational grounds remain gradual, conflicting, and underdeterminate.","Integral rights and stable verdicts require imposed closure because their affective, possessory, utilitarian, and relational grounds remain gradual, conflicting, and underdeterminate."]],"MC_THN_L1_03:GA-11":[["[Mutating] Utility changes function across the architecture: it motivates coordination, necessitates institutions, sanctions rule-systems, and tests political authority, but does not uniquely determine every title or exhaust moral merit.","Utility changes function across the architecture: it motivates coordination, necessitates institutions, sanctions rule-systems, and tests political authority, but does not uniquely determine every title or exhaust moral merit."]],"MC_THN_L1_03:GA-12":[["[Mutating] Sympathy expands from affective transmission into institutional sanction and standpoint generalization, while never becoming universal benevolence or complete motivational impartiality.","Sympathy expands from affective transmission into institutional sanction and standpoint generalization, while never becoming universal benevolence or complete motivational impartiality."]],"MC_THN_L1_03:GA-13":[["[Attractor] Impartiality is manufactured by general rules, corrected standpoints, and invariant application rather than discovered in an originally impartial subject.","Impartiality is manufactured by general rules, corrected standpoints, and invariant application rather than discovered in an originally impartial subject."]],"MC_THN_L1_03:GA-14":[["[Persistent] Durable tendency, coordinated scheme, and relational function outrank isolated action, immediate consequence, and accidental outcome as objects of normative evaluation.","Durable tendency, coordinated scheme, and relational function outrank isolated action, immediate consequence, and accidental outcome as objects of normative evaluation."]],"MC_THN_L1_03:GA-15":[["[Emergent] Generated norms acquire relative autonomy: they can outlast their immediate motives, redirect later passions, and authorize judgments unavailable at the moment of their origin.","Generated norms acquire relative autonomy: they can outlast their immediate motives, redirect later passions, and authorize judgments unavailable at the moment of their origin."]],"MC_THN_L1_03:GA-16":[["[Terminal] Legitimate reversal must itself be generalized: accumulated, public, and recurrent anti-function—not isolated dislike or private injury—can terminate established authority.","Legitimate reversal must itself be generalized: accumulated, public, and recurrent anti-function—not isolated dislike or private injury—can terminate established authority."]],"MC_THN_L1_03:GA-17":[["[Terminal] The resulting order is endogenous, relational, plural, and conditionally stable; no single affective, legal, utilitarian, or moral mechanism completes every stage.","The resulting order is endogenous, relational, plural, and conditionally stable; no single affective, legal, utilitarian, or moral mechanism completes every stage."]],"MC_THN_L1_03:RMD-01":[["[Stable identity] Pleasure and pain remain the basic currency, but their function expands from direct affective modulation into support for inclination, institutional observance, moral approval, blame, and resistance.","Pleasure and pain remain the basic currency, but their function expands from direct affective modulation into support for inclination, institutional observance, moral approval, blame, and resistance."]],"MC_THN_L1_03:RMD-02":[["[Domain expansion] Relation moves from association and affective transfer to juridical attachment and finally to the evaluative field in which dispositions and institutions acquire moral identity.","Relation moves from association and affective transfer to juridical attachment and finally to the evaluative field in which dispositions and institutions acquire moral identity."]],"MC_THN_L1_03:RMD-03":[["[Functional recurrence] Repetition successively produces habit, reciprocal confidence, institutional sedimentation, stable moral language, and historical evidence of durable function or anti-function.","Repetition successively produces habit, reciprocal confidence, institutional sedimentation, stable moral language, and historical evidence of durable function or anti-function."]],"MC_THN_L1_03:RMD-04":[["[Mutation] Stability changes from affective relief into possessory security, juridical rigidity, normative inertia, and finally a condition vulnerable to reversal when it protects recurrent anti-function.","Stability changes from affective relief into possessory security, juridical rigidity, normative inertia, and finally a condition vulnerable to reversal when it protects recurrent anti-function."]],"MC_THN_L1_03:RMD-05":[["[Escalation] Sympathy begins as inter-organismic communication, becomes approval of public utility, and culminates in corrected moral judgment capable of evaluating strangers, institutions, and political effects.","Sympathy begins as inter-organismic communication, becomes approval of public utility, and culminates in corrected moral judgment capable of evaluating strangers, institutions, and political effects."]],"MC_THN_L1_03:RMD-06":[["[Mutation] Cognition shifts from an affective channel-selector into reflective interest, genealogical correction, and standpoint adjustment; its function is organizational rather than value-creating.","Cognition shifts from an affective channel-selector into reflective interest, genealogical correction, and standpoint adjustment; its function is organizational rather than value-creating."]],"MC_THN_L1_03:RMD-07":[["[Reversal] Self-interest changes from immediate acquisitive disruption into reciprocal restraint and then into allegiance to a system whose generalized rules can oppose immediate interest.","Self-interest changes from immediate acquisitive disruption into reciprocal restraint and then into allegiance to a system whose generalized rules can oppose immediate interest."]],"MC_THN_L1_03:RMD-08":[["[Mutation] Utility moves from an affectively mediated input to the necessity of settlement, then to institutional sanction, and finally to a functional criterion capable of withdrawing political authority.","Utility moves from an affectively mediated input to the necessity of settlement, then to institutional sanction, and finally to a functional criterion capable of withdrawing political authority."]],"MC_THN_L1_03:RMD-09":[["[Reversal] General rules first suppress local variability and preserve authority beyond immediate causes; recurrent public failure then produces a counter-rule that authorizes reclassification and resistance.","General rules first suppress local variability and preserve authority beyond immediate causes; recurrent public failure then produces a counter-rule that authorizes reclassification and resistance."]],"MC_THN_L1_03:RMD-10":[["[Absorption] The natural/artificial distinction is absorbed into a layered model in which natural affects and limitations supply materials while artificial coordination produces objects, rules, standpoints, and second-order dispositions.","The natural/artificial distinction is absorbed into a layered model in which natural affects and limitations supply materials while artificial coordination produces objects, rules, standpoints, and second-order dispositions."]],"MC_THN_L1_03:RMD-11":[["[Terminal transformation] Normative objects cease to appear antecedent to their relations: affective value, property, moral character, and political authority become stabilized outcomes of mediation, institution, and functional judgment.","Normative objects cease to appear antecedent to their relations: affective value, property, moral character, and political authority become stabilized outcomes of mediation, institution, and functional judgment."]],"MC_THN_L1_03:CGD-01":[["[Local] Species comparison, cognitive thresholds, excitatory bands, and the detailed mechanisms of curiosity remain affective diagnostics; their scalable result is the mediated and phase-sensitive constitution of motivation.","Species comparison, cognitive thresholds, excitatory bands, and the detailed mechanisms of curiosity remain affective diagnostics; their scalable result is the mediated and phase-sensitive constitution of motivation."]],"MC_THN_L1_03:CGD-02":[["[Local] Occupation, prescription, accession, succession, and municipal title rules remain juridical implementations; their scalable result is that gradual relations require socially imposed determinacy.","Occupation, prescription, accession, succession, and municipal title rules remain juridical implementations; their scalable result is that gradual relations require socially imposed determinacy."]],"MC_THN_L1_03:CGD-03":[["[Local] Pride, tenderness, anger, allegiance, and tyranny remain differentiated moral-political cases; their scalable result is evaluation by durable relational tendency and generalizable exception.","Pride, tenderness, anger, allegiance, and tyranny remain differentiated moral-political cases; their scalable result is evaluation by durable relational tendency and generalizable exception."]],"MC_THN_L1_03:CGD-04":[["[Scales upward] Affective mediation becomes the substrate of institutional genesis: passions can be redirected, transferred, and stabilized because they are not fixed responses to intrinsic object-values.","Affective mediation becomes the substrate of institutional genesis: passions can be redirected, transferred, and stabilized because they are not fixed responses to intrinsic object-values."]],"MC_THN_L1_03:CGD-05":[["[Scales upward] Path-dependence becomes sedimentary social ontology: repeated encounters create inclinations, repeated restraint creates convention, and repeated evaluation creates stable authority or evidence of anti-function.","Path-dependence becomes sedimentary social ontology: repeated encounters create inclinations, repeated restraint creates convention, and repeated evaluation creates stable authority or evidence of anti-function."]],"MC_THN_L1_03:CGD-06":[["[Bridge] Affective transfer and sympathy connect individual passion to public normativity by allowing generated force and perceived consequences to cross persons, practices, and institutions.","Affective transfer and sympathy connect individual passion to public normativity by allowing generated force and perceived consequences to cross persons, practices, and institutions."]],"MC_THN_L1_03:CGD-07":[["[Bridge] Relation and imagination connect affective association to juridical and moral object-construction: the same relational field joins ideas, persons, goods, duties, and evaluative roles.","Relation and imagination connect affective association to juridical and moral object-construction: the same relational field joins ideas, persons, goods, duties, and evaluative roles."]],"MC_THN_L1_03:CGD-08":[["[Catalyst] The possibility that conduct generates its later motive scales into the claim that observance can precede duty and that institutional authority can be retrospectively moralized.","The possibility that conduct generates its later motive scales into the claim that observance can precede duty and that institutional authority can be retrospectively moralized."]],"MC_THN_L1_03:CGD-09":[["[Recoded] Instinct, scarcity, limited benevolence, and shared affective constitution are retained not as complete explanations but as boundary conditions constraining what recursive construction can generate.","Instinct, scarcity, limited benevolence, and shared affective constitution are retained not as complete explanations but as boundary conditions constraining what recursive construction can generate."]],"MC_THN_L1_03:CGD-10":[["[Superseded] Intrinsic value, pre-social property, naturally impartial motivation, and absolute political title are replaced by mediated force, constituted relation, corrected judgment, and conditional function.","Intrinsic value, pre-social property, naturally impartial motivation, and absolute political title are replaced by mediated force, constituted relation, corrected judgment, and conditional function."]],"MC_THN_L1_03:ALT-B01":[["[Surface level] The explicit objects are affective variation, habit, curiosity, justice, possession, property, moral merit, political allegiance, tyranny, and resistance.","The explicit objects are affective variation, habit, curiosity, justice, possession, property, moral merit, political allegiance, tyranny, and resistance."]],"MC_THN_L1_03:ALT-B02":[["[Structural level] Mediation, transfer, repetition, reflected interest, reciprocal expectation, relation, imagination, general rules, sympathy, and functional testing form one recursive production system.","Mediation, transfer, repetition, reflected interest, reciprocal expectation, relation, imagination, general rules, sympathy, and functional testing form one recursive production system."]],"MC_THN_L1_03:ALT-B03":[["[Metastrategic level] Intervention requires diagnosing phase and scale: whether a force should be redirected, a relation stabilized, a boundary stipulated, a judgment corrected, or an institution reclassified under recurrent anti-function.","Intervention requires diagnosing phase and scale: whether a force should be redirected, a relation stabilized, a boundary stipulated, a judgment corrected, or an institution reclassified under recurrent anti-function."]],"MC_THN_L1_03:ALT-B04":[["[Ontological / Temporal level] Reality consists of historically accumulated relational configurations whose status can persist beyond immediate causes yet change through repeated performance and public reassessment.","Reality consists of historically accumulated relational configurations whose status can persist beyond immediate causes yet change through repeated performance and public reassessment."]],"MC_THN_L1_03:ALT-B05":[["[Methodological / Performative level] The architecture performs its thesis through differential variation, genealogical inversion, staged constitution, objection-driven correction, and terminal stress-testing of stabilized categories.","The architecture performs its thesis through differential variation, genealogical inversion, staged constitution, objection-driven correction, and terminal stress-testing of stabilized categories."]],"WB_THN:GA-01":[["[Attractor] Human nature is the medium within which evidence, reality, agency, value, and authority must be reconstructed and through which every reconstruction must itself operate.","Human nature is the medium within which evidence, reality, agency, value, and authority must be reconstructed and through which every reconstruction must itself operate."]],"WB_THN:GA-02":[["[Persistent] Legitimate explanation begins from perceptions, affects, experienced relations, observable operations, and recurrent effects rather than from inaccessible substances, essences, powers, or intrinsic values.","Legitimate explanation begins from perceptions, affects, experienced relations, observable operations, and recurrent effects rather than from inaccessible substances, essences, powers, or intrinsic values."]],"WB_THN:GA-03":[["[Persistent] The system produces no ex nihilo content, affective valence, or normative authority: higher-order novelty arises by reorganizing constrained perceptual, affective, natural, and social materials.","The system produces no ex nihilo content, affective valence, or normative authority: higher-order novelty arises by reorganizing constrained perceptual, affective, natural, and social materials."]],"WB_THN:GA-04":[["[Attractor] Relation is the trans-scalar operator that organizes perception, association, causation, self-reference, affective transmission, comparison, possession, duty, moral identity, and political function.","Relation is the trans-scalar operator that organizes perception, association, causation, self-reference, affective transmission, comparison, possession, duty, moral identity, and political function."]],"WB_THN:GA-05":[["[Mutating] Force develops from a difference among perceptions into transferable vivacity, affective activation, social efficacy, institutional adherence, and practical authority.","Force develops from a difference among perceptions into transferable vivacity, affective activation, social efficacy, institutional adherence, and practical authority."]],"WB_THN:GA-06":[["[Mutating] Repetition and custom move from stabilizing mental transitions to producing expectations, selves, social values, conventions, rights, moral inertia, and evidence for terminal reversal.","Repetition and custom move from stabilizing mental transitions to producing expectations, selves, social values, conventions, rights, moral inertia, and evidence for terminal reversal."]],"WB_THN:GA-07":[["[Attractor] Generated effects recursively become causes: ideas, beliefs, passions, reflected judgments, conventions, rules, and institutions return to reorganize subsequent perception, conduct, and relation.","Generated effects recursively become causes: ideas, beliefs, passions, reflected judgments, conventions, rules, and institutions return to reorganize subsequent perception, conduct, and relation."]],"WB_THN:GA-08":[["[Mutating] Imagination is both the productive medium of synthesis and the endogenous source of fictive completion, projected unity, social simulation, and institutionally mediated object-construction.","Imagination is both the productive medium of synthesis and the endogenous source of fictive completion, projected unity, social simulation, and institutionally mediated object-construction."]],"WB_THN:GA-09":[["[Emergent] Comparison is a branching operator: controlled variation can correct projection, retained contrast can produce rivalry, and generalized standpoint-comparison can stabilize public judgment.","Comparison is a branching operator: controlled variation can correct projection, retained contrast can produce rivalry, and generalized standpoint-comparison can stabilize public judgment."]],"WB_THN:GA-10":[["[Mutating] The self has no warranted status as a substantial origin but remains operationally indispensable as relay, temporal comparator, represented object, institutional participant, and recursive locus of attribution.","The self has no warranted status as a substantial origin but remains operationally indispensable as relay, temporal comparator, represented object, institutional participant, and recursive locus of attribution."]],"WB_THN:GA-11":[["[Emergent] Practical reality consists in stable relational efficacy: factual objects, social ranks, property, character, and authority become operative through regulated effects, expectations, classifications, and conduct.","Practical reality consists in stable relational efficacy: factual objects, social ranks, property, character, and authority become operative through regulated effects, expectations, classifications, and conduct."]],"WB_THN:GA-12":[["[Persistent] Natural production, subjective force, social circulation, and institutional stability do not by themselves establish truth, warrant, merit, justice, or legitimacy.","Natural production, subjective force, social circulation, and institutional stability do not by themselves establish truth, warrant, merit, justice, or legitimacy."]],"WB_THN:GA-13":[["[Attractor] Correction is immanent and recursive: source-audit, comparison, controlled variation, general rules, corrected standpoints, and functional reassessment regulate mechanisms from within the same system that generates error.","Correction is immanent and recursive: source-audit, comparison, controlled variation, general rules, corrected standpoints, and functional reassessment regulate mechanisms from within the same system that generates error."]],"WB_THN:GA-14":[["[Emergent] Time is constitutive and phase-changing: succession permits memory and projection, repetition creates disposition and authority, and accumulated performance can transform status rather than merely extend it.","Time is constitutive and phase-changing: succession permits memory and projection, repetition creates disposition and authority, and accumulated performance can transform status rather than merely extend it."]],"WB_THN:GA-15":[["[Emergent] Artifice is necessary without being arbitrary when natural constraints underdetermine the second-order forms required for stable coordination, judgment, and authority.","Artifice is necessary without being arbitrary when natural constraints underdetermine the second-order forms required for stable coordination, judgment, and authority."]],"WB_THN:GA-16":[["[Emergent] Agency is second-order navigation: intervention alters attention, association, comparison, circumstance, authority, expectation, rule, and institutional route rather than escaping the machinery of human nature.","Agency is second-order navigation: intervention alters attention, association, comparison, circumstance, authority, expectation, rule, and institutional route rather than escaping the machinery of human nature."]],"WB_THN:GA-17":[["[Terminal] The system closes as bounded recursive naturalism: explanatory operations are preserved, metaphysical foundations are withheld, determinate institutions remain revisable, and no stabilization is exempt from renewed audit.","The system closes as bounded recursive naturalism: explanatory operations are preserved, metaphysical foundations are withheld, determinate institutions remain revisable, and no stabilization is exempt from renewed audit."]],"WB_THN:RMD-01":[["[Stable identity] Experience remains the admissible field from perceptual genealogy through causal experiment, affective analysis, institutional genesis, and political reassessment.","Experience remains the admissible field from perceptual genealogy through causal experiment, affective analysis, institutional genesis, and political reassessment."]],"WB_THN:RMD-02":[["[Escalation] Genealogy expands from tracing ideational content to tracing conviction, self-attribution, social value, property, obligation, and political legitimacy.","Genealogy expands from tracing ideational content to tracing conviction, self-attribution, social value, property, obligation, and political legitimacy."]],"WB_THN:RMD-03":[["[Absorption] The idea begins as a derivative switching element and is progressively absorbed into the broader categories of representation, simulated condition, social classification, and constituted normative object.","The idea begins as a derivative switching element and is progressively absorbed into the broader categories of representation, simulated condition, social classification, and constituted normative object."]],"WB_THN:RMD-04":[["[Domain expansion] Relation moves from perceptual arrangement and association into causal routing, affective transmission, social topology, juridical attachment, and moral-political identity.","Relation moves from perceptual arrangement and association into causal routing, affective transmission, social topology, juridical attachment, and moral-political identity."]],"WB_THN:RMD-05":[["[Escalation] Force progresses from perceptual classification to belief-production, affective activation, social circulation, institutional observance, and practical authority.","Force progresses from perceptual classification to belief-production, affective activation, social circulation, institutional observance, and practical authority."]],"WB_THN:RMD-06":[["[Terminal transformation] Repetition changes from recurrence into custom, feedback, convention, second nature, normative inertia, and finally accumulated evidence capable of authorizing reversal.","Repetition changes from recurrence into custom, feedback, convention, second nature, normative inertia, and finally accumulated evidence capable of authorizing reversal."]],"WB_THN:RMD-07":[["[Mutation] Imagination changes from recombination and associative completion into factual projection, metaphysical fiction, constructive sympathy, and social object-production.","Imagination changes from recombination and associative completion into factual projection, metaphysical fiction, constructive sympathy, and social object-production."]],"WB_THN:RMD-08":[["[Reversal] Comparison begins as source-sensitive differentiation, reverses into affective opposition and self-estimation, and is recoded as corrected public standpoint.","Comparison begins as source-sensitive differentiation, reverses into affective opposition and self-estimation, and is recoded as corrected public standpoint."]],"WB_THN:RMD-09":[["[Escalation] Causation moves from perceptual dependence and customary transition to gated conversion, social feedback, institutional path-production, and historical reassessment.","Causation moves from perceptual dependence and customary transition to gated conversion, social feedback, institutional path-production, and historical reassessment."]],"WB_THN:RMD-10":[["[Mutation] Reality moves from regulated factual presence to socially productive representation and finally to historically stabilized juridical, moral, and political status.","Reality moves from regulated factual presence to socially productive representation and finally to historically stabilized juridical, moral, and political status."]],"WB_THN:RMD-11":[["[Terminal transformation] The subject changes from non-originating relay to temporal comparator, socially permeable self-reference, institutionally installed participant, and possible resister.","The subject changes from non-originating relay to temporal comparator, socially permeable self-reference, institutionally installed participant, and possible resister."]],"WB_THN:RMD-12":[["[Reversal] General rules first regulate conviction and suppress local variation, then produce stable public judgment, and finally become counter-rules capable of revising authority.","General rules first regulate conviction and suppress local variation, then produce stable public judgment, and finally become counter-rules capable of revising authority."]],"WB_THN:RMD-13":[["[Terminal transformation] Ignorance and skepticism cease to be merely privative: they become permanent controls that prohibit metaphysical completion while preserving operational inquiry and conditional authority.","Ignorance and skepticism cease to be merely privative: they become permanent controls that prohibit metaphysical completion while preserving operational inquiry and conditional authority."]],"WB_THN:RMD-14":[["[Disappearance] Substance, autonomous faculties, intrinsic powers, pre-social rights, and sovereign reason disappear after their explanatory functions are redistributed across materials, relations, force, repetition, gates, and institutions.","Substance, autonomous faculties, intrinsic powers, pre-social rights, and sovereign reason disappear after their explanatory functions are redistributed across materials, relations, force, repetition, gates, and institutions."]],"WB_THN:CGD-01":[["[Local] The missing shade, exact mnemonic fidelity, perceptual minima, and the sensory specifications of extension remain local tests of the early content-genealogy.","The missing shade, exact mnemonic fidelity, perceptual minima, and the sensory specifications of extension remain local tests of the early content-genealogy."]],"WB_THN:CGD-02":[["[Local] The exact inventory of associative relations, the detailed status of empty space and time, and particular classifications of fiction remain subordinate implementations of the de-additive architecture.","The exact inventory of associative relations, the detailed status of empty space and time, and particular classifications of fiction remain subordinate implementations of the de-additive architecture."]],"WB_THN:CGD-03":[["[Local] Particular experimental rules, questions of spatial compatibility, soul-substance, and the exact gates of pride and humility remain domain-specific instruments or targets.","Particular experimental rules, questions of spatial compatibility, soul-substance, and the exact gates of pride and humility remain domain-specific instruments or targets."]],"WB_THN:CGD-04":[["[Local] Named passions, title doctrines, legal modes of acquisition, and particular political cases remain local outputs of broader relational and institutional machinery.","Named passions, title doctrines, legal modes of acquisition, and particular political cases remain local outputs of broader relational and institutional machinery."]],"WB_THN:CGD-05":[["[Domain-bound] Utility scales as motive, sanction, and functional test but does not become a universal metric of truth, title, virtue, or every institutional decision.","Utility scales as motive, sanction, and functional test but does not become a universal metric of truth, title, virtue, or every institutional decision."]],"WB_THN:CGD-06":[["[Scales upward] The prohibition on essence-first explanation governs the treatment of mind, causation, self, value, property, morality, and authority.","The prohibition on essence-first explanation governs the treatment of mind, causation, self, value, property, morality, and authority."]],"WB_THN:CGD-07":[["[Scales upward] Relation-mediated force becomes the common architecture connecting factual belief, passion, social valuation, institutional adherence, and political efficacy.","Relation-mediated force becomes the common architecture connecting factual belief, passion, social valuation, institutional adherence, and political efficacy."]],"WB_THN:CGD-08":[["[Bridge] Ideas, imagination, and represented conditions connect perceptual derivation to belief, sympathy, comparison, social object-construction, and moral classification.","Ideas, imagination, and represented conditions connect perceptual derivation to belief, sympathy, comparison, social object-construction, and moral classification."]],"WB_THN:CGD-09":[["[Bridge] Custom and repetition connect mental regularity to social expectation, reciprocal convention, institutional persistence, and normative inertia.","Custom and repetition connect mental regularity to social expectation, reciprocal convention, institutional persistence, and normative inertia."]],"WB_THN:CGD-10":[["[Catalyst] Counterfeit belief, contradictory affect, reversed social valence, and recurrent institutional failure scale upward as anomaly-mechanisms forcing restriction, differentiation, and reversal.","Counterfeit belief, contradictory affect, reversed social valence, and recurrent institutional failure scale upward as anomaly-mechanisms forcing restriction, differentiation, and reversal."]],"WB_THN:CGD-11":[["[Superseded and recoded] Passive copying, sealed faculties, linear causation, pre-social subjects, intrinsic value, and unconditional authority are replaced by recursive production, distributed routing, constituted objects, and conditional legitimacy.","Passive copying, sealed faculties, linear causation, pre-social subjects, intrinsic value, and unconditional authority are replaced by recursive production, distributed routing, constituted objects, and conditional legitimacy."]],"WB_THN:ALT-B01":[["[Surface level] The explicit field comprises perceptions, ideas, space, time, causation, belief, selfhood, passions, social esteem, justice, property, morality, allegiance, tyranny, and resistance.","The explicit field comprises perceptions, ideas, space, time, causation, belief, selfhood, passions, social esteem, justice, property, morality, allegiance, tyranny, and resistance."]],"WB_THN:ALT-B02":[["[Structural level] Copying, relation, recombination, force-transfer, repetition, comparison, gating, feedback, convention, generalization, and functional reassessment form the distributed mechanism.","Copying, relation, recombination, force-transfer, repetition, comparison, gating, feedback, convention, generalization, and functional reassessment form the distributed mechanism."]],"WB_THN:ALT-B03":[["[Metastrategic level] Inquiry and intervention proceed by auditing provenance, widening comparison, varying circumstances, rerouting force, diagnosing temporal phase, and distinguishing local failure from general anti-function.","Inquiry and intervention proceed by auditing provenance, widening comparison, varying circumstances, rerouting force, diagnosing temporal phase, and distinguishing local failure from general anti-function."]],"WB_THN:ALT-B04":[["[Ontological / Temporal level] Reality consists of historically organized events and relations whose identities arise through recurrence, efficacy, attribution, and institutional stabilization; time can preserve, intensify, constitute, or reverse them.","Reality consists of historically organized events and relations whose identities arise through recurrence, efficacy, attribution, and institutional stabilization; time can preserve, intensify, constitute, or reverse them."]],"WB_THN:ALT-B05":[["[Social / Political level] Authority, testimony, proximity, reputation, convention, law, and reflected esteem distribute the force through which judgments, rights, hierarchies, and resistance become operative.","Authority, testimony, proximity, reputation, convention, law, and reflected esteem distribute the force through which judgments, rights, hierarchies, and resistance become operative."]],"WB_THN:ALT-B06":[["[Methodological / Performative level] The system performs its thesis by decomposing apparent unities, producing controlled excess, converting anomaly into differential analysis, and recursively testing every stabilization against its effects.","The system performs its thesis by decomposing apparent unities, producing controlled excess, converting anomaly into differential analysis, and recursively testing every stabilization against its effects."]],"CL_MEMA_01:GA-01":[["[Persistent] La matière constitue un champ d’images indépendant de la perception particulière qui le centre ou le sélectionne.","La matière constitue un champ d’images indépendant de la perception particulière qui le centre ou le sélectionne."]],"CL_MEMA_01:GA-02":[["[Persistent] Le corps est simultanément une image du champ matériel et un centre d’action capable de suspendre, choisir et transmettre des mouvements.","Le corps est simultanément une image du champ matériel et un centre d’action capable de suspendre, choisir et transmettre des mouvements."]],"CL_MEMA_01:GA-03":[["[Persistent] Le cerveau distribue les conditions motrices de l’action sans produire ni contenir la totalité représentative de la conscience.","Le cerveau distribue les conditions motrices de l’action sans produire ni contenir la totalité représentative de la conscience."]],"CL_MEMA_01:GA-04":[["[Persistent] La perception est une sélection soustractive du réel matériel en fonction des actions possibles d’un corps, non une construction ajoutée au monde.","La perception est une sélection soustractive du réel matériel en fonction des actions possibles d’un corps, non une construction ajoutée au monde."]],"CL_MEMA_01:GA-05":[["[Mutating] L’action passe du statut d’orientation utilitaire des fonctions mentales à celui d’opérateur qui inhibe, contracte et actualise le passé.","L’action passe du statut d’orientation utilitaire des fonctions mentales à celui d’opérateur qui inhibe, contracte et actualise le passé."]],"CL_MEMA_01:GA-06":[["[Mutating] La mémoire passe d’un point d’intersection entre esprit et matière à une survivance virtuelle du passé qui temporalise et subjectivise la perception.","La mémoire passe d’un point d’intersection entre esprit et matière à une survivance virtuelle du passé qui temporalise et subjectivise la perception."]],"CL_MEMA_01:GA-07":[["[Persistent] Perception, affection, souvenir et habitude ne forment pas une série homogène d’intensités, mais des régimes fonctionnels ou ontologiques distincts.","Perception, affection, souvenir et habitude ne forment pas une série homogène d’intensités, mais des régimes fonctionnels ou ontologiques distincts."]],"CL_MEMA_01:GA-08":[["[Emergent] Le passé survit selon deux modalités irréductibles : dispositif moteur incorporé au corps et image-souvenir conservée indépendamment de lui.","Le passé survit selon deux modalités irréductibles : dispositif moteur incorporé au corps et image-souvenir conservée indépendamment de lui."]],"CL_MEMA_01:GA-09":[["[Emergent] La reconnaissance se distribue entre prolongement moteur automatique et reconstruction attentive par insertion de souvenirs.","La reconnaissance se distribue entre prolongement moteur automatique et reconstruction attentive par insertion de souvenirs."]],"CL_MEMA_01:GA-10":[["[Emergent] L’attention est une boucle récursive dans laquelle la mémoire projetée reconstruit la perception qui l’a sollicitée et élargit progressivement son réseau de relations.","L’attention est une boucle récursive dans laquelle la mémoire projetée reconstruit la perception qui l’a sollicitée et élargit progressivement son réseau de relations."]],"CL_MEMA_01:GA-11":[["[Terminal] Dans le modèle reconstruit, la lésion cérébrale altère la sélection, la coordination ou l’application des souvenirs sans démontrer leur destruction.","Dans le modèle reconstruit, la lésion cérébrale altère la sélection, la coordination ou l’application des souvenirs sans démontrer leur destruction."]],"CL_MEMA_01:GA-12":[["[Attractor] Le sujet est la temporalisation d’un centre d’action : la mémoire contracte le passé virtuel au point mobile où il peut infléchir l’avenir.","Le sujet est la temporalisation d’un centre d’action : la mémoire contracte le passé virtuel au point mobile où il peut infléchir l’avenir."]],"CL_MEMA_01:GA-13":[["[Terminal] Le mouvement matériel peut conditionner le passage d’une représentation à l’action, mais il ne peut engendrer par lui-même une représentation qualitative.","Le mouvement matériel peut conditionner le passage d’une représentation à l’action, mais il ne peut engendrer par lui-même une représentation qualitative."]],"CL_MEMA_01:RMD-01":[["[Stable identity] L’image demeure l’unité commune de la matière et de la perception, mais son organisation passe d’un champ acentrique d’actions réelles à un système centré d’actions virtuelles.","L’image demeure l’unité commune de la matière et de la perception, mais son organisation passe d’un champ acentrique d’actions réelles à un système centré d’actions virtuelles."]],"CL_MEMA_01:RMD-02":[["[Functional recurrence] Le cerveau conserve sa fonction de transmission motrice tout en l’étendant à l’inhibition, à la sélection et à la coordination des conditions d’actualisation.","Le cerveau conserve sa fonction de transmission motrice tout en l’étendant à l’inhibition, à la sélection et à la coordination des conditions d’actualisation."]],"CL_MEMA_01:RMD-03":[["[Mutation] L’action, d’abord principe de sélection perceptive, devient le régime temporel qui contracte le passé et décide de son efficacité présente.","L’action, d’abord principe de sélection perceptive, devient le régime temporel qui contracte le passé et décide de son efficacité présente."]],"CL_MEMA_01:RMD-04":[["[Escalation] La mémoire migre d’un terrain probatoire du dualisme vers l’opérateur de subjectivation, puis vers le mode ontologique de survivance virtuelle du passé.","La mémoire migre d’un terrain probatoire du dualisme vers l’opérateur de subjectivation, puis vers le mode ontologique de survivance virtuelle du passé."]],"CL_MEMA_01:RMD-05":[["[Absorption into a higher-order structure] La perception pure accomplit sa fonction en établissant l’extériorité de la perception, puis est absorbée dans la perception concrète comme couche limite toujours mêlée de mémoire et d’affection.","La perception pure accomplit sa fonction en établissant l’extériorité de la perception, puis est absorbée dans la perception concrète comme couche limite toujours mêlée de mémoire et d’affection."]],"CL_MEMA_01:RMD-06":[["[Displacement] La pathologie quitte le modèle de la destruction d’un contenu pour devenir une cartographie des ruptures entre perception, attitude motrice, actualisation et action.","La pathologie quitte le modèle de la destruction d’un contenu pour devenir une cartographie des ruptures entre perception, attitude motrice, actualisation et action."]],"CL_MEMA_01:RMD-07":[["[Terminal transformation] Le conflit entre matérialisme et spiritualisme est déplacé de la production de la perception vers la conservation et l’actualisation du passé.","Le conflit entre matérialisme et spiritualisme est déplacé de la production de la perception vers la conservation et l’actualisation du passé."]],"CL_MEMA_01:CGD-01":[["[Local] La perception pure, la douleur, l’éducation sensorielle et les schèmes verbaux sont des machines analytiques locales ; elles ne portent le cluster qu’en tant qu’épreuves différentielles des fonctions de passage.","La perception pure, la douleur, l’éducation sensorielle et les schèmes verbaux sont des machines analytiques locales ; elles ne portent le cluster qu’en tant qu’épreuves différentielles des fonctions de passage."]],"CL_MEMA_01:CGD-02":[["[Scale change] La matière-image cesse d’être seulement une solution au débat réaliste-idéaliste et devient le fond ontologique nécessaire à la limitation du pouvoir représentatif du cerveau.","La matière-image cesse d’être seulement une solution au débat réaliste-idéaliste et devient le fond ontologique nécessaire à la limitation du pouvoir représentatif du cerveau."]],"CL_MEMA_01:CGD-03":[["[Connector] L’orientation vers l’action relie l’ontologie des images, la sélection perceptive, l’inhibition mnésique, la reconnaissance et l’interprétation des lésions.","L’orientation vers l’action relie l’ontologie des images, la sélection perceptive, l’inhibition mnésique, la reconnaissance et l’interprétation des lésions."]],"CL_MEMA_01:CGD-04":[["[Catalyst] La mémoire catalyse le passage d’une topologie du corps parmi les images à une ontologie temporelle du passé virtuel.","La mémoire catalyse le passage d’une topologie du corps parmi les images à une ontologie temporelle du passé virtuel."]],"CL_MEMA_01:CGD-05":[["[Recoded] La corrélation psychophysiologique n’est plus l’indice d’une équivalence entre séries mentale et cérébrale, mais celui de leur coordination autour d’une même possibilité d’action.","La corrélation psychophysiologique n’est plus l’indice d’une équivalence entre séries mentale et cérébrale, mais celui de leur coordination autour d’une même possibilité d’action."]],"CL_MEMA_01:CGD-06":[["[Obsolescent] Les modèles du cerveau-magasin, de l’association linéaire et de la représentation comme copie deviennent inutilisables dès que le système adopte la sélection et l’actualisation comme opérations fondamentales.","Les modèles du cerveau-magasin, de l’association linéaire et de la représentation comme copie deviennent inutilisables dès que le système adopte la sélection et l’actualisation comme opérations fondamentales."]],"CL_MEMA_01:ALT-B01":[["[Surface level] Les objets explicites sont les images matérielles, le corps, le cerveau, la perception, les deux mémoires, les reconnaissances et leurs troubles.","Les objets explicites sont les images matérielles, le corps, le cerveau, la perception, les deux mémoires, les reconnaissances et leurs troubles."]],"CL_MEMA_01:ALT-B02":[["[Structural level] La machine active articule indétermination, circuit sensori-moteur, sélection perceptive, inhibition du passé, projection mnésique et insertion dans l’action.","La machine active articule indétermination, circuit sensori-moteur, sélection perceptive, inhibition du passé, projection mnésique et insertion dans l’action."]],"CL_MEMA_01:ALT-B03":[["[Metastrategic level] Les oppositions d’école sont remplacées par l’analyse différentielle des fonctions de production supposée, de sélection réelle, de conservation et d’actualisation.","Les oppositions d’école sont remplacées par l’analyse différentielle des fonctions de production supposée, de sélection réelle, de conservation et d’actualisation."]],"CL_MEMA_01:ALT-B04":[["[Ontological / Temporal level] Le réel combine un présent matériel actif, un passé virtuellement conservé et un avenir défini par la latitude motrice du corps.","Le réel combine un présent matériel actif, un passé virtuellement conservé et un avenir défini par la latitude motrice du corps."]],"CL_MEMA_01:ALT-B05":[["[Methodological / Performative level] La forme de l’argument accomplit sa thèse en abstrayant d’abord la mémoire pour isoler une fonction, puis en la réintroduisant afin de reconstruire récursivement l’objet à un niveau plus complexe.","La forme de l’argument accomplit sa thèse en abstrayant d’abord la mémoire pour isoler une fonction, puis en la réintroduisant afin de reconstruire récursivement l’objet à un niveau plus complexe."]],"CL_MEMA_02:GA-01":[["[Persistent] L’action constitue la norme de sélection qui organise la perception, l’actualisation mnésique et la conscience corporelle.","L’action constitue la norme de sélection qui organise la perception, l’actualisation mnésique et la conscience corporelle."]],"CL_MEMA_02:GA-02":[["[Persistent] Le corps et le cerveau relaient, sélectionnent et actualisent les représentations sans les produire ni les conserver.","Le corps et le cerveau relaient, sélectionnent et actualisent les représentations sans les produire ni les conserver."]],"CL_MEMA_02:GA-03":[["[Persistent] Le réel excède l’actuel conscient ; l’absence d’action présente ne constitue donc pas un critère d’inexistence.","Le réel excède l’actuel conscient ; l’absence d’action présente ne constitue donc pas un critère d’inexistence."]],"CL_MEMA_02:GA-04":[["[Mutating] La perception passe du statut d’état interne à celui de sélection objective et partielle d’actions virtuelles dans les choses.","La perception passe du statut d’état interne à celui de sélection objective et partielle d’actions virtuelles dans les choses."]],"CL_MEMA_02:GA-05":[["[Persistent] Le passé subsiste virtuellement dans la mémoire pure indépendamment de sa conservation cérébrale.","Le passé subsiste virtuellement dans la mémoire pure indépendamment de sa conservation cérébrale."]],"CL_MEMA_02:GA-06":[["[Mutating] Le présent et la conscience désignent l’efficacité agissante d’un état plutôt que la totalité de ce qui existe psychologiquement.","Le présent et la conscience désignent l’efficacité agissante d’un état plutôt que la totalité de ce qui existe psychologiquement."]],"CL_MEMA_02:GA-07":[["[Emergent] Toute perception concrète résulte d’une synthèse durable entre présence matérielle, affection corporelle et contraction mémorielle.","Toute perception concrète résulte d’une synthèse durable entre présence matérielle, affection corporelle et contraction mémorielle."]],"CL_MEMA_02:GA-08":[["[Persistent] La réalité doit être saisie comme continuité de devenir et de transformations, non comme assemblage d’états isolés.","La réalité doit être saisie comme continuité de devenir et de transformations, non comme assemblage d’états isolés."]],"CL_MEMA_02:GA-09":[["[Persistent] L’espace et le temps homogènes sont des instruments pratiques de division et de fixation, non les formes originaires du réel.","L’espace et le temps homogènes sont des instruments pratiques de division et de fixation, non les formes originaires du réel."]],"CL_MEMA_02:GA-10":[["[Emergent] L’extension, la tension, la contraction et le rythme convertissent les oppositions absolues en différences graduelles de durée.","L’extension, la tension, la contraction et le rythme convertissent les oppositions absolues en différences graduelles de durée."]],"CL_MEMA_02:GA-11":[["[Terminal] La matière tend à répéter des moments équivalents, tandis que l’esprit conserve le passé et l’engage dans une action capable de nouveauté.","La matière tend à répéter des moments équivalents, tandis que l’esprit conserve le passé et l’engage dans une action capable de nouveauté."]],"CL_MEMA_02:GA-12":[["[Attractor] L’union du corps et de l’esprit réside dans le passage opératoire du virtuel à l’agissant, non dans une causalité représentative ou un pont extérieur.","L’union du corps et de l’esprit réside dans le passage opératoire du virtuel à l’agissant, non dans une causalité représentative ou un pont extérieur."]],"CL_MEMA_02:GA-13":[["[Terminal] La liberté croît avec la contraction du passé et la pluralité des réponses motrices, tout en restant organisée avec la nécessité matérielle.","La liberté croît avec la contraction du passé et la pluralité des réponses motrices, tout en restant organisée avec la nécessité matérielle."]],"WB_MEMA:GA-01":[["[Persistent] L’action est la norme transversale qui sélectionne la perception, inhibe ou actualise le souvenir et organise les réponses corporelles.","L’action est la norme transversale qui sélectionne la perception, inhibe ou actualise le souvenir et organise les réponses corporelles."],["[Persistent] Action is the transversal norm that selects perception, inhibits or actualizes memory, and organizes bodily responses.","Action is the transversal norm that selects perception, inhibits or actualizes memory, and organizes bodily responses."]],"WB_MEMA:GA-02":[["[Mutating] La matière passe du champ acentrique d’images à une continuité de transformations rythmiques sans devenir une substance cachée derrière ses manifestations.","La matière passe du champ acentrique d’images à une continuité de transformations rythmiques sans devenir une substance cachée derrière ses manifestations."],["[Mutating] Matter moves from the acentric field of images to a continuity of rhythmic transformations without becoming a substance hidden behind its manifestations.","Matter moves from the acentric field of images to a continuity of rhythmic transformations without becoming a substance hidden behind its manifestations."]],"WB_MEMA:GA-03":[["[Persistent] Le corps est une image différenciée en centre d’action, capable de fermer certains accès et de retarder la conversion de l’excitation en mouvement.","Le corps est une image différenciée en centre d’action, capable de fermer certains accès et de retarder la conversion de l’excitation en mouvement."],["[Persistent] The body is an image differentiated into a center of action, capable of closing certain accesses and delaying the conversion of excitation into movement.","The body is an image differentiated into a center of action, capable of closing certain accesses and delaying the conversion of excitation into movement."]],"WB_MEMA:GA-04":[["[Persistent] Le cerveau règle les conditions motrices, sélectives et inhibitrices de l’actualisation sans produire ni conserver les représentations qu’il rend efficaces.","Le cerveau règle les conditions motrices, sélectives et inhibitrices de l’actualisation sans produire ni conserver les représentations qu’il rend efficaces."],["[Persistent] The brain regulates the motor, selective, and inhibitory conditions of actualization without producing or preserving the representations it renders effective.","The brain regulates the motor, selective, and inhibitory conditions of actualization without producing or preserving the representations it renders effective."]],"WB_MEMA:GA-05":[["[Mutating] La perception passe d’une soustraction limite du champ matériel à une synthèse concrète de présence, d’affection et de contraction mémorielle.","La perception passe d’une soustraction limite du champ matériel à une synthèse concrète de présence, d’affection et de contraction mémorielle."],["[Mutating] Perception moves from a subtractive limit of the material field to a concrete synthesis of presence, affection, and memorial contraction.","Perception moves from a subtractive limit of the material field to a concrete synthesis of presence, affection, and memorial contraction."]],"WB_MEMA:GA-06":[["[Mutating] La mémoire passe de la survivance virtuelle du passé au principe temporel de subjectivation, d’indétermination et de liberté.","La mémoire passe de la survivance virtuelle du passé au principe temporel de subjectivation, d’indétermination et de liberté."],["[Mutating] Memory moves from the virtual survival of the past to the temporal principle of subjectivation, indetermination, and freedom.","Memory moves from the virtual survival of the past to the temporal principle of subjectivation, indetermination, and freedom."]],"WB_MEMA:GA-07":[["[Persistent] Le réel excède l’actuel conscient : l’inefficacité présente ne constitue ni inexistence ni annihilation ontologique.","Le réel excède l’actuel conscient : l’inefficacité présente ne constitue ni inexistence ni annihilation ontologique."],["[Persistent] The real exceeds the conscious actual: present inefficacy constitutes neither nonexistence nor ontological annihilation.","The real exceeds the conscious actual: present inefficacy constitutes neither nonexistence nor ontological annihilation."]],"WB_MEMA:GA-08":[["[Emergent] L’union du corps et de l’esprit consiste en une continuité opératoire entre des termes distincts, le corps réglant le passage du virtuel à l’agissant.","L’union du corps et de l’esprit consiste en une continuité opératoire entre des termes distincts, le corps réglant le passage du virtuel à l’agissant."],["[Emergent] The union of body and mind consists in an operative continuity between distinct terms, the body regulating the passage from the virtual to the acting.","The union of body and mind consists in an operative continuity between distinct terms, the body regulating the passage from the virtual to the acting."]],"WB_MEMA:GA-09":[["[Emergent] La spatialisation est un produit pratique de division et de fixation dont la réification engendre les antinomies métaphysiques.","La spatialisation est un produit pratique de division et de fixation dont la réification engendre les antinomies métaphysiques."],["[Emergent] Spatialization is a practical product of division and fixation whose reification engenders metaphysical antinomies.","Spatialization is a practical product of division and fixation whose reification engenders metaphysical antinomies."]],"WB_MEMA:GA-10":[["[Terminal] La différence entre matière et esprit est finalement temporelle : répétition de moments équivalents contre conservation transformatrice du passé.","La différence entre matière et esprit est finalement temporelle : répétition de moments équivalents contre conservation transformatrice du passé."],["[Terminal] The difference between matter and mind is ultimately temporal: repetition of equivalent moments versus transformative preservation of the past.","The difference between matter and mind is ultimately temporal: repetition of equivalent moments versus transformative preservation of the past."]],"WB_MEMA:GA-11":[["[Attractor] La contraction règle conjointement la densité perceptive, la mobilisation du passé, les rythmes matériels et les degrés d’agentivité.","La contraction règle conjointement la densité perceptive, la mobilisation du passé, les rythmes matériels et les degrés d’agentivité."],["[Attractor] Contraction jointly regulates perceptual density, mobilization of the past, material rhythms, and degrees of agency.","Contraction jointly regulates perceptual density, mobilization of the past, material rhythms, and degrees of agency."]],"WB_MEMA:GA-12":[["[Terminal] La liberté est une capacité graduelle de différer la réaction et de pluraliser les réponses à l’intérieur de la nécessité matérielle.","La liberté est une capacité graduelle de différer la réaction et de pluraliser les réponses à l’intérieur de la nécessité matérielle."],["[Terminal] Freedom is a gradual capacity to defer reaction and pluralize responses within material necessity.","Freedom is a gradual capacity to defer reaction and pluralize responses within material necessity."]],"WB_MEMA:GA-13":[["[Persistent] Perception, affection, habitude et souvenir appartiennent à des régimes hétérogènes ; les degrés décrivent leurs médiations, non leur dérivation les uns des autres.","Perception, affection, habitude et souvenir appartiennent à des régimes hétérogènes ; les degrés décrivent leurs médiations, non leur dérivation les uns des autres."],["[Persistent] Perception, affection, habit, and memory belong to heterogeneous regimes; degrees describe their mediations, not their derivation from one another.","Perception, affection, habit, and memory belong to heterogeneous regimes; degrees describe their mediations, not their derivation from one another."]],"WB_MEMA:RMD-01":[["[Stable identity] L’image demeure l’unité commune du matériel et du perceptible, mais le champ acentrique d’actions devient progressivement un continuum de transformations rythmiques.","L’image demeure l’unité commune du matériel et du perceptible, mais le champ acentrique d’actions devient progressivement un continuum de transformations rythmiques."],["[Stable identity] The image remains the common unit of the material and the perceptible, but the acentric field of actions progressively becomes a continuum of rhythmic transformations.","The image remains the common unit of the material and the perceptible, but the acentric field of actions progressively becomes a continuum of rhythmic transformations."]],"WB_MEMA:RMD-02":[["[Reversal] L’action revient d’abord comme principe de sélection, puis comme origine des découpages réifiés qu’une métaphysique du continu doit renverser.","L’action revient d’abord comme principe de sélection, puis comme origine des découpages réifiés qu’une métaphysique du continu doit renverser."],["[Reversal] Action first returns as a principle of selection, then as the origin of reified divisions that a metaphysics of the continuous must reverse.","Action first returns as a principle of selection, then as the origin of reified divisions that a metaphysics of the continuous must reverse."]],"WB_MEMA:RMD-03":[["[Functional recurrence] Le cerveau conserve sa fonction de relais tout en devenant filtre, inhibiteur, commutateur et organe positif d’exclusion.","Le cerveau conserve sa fonction de relais tout en devenant filtre, inhibiteur, commutateur et organe positif d’exclusion."],["[Functional recurrence] The brain retains its function as relay while becoming filter, inhibitor, switch, and positive organ of exclusion.","The brain retains its function as relay while becoming filter, inhibitor, switch, and positive organ of exclusion."]],"WB_MEMA:RMD-04":[["[Mutation] La perception pure, d’abord limite soustractive, est absorbée dans une perception concrète où l’extraction objective est inséparable de la mémoire et de l’affection.","La perception pure, d’abord limite soustractive, est absorbée dans une perception concrète où l’extraction objective est inséparable de la mémoire et de l’affection."],["[Mutation] Pure perception, initially a subtractive limit, is absorbed into a concrete perception in which objective extraction is inseparable from memory and affection.","Pure perception, initially a subtractive limit, is absorbed into a concrete perception in which objective extraction is inseparable from memory and affection."]],"WB_MEMA:RMD-05":[["[Escalation] La mémoire s’étend de la survivance psychologique à la définition temporelle de l’esprit, puis à une réserve d’indétermination et de liberté.","La mémoire s’étend de la survivance psychologique à la définition temporelle de l’esprit, puis à une réserve d’indétermination et de liberté."],["[Escalation] Memory extends from psychological survival to the temporal definition of mind, then to a reserve of indetermination and freedom.","Memory extends from psychological survival to the temporal definition of mind, then to a reserve of indetermination and freedom."]],"WB_MEMA:RMD-06":[["[Reversal] L’espace homogène passe du statut de cadre présumé du réel à celui d’abstraction opératoire dérivée de besoins pratiques.","L’espace homogène passe du statut de cadre présumé du réel à celui d’abstraction opératoire dérivée de besoins pratiques."],["[Reversal] Homogeneous space passes from the status of presumed framework of reality to that of operative abstraction derived from practical needs.","Homogeneous space passes from the status of presumed framework of reality to that of operative abstraction derived from practical needs."]],"WB_MEMA:RMD-07":[["[Displacement] Le dualisme migre de la séparation spatiale des substances vers la différenciation temporelle entre répétition matérielle et conservation créatrice.","Le dualisme migre de la séparation spatiale des substances vers la différenciation temporelle entre répétition matérielle et conservation créatrice."],["[Displacement] Dualism migrates from the spatial separation of substances toward temporal differentiation between material repetition and creative preservation.","Dualism migrates from the spatial separation of substances toward temporal differentiation between material repetition and creative preservation."]],"WB_MEMA:RMD-08":[["[Terminal transformation] La pathologie cesse d’être une localisation de contenus et devient une cartographie des ruptures entre conservation, accès, attitude motrice et application.","La pathologie cesse d’être une localisation de contenus et devient une cartographie des ruptures entre conservation, accès, attitude motrice et application."],["[Terminal transformation] Pathology ceases to be a localization of contents and becomes a mapping of ruptures between preservation, access, motor attitude, and application.","Pathology ceases to be a localization of contents and becomes a mapping of ruptures between preservation, access, motor attitude, and application."]],"WB_MEMA:CGD-01":[["[Local] La douleur, les schèmes verbaux, la genèse des idées générales et les paradoxes du mouvement restent des dispositifs analytiques locaux servant à différencier des fonctions.","La douleur, les schèmes verbaux, la genèse des idées générales et les paradoxes du mouvement restent des dispositifs analytiques locaux servant à différencier des fonctions."],["[Local] Pain, verbal schemas, the genesis of general ideas, and the paradoxes of movement remain local analytic devices serving to differentiate functions.","Pain, verbal schemas, the genesis of general ideas, and the paradoxes of movement remain local analytic devices serving to differentiate functions."]],"WB_MEMA:CGD-02":[["[Scale change] L’ontologie des images et la restitution locale du mouvement continu changent d’échelle lorsqu’elles convergent dans une conception rythmique de la matière.","L’ontologie des images et la restitution locale du mouvement continu changent d’échelle lorsqu’elles convergent dans une conception rythmique de la matière."],["[Scale change] The ontology of images and the local restitution of continuous movement change scale when they converge in a rhythmic conception of matter.","The ontology of images and the local restitution of continuous movement change scale when they converge in a rhythmic conception of matter."]],"WB_MEMA:CGD-03":[["[Connector] L’action relie l’ontologie matérielle, la perception, la mémoire et la pathologie en fournissant le modèle général de leur articulation.","L’action relie l’ontologie matérielle, la perception, la mémoire et la pathologie en fournissant le modèle général de leur articulation."],["[Connector] Action connects material ontology, perception, memory, and pathology by supplying the general model of their articulation.","Action connects material ontology, perception, memory, and pathology by supplying the general model of their articulation."]],"WB_MEMA:CGD-04":[["[Catalyst] La mémoire convertit la topologie du corps parmi les images en ontologie temporelle, puis intègre sélection corporelle et liberté graduelle.","La mémoire convertit la topologie du corps parmi les images en ontologie temporelle, puis intègre sélection corporelle et liberté graduelle."],["[Catalyst] Memory converts the topology of the body among images into temporal ontology, then integrates bodily selection and gradual freedom.","Memory converts the topology of the body among images into temporal ontology, then integrates bodily selection and gradual freedom."]],"WB_MEMA:CGD-05":[["[Current-level emergence] L’action acquiert une double fonction indisponible localement : elle produit les découpages qui faussent la métaphysique et opère l’union du virtuel avec l’actuel.","L’action acquiert une double fonction indisponible localement : elle produit les découpages qui faussent la métaphysique et opère l’union du virtuel avec l’actuel."],["[Current-level emergence] Action acquires a double function unavailable locally: it produces the divisions that distort metaphysics and effects the union of the virtual with the actual.","Action acquires a double function unavailable locally: it produces the divisions that distort metaphysics and effects the union of the virtual with the actual."]],"WB_MEMA:CGD-06":[["[Recoded] La corrélation psychophysiologique devient coordination pragmatique : la dépendance corporelle de l’actualisation ne vaut plus comme production corporelle du contenu.","La corrélation psychophysiologique devient coordination pragmatique : la dépendance corporelle de l’actualisation ne vaut plus comme production corporelle du contenu."],["[Recoded] Psychophysiological correlation becomes pragmatic coordination: the bodily dependence of actualization no longer counts as bodily production of content.","Psychophysiological correlation becomes pragmatic coordination: the bodily dependence of actualization no longer counts as bodily production of content."]],"WB_MEMA:CGD-07":[["[Obsolescent] Les modèles du cerveau-réservoir, de l’association linéaire et du réel composé d’états immobiles sont remplacés par la sélection, l’accès et l’actualisation.","Les modèles du cerveau-réservoir, de l’association linéaire et du réel composé d’états immobiles sont remplacés par la sélection, l’accès et l’actualisation."],["[Obsolescent] The models of the brain-reservoir, linear association, and reality composed of immobile states are replaced by selection, access, and actualization.","The models of the brain-reservoir, linear association, and reality composed of immobile states are replaced by selection, access, and actualization."]],"WB_MEMA:ALT-B01":[["[Surface level] Le système traite explicitement des images, du corps, du cerveau, de la perception, des formes de mémoire, de la reconnaissance, des lésions et du mouvement matériel.","Le système traite explicitement des images, du corps, du cerveau, de la perception, des formes de mémoire, de la reconnaissance, des lésions et du mouvement matériel."],["[Surface level] The system explicitly addresses images, the body, the brain, perception, forms of memory, recognition, lesions, and material movement.","The system explicitly addresses images, the body, the brain, perception, forms of memory, recognition, lesions, and material movement."]],"WB_MEMA:ALT-B02":[["[Structural level] Ces objets sont distribués entre sélection sensori-motrice, inhibition du passé, plans de tension, projection mnésique et insertion dans l’action.","Ces objets sont distribués entre sélection sensori-motrice, inhibition du passé, plans de tension, projection mnésique et insertion dans l’action."],["[Structural level] These objects are distributed among sensorimotor selection, inhibition of the past, planes of tension, mnemonic projection, and insertion into action.","These objects are distributed among sensorimotor selection, inhibition of the past, planes of tension, mnemonic projection, and insertion into action."]],"WB_MEMA:ALT-B03":[["[Metastrategic level] L’intervention remplace les oppositions d’école et les états achevés par une analyse génétique des fonctions de sélection, de conservation et d’actualisation.","L’intervention remplace les oppositions d’école et les états achevés par une analyse génétique des fonctions de sélection, de conservation et d’actualisation."],["[Metastrategic level] The intervention replaces school oppositions and completed states with a genetic analysis of functions of selection, preservation, and actualization.","The intervention replaces school oppositions and completed states with a genetic analysis of functions of selection, preservation, and actualization."]],"WB_MEMA:ALT-B04":[["[Ontological / Temporal level] Le réel articule un présent matériel actif, un passé virtuellement conservé, une pluralité de rythmes et un avenir défini par les conduites possibles.","Le réel articule un présent matériel actif, un passé virtuellement conservé, une pluralité de rythmes et un avenir défini par les conduites possibles."],["[Ontological / Temporal level] The real articulates an active material present, a virtually preserved past, a plurality of rhythms, and a future defined by possible conduct.","The real articulates an active material present, a virtually preserved past, a plurality of rhythms, and a future defined by possible conduct."]],"WB_MEMA:ALT-B05":[["[Methodological / Performative level] La forme accomplit sa thèse en isolant des fonctions, en réintroduisant ce qu’elle avait abstrait, en revenant au continu et en reconstruisant récursivement ses différenciations.","La forme accomplit sa thèse en isolant des fonctions, en réintroduisant ce qu’elle avait abstrait, en revenant au continu et en reconstruisant récursivement ses différenciations."],["[Methodological / Performative level] The form accomplishes its thesis by isolating functions, reintroducing what it had abstracted, returning to the continuous, and recursively reconstructing its differentiations.","The form accomplishes its thesis by isolating functions, reintroducing what it had abstracted, returning to the continuous, and recursively reconstructing its differentiations."]],"CL_R2TV_01:GA-01":[["[Persistent] Weder subjektive Intensität noch kollektive Zustimmung legitimieren einen psychischen Inhalt als ontologische oder religiöse Wahrheit.","Weder subjektive Intensität noch kollektive Zustimmung legitimieren einen psychischen Inhalt als ontologische oder religiöse Wahrheit."],["[Persistent] Neither subjective intensity nor collective assent legitimates a psychic content as ontological or religious truth.","Neither subjective intensity nor collective assent legitimates a psychic content as ontological or religious truth."]],"CL_R2TV_01:GA-02":[["[Persistent] Das Subjekt ist kein souveräner Ausgangspunkt, sondern eine geschichtete, begrenzte und von Körper, Außenwelt, Objekten und Trieben abhängige Formation.","Das Subjekt ist kein souveräner Ausgangspunkt, sondern eine geschichtete, begrenzte und von Körper, Außenwelt, Objekten und Trieben abhängige Formation."],["[Persistent] The subject is not a sovereign point of departure, but a layered, bounded formation dependent on body, external world, objects, and drives.","The subject is not a sovereign point of departure, but a layered, bounded formation dependent on body, external world, objects, and drives."]],"CL_R2TV_01:GA-03":[["[Persistent] Das Lustprinzip setzt ein unerfüllbares Glücksprogramm, das unter dem Druck der Realität in eine Vorrangordnung der Leidvermeidung überführt wird.","Das Lustprinzip setzt ein unerfüllbares Glücksprogramm, das unter dem Druck der Realität in eine Vorrangordnung der Leidvermeidung überführt wird."],["[Persistent] The pleasure principle posits an unfulfillable happiness programme that, under the pressure of reality, is transformed into an order prioritizing the avoidance of suffering.","The pleasure principle posits an unfulfillable happiness programme that, under the pressure of reality, is transformed into an order prioritizing the avoidance of suffering."]],"CL_R2TV_01:GA-04":[["[Mutating] Infantile Hilflosigkeit wird von einer Quelle religiöser Energie zur Grundlage eines kollektiv standardisierten Schutz- und Vorsehungsmodells erweitert.","Infantile Hilflosigkeit wird von einer Quelle religiöser Energie zur Grundlage eines kollektiv standardisierten Schutz- und Vorsehungsmodells erweitert."],["[Mutating] Infantile helplessness is expanded from a source of religious energy into the foundation of a collectively standardized model of protection and providence.","Infantile helplessness is expanded from a source of religious energy into the foundation of a collectively standardized model of protection and providence."]],"CL_R2TV_01:GA-05":[["[Emergent] Psychische Techniken und kulturelle Einrichtungen beseitigen Abhängigkeit nicht, sondern verteilen Lust, Leiden, Realitätsbindung und Verwundbarkeit neu.","Psychische Techniken und kulturelle Einrichtungen beseitigen Abhängigkeit nicht, sondern verteilen Lust, Leiden, Realitätsbindung und Verwundbarkeit neu."],["[Emergent] Psychic techniques and cultural institutions do not eliminate dependency, but redistribute pleasure, suffering, reality-bondage, and vulnerability.","Psychic techniques and cultural institutions do not eliminate dependency, but redistribute pleasure, suffering, reality-bondage, and vulnerability."]],"CL_R2TV_01:GA-06":[["[Persistent] Körper, Außenwelt und soziale Beziehungen bilden irreduzible Leidensfelder, wobei nur das soziale Feld institutionell veränderbar und zugleich psychisch rückgebunden ist.","Körper, Außenwelt und soziale Beziehungen bilden irreduzible Leidensfelder, wobei nur das soziale Feld institutionell veränderbar und zugleich psychisch rückgebunden ist."],["[Persistent] Body, external world, and social relations constitute irreducible fields of suffering, whereby only the social field is institutionally alterable and simultaneously psychically tethered.","Body, external world, and social relations constitute irreducible fields of suffering, whereby only the social field is institutionally alterable and simultaneously psychically tethered."]],"CL_R2TV_01:GA-07":[["[Mutating] Das Realitätsprinzip erweitert sich von der Korrektur früher Ichgrenzen zur übergreifenden Logik individueller Anpassung und kultureller Regelung.","Das Realitätsprinzip erweitert sich von der Korrektur früher Ichgrenzen zur übergreifenden Logik individueller Anpassung und kultureller Regelung."],["[Mutating] The reality principle expands from the correction of early ego boundaries into the overarching logic of individual adaptation and cultural regulation.","The reality principle expands from the correction of early ego boundaries into the overarching logic of individual adaptation and cultural regulation."]],"CL_R2TV_01:GA-08":[["[Terminal] Eine dauerhafte, allgemein gültige Versöhnung von Lust, Leidensschutz, Freiheit, psychischer Konstitution und Realität ist nicht verfügbar.","Eine dauerhafte, allgemein gültige Versöhnung von Lust, Leidensschutz, Freiheit, psychischer Konstitution und Realität ist nicht verfügbar."],["[Terminal] A lasting, universally valid reconciliation of pleasure, protection from suffering, freedom, psychic constitution, and reality is unavailable.","A lasting, universally valid reconciliation of pleasure, protection from suffering, freedom, psychic constitution, and reality is unavailable."]],"CL_R2TV_01:GA-09":[["[Emergent] Religion transformiert ein Schutzbedürfnis in eine uniforme Technik, die individuelle Anpassung durch kollektive Fixierung und Wirklichkeitsentstellung ersetzt.","Religion transformiert ein Schutzbedürfnis in eine uniforme Technik, die individuelle Anpassung durch kollektive Fixierung und Wirklichkeitsentstellung ersetzt."],["[Emergent] Religion transforms a need for protection into a uniform technique that replaces individual adaptation with collective fixation and distortion of reality.","Religion transforms a need for protection into a uniform technique that replaces individual adaptation with collective fixation and distortion of reality."]],"CL_R2TV_01:GA-10":[["[Attractor] Kultur ist zugleich Schutzapparat und endogene Leidensproduktion, weil dieselben Einrichtungen, die Natur und soziale Gewalt begrenzen, Triebverzicht erzwingen.","Kultur ist zugleich Schutzapparat und endogene Leidensproduktion, weil dieselben Einrichtungen, die Natur und soziale Gewalt begrenzen, Triebverzicht erzwingen."],["[Attractor] Culture is at once a protective apparatus and endogenous production of suffering, because the very institutions that limit nature and social violence enforce instinctual renunciation.","Culture is at once a protective apparatus and endogenous production of suffering, because the very institutions that limit nature and social violence enforce instinctual renunciation."]],"CL_R2TV_01:GA-11":[["[Mutating] Recht hebt Gewalt nicht auf, sondern transformiert individuelle Gewalt in überlegene Gemeinschaftsmacht und bindet deren Stabilität an allgemeine Einschränkung.","Recht hebt Gewalt nicht auf, sondern transformiert individuelle Gewalt in überlegene Gemeinschaftsmacht und bindet deren Stabilität an allgemeine Einschränkung."],["[Mutating] Law does not abolish violence, but transforms individual violence into superior communal power and ties its stability to universal restriction.","Law does not abolish violence, but transforms individual violence into superior communal power and ties its stability to universal restriction."]],"CL_R2TV_01:GA-12":[["[Attractor] Triebverzicht bleibt nur begrenzt stabil, wenn die entzogene Befriedigung ökonomisch kompensiert wird; ausbleibende Kompensation erzeugt Störung und Kulturfeindseligkeit.","Triebverzicht bleibt nur begrenzt stabil, wenn die entzogene Befriedigung ökonomisch kompensiert wird; ausbleibende Kompensation erzeugt Störung und Kulturfeindseligkeit."],["[Attractor] Instinctual renunciation remains stable only to a limited extent when withdrawn satisfaction is economically compensated; absent compensation produces disturbance and hostility to culture.","Instinctual renunciation remains stable only to a limited extent when withdrawn satisfaction is economically compensated; absent compensation produces disturbance and hostility to culture."]],"CL_R2TV_01:GA-13":[["[Emergent] Technische Verfügungsmacht und Kulturfortschritt bezeichnen keine proportionale Zunahme von Glück oder Vervollkommnung, sondern eine Reorganisation von Lebensbedingungen und Triebzielen.","Technische Verfügungsmacht und Kulturfortschritt bezeichnen keine proportionale Zunahme von Glück oder Vervollkommnung, sondern eine Reorganisation von Lebensbedingungen und Triebzielen."],["[Emergent] Technical power of disposal and cultural progress do not denote a proportional increase in happiness or perfection, but a reorganization of conditions of life and instinctual aims.","Technical power of disposal and cultural progress do not denote a proportional increase in happiness or perfection, but a reorganization of conditions of life and instinctual aims."]],"CL_R2TV_01:GA-14":[["[Persistent] Vorgegebene Teleologie wird durch genetische und funktionale Rekonstruktion ersetzt: Zwecke gelten nur insoweit, als sie sich in psychischen und sozialen Operationen nachweisen lassen.","Vorgegebene Teleologie wird durch genetische und funktionale Rekonstruktion ersetzt: Zwecke gelten nur insoweit, als sie sich in psychischen und sozialen Operationen nachweisen lassen."],["[Persistent] Given teleology is replaced by genetic and functional reconstruction: purposes hold only insofar as they can be demonstrated in psychic and social operations.","Given teleology is replaced by genetic and functional reconstruction: purposes hold only insofar as they can be demonstrated in psychic and social operations."]],"CL_R2TV_02:GA-01":[["[Persistent] Große kulturelle Verbände benötigen libidinöse Bindungen, weil Arbeitsvorteil und Zweckgemeinschaft menschliche Mengen nicht dauerhaft zusammenhalten.","Große kulturelle Verbände benötigen libidinöse Bindungen, weil Arbeitsvorteil und Zweckgemeinschaft menschliche Mengen nicht dauerhaft zusammenhalten."],["[Persistent] Large cultural associations require libidinal attachments because the advantages of labor and purposive association do not hold human multitudes together permanently.","Large cultural associations require libidinal attachments because the advantages of labor and purposive association do not hold human multitudes together permanently."]],"CL_R2TV_02:GA-02":[["[Persistent] Libido und psychische Energie sind begrenzt und besetzungsträge; jede kulturelle Umverteilung erzeugt deshalb Widerstand, Entzug oder Ersatzbildung.","Libido und psychische Energie sind begrenzt und besetzungsträge; jede kulturelle Umverteilung erzeugt deshalb Widerstand, Entzug oder Ersatzbildung."],["[Persistent] Libido and psychic energy are limited and inertial in cathexis; every cultural redistribution therefore produces resistance, withdrawal, or substitute formation.","Libido and psychic energy are limited and inertial in cathexis; every cultural redistribution therefore produces resistance, withdrawal, or substitute formation."]],"CL_R2TV_02:GA-03":[["[Mutating] Liebe ist zunächst Keimform intensiver Sozialität, wird dann zum Hindernis ihrer Ausdehnung und schließlich als Eros zum allgemeinen Prinzip wachsender Einheitsbildung erweitert.","Liebe ist zunächst Keimform intensiver Sozialität, wird dann zum Hindernis ihrer Ausdehnung und schließlich als Eros zum allgemeinen Prinzip wachsender Einheitsbildung erweitert."],["[Mutating] Love is initially the germinal form of intense sociality, then becomes an obstacle to its expansion, and finally is extended as Eros into the general principle of increasing unity formation.","Love is initially the germinal form of intense sociality, then becomes an obstacle to its expansion, and finally is extended as Eros into the general principle of increasing unity formation."]],"CL_R2TV_02:GA-04":[["[Persistent] Die Vergrößerung kultureller Einheiten verlangt eine Transformation exklusiver sexueller und familialer Bindungen in breiter verteilte, zielgehemmte oder identifikatorische Beziehungen.","Die Vergrößerung kultureller Einheiten verlangt eine Transformation exklusiver sexueller und familialer Bindungen in breiter verteilte, zielgehemmte oder identifikatorische Beziehungen."],["[Persistent] The enlargement of cultural units requires a transformation of exclusive sexual and familial attachments into more broadly distributed, aim-inhibited, or identificatory relations.","The enlargement of cultural units requires a transformation of exclusive sexual and familial attachments into more broadly distributed, aim-inhibited, or identificatory relations."]],"CL_R2TV_02:GA-05":[["[Persistent] Kultur institutionalisiert wechselseitige Triebeinschränkung als Recht, Norm und Sicherheitsordnung und erkauft dadurch Stabilität mit verminderter unmittelbarer Befriedigung.","Kultur institutionalisiert wechselseitige Triebeinschränkung als Recht, Norm und Sicherheitsordnung und erkauft dadurch Stabilität mit verminderter unmittelbarer Befriedigung."],["[Persistent] Culture institutionalizes reciprocal drive restriction as law, norm, and an order of security, thereby purchasing stability at the cost of diminished immediate satisfaction.","Culture institutionalizes reciprocal drive restriction as law, norm, and an order of security, thereby purchasing stability at the cost of diminished immediate satisfaction."]],"CL_R2TV_02:GA-06":[["[Mutating] Aggression wird von einer diagnostizierten menschlichen Feindseligkeit zur ursprünglichen Triebanlage und schließlich zur nach außen gewendeten Erscheinungsform des Todestriebs.","Aggression wird von einer diagnostizierten menschlichen Feindseligkeit zur ursprünglichen Triebanlage und schließlich zur nach außen gewendeten Erscheinungsform des Todestriebs."],["[Mutating] Aggression is transformed from a diagnosed human hostility into an original drive disposition and finally into the outwardly directed manifestation of the death drive.","Aggression is transformed from a diagnosed human hostility into an original drive disposition and finally into the outwardly directed manifestation of the death drive."]],"CL_R2TV_02:GA-07":[["[Emergent] Kultur ist ein Doppelapparat, der Libido sozial verteilt und Aggression begrenzt, ohne die von ihm bearbeiteten Kräfte endgültig aufheben zu können.","Kultur ist ein Doppelapparat, der Libido sozial verteilt und Aggression begrenzt, ohne die von ihm bearbeiteten Kräfte endgültig aufheben zu können."],["[Emergent] Culture is a dual apparatus that distributes libido socially and limits aggression, without being able definitively to abolish the forces it processes.","Culture is a dual apparatus that distributes libido socially and limits aggression, without being able definitively to abolish the forces it processes."]],"CL_R2TV_02:GA-08":[["[Mutating] Nach außen gewendete Destruktion kann individuelle Selbsterhaltung und lokale Gruppenkohäsion fördern, widersetzt sich aber der kulturellen Einigung auf größerem Maßstab.","Nach außen gewendete Destruktion kann individuelle Selbsterhaltung und lokale Gruppenkohäsion fördern, widersetzt sich aber der kulturellen Einigung auf größerem Maßstab."],["[Mutating] Outwardly directed destruction can promote individual self-preservation and local group cohesion, but resists cultural unification on a larger scale.","Outwardly directed destruction can promote individual self-preservation and local group cohesion, but resists cultural unification on a larger scale."]],"CL_R2TV_02:GA-09":[["[Emergent] Aggressionshemmung beseitigt Destruktion nicht, sondern erzeugt durch Externalisierung, psychische Umformung oder Rückwendung neue individuelle und kollektive Pathologien.","Aggressionshemmung beseitigt Destruktion nicht, sondern erzeugt durch Externalisierung, psychische Umformung oder Rückwendung neue individuelle und kollektive Pathologien."],["[Emergent] The inhibition of aggression does not eliminate destruction, but produces new individual and collective pathologies through externalization, psychic transformation, or reversal against the self.","The inhibition of aggression does not eliminate destruction, but produces new individual and collective pathologies through externalization, psychic transformation, or reversal against the self."]],"CL_R2TV_02:GA-10":[["[Terminal] Reformen können institutionelle Werkzeuge der Aggression verändern und vermeidbares Leiden mindern, nicht aber notwendig den Triebkonflikt beseitigen, der Kultur erforderlich macht.","Reformen können institutionelle Werkzeuge der Aggression verändern und vermeidbares Leiden mindern, nicht aber notwendig den Triebkonflikt beseitigen, der Kultur erforderlich macht."],["[Terminal] Reforms can alter institutional instruments of aggression and reduce avoidable suffering, but cannot necessarily eliminate the conflict of drives that makes culture necessary.","Reforms can alter institutional instruments of aggression and reduce avoidable suffering, but cannot necessarily eliminate the conflict of drives that makes culture necessary."]],"CL_R2TV_02:GA-11":[["[Attractor] Kulturentwicklung ist die geschichtliche Vollzugsform des unabschließbaren Kampfes zwischen dem einheitsbildenden Eros und der gegen Einigung gerichteten Destruktion.","Kulturentwicklung ist die geschichtliche Vollzugsform des unabschließbaren Kampfes zwischen dem einheitsbildenden Eros und der gegen Einigung gerichteten Destruktion."],["[Attractor] Cultural development is the historical mode of enactment of the interminable struggle between unifying Eros and destruction directed against unification.","Cultural development is the historical mode of enactment of the interminable struggle between unifying Eros and destruction directed against unification."]],"CL_R2TV_02:GA-12":[["[Terminal] Kulturfortschritt garantiert weder Glück noch Befreiung, weil jeder Sicherheitsgewinn Kosten an sexueller Befriedigung, Freiheit und psychischer Integrität erzeugt.","Kulturfortschritt garantiert weder Glück noch Befreiung, weil jeder Sicherheitsgewinn Kosten an sexueller Befriedigung, Freiheit und psychischer Integrität erzeugt."],["[Terminal] Cultural progress guarantees neither happiness nor liberation, because every gain in security incurs costs in sexual satisfaction, freedom, and psychic integrity.","Cultural progress guarantees neither happiness nor liberation, because every gain in security incurs costs in sexual satisfaction, freedom, and psychic integrity."]],"CL_R2TV_03:GA-01":[["[Persistent] Kultur kann Zusammenleben nur sichern, indem sie individuelle Aggression hemmt und deren Energie umverteilt, nicht indem sie Aggression aufhebt.","Kultur kann Zusammenleben nur sichern, indem sie individuelle Aggression hemmt und deren Energie umverteilt, nicht indem sie Aggression aufhebt."],["[Persistent] Culture can secure coexistence only by inhibiting individual aggression and redistributing its energy, not by abolishing aggression.","Culture can secure coexistence only by inhibiting individual aggression and redistributing its energy, not by abolishing aggression."]],"CL_R2TV_03:GA-02":[["[Mutating] Autorität wandert von äußerer Liebes- und Strafabhängigkeit in das individuelle Über-Ich und von dort in die normsetzende Struktur des Kultur-Über-Ichs.","Autorität wandert von äußerer Liebes- und Strafabhängigkeit in das individuelle Über-Ich und von dort in die normsetzende Struktur des Kultur-Über-Ichs."],["[Mutating] Authority migrates from external dependence on love and punishment into the individual superego and from there into the norm-setting structure of the cultural superego.","Authority migrates from external dependence on love and punishment into the individual superego and from there into the norm-setting structure of the cultural superego."]],"CL_R2TV_03:GA-03":[["[Mutating] Schuld ist die als Angst, Spannung oder diffuses Unbehagen wirksame Beziehung des Ichs zur internalisierten Autorität und benötigt kein bewusstes Schuldbewusstsein.","Schuld ist die als Angst, Spannung oder diffuses Unbehagen wirksame Beziehung des Ichs zur internalisierten Autorität und benötigt kein bewusstes Schuldbewusstsein."],["[Mutating] Guilt is the relation of the ego to internalized authority, effective as anxiety, tension, or diffuse malaise, and requires no conscious sense of guilt.","Guilt is the relation of the ego to internalized authority, effective as anxiety, tension, or diffuse malaise, and requires no conscious sense of guilt."]],"CL_R2TV_03:GA-04":[["[Attractor] Triebverzicht bildet nach der Über-Ich-Bildung keinen Endpunkt, sondern einen rekursiven Verstärker, der zusätzliche Aggression an die innere Strafinstanz überträgt.","Triebverzicht bildet nach der Über-Ich-Bildung keinen Endpunkt, sondern einen rekursiven Verstärker, der zusätzliche Aggression an die innere Strafinstanz überträgt."],["[Attractor] After the formation of the superego, instinctual renunciation constitutes not an endpoint but a recursive amplifier that transfers additional aggression to the internal punitive agency.","After the formation of the superego, instinctual renunciation constitutes not an endpoint but a recursive amplifier that transfers additional aggression to the internal punitive agency."]],"CL_R2TV_03:GA-05":[["[Emergent] Die libidinöse Erweiterung von Gemeinschaft und die Steigerung von Schuld sind gekoppelt, sodass kulturelle Bindungsgewinne systematisch mit individuellem Glücksverlust bezahlt werden.","Die libidinöse Erweiterung von Gemeinschaft und die Steigerung von Schuld sind gekoppelt, sodass kulturelle Bindungsgewinne systematisch mit individuellem Glücksverlust bezahlt werden."],["[Emergent] The libidinal expansion of community and the intensification of guilt are coupled, so that gains in cultural bonding are systematically paid for by losses in individual happiness.","The libidinal expansion of community and the intensification of guilt are coupled, so that gains in cultural bonding are systematically paid for by losses in individual happiness."]],"CL_R2TV_03:GA-06":[["[Mutating] Die Aggressivität des Über-Ichs vereinigt fortgesetzte äußere Strafgewalt und die gegen Autorität gerichtete, aber nach innen gewendete Eigenaggression, ohne beide Quellen kausal gleichzusetzen.","Die Aggressivität des Über-Ichs vereinigt fortgesetzte äußere Strafgewalt und die gegen Autorität gerichtete, aber nach innen gewendete Eigenaggression, ohne beide Quellen kausal gleichzusetzen."],["[Mutating] The aggressiveness of the superego combines continuing external punitive force and the subject's own aggression directed against authority but turned inward, without causally equating the two sources.","The aggressiveness of the superego combines continuing external punitive force and the subject's own aggression directed against authority but turned inward, without causally equating the two sources."]],"CL_R2TV_03:GA-07":[["[Persistent] Nach der Verinnerlichung verliert die Differenz zwischen Aggressionswunsch und Aggressionstat ihre entlastende Funktion, während Reue als Reaktion auf tatsächlich ausgeführte Aggression begrifflich begrenzt bleibt.","Nach der Verinnerlichung verliert die Differenz zwischen Aggressionswunsch und Aggressionstat ihre entlastende Funktion, während Reue als Reaktion auf tatsächlich ausgeführte Aggression begrifflich begrenzt bleibt."],["[Persistent] After internalization, the difference between the wish for aggression and the act of aggression loses its exculpatory function, while remorse remains conceptually limited to a reaction to aggression actually carried out.","After internalization, the difference between the wish for aggression and the act of aggression loses its exculpatory function, while remorse remains conceptually limited to a reaction to aggression actually carried out."]],"CL_R2TV_03:GA-08":[["[Emergent] Individual- und Kulturentwicklung sind analog strukturierte Integrationsprozesse, deren Zielordnungen auseinanderfallen, weil individuelles Glück und kollektive Einheitsbildung verschieden priorisiert werden.","Individual- und Kulturentwicklung sind analog strukturierte Integrationsprozesse, deren Zielordnungen auseinanderfallen, weil individuelles Glück und kollektive Einheitsbildung verschieden priorisiert werden."],["[Emergent] Individual and cultural development are analogously structured processes of integration whose orders of aims diverge because individual happiness and collective unification are differently prioritized.","Individual and cultural development are analogously structured processes of integration whose orders of aims diverge because individual happiness and collective unification are differently prioritized."]],"CL_R2TV_03:GA-09":[["[Mutating] Ethik wird zur therapeutischen Technik des Kultur-Über-Ichs, schlägt aber bei psychisch undurchführbaren Forderungen in Schuldsteigerung, Auflehnung, Neurose oder Unglück um.","Ethik wird zur therapeutischen Technik des Kultur-Über-Ichs, schlägt aber bei psychisch undurchführbaren Forderungen in Schuldsteigerung, Auflehnung, Neurose oder Unglück um."],["[Mutating] Ethics becomes the therapeutic technique of the cultural superego, but turns, when demands are psychically infeasible, into intensified guilt, rebellion, neurosis, or unhappiness.","Ethics becomes the therapeutic technique of the cultural superego, but turns, when demands are psychically infeasible, into intensified guilt, rebellion, neurosis, or unhappiness."]],"CL_R2TV_03:GA-10":[["[Emergent] Der Konflikt zwischen Individuum und Gemeinschaft bleibt als veränderbare Libidoverteilung von dem nicht terminal lösbaren Konflikt zwischen Eros und Destruktion unterschieden.","Der Konflikt zwischen Individuum und Gemeinschaft bleibt als veränderbare Libidoverteilung von dem nicht terminal lösbaren Konflikt zwischen Eros und Destruktion unterschieden."],["[Emergent] The conflict between individual and community remains distinct, as a modifiable distribution of libido, from the conflict between Eros and destruction, which is not terminally soluble.","The conflict between individual and community remains distinct, as a modifiable distribution of libido, from the conflict between Eros and destruction, which is not terminally soluble."]],"CL_R2TV_03:GA-11":[["[Terminal] Die Skalierung psychischer Diagnostik auf Kulturen bleibt ohne externen Normalitätsmaßstab und ohne therapiefähige kollektive Autorität diagnostisch und praktisch unabschließbar.","Die Skalierung psychischer Diagnostik auf Kulturen bleibt ohne externen Normalitätsmaßstab und ohne therapiefähige kollektive Autorität diagnostisch und praktisch unabschließbar."],["[Terminal] The scaling of psychic diagnosis to cultures remains diagnostically and practically inconclusive without an external standard of normality and without a collective authority capable of therapy.","The scaling of psychic diagnosis to cultures remains diagnostically and practically inconclusive without an external standard of normality and without a collective authority capable of therapy."]],"CL_R2TV_03:GA-12":[["[Attractor] Technische Naturbeherrschung steigert die Reichweite destruktiver Handlungsmacht bis zur möglichen Selbstvernichtung, während die Gegenanstrengung des Eros weder prognostisch noch teleologisch garantiert ist.","Technische Naturbeherrschung steigert die Reichweite destruktiver Handlungsmacht bis zur möglichen Selbstvernichtung, während die Gegenanstrengung des Eros weder prognostisch noch teleologisch garantiert ist."],["[Attractor] Technical mastery of nature increases the range of destructive agency up to possible self-annihilation, while the counter-effort of Eros is guaranteed neither prognostically nor teleologically.","Technical mastery of nature increases the range of destructive agency up to possible self-annihilation, while the counter-effort of Eros is guaranteed neither prognostically nor teleologically."]],"WB_R2TV:GA-01":[["[Persistent] Subjektive Intensität, kollektive Zustimmung, moralische Geltung und behauptete Zweckmäßigkeit legitimieren keinen Inhalt ohne genetische, funktionale und ökonomische Rekonstruktion.","Subjektive Intensität, kollektive Zustimmung, moralische Geltung und behauptete Zweckmäßigkeit legitimieren keinen Inhalt ohne genetische, funktionale und ökonomische Rekonstruktion."],["[Persistent] Subjective intensity, collective assent, moral validity, and asserted purposiveness do not legitimize any content without genetic, functional, and economic reconstruction.","Subjective intensity, collective assent, moral validity, and asserted purposiveness do not legitimize any content without genetic, functional, and economic reconstruction."]],"WB_R2TV:GA-02":[["[Persistent] Das Subjekt ist kein souveräner Ursprung, sondern ein geschichteter Umschlagpunkt körperlicher Bedürfnisse, libidinöser Besetzungen, destruktiver Richtungen, äußerer Autorität und internalisierter Forderungen.","Das Subjekt ist kein souveräner Ursprung, sondern ein geschichteter Umschlagpunkt körperlicher Bedürfnisse, libidinöser Besetzungen, destruktiver Richtungen, äußerer Autorität und internalisierter Forderungen."],["[Persistent] The subject is not a sovereign origin, but a stratified point of conversion of bodily needs, libidinal cathexes, destructive directions, external authority, and internalized demands.","The subject is not a sovereign origin, but a stratified point of conversion of bodily needs, libidinal cathexes, destructive directions, external authority, and internalized demands."]],"WB_R2TV:GA-03":[["[Persistent] Kultur sichert größere Gemeinschaften durch Schutz, Recht, Bindung und Triebeinschränkung, produziert jedoch gerade durch diese Integrationsmittel eigene Formen des Leidens.","Kultur sichert größere Gemeinschaften durch Schutz, Recht, Bindung und Triebeinschränkung, produziert jedoch gerade durch diese Integrationsmittel eigene Formen des Leidens."],["[Persistent] Culture secures larger communities through protection, law, binding, and drive restriction, yet produces its own forms of suffering precisely through these means of integration.","Culture secures larger communities through protection, law, binding, and drive restriction, yet produces its own forms of suffering precisely through these means of integration."]],"WB_R2TV:GA-04":[["[Emergent] Jede psychische oder kulturelle Schutzleistung ist eine Umverteilung begrenzter Befriedigung, Bindung und Aggression; sie kann Gefahren vermindern, ohne Abhängigkeit oder Triebkosten aufzuheben.","Jede psychische oder kulturelle Schutzleistung ist eine Umverteilung begrenzter Befriedigung, Bindung und Aggression; sie kann Gefahren vermindern, ohne Abhängigkeit oder Triebkosten aufzuheben."],["[Emergent] Every psychic or cultural protective achievement is a redistribution of limited satisfaction, binding, and aggression; it can diminish dangers without abolishing dependency or drive costs.","Every psychic or cultural protective achievement is a redistribution of limited satisfaction, binding, and aggression; it can diminish dangers without abolishing dependency or drive costs."]],"WB_R2TV:GA-05":[["[Terminal] Das vom Lustprinzip gesetzte Glücksprogramm ist weder dauerhaft noch universell erfüllbar, und kultureller Fortschritt kann seine Unerfüllbarkeit nicht in eine gesicherte Versöhnung überführen.","Das vom Lustprinzip gesetzte Glücksprogramm ist weder dauerhaft noch universell erfüllbar, und kultureller Fortschritt kann seine Unerfüllbarkeit nicht in eine gesicherte Versöhnung überführen."],["[Terminal] The happiness programme posited by the pleasure principle is neither durably nor universally fulfillable, and cultural progress cannot transform its unfulfillability into a secured reconciliation.","The happiness programme posited by the pleasure principle is neither durably nor universally fulfillable, and cultural progress cannot transform its unfulfillability into a secured reconciliation."]],"WB_R2TV:GA-06":[["[Mutating] Liebe mutiert von exklusiver Objekt- und Familienbindung über zielgehemmte Sozialbindung zum Erosprinzip kultureller Einheitsbildung, wobei jede Erweiterung ihre intensiven Ausgangsformen beschneiden muss.","Liebe mutiert von exklusiver Objekt- und Familienbindung über zielgehemmte Sozialbindung zum Erosprinzip kultureller Einheitsbildung, wobei jede Erweiterung ihre intensiven Ausgangsformen beschneiden muss."],["[Mutating] Love mutates from exclusive object- and family-binding, through aim-inhibited social binding, into the Eros principle of cultural unification, whereby every expansion must curtail its intensive initial forms.","Love mutates from exclusive object- and family-binding, through aim-inhibited social binding, into the Eros principle of cultural unification, whereby every expansion must curtail its intensive initial forms."]],"WB_R2TV:GA-07":[["[Mutating] Aggression eskaliert von zwischenmenschlicher Feindseligkeit zur Erscheinungsform des Todestriebs, wird kulturell nach außen oder innen umgelenkt und durch technische Macht bis zur möglichen Selbstvernichtung potenziert.","Aggression eskaliert von zwischenmenschlicher Feindseligkeit zur Erscheinungsform des Todestriebs, wird kulturell nach außen oder innen umgelenkt und durch technische Macht bis zur möglichen Selbstvernichtung potenziert."],["[Mutating] Aggression escalates from interpersonal hostility to a manifestation of the death drive, is culturally redirected outward or inward, and is potentiated by technical power up to possible self-destruction.","Aggression escalates from interpersonal hostility to a manifestation of the death drive, is culturally redirected outward or inward, and is potentiated by technical power up to possible self-destruction."]],"WB_R2TV:GA-08":[["[Mutating] Grenzbildung mutiert von der psychischen Unterscheidung zwischen Selbst und Außen über Recht und Triebeinschränkung zur internalisierten Autorität des Über-Ichs.","Grenzbildung mutiert von der psychischen Unterscheidung zwischen Selbst und Außen über Recht und Triebeinschränkung zur internalisierten Autorität des Über-Ichs."],["[Mutating] Boundary formation mutates from the psychic distinction between self and outside, through law and drive restriction, into the internalized authority of the superego.","Boundary formation mutates from the psychic distinction between self and outside, through law and drive restriction, into the internalized authority of the superego."]],"WB_R2TV:GA-09":[["[Attractor] Triebverzicht wird nach der Verinnerlichung von Autorität zum rekursiven Schuldverstärker, weil jeder neue Verzicht weitere Aggression an die Instanz überträgt, die ihn fordert.","Triebverzicht wird nach der Verinnerlichung von Autorität zum rekursiven Schuldverstärker, weil jeder neue Verzicht weitere Aggression an die Instanz überträgt, die ihn fordert."],["[Attractor] After the internalization of authority, drive renunciation becomes a recursive intensifier of guilt, because every new renunciation transfers further aggression to the agency that demands it.","After the internalization of authority, drive renunciation becomes a recursive intensifier of guilt, because every new renunciation transfers further aggression to the agency that demands it."]],"WB_R2TV:GA-10":[["[Attractor] Kulturgeschichte ist die unabschließbare Austragung des Konflikts zwischen einheitsbildendem Eros und bindungslösender Destruktion auf psychischen, institutionellen und menschheitsgeschichtlichen Maßstäben.","Kulturgeschichte ist die unabschließbare Austragung des Konflikts zwischen einheitsbildendem Eros und bindungslösender Destruktion auf psychischen, institutionellen und menschheitsgeschichtlichen Maßstäben."],["[Attractor] Cultural history is the interminable working-out of the conflict between unifying Eros and binding-dissolving destruction on psychic, institutional, and human-historical scales.","Cultural history is the interminable working-out of the conflict between unifying Eros and binding-dissolving destruction on psychic, institutional, and human-historical scales."]],"WB_R2TV:GA-11":[["[Emergent] Kulturelle Zeit ist nichtteleologisch und rekursiv: Frühere Formationen bleiben unter funktionaler Mutation wirksam, während ungelöste Aggression, Schuld und technische Reichweite akkumulieren.","Kulturelle Zeit ist nichtteleologisch und rekursiv: Frühere Formationen bleiben unter funktionaler Mutation wirksam, während ungelöste Aggression, Schuld und technische Reichweite akkumulieren."],["[Emergent] Cultural time is non-teleological and recursive: earlier formations remain effective under functional mutation, while unresolved aggression, guilt, and technical reach accumulate.","Cultural time is non-teleological and recursive: earlier formations remain effective under functional mutation, while unresolved aggression, guilt, and technical reach accumulate."]],"WB_R2TV:GA-12":[["[Terminal] Technische Naturbeherrschung steigert Handlungsmacht ohne proportionale psychische Selbstbindung; deshalb endet die Architektur in einem offenen Überlebenskonflikt, nicht in einer Fortschrittsgarantie.","Technische Naturbeherrschung steigert Handlungsmacht ohne proportionale psychische Selbstbindung; deshalb endet die Architektur in einem offenen Überlebenskonflikt, nicht in einer Fortschrittsgarantie."],["[Terminal] Technical mastery of nature increases agency without proportional psychic self-binding; therefore, the architecture ends in an open conflict of survival, not in a guarantee of progress.","Technical mastery of nature increases agency without proportional psychic self-binding; therefore, the architecture ends in an open conflict of survival, not in a guarantee of progress."]],"CH_TFRR_MPCA:ALT1":[["**Altitude 1 — Surface:** The record coordinates Prague resettlement, diplomatic correspondence, prayer sessions, elemental visions, cryptic words, and numerical dictation.","Altitude 1 — Surface: The record coordinates Prague resettlement, diplomatic correspondence, prayer sessions, elemental visions, cryptic words, and numerical dictation."]],"CH_TFRR_MPCA:ALT2":[["**Altitude 2 — Structural:** Revelation operates through a distributed chain of God, Christ, angelic ministers, visionary perception, scribal transcription, books, and decoding procedures.","Altitude 2 — Structural: Revelation operates through a distributed chain of God, Christ, angelic ministers, visionary perception, scribal transcription, books, and decoding procedures."]],"CH_TFRR_MPCA:ALT3":[["**Altitude 3 — Metastrategic:** Obscurity, failure, hostility, and temptation are reframed as conditions to be overcome through preparation, obedience, common labor, and discernment.","Altitude 3 — Metastrategic: Obscurity, failure, hostility, and temptation are reframed as conditions to be overcome through preparation, obedience, common labor, and discernment."]],"CH_TFRR_MPCA:ALT4":[["**Altitude 4 — Ontological/Temporal:** Reality is presupposed to be ordered, correspondential, transformable, and centered; its disclosure is gradual, its decoding potentially rapid, and its worldly horizon apocalyptically limited.","Altitude 4 — Ontological/Temporal: Reality is presupposed to be ordered, correspondential, transformable, and centered; its disclosure is gradual, its decoding potentially rapid, and its worldly horizon apocalyptically limited."]],"CL_TFRR_01:GA-01":[["[Persistent] The system posits divine unity, word, and will as the singular source, measure, and end of created order.","The system posits divine unity, word, and will as the singular source, measure, and end of created order."]],"CL_TFRR_01:GA-02":[["[Persistent] Every legitimate power is delegated through a commissioned hierarchy whose ministers remain servants of hidden divine determination.","Every legitimate power is delegated through a commissioned hierarchy whose ministers remain servants of hidden divine determination."]],"CL_TFRR_01:GA-03":[["[Mutating] Fallen disorder develops from moral and natural corruption into social contamination and finally into epistemic, linguistic, and jurisdictional exile.","Fallen disorder develops from moral and natural corruption into social contamination and finally into epistemic, linguistic, and jurisdictional exile."]],"CL_TFRR_01:GA-04":[["[Persistent] Revelation depends on a differentiated seer–scribe relay whose human faculties materially transmit an authority they do not own.","Revelation depends on a differentiated seer–scribe relay whose human faculties materially transmit an authority they do not own."]],"CL_TFRR_01:GA-05":[["[Mutating] Moral and ritual discipline regulates receptivity, collective protection, textual exactness, and operative efficacy.","Moral and ritual discipline regulates receptivity, collective protection, textual exactness, and operative efficacy."]],"CL_TFRR_01:GA-06":[["[Persistent] Apparitional form cannot authenticate itself; legitimacy requires doctrinal consistency, moral consequence, logical testing, and discrimination of mixture.","Apparitional form cannot authenticate itself; legitimacy requires doctrinal consistency, moral consequence, logical testing, and discrimination of mixture."]],"CL_TFRR_01:GA-07":[["[Mutating] Inscription changes from preservation of revelation into an exact material apparatus whose names, numbers, and words enter causal relations with creation.","Inscription changes from preservation of revelation into an exact material apparatus whose names, numbers, and words enter causal relations with creation."]],"CL_TFRR_01:GA-08":[["[Emergent] Persons, places, natural beings, political powers, and spiritual offices form one morally differentiated and jurisdictionally ordered field.","Persons, places, natural beings, political powers, and spiritual offices form one morally differentiated and jurisdictionally ordered field."]],"CL_TFRR_01:GA-09":[["[Mutating] Election is unmerited and empowering but remains conditional on living faith, obedience, holiness, and refusal of self-possession.","Election is unmerited and empowering but remains conditional on living faith, obedience, holiness, and refusal of self-possession."]],"CL_TFRR_01:GA-10":[["[Attractor] Adversity, deception, delay, and anomaly are bounded threats that the system repeatedly converts into trials reinforcing the mission.","Adversity, deception, delay, and anomaly are bounded threats that the system repeatedly converts into trials reinforcing the mission."]],"CL_TFRR_01:GA-11":[["[Terminal] The destination of history is predetermined, but its passage remains delayed and conditionally dependent on human consent, perseverance, and obedience.","The destination of history is predetermined, but its passage remains delayed and conditionally dependent on human consent, perseverance, and obedience."]],"CL_TFRR_01:GA-12":[["[Emergent] Operative access to derivative creation is secured around an inaccessible divine center and without an independent external tribunal.","Operative access to derivative creation is secured around an inaccessible divine center and without an independent external tribunal."]],"CL_TFRR_01:GA-13":[["[Attractor] The system converges on universal restoration and judgment by integrating sacred history, natural order, political transformation, and operative language.","The system converges on universal restoration and judgment by integrating sacred history, natural order, political transformation, and operative language."]],"CL_TFRR_02:GA-01":[["[Persistent] The disclosed architecture represents God as the transcendent source, sustainer, governor, judge, and end of every created order.","The disclosed architecture represents God as the transcendent source, sustainer, governor, judge, and end of every created order."]],"CL_TFRR_02:GA-02":[["[Mutating] Purity begins as removal of contaminating affiliations and expands into the moral, communal, and obedient condition of operational access.","Purity begins as removal of contaminating affiliations and expands into the moral, communal, and obedient condition of operational access."]],"CL_TFRR_02:GA-03":[["[Persistent] Divine power remains mediated through selected humans, angels, material instruments, operative names, and manifested beings rather than becoming directly accessible.","Divine power remains mediated through selected humans, angels, material instruments, operative names, and manifested beings rather than becoming directly accessible."]],"CL_TFRR_02:GA-04":[["[Emergent] Authority is distributed asymmetrically: revelation is treated as invariant, while seeing, hearing, writing, ordering, understanding, and execution remain correctable.","Authority is distributed asymmetrically: revelation is treated as invariant, while seeing, hearing, writing, ordering, understanding, and execution remain correctable."]],"CL_TFRR_02:GA-05":[["[Persistent] Natural, terrestrial, political, and temporal processes are represented as governed through a nested hierarchy of celestial offices and differentiated jurisdictions.","Natural, terrestrial, political, and temporal processes are represented as governed through a nested hierarchy of celestial offices and differentiated jurisdictions."]],"CL_TFRR_02:GA-06":[["[Mutating] Operative language develops from a key opening governed domains into an interface whose names and letters participate in the conjunction of powers and manifested beings.","Operative language develops from a key opening governed domains into an interface whose names and letters participate in the conjunction of powers and manifested beings."]],"CL_TFRR_02:GA-07":[["[Attractor] The distinction between licit and illicit operation depends principally on provenance, allegiance, authorization, moral condition, and purpose rather than on ritual form alone.","The distinction between licit and illicit operation depends principally on provenance, allegiance, authorization, moral condition, and purpose rather than on ritual form alone."]],"CL_TFRR_02:GA-08":[["[Attractor] Epistemic disturbance is absorbed into discipline, so doubt, interruption, and practical obstruction intensify rather than terminate the demand for obedience.","Epistemic disturbance is absorbed into discipline, so doubt, interruption, and practical obstruction intensify rather than terminate the demand for obedience."]],"CL_TFRR_02:GA-09":[["[Mutating] Election confers no secure possession of authority; each disclosure, office, or power increases exposure to obligation, correction, and possible rejection.","Election confers no secure possession of authority; each disclosure, office, or power increases exposure to obligation, correction, and possible rejection."]],"CL_TFRR_02:GA-10":[["[Attractor] Providence is not constrained by created chronology or prior material provision, allowing delayed fulfillment and logistical insufficiency to become tests of fidelity.","Providence is not constrained by created chronology or prior material provision, allowing delayed fulfillment and logistical insufficiency to become tests of fidelity."]],"CL_TFRR_02:GA-11":[["[Terminal] Authorized action must finally outrun technical possession, exhaustive knowledge, and exact foreknowledge, culminating in enacted obedience under unresolved interpretation.","Authorized action must finally outrun technical possession, exhaustive knowledge, and exact foreknowledge, culminating in enacted obedience under unresolved interpretation."]],"CL_TFRR_02:ALT-B01":[["[Surface level] The explicit field comprises destroyed magical objects, corrected texts, geographical names, Tables, Calls, apparitions, travel disputes, and commanded departure.","The explicit field comprises destroyed magical objects, corrected texts, geographical names, Tables, Calls, apparitions, travel disputes, and commanded departure."]],"CL_TFRR_02:ALT-B02":[["[Structural level] These objects are organized by purification protocols, hierarchical mediation, Adamic conflict, celestial administration, and ritual-linguistic access.","These objects are organized by purification protocols, hierarchical mediation, Adamic conflict, celestial administration, and ritual-linguistic access."]],"CL_TFRR_02:ALT-B03":[["[Metastrategic level] The cluster turns epistemic instability into discipline and subordinates interpretation, political intervention, material planning, and travel to authorized obedience.","The cluster turns epistemic instability into discipline and subordinates interpretation, political intervention, material planning, and travel to authorized obedience."]],"CL_TFRR_02:ALT-B04":[["[Ontological / Temporal level] Reality is hierarchically differentiated and providentially governed, while evil lacks enduring being and promises remain active across deferred temporal realization.","Reality is hierarchically differentiated and providentially governed, while evil lacks enduring being and promises remain active across deferred temporal realization."]],"CL_TFRR_02:ALT-B05":[["[Methodological / Performative level] The record performs its doctrine by making each obstruction generate correction, each correction further disclosure, and final action an interpretation of unresolved speech.","The record performs its doctrine by making each obstruction generate correction, each correction further disclosure, and final action an interpretation of unresolved speech."]],"CL_TFRR_03:GA-01":[["[Persistent] Significant events are ordered within providential causality and therefore cannot remain merely accidental circumstances.","Significant events are ordered within providential causality and therefore cannot remain merely accidental circumstances."]],"CL_TFRR_03:GA-02":[["[Persistent] Divine knowledge reaches human action through a differentiated chain of angelic, sensory, scribal, textual, and material mediators rather than through immediate transparency.","Divine knowledge reaches human action through a differentiated chain of angelic, sensory, scribal, textual, and material mediators rather than through immediate transparency."]],"CL_TFRR_03:GA-03":[["[Mutating] Christological and scriptural authority first tests revelation, then legitimates continuing prophecy, and finally grounds commands that claim precedence over temporal counsel.","Christological and scriptural authority first tests revelation, then legitimates continuing prophecy, and finally grounds commands that claim precedence over temporal counsel."]],"CL_TFRR_03:GA-04":[["[Persistent] Epistemic and operative fitness depend upon purification, repentance, humility, patience, obedience, faith, and coordinated labor.","Epistemic and operative fitness depend upon purification, repentance, humility, patience, obedience, faith, and coordinated labor."]],"CL_TFRR_03:GA-05":[["[Emergent] Created reality is formally ordered through position, number, proportion, conjunction, and materially effective correspondences that can be decoded and manipulated.","Created reality is formally ordered through position, number, proportion, conjunction, and materially effective correspondences that can be decoded and manipulated."]],"CL_TFRR_03:GA-06":[["[Persistent] Obedience is valid only within appointed time, and delay changes both the moral status and strategic efficacy of action.","Obedience is valid only within appointed time, and delay changes both the moral status and strategic efficacy of action."]],"CL_TFRR_03:GA-07":[["[Mutating] Error and failure are assigned to human impurity, defective preparation, satanic interpolation, counterfeit mediation, or hostile interference rather than to the divine source.","Error and failure are assigned to human impurity, defective preparation, satanic interpolation, counterfeit mediation, or hostile interference rather than to the divine source."]],"CL_TFRR_03:GA-08":[["[Emergent] The written archive converts secret vision into durable evidence, public admonition, political testimony, and prospective judgment.","The written archive converts secret vision into durable evidence, public admonition, political testimony, and prospective judgment."]],"CL_TFRR_03:GA-09":[["[Mutating] Elected agency is distributed across unequal offices and consolidated into a collective operational body whose mission outranks private will.","Elected agency is distributed across unequal offices and consolidated into a collective operational body whose mission outranks private will."]],"CL_TFRR_03:GA-10":[["[Mutating] Natural knowledge and alchemical matter become strategic instruments for material sufficiency, public authentication, and political access.","Natural knowledge and alchemical matter become strategic instruments for material sufficiency, public authentication, and political access."]],"CL_TFRR_03:GA-11":[["[Emergent] Temporal sovereignty is conditionally valid and remains subordinate to prophetic correction, recruitment, and replacement.","Temporal sovereignty is conditionally valid and remains subordinate to prophetic correction, recruitment, and replacement."]],"CL_TFRR_03:GA-12":[["[Attractor] Approaching judgment and the projected historical advent of heavenly order draw natural science, personal discipline, and political action into one terminal horizon.","Approaching judgment and the projected historical advent of heavenly order draw natural science, personal discipline, and political action into one terminal horizon."]],"CL_TFRR_03:GA-13":[["[Terminal] Withdrawal, interruption, or commanded silence suspends access without retracting prior revelation, thereby preserving both authority and the possibility of later resumption.","Withdrawal, interruption, or commanded silence suspends access without retracting prior revelation, thereby preserving both authority and the possibility of later resumption."]],"CL_TFRR_03:RMD-01":[["[Escalation] Revelation retains divine provenance while expanding from private prophetic commission into comprehensive natural science and then into an explicit political program.","Revelation retains divine provenance while expanding from private prophetic commission into comprehensive natural science and then into an explicit political program."]],"CL_TFRR_03:RMD-02":[["[Functional Recurrence] Mediation recurs first as a division between seer and recipient, then as an extended chain of books and decoding procedures, and finally as one hierarchized operational body.","Mediation recurs first as a division between seer and recipient, then as an extended chain of books and decoding procedures, and finally as one hierarchized operational body."]],"CL_TFRR_03:RMD-03":[["[Mutation] Obscurity changes from a veil protecting divine secrets into structured encoding whose decipherment is treated as technically recoverable.","Obscurity changes from a veil protecting divine secrets into structured encoding whose decipherment is treated as technically recoverable."]],"CL_TFRR_03:RMD-04":[["[Escalation] Alchemy moves from a worldly lure subordinated to revelation, through a claimed ontology of lower nature, into the mission’s proof-producing and logistical infrastructure.","Alchemy moves from a worldly lure subordinated to revelation, through a claimed ontology of lower nature, into the mission’s proof-producing and logistical infrastructure."]],"CL_TFRR_03:RMD-05":[["[Stable Identity] Failure repeatedly preserves rather than dissolves the system because each adverse result becomes evidence of contamination, unreadiness, opposition, or delayed timing.","Failure repeatedly preserves rather than dissolves the system because each adverse result becomes evidence of contamination, unreadiness, opposition, or delayed timing."]],"CL_TFRR_03:RMD-06":[["[Mutation] Writing changes from the required public exposure of revelation into a decipherable technical substrate and then into portable political and judicial evidence.","Writing changes from the required public exposure of revelation into a decipherable technical substrate and then into portable political and judicial evidence."]],"CL_TFRR_03:RMD-07":[["[Reversal] The ruler changes from the judge and recipient of a prophetic appeal into a conditionally elected subordinate whose authority depends upon compliance.","The ruler changes from the judge and recipient of a prophetic appeal into a conditionally elected subordinate whose authority depends upon compliance."]],"CL_TFRR_03:RMD-08":[["[Displacement] Ecclesial reconciliation remains explicit only at the earlier stage; later Christic renewal and private angelic jurisdiction absorb its qualifying function without resolving the conflict of authority.","Ecclesial reconciliation remains explicit only at the earlier stage; later Christic renewal and private angelic jurisdiction absorb its qualifying function without resolving the conflict of authority."]],"CL_TFRR_03:CGD-01":[["[Local] Particular illnesses, diplomatic exchanges, cryptic words, numerical sequences, household conflicts, and specific alchemical terms remain contingent machinery rather than global propositions.","Particular illnesses, diplomatic exchanges, cryptic words, numerical sequences, household conflicts, and specific alchemical terms remain contingent machinery rather than global propositions."]],"CL_TFRR_03:CGD-02":[["[Scales Upward] Providence, moralized cognition, differentiated mediation, material receptivity, and apocalyptic timing organize all three units and therefore become cluster-level architecture.","Providence, moralized cognition, differentiated mediation, material receptivity, and apocalyptic timing organize all three units and therefore become cluster-level architecture."]],"CL_TFRR_03:CGD-03":[["[Bridge] The quaternary natural model bridges symbolic vision and technical operation by supplying a common grammar of differentiation, purification, conjunction, and ascent.","The quaternary natural model bridges symbolic vision and technical operation by supplying a common grammar of differentiation, purification, conjunction, and ascent."]],"CL_TFRR_03:CGD-04":[["[Catalyst] Counterfeit mediation converts deception from an external objection into an internal problem of the revelatory apparatus, forcing authentication to depend increasingly on function and conformity.","Counterfeit mediation converts deception from an external objection into an internal problem of the revelatory apparatus, forcing authentication to depend increasingly on function and conformity."]],"CL_TFRR_03:CGD-05":[["[Recoded] Material desire is initially repudiated, then tactically exploited, and finally legitimated only as independence and infrastructure for the mission.","Material desire is initially repudiated, then tactically exploited, and finally legitimated only as independence and infrastructure for the mission."]],"CL_TFRR_03:CGD-06":[["[Superseded] The announced end of teaching becomes obsolete as a final closure because later confirmations reopen instruction; withdrawal functions instead as intermittent disciplinary control.","The announced end of teaching becomes obsolete as a final closure because later confirmations reopen instruction; withdrawal functions instead as intermittent disciplinary control."]],"CL_TFRR_04:GA-01":[["[Attractor] Purported divine speech requires mediation, yet the legitimacy of every mediator depends on the authority regime that the mediated speech is invoked to establish.","Purported divine speech requires mediation, yet the legitimacy of every mediator depends on the authority regime that the mediated speech is invoked to establish."]],"CL_TFRR_04:GA-02":[["[Persistent] Obedience is treated as the primary form through which truth, vocation, and effective agency become available to the human subject.","Obedience is treated as the primary form through which truth, vocation, and effective agency become available to the human subject."]],"CL_TFRR_04:GA-03":[["[Mutating] Final authority shifts between an apostolic-ecclesial chain and claimed immediate divine will, without an accepted jurisdiction capable of adjudicating the shift.","Final authority shifts between an apostolic-ecclesial chain and claimed immediate divine will, without an accepted jurisdiction capable of adjudicating the shift."]],"CL_TFRR_04:GA-04":[["[Persistent] Moral corruption does not automatically invalidate an office, release subjects from obedience, or extinguish the possibility of divinely directed action through existing institutions.","Moral corruption does not automatically invalidate an office, release subjects from obedience, or extinguish the possibility of divinely directed action through existing institutions."]],"CL_TFRR_04:GA-05":[["[Persistent] Revelatory access is distributed through regulated collectivities, designated offices, secrecy, custody, and restricted participation rather than unrestricted private possession.","Revelatory access is distributed through regulated collectivities, designated offices, secrecy, custody, and restricted participation rather than unrestricted private possession."]],"CL_TFRR_04:GA-06":[["[Emergent] Extraordinary delegation creates a legitimate exception within systems that otherwise condemn self-authorization and unauthorized religious speech.","Extraordinary delegation creates a legitimate exception within systems that otherwise condemn self-authorization and unauthorized religious speech."]],"CL_TFRR_04:GA-07":[["[Mutating] Inherited doctrine and Christian law initially judge purported revelation, but exceptional revelation can reverse the relation and determine whether ordinary law applies.","Inherited doctrine and Christian law initially judge purported revelation, but exceptional revelation can reverse the relation and determine whether ordinary law applies."]],"CL_TFRR_04:GA-08":[["[Persistent] Corruption, accusation, exile, and persecution are not admitted as sufficient disproof of either institutional continuity or prophetic vocation.","Corruption, accusation, exile, and persecution are not admitted as sufficient disproof of either institutional continuity or prophetic vocation."]],"CL_TFRR_04:GA-09":[["[Attractor] Judgment functions simultaneously as threatened enforcement, future verification, purification of the authorized community, and destruction of its opponents.","Judgment functions simultaneously as threatened enforcement, future verification, purification of the authorized community, and destruction of its opponents."]],"CL_TFRR_04:GA-10":[["[Emergent] Books and archives become jurisdictional objects whose opening, recovery, sealing, custody, and appointed use regulate access to truth.","Books and archives become jurisdictional objects whose opening, recovery, sealing, custody, and appointed use regulate access to truth."]],"CL_TFRR_04:GA-11":[["[Attractor] The less publicly secure the mediation becomes, the more strongly certainty is relocated to divine intention, disciplined obedience, and deferred vindication.","The less publicly secure the mediation becomes, the more strongly certainty is relocated to divine intention, disciplined obedience, and deferred vindication."]],"CL_TFRR_04:GA-12":[["[Terminal] Vocation closes not in independent demonstration but in conditional incorporation into a mission whose promised efficacy depends on continued obedience.","Vocation closes not in independent demonstration but in conditional incorporation into a mission whose promised efficacy depends on continued obedience."]],"CL_TFRR_04:GA-13":[["[Attractor] Purification and reunification supply the terminal horizon that connects ecclesial return, household covenant, apocalyptic restoration, and projected universal order.","Purification and reunification supply the terminal horizon that connects ecclesial return, household covenant, apocalyptic restoration, and projected universal order."]],"CL_TFRR_04:ALT-B01":[["[Surface] Apparitions, books, archives, ecclesiastical disputes, political expulsions, prophetic missions, and household commands serve as the explicit objects through which authorization is contested.","Apparitions, books, archives, ecclesiastical disputes, political expulsions, prophetic missions, and household commands serve as the explicit objects through which authorization is contested."]],"CL_TFRR_04:ALT-B02":[["[Structural] The active machinery consists of mediation, delegated office, sacred custody, restricted access, obedience, exception, and deferred enforcement.","The active machinery consists of mediation, delegated office, sacred custody, restricted access, obedience, exception, and deferred enforcement."]],"CL_TFRR_04:ALT-B03":[["[Metastrategic] Potential refutations are redistributed into the system as evidence of corruption, persecution, trial, or the need for stronger internal discipline.","Potential refutations are redistributed into the system as evidence of corruption, persecution, trial, or the need for stronger internal discipline."]],"CL_TFRR_04:ALT-B04":[["[Ontological / Temporal] Invisible agency is represented as governing matter, office, history, and moral classification through measured but incompletely disclosed sequences of judgment and restoration.","Invisible agency is represented as governing matter, office, history, and moral classification through measured but incompletely disclosed sequences of judgment and restoration."]],"CL_TFRR_04:ALT-B05":[["[Methodological / Performative] The records perform their claims through recurrent revelation, accumulated signs, recursive correction, controlled omission, and promises whose delay requires continued reading and obedience.","The records perform their claims through recurrent revelation, accumulated signs, recursive correction, controlled omission, and promises whose delay requires continued reading and obedience."]],"CL_TFRR_05:GA-01":[["[Persistent] Within the discourse, legitimate angelic, human, material, and epistemic authority is derivative from divine commission.","Within the discourse, legitimate angelic, human, material, and epistemic authority is derivative from divine commission."]],"CL_TFRR_05:GA-02":[["[Persistent] Dee is positioned as the elected recipient and future operator of hidden wisdom ordered toward divine service.","Dee is positioned as the elected recipient and future operator of hidden wisdom ordered toward divine service."]],"CL_TFRR_05:GA-03":[["[Mutating] The withholding of revelation begins as protection from hostile recipients and expands into a judgment that England is morally and epistemically unfit.","The withholding of revelation begins as protection from hostile recipients and expands into a judgment that England is morally and epistemically unfit."]],"CL_TFRR_05:GA-04":[["[Mutating] Delay is not empty postponement but a providential mechanism whose causes expand from protection to divine timing and human noncompliance.","Delay is not empty postponement but a providential mechanism whose causes expand from protection to divine timing and human noncompliance."]],"CL_TFRR_05:GA-05":[["[Persistent] Departure from England is a binding command, and arrival elsewhere is a precondition of the assigned service and fuller revelation.","Departure from England is a binding command, and arrival elsewhere is a precondition of the assigned service and fuller revelation."]],"CL_TFRR_05:GA-06":[["[Attractor] Fulfillment is conditional upon willing obedience, while the command itself is claimed to entail the preservation and aid required for execution.","Fulfillment is conditional upon willing obedience, while the command itself is claimed to entail the preservation and aid required for execution."]],"CL_TFRR_05:GA-07":[["[Persistent] Providence fixes the governing end, whereas Dee remains responsible for diligent selection and execution of subordinate means.","Providence fixes the governing end, whereas Dee remains responsible for diligent selection and execution of subordinate means."]],"CL_TFRR_05:GA-08":[["[Emergent] Logistics, law, finance, bodily preservation, and material media become socially legible mechanisms through which the mission is implemented.","Logistics, law, finance, bodily preservation, and material media become socially legible mechanisms through which the mission is implemented."]],"CL_TFRR_05:GA-09":[["[Emergent] Sacred knowledge is an environmentally dependent power whose legitimate reception requires a suitable place, recipient, custody, and political field.","Sacred knowledge is an environmentally dependent power whose legitimate reception requires a suitable place, recipient, custody, and political field."]],"CL_TFRR_05:GA-10":[["[Attractor] Promised futurity governs present obedience without becoming present possession or acquiring a specified terminal failure condition.","Promised futurity governs present obedience without becoming present possession or acquiring a specified terminal failure condition."]],"CL_TFRR_05:GA-11":[["[Terminal] Each revelatory cycle ends through conditional suspension—withdrawal after disobedience or promised correction at a future reunion—rather than final doctrinal closure.","Each revelatory cycle ends through conditional suspension—withdrawal after disobedience or promised correction at a future reunion—rather than final doctrinal closure."]],"CL_TFRR_05:RMD-01":[["[Stable identity] Raphael’s authority remains consistently derivative, bounded, and revocable rather than becoming autonomous through repetition.","Raphael’s authority remains consistently derivative, bounded, and revocable rather than becoming autonomous through repetition."]],"CL_TFRR_05:RMD-02":[["[Mutation] Nonfulfillment first protects the promise and then becomes an affirmative reason for relocation, converting defensive explanation into strategic command.","Nonfulfillment first protects the promise and then becomes an affirmative reason for relocation, converting defensive explanation into strategic command."]],"CL_TFRR_05:RMD-03":[["[Escalation] Delay expands from a local interval protecting revelation into a general explanatory buffer encompassing timing, resistance, and human default.","Delay expands from a local interval protecting revelation into a general explanatory buffer encompassing timing, resistance, and human default."]],"CL_TFRR_05:RMD-04":[["[Displacement] Geography changes from a practical question of residence into a morally and epistemically differentiated field of danger and disclosure.","Geography changes from a practical question of residence into a morally and epistemically differentiated field of danger and disclosure."]],"CL_TFRR_05:RMD-05":[["[Functional mutation] Choice ceases to mean sovereign selection of ends and becomes guided selection within an end that Dee does not control.","Choice ceases to mean sovereign selection of ends and becomes guided selection within an end that Dee does not control."]],"CL_TFRR_05:RMD-06":[["[Domain migration] Mediation moves from appointed human helpers into stones, voices, legal procedures, and other material vehicles without escaping divine authorization.","Mediation moves from appointed human helpers into stones, voices, legal procedures, and other material vehicles without escaping divine authorization."]],"CL_TFRR_05:RMD-07":[["[Absorption] Earthly requests lose independent legitimacy and are absorbed into a total interpretive frame ordered by mission, timing, and service.","Earthly requests lose independent legitimacy and are absorbed into a total interpretive frame ordered by mission, timing, and service."]],"CL_TFRR_05:RMD-08":[["[Reversal] Political patronage changes from a presumed source of legitimacy into an inferior dependency expected eventually to run from rulers toward Dee.","Political patronage changes from a presumed source of legitimacy into an inferior dependency expected eventually to run from rulers toward Dee."]],"CL_TFRR_05:RMD-09":[["[Terminal absorption] Treasure, theft, and patronage disputes disappear as independent centers after demonstrating how secondary affairs are regulated by the journey-command.","Treasure, theft, and patronage disputes disappear as independent centers after demonstrating how secondary affairs are regulated by the journey-command."]],"CL_TFRR_05:CGD-01":[["[Local] Pontoys, the Pearl, the Dust, particular treasures, and named intermediaries remain contingent implementations; only their mediating function scales upward.","Pontoys, the Pearl, the Dust, particular treasures, and named intermediaries remain contingent implementations; only their mediating function scales upward."]],"CL_TFRR_05:CGD-02":[["[Scales upward] Particular illness and medical intervention become the broader proposition that bodily preservation conditions revelatory and practical capacity.","Particular illness and medical intervention become the broader proposition that bodily preservation conditions revelatory and practical capacity."]],"CL_TFRR_05:CGD-03":[["[Scales upward] The local travel injunction becomes a cluster-level rule that spatial relocation is necessary for safe knowledge and assigned service.","The local travel injunction becomes a cluster-level rule that spatial relocation is necessary for safe knowledge and assigned service."]],"CL_TFRR_05:CGD-04":[["[Bridge] Moral timing and occult cooperation connect with lawful procedure to make invisible causation dependent upon visible, socially intelligible execution.","Moral timing and occult cooperation connect with lawful procedure to make invisible causation dependent upon visible, socially intelligible execution."]],"CL_TFRR_05:CGD-05":[["[Catalyst] English hostility converts exile from deprivation into the transition mechanism linking election, protection, and revelation.","English hostility converts exile from deprivation into the transition mechanism linking election, protection, and revelation."]],"CL_TFRR_05:CGD-06":[["[Superseded] Treasure, retaliation, alchemy, and unrestricted inquiry are recoded from alternative projects into timed and subordinate instruments of departure.","Treasure, retaliation, alchemy, and unrestricted inquiry are recoded from alternative projects into timed and subordinate instruments of departure."]],"CL_TFRR_05:CGD-07":[["[Residual] Uncertain figures and untranslated textual sequences remain lower-layer documentary residues because they lack secure semantic integration into the generative architecture.","Uncertain figures and untranslated textual sequences remain lower-layer documentary residues because they lack secure semantic integration into the generative architecture."]],"CL_TFRR_05:FGS-B01":[["[Stage 1] Claimed election plus illness, poverty, hostility, and nonfulfillment generates the contradiction that demands revelatory interpretation.","Claimed election plus illness, poverty, hostility, and nonfulfillment generates the contradiction that demands revelatory interpretation."]],"CL_TFRR_05:FGS-B02":[["[Stage 2] Invocation establishes divine commission, which authorizes an angelic agent and passes instruction through appointed human or material media.","Invocation establishes divine commission, which authorizes an angelic agent and passes instruction through appointed human or material media."]],"CL_TFRR_05:FGS-B03":[["[Stage 3] Providential recoding converts weakness into preservation, delay into protection, and deferred outcomes into preservation of the promise.","Providential recoding converts weakness into preservation, delay into protection, and deferred outcomes into preservation of the promise."]],"CL_TFRR_05:FGS-B04":[["[Stage 4] Political and demonic hostility spatializes the contradiction by classifying England as an unsafe and unworthy revelatory field.","Political and demonic hostility spatializes the contradiction by classifying England as an unsafe and unworthy revelatory field."]],"CL_TFRR_05:FGS-B05":[["[Stage 5] Commanded relocation converts consent into eligibility for protection and revelation while imposing faith, diligence, and restraint.","Commanded relocation converts consent into eligibility for protection and revelation while imposing faith, diligence, and restraint."]],"CL_TFRR_05:FGS-B06":[["[Stage 6] Human supporters, material resources, and socially legible procedures translate the revelatory command into practical execution.","Human supporters, material resources, and socially legible procedures translate the revelatory command into practical execution."]],"CL_TFRR_05:FGS-B07":[["[Stage 7] Uncertainty generates renewed consultation, while promised future correction suspends rather than completes the architecture.","Uncertainty generates renewed consultation, while promised future correction suspends rather than completes the architecture."]],"CL_TFRR_05:ALT-B01":[["[Surface level] The explicit field consists of illness, travel, patronage, money, treasure, theft, companions, material media, and access to angelic counsel.","The explicit field consists of illness, travel, patronage, money, treasure, theft, companions, material media, and access to angelic counsel."]],"CL_TFRR_05:ALT-B02":[["[Structural level] Bodily capacity, appointed timing, conditional obedience, angelic mediation, human procedure, and material support form one ranked administration.","Bodily capacity, appointed timing, conditional obedience, angelic mediation, human procedure, and material support form one ranked administration."]],"CL_TFRR_05:ALT-B03":[["[Metastrategic level] Failed patronage and competing projects are converted into reasons to privilege relocation, restrain alternatives, and continue adherence to the revelatory frame.","Failed patronage and competing projects are converted into reasons to privilege relocation, restrain alternatives, and continue adherence to the revelatory frame."]],"CL_TFRR_05:ALT-B04":[["[Ontological / Temporal level] Reality is represented as providentially unified and hierarchically mediated, while promised futurity governs action through deferral.","Reality is represented as providentially unified and hierarchically mediated, while promised futurity governs action through deferral."]],"CL_TFRR_05:ALT-B05":[["[Methodological / Performative level] Serial inquiry, restricted answers, renewed uncertainty, and postponed correction perform the dependence and deferred verification asserted by the system.","Serial inquiry, restricted answers, renewed uncertainty, and postponed correction perform the dependence and deferred verification asserted by the system."]],"MC_TFRR_L1_01:GA-01":[["[Persistent] Divine unity and will constitute the singular source, measure, government, and terminal end of every significant event and created order.","Divine unity and will constitute the singular source, measure, government, and terminal end of every significant event and created order."]],"MC_TFRR_L1_01:GA-02":[["[Persistent] Divine power becomes accessible only through a delegated and differentiated hierarchy of spiritual, human, sensory, textual, and material mediators.","Divine power becomes accessible only through a delegated and differentiated hierarchy of spiritual, human, sensory, textual, and material mediators."]],"MC_TFRR_L1_01:GA-03":[["[Mutating] Purification and obedience expand from moral preparation into the epistemic, communal, protective, and technical infrastructure of revelation and operation.","Purification and obedience expand from moral preparation into the epistemic, communal, protective, and technical infrastructure of revelation and operation."]],"MC_TFRR_L1_01:GA-04":[["[Persistent] Revelation requires an asymmetrically distributed relay whose recipients, recorders, interpreters, instruments, and executors transmit authority without owning it.","Revelation requires an asymmetrically distributed relay whose recipients, recorders, interpreters, instruments, and executors transmit authority without owning it."]],"MC_TFRR_L1_01:GA-05":[["[Mutating] Inscription develops from preserving disclosure into an operative interface, a formally decodable substrate, and a durable instrument of public and political jurisdiction.","Inscription develops from preserving disclosure into an operative interface, a formally decodable substrate, and a durable instrument of public and political jurisdiction."]],"MC_TFRR_L1_01:GA-06":[["[Emergent] Persons, natural beings, substances, territories, political offices, and historical events form one morally differentiated and hierarchically administered providential field.","Persons, natural beings, substances, territories, political offices, and historical events form one morally differentiated and hierarchically administered providential field."]],"MC_TFRR_L1_01:GA-07":[["[Attractor] Revelatory legitimacy depends on provenance, doctrinal conformity, moral effect, authorization, and functional consistency rather than on appearance or ritual form alone.","Revelatory legitimacy depends on provenance, doctrinal conformity, moral effect, authorization, and functional consistency rather than on appearance or ritual form alone."]],"MC_TFRR_L1_01:GA-08":[["[Attractor] Adversity, discrepancy, delay, deception, and failed operation are repeatedly absorbed as bounded tests or mediation defects that generate correction rather than terminate the mission.","Adversity, discrepancy, delay, deception, and failed operation are repeatedly absorbed as bounded tests or mediation defects that generate correction rather than terminate the mission."]],"MC_TFRR_L1_01:GA-09":[["[Mutating] Election enlarges agency only by intensifying conditional obedience, unequal office, exposure to correction, and replaceability within the collective apparatus.","Election enlarges agency only by intensifying conditional obedience, unequal office, exposure to correction, and replaceability within the collective apparatus."]],"MC_TFRR_L1_01:GA-10":[["[Mutating] Time combines a predetermined destination with conditional passage, appointed openings, delayed fulfillment, and recurrent opportunities for corrected action.","Time combines a predetermined destination with conditional passage, appointed openings, delayed fulfillment, and recurrent opportunities for corrected action."]],"MC_TFRR_L1_01:GA-11":[["[Attractor] Universal restoration, judgment, and heavenly order draw moral discipline, natural science, material operation, and political action into one apocalyptic horizon.","Universal restoration, judgment, and heavenly order draw moral discipline, natural science, material operation, and political action into one apocalyptic horizon."]],"MC_TFRR_L1_01:GA-12":[["[Terminal] Enacted obedience and provisional withdrawal provide practical closure where exhaustive knowledge, completed verification, and final consummation remain unavailable.","Enacted obedience and provisional withdrawal provide practical closure where exhaustive knowledge, completed verification, and final consummation remain unavailable."]],"MC_TFRR_L1_01:GA-13":[["[Persistent] Operative access remains confined to derivative creation because the divine center is inaccessible, mediation is unavoidable, and exhaustive transparency is excluded.","Operative access remains confined to derivative creation because the divine center is inaccessible, mediation is unavoidable, and exhaustive transparency is excluded."]],"MC_TFRR_L1_01:RMD-01":[["[Stable Identity / Expansion] Divine determination retains its identity while expanding from control of particular sessions into the comprehensive government of creation, history, and circumstance.","Divine determination retains its identity while expanding from control of particular sessions into the comprehensive government of creation, history, and circumstance."]],"MC_TFRR_L1_01:RMD-02":[["[Functional Mutation] Purification changes from preparatory cleansing into the positive formation of subjects whose moral state governs reception, decoding, protection, and material efficacy.","Purification changes from preparatory cleansing into the positive formation of subjects whose moral state governs reception, decoding, protection, and material efficacy."]],"MC_TFRR_L1_01:RMD-03":[["[Escalation] The seer–scribe division expands from a local labor arrangement into an extended and hierarchized collective body of perception, recording, interpretation, and execution.","The seer–scribe division expands from a local labor arrangement into an extended and hierarchized collective body of perception, recording, interpretation, and execution."]],"MC_TFRR_L1_01:RMD-04":[["[Terminal Transformation] Writing changes from a record of vision into a causal interface and then into portable public, political, and judicial evidence.","Writing changes from a record of vision into a causal interface and then into portable public, political, and judicial evidence."]],"MC_TFRR_L1_01:RMD-05":[["[Domain Migration] Exact language moves from semantic representation into causal address, variable jurisdictional protocol, and formally reconstructed natural operation.","Exact language moves from semantic representation into causal address, variable jurisdictional protocol, and formally reconstructed natural operation."]],"MC_TFRR_L1_01:RMD-06":[["[Scope Expansion] Geography develops from morally charged travel and appointed destinations into a topology of governed jurisdictions and politically revocable territories.","Geography develops from morally charged travel and appointed destinations into a topology of governed jurisdictions and politically revocable territories."]],"MC_TFRR_L1_01:RMD-07":[["[Valence Reversal] Adversarial resistance changes from possible disconfirmation into an internal diagnostic mechanism that locates contamination, unreadiness, interference, or missed timing.","Adversarial resistance changes from possible disconfirmation into an internal diagnostic mechanism that locates contamination, unreadiness, interference, or missed timing."]],"MC_TFRR_L1_01:RMD-08":[["[Absorption] Alchemy does not remain an independent axiom but becomes a late material specialization of the broader conversion of revelation into operational and evidentiary infrastructure.","Alchemy does not remain an independent axiom but becomes a late material specialization of the broader conversion of revelation into operational and evidentiary infrastructure."]],"MC_TFRR_L1_01:RMD-09":[["[Political Reversal] Political rulers shift from patrons and external recipients into conditionally elected instruments whose authority is subordinate to prophetic commission.","Political rulers shift from patrons and external recipients into conditionally elected instruments whose authority is subordinate to prophetic commission."]],"MC_TFRR_L1_01:RMD-10":[["[Terminal Displacement] Silence and withdrawal cease to signify simple absence and become disciplinary controls that suspend access while preserving prior authority and possible resumption.","Silence and withdrawal cease to signify simple absence and become disciplinary controls that suspend access while preserving prior authority and possible resumption."]],"MC_TFRR_L1_01:CGD-01":[["[Local] Named political roles, particular illnesses, diplomatic incidents, household conflicts, and individual dangers remain contingent machinery rather than meta-cluster axioms.","Named political roles, particular illnesses, diplomatic incidents, household conflicts, and individual dangers remain contingent machinery rather than meta-cluster axioms."]],"MC_TFRR_L1_01:CGD-02":[["[Scales Upward] Exact grids, enumerations, Aires, tables, and correspondences remain implementation-level structures, while bounded and encoded jurisdictional access becomes globally load-bearing.","Exact grids, enumerations, Aires, tables, and correspondences remain implementation-level structures, while bounded and encoded jurisdictional access becomes globally load-bearing."]],"MC_TFRR_L1_01:CGD-03":[["[Catalyst] The destruction of specific magical materials remains local initiatory machinery, but its conversion of contamination into purification establishes a general condition of eligibility.","The destruction of specific magical materials remains local initiatory machinery, but its conversion of contamination into purification establishes a general condition of eligibility."]],"MC_TFRR_L1_01:CGD-04":[["[Recoded] Alchemical procedures remain a specialized lower-layer modality, while material mediation, practical sufficiency, and public authentication scale into the broader architecture.","Alchemical procedures remain a specialized lower-layer modality, while material mediation, practical sufficiency, and public authentication scale into the broader architecture."]],"MC_TFRR_L1_01:CGD-05":[["[Scales Upward] Particular journeys remain itinerary-specific, but commanded movement scales into an epistemic enactment of obedience under danger, insufficient provision, and unresolved interpretation.","Particular journeys remain itinerary-specific, but commanded movement scales into an epistemic enactment of obedience under danger, insufficient provision, and unresolved interpretation."]],"MC_TFRR_L1_01:CGD-06":[["[Bridge] The book and archive bridge private disclosure to operative procedure, public testimony, political responsibility, and prospective judgment.","The book and archive bridge private disclosure to operative procedure, public testimony, political responsibility, and prospective judgment."]],"MC_TFRR_L1_01:CGD-07":[["[Superseded / Recoded] Particular sensible forms and competing accounts of names are superseded as final ontologies but retained as variable accommodations within a functionally exact system of address.","Particular sensible forms and competing accounts of names are superseded as final ontologies but retained as variable accommodations within a functionally exact system of address."]],"MC_TFRR_L1_02:GA-01":[["[Persistent] Divine authority operates only through derivative mediation, while every mediator remains dependent on the commission the mediated communication is invoked to establish.","Divine authority operates only through derivative mediation, while every mediator remains dependent on the commission the mediated communication is invoked to establish."]],"MC_TFRR_L1_02:GA-02":[["[Persistent] Obedience is the condition of revelatory access and effective agency, but it permits bounded practical choice within an end the subject does not originate.","Obedience is the condition of revelatory access and effective agency, but it permits bounded practical choice within an end the subject does not originate."]],"MC_TFRR_L1_02:GA-03":[["[Emergent] Revelation is an ecology of recipient, office, custody, place, time, and medium rather than an utterance separable from its authorized conditions.","Revelation is an ecology of recipient, office, custody, place, time, and medium rather than an utterance separable from its authorized conditions."]],"MC_TFRR_L1_02:GA-04":[["[Mutating] Adversity changes from a condition compatible with election into a positive diagnostic that directs correction, withdrawal, relocation, and future action.","Adversity changes from a condition compatible with election into a positive diagnostic that directs correction, withdrawal, relocation, and future action."]],"MC_TFRR_L1_02:GA-05":[["[Mutating] Extraordinary delegation expands from an exception within established religious order into authority to redraw the spatial and practical conditions under which that order can be served.","Extraordinary delegation expands from an exception within established religious order into authority to redraw the spatial and practical conditions under which that order can be served."]],"MC_TFRR_L1_02:GA-06":[["[Emergent] Books, bodies, finance, law, logistics, and material media are intrinsic components of revelatory administration rather than external supports added after authorization.","Books, bodies, finance, law, logistics, and material media are intrinsic components of revelatory administration rather than external supports added after authorization."]],"MC_TFRR_L1_02:GA-07":[["[Attractor] Time governs authentication by postponing verification, disciplining conduct, and translating nonfulfillment into protection, judgment, timing, or human default.","Time governs authentication by postponing verification, disciplining conduct, and translating nonfulfillment into protection, judgment, timing, or human default."]],"MC_TFRR_L1_02:GA-08":[["[Persistent] Knowledge is jurisdictionally distributed through secrecy, custody, restricted inquiry, authorized purpose, and differential permission to see, possess, interpret, or disclose.","Knowledge is jurisdictionally distributed through secrecy, custody, restricted inquiry, authorized purpose, and differential permission to see, possess, interpret, or disclose."]],"MC_TFRR_L1_02:GA-09":[["[Emergent] Political and ecclesiastical authorities remain instrumentally usable and conditionally obeyable but cannot possess final jurisdiction over revelation or its projected effects.","Political and ecclesiastical authorities remain instrumentally usable and conditionally obeyable but cannot possess final jurisdiction over revelation or its projected effects."]],"MC_TFRR_L1_02:GA-10":[["[Attractor] Purification, reunification, and exceptional future wisdom converge as the horizon promising reversal of present disorder and dependency.","Purification, reunification, and exceptional future wisdom converge as the horizon promising reversal of present disorder and dependency."]],"MC_TFRR_L1_02:GA-11":[["[Terminal] Revelatory cycles terminate only in conditional suspension, because present uncertainty is preserved for later correction, fulfillment, judgment, or renewed disclosure.","Revelatory cycles terminate only in conditional suspension, because present uncertainty is preserved for later correction, fulfillment, judgment, or renewed disclosure."]],"MC_TFRR_L1_02:RMD-01":[["[Stable identity] Divine authorization retains its derivative structure while expanding from ecclesial and prophetic offices into a ranked relay of angelic, human, material, and procedural agencies.","Divine authorization retains its derivative structure while expanding from ecclesial and prophetic offices into a ranked relay of angelic, human, material, and procedural agencies."]],"MC_TFRR_L1_02:RMD-02":[["[Functional recurrence] Obedience retains positive valence but changes object from ecclesial incorporation and exceptional covenant to commanded departure and bounded execution.","Obedience retains positive valence but changes object from ecclesial incorporation and exceptional covenant to commanded departure and bounded execution."]],"MC_TFRR_L1_02:RMD-03":[["[Displacement] Custody migrates from books and archives into geography itself, so the protected field becomes as jurisdictionally decisive as the protected document.","Custody migrates from books and archives into geography itself, so the protected field becomes as jurisdictionally decisive as the protected document."]],"MC_TFRR_L1_02:RMD-04":[["[Mutation] The authorized exception expands from interpreting or suspending ordinary law into reclassifying exile and relocation as necessary conditions of revelation.","The authorized exception expands from interpreting or suspending ordinary law into reclassifying exile and relocation as necessary conditions of revelation."]],"MC_TFRR_L1_02:RMD-05":[["[Escalation] Corruption and persecution first lose their power to disprove authority and then acquire the stronger function of identifying where correction or departure must occur.","Corruption and persecution first lose their power to disprove authority and then acquire the stronger function of identifying where correction or departure must occur."]],"MC_TFRR_L1_02:RMD-06":[["[Terminal transformation] Delay changes from a temporary interval before verification into the standing temporal form through which the system preserves authority.","Delay changes from a temporary interval before verification into the standing temporal form through which the system preserves authority."]],"MC_TFRR_L1_02:RMD-07":[["[Reversal] Political centers change from possible sources of authorization into defective fields that may later become dependent on the displaced wisdom they failed to recognize.","Political centers change from possible sources of authorization into defective fields that may later become dependent on the displaced wisdom they failed to recognize."]],"MC_TFRR_L1_02:RMD-08":[["[Absorption] Foundational signs recede after authorization, while the offices, journeys, covenants, and custodial practices they initiate become self-renewing machines.","Foundational signs recede after authorization, while the offices, journeys, covenants, and custodial practices they initiate become self-renewing machines."]],"MC_TFRR_L1_02:ALT-B01":[["[Surface level] Apparitions, archives, ecclesiastical disputes, illness, travel, patronage, money, household commands, and angelic counsel constitute the explicit field.","Apparitions, archives, ecclesiastical disputes, illness, travel, patronage, money, household commands, and angelic counsel constitute the explicit field."]],"MC_TFRR_L1_02:ALT-B02":[["[Structural level] Mediation, office, custody, place, timing, obedience, material support, and restricted access form one ranked revelatory administration.","Mediation, office, custody, place, timing, obedience, material support, and restricted access form one ranked revelatory administration."]],"MC_TFRR_L1_02:ALT-B03":[["[Metastrategic level] Apparent refutations and failed alternatives are redistributed into reasons for stronger discipline, corrected mediation, or relocation.","Apparent refutations and failed alternatives are redistributed into reasons for stronger discipline, corrected mediation, or relocation."]],"MC_TFRR_L1_02:ALT-B04":[["[Ontological / Temporal level] Reality is represented as providentially unified, hierarchically mediated, and governed by a futurity that acts before becoming present.","Reality is represented as providentially unified, hierarchically mediated, and governed by a futurity that acts before becoming present."]],"MC_TFRR_L1_02:ALT-B05":[["[Methodological / Performative level] Recurrent inquiry, restricted answers, accumulated signs, omission, and postponed correction perform the dependence and deferred verification the system asserts.","Recurrent inquiry, restricted answers, accumulated signs, omission, and postponed correction perform the dependence and deferred verification the system asserts."]],"WB_TFRR:GA-01":[["[Persistent] Divine unity functions as the singular source and terminal government of a reality represented as providentially integrated.","Divine unity functions as the singular source and terminal government of a reality represented as providentially integrated."]],"WB_TFRR:GA-02":[["[Persistent] Authority exists only through differentiated mediation whose transmitters remain indispensable without becoming owners of the authority transmitted.","Authority exists only through differentiated mediation whose transmitters remain indispensable without becoming owners of the authority transmitted."]],"WB_TFRR:GA-03":[["[Emergent] Revelation is an infrastructure composed of offices, bodies, texts, media, places, procedures, and custodial relations.","Revelation is an infrastructure composed of offices, bodies, texts, media, places, procedures, and custodial relations."]],"WB_TFRR:GA-04":[["[Mutating] Purification and obedience develop from moral preparation into bounded practical agency and the technical condition of revelatory access.","Purification and obedience develop from moral preparation into bounded practical agency and the technical condition of revelatory access."]],"WB_TFRR:GA-05":[["[Mutating] Inscription develops into an operative interface whose efficacy depends on controlled custody, placement, and jurisdiction.","Inscription develops into an operative interface whose efficacy depends on controlled custody, placement, and jurisdiction."]],"WB_TFRR:GA-06":[["[Emergent] Creation becomes materially addressable, but knowledge of its operations remains jurisdictionally and differentially distributed.","Creation becomes materially addressable, but knowledge of its operations remains jurisdictionally and differentially distributed."]],"WB_TFRR:GA-07":[["[Attractor] Legitimate revelation is authenticated through provenance, conformity, moral effect, authorization, environmental fitness, and purpose rather than appearance alone.","Legitimate revelation is authenticated through provenance, conformity, moral effect, authorization, environmental fitness, and purpose rather than appearance alone."]],"WB_TFRR:GA-08":[["[Mutating] Adversity changes from possible disconfirmation into a bounded diagnostic directing correction, restriction, withdrawal, or relocation.","Adversity changes from possible disconfirmation into a bounded diagnostic directing correction, restriction, withdrawal, or relocation."]],"WB_TFRR:GA-09":[["[Mutating] Election enlarges agency by producing a custodial executor who is more obligated, correctable, and replaceable rather than more sovereign.","Election enlarges agency by producing a custodial executor who is more obligated, correctable, and replaceable rather than more sovereign."]],"WB_TFRR:GA-10":[["[Emergent] Geography and chronology are active media of revelation, organizing appointed openings, delayed fulfillment, jurisdictional differentiation, and commanded movement.","Geography and chronology are active media of revelation, organizing appointed openings, delayed fulfillment, jurisdictional differentiation, and commanded movement."]],"WB_TFRR:GA-11":[["[Emergent] Political authority is conditionally usable but remains subordinate to prophetic jurisdiction and may be corrected, displaced, or recruited as an instrument.","Political authority is conditionally usable but remains subordinate to prophetic jurisdiction and may be corrected, displaced, or recruited as an instrument."]],"WB_TFRR:GA-12":[["[Attractor] Apocalyptic restoration, judgment, reunification, and future wisdom draw ethical, technical, material, and political processes toward a common terminal horizon.","Apocalyptic restoration, judgment, reunification, and future wisdom draw ethical, technical, material, and political processes toward a common terminal horizon."]],"WB_TFRR:GA-13":[["[Terminal] The system closes only through enacted obedience or conditional suspension because exhaustive verification and final consummation remain unavailable.","The system closes only through enacted obedience or conditional suspension because exhaustive verification and final consummation remain unavailable."]],"WB_TFRR:GA-14":[["[Persistent] Operative access remains derivative because the divine center and any nonrecursive criterion of authentication remain inaccessible.","Operative access remains derivative because the divine center and any nonrecursive criterion of authentication remain inaccessible."]],"WB_TFRR:RMD-01":[["[Stable Identity / Scope Expansion] Divine determination retains its identity while expanding from localized sessions into a ranked and mobile administration of creation.","Divine determination retains its identity while expanding from localized sessions into a ranked and mobile administration of creation."]],"WB_TFRR:RMD-02":[["[Functional Mutation] Purification changes from preparatory cleansing into the production of subjects and environments qualified for reception and operation.","Purification changes from preparatory cleansing into the production of subjects and environments qualified for reception and operation."]],"WB_TFRR:RMD-03":[["[Escalation] The seer–scribe division expands into a heterogeneous infrastructure of persons, offices, bodies, finance, law, and material support.","The seer–scribe division expands into a heterogeneous infrastructure of persons, offices, bodies, finance, law, and material support."]],"WB_TFRR:RMD-04":[["[Terminal Transformation] Writing changes from visionary record into causal interface and then into a context-bound event of custodial placement.","Writing changes from visionary record into causal interface and then into a context-bound event of custodial placement."]],"WB_TFRR:RMD-05":[["[Domain Migration] Exact language and sacred geography migrate from representation and setting into causal address, permission, jurisdiction, and operative topology.","Exact language and sacred geography migrate from representation and setting into causal address, permission, jurisdiction, and operative topology."]],"WB_TFRR:RMD-06":[["[Valence Reversal] Resistance changes from potential disconfirmation into an internal diagnostic and then into a directional signal for intensified compliance.","Resistance changes from potential disconfirmation into an internal diagnostic and then into a directional signal for intensified compliance."]],"WB_TFRR:RMD-07":[["[Political Reversal] Rulers change from external patrons into conditional instruments, while political centers become prospective dependents on displaced revelatory wisdom.","Rulers change from external patrons into conditional instruments, while political centers become prospective dependents on displaced revelatory wisdom."]],"WB_TFRR:RMD-08":[["[Terminal Displacement] Silence and delay cease to mark absence and become disciplinary controls and temporal technologies for preserving authority.","Silence and delay cease to mark absence and become disciplinary controls and temporal technologies for preserving authority."]],"WB_TFRR:CGD-01":[["[Local] Named rulers, illnesses, schisms, treasures, substances, intermediaries, and household disputes remain contingent implementations rather than whole-book axioms.","Named rulers, illnesses, schisms, treasures, substances, intermediaries, and household disputes remain contingent implementations rather than whole-book axioms."]],"WB_TFRR:CGD-02":[["[Recoded] Exact grids, enumerations, calls, and alchemical procedures remain local techniques, while encoded access and materially sufficient mediation scale upward.","Exact grids, enumerations, calls, and alchemical procedures remain local techniques, while encoded access and materially sufficient mediation scale upward."]],"WB_TFRR:CGD-03":[["[Scales Upward] Particular journeys remain local itineraries, but commanded movement becomes an epistemic enactment that generates mobile jurisdiction.","Particular journeys remain local itineraries, but commanded movement becomes an epistemic enactment that generates mobile jurisdiction."]],"WB_TFRR:CGD-04":[["[Bridge] Archive and custody connect private disclosure to controlled distribution, public testimony, political responsibility, and practical execution.","Archive and custody connect private disclosure to controlled distribution, public testimony, political responsibility, and practical execution."]],"WB_TFRR:CGD-05":[["[Scales Upward] Ranked administration, restricted access, delegated mediation, and obedience govern both stationary and mobile revelatory orders.","Ranked administration, restricted access, delegated mediation, and obedience govern both stationary and mobile revelatory orders."]],"WB_TFRR:CGD-06":[["[Catalyst] Destruction of contaminated materials remains a local rite, but its conversion of contamination into eligibility establishes the general purification mechanism.","Destruction of contaminated materials remains a local rite, but its conversion of contamination into eligibility establishes the general purification mechanism."]],"WB_TFRR:CGD-07":[["[Absorption] Distinct local visions of restoration and future wisdom are absorbed into the global attractor of apocalyptic reunification and judgment.","Distinct local visions of restoration and future wisdom are absorbed into the global attractor of apocalyptic reunification and judgment."]]};
export function publicReadingText(item) {
  const source = String(item?.text ?? '');
  return views[item?.id]?.find(([original]) => original === source)?.[1] ?? source;
}
